-- >>> supabase/schemas/50_notifications/020_notifications.sql
-- Notifications · notifications (the in-app notification centre, D7, D26)
--
-- One row per notification a member sees. Rows are written only by the delivery function
-- (030_notification_delivery.sql) and are append-mostly, so the table is partitioned by
-- month on `created_at`: retention (180 days) drops whole partitions instead of deleting
-- rows. Partitions are plain declarative ones, created ahead of time by
-- kc_private.notifications_ensure_partition; they live in `kc_private`, so only this
-- parent is part of the API.

create table public.notifications (
  id          uuid not null default gen_random_uuid(),
  user_id     uuid not null references public.users (id) on delete cascade,
  -- A kind of kc_private.notification_kinds; `category` and the text keys are copied from
  -- it at delivery, so reading the centre never touches the private registry. No foreign
  -- key: the only writer takes the values from the registry row itself.
  kind        text not null,
  category    text not null check (category in ('critical', 'social')),
  -- Giving world of the entity, for the world filter of the centre; null when none.
  world_slug  text,
  -- What the notification is about and where a tap leads (a chat, a post handoff, a member).
  entity_type text,
  entity_id   uuid,
  title_key   text not null,
  body_key    text not null,
  -- Arguments of the text and of the tap route, as sent by the emitting module (ids,
  -- statuses). Display names are not stored: the app resolves them from `actor_ids`.
  data        jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'),
  -- Set for kinds that merge: later events with the same key join this row while it is
  -- unread and inside the kind's group window.
  group_key   text,
  -- Members who caused the notification, newest first, at most five; `group_count` is the
  -- number of merged events ("X and 3 others").
  actor_ids   uuid[] not null default '{}',
  group_count integer not null default 1 check (group_count >= 1),
  read_at     timestamptz,
  created_at  timestamptz not null default now(),
  -- Last merge; equal to created_at for a notification that never merged.
  updated_at  timestamptz not null default now(),
  primary key (id, created_at)
) partition by range (created_at);
comment on table public.notifications is
  'In-app notification centre of a member. Written by server code; partitioned by month, kept 180 days.';

-- The centre, newest first: keyset on (created_at, id).
create index notifications_user_recent_idx on public.notifications (user_id, created_at desc, id desc);
-- Unread rows of a member: the badge count, "mark all read", and the lookup of the open
-- group a new event merges into.
create index notifications_user_unread_idx on public.notifications (user_id, group_key)
  where read_at is null;

alter table public.notifications enable row level security;
alter table public.notifications force row level security;

-- A member reads their own notifications. Marking them read goes through RPCs.
create policy notifications_select_self on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.notifications to authenticated;

-- Rows whose month has no partition yet land here, so a missed scheduler run never fails a
-- delivery; ensure_partition moves them out when it creates the month.
create table kc_private.notifications_default partition of public.notifications default;
alter table kc_private.notifications_default enable row level security;
alter table kc_private.notifications_default force row level security;

-- Creates the partition of the month containing p_day, if it does not exist. Rows of that
-- month waiting in the default partition are moved into it. Run monthly, one month ahead.
create function kc_private.notifications_ensure_partition(p_day date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from constant date := date_trunc('month', p_day)::date;
  v_to constant date := (v_from + interval '1 month')::date;
  v_name constant text := 'notifications_y' || to_char(v_from, 'YYYY"m"MM');
begin
  if to_regclass('kc_private.' || v_name) is not null then
    return;
  end if;
  execute format('create table kc_private.%I (like public.notifications including defaults including constraints)', v_name);
  execute format('alter table kc_private.%I enable row level security', v_name);
  execute format('alter table kc_private.%I force row level security', v_name);
  execute format(
    'with moved as (delete from kc_private.notifications_default d
                     where d.created_at >= %L and d.created_at < %L returning d.*)
     insert into kc_private.%I select * from moved', v_from, v_to, v_name);
  execute format(
    'alter table public.notifications attach partition kc_private.%I for values from (%L) to (%L)',
    v_name, v_from, v_to);
end;
$$;
comment on function kc_private.notifications_ensure_partition(date) is
  'Creates the monthly partition of notifications for the given day, if missing.';

-- The month the baseline is applied in and the one after it.
do $$
begin
  perform kc_private.notifications_ensure_partition(current_date);
  perform kc_private.notifications_ensure_partition((current_date + interval '1 month')::date);
end $$;

-- Dedupe ledger: one row per (member, key) that already produced a notification. Kept apart
-- from the partitioned table because a uniqueness guarantee cannot span partitions.
create table kc_private.notification_dedupe (
  user_id    uuid not null references public.users (id) on delete cascade,
  dedupe_key text not null check (char_length(dedupe_key) between 1 and 200),
  created_at timestamptz not null default now(),
  primary key (user_id, dedupe_key)
);
comment on table kc_private.notification_dedupe is
  'Keys that already produced a notification for a member; purged with the notifications.';
-- Retention purge: keys older than the window.
create index notification_dedupe_created_idx on kc_private.notification_dedupe (created_at);

alter table kc_private.notification_dedupe enable row level security;
alter table kc_private.notification_dedupe force row level security;

-- Retention (180 days): drops every monthly partition that lies entirely before the
-- window, and deletes older rows left in the default partition and in the dedupe ledger.
-- Returns the number of partitions dropped. Run daily.
create function kc_private.notifications_purge(p_keep interval default interval '180 days')
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cutoff constant timestamptz := now() - p_keep;
  v_partition record;
  v_dropped integer := 0;
begin
  for v_partition in
    select c.relname
      from pg_catalog.pg_inherits i
      join pg_catalog.pg_class c on c.oid = i.inhrelid
     where i.inhparent = 'public.notifications'::regclass
       and c.relname ~ '^notifications_y\d{4}m\d{2}$'
       -- The partition ends where the next month begins.
       and to_date(substr(c.relname, 16), 'YYYY"m"MM') + interval '1 month' <= v_cutoff
  loop
    execute format('drop table kc_private.%I', v_partition.relname);
    v_dropped := v_dropped + 1;
  end loop;

  delete from kc_private.notifications_default d where d.created_at < v_cutoff;
  delete from kc_private.notification_dedupe d where d.created_at < v_cutoff;
  return v_dropped;
end;
$$;
comment on function kc_private.notifications_purge(interval) is
  'Retention: drops monthly partitions older than the window and purges the dedupe ledger.';

-- >>> supabase/schemas/50_notifications/025_notification_push.sql
-- Notifications · the push of a notification
--
-- What the push worker (`dispatch-notification` Edge Function) needs to send one
-- notification to the member's devices, built from the notification row at the moment it is
-- asked for — at delivery (030_notification_delivery.sql) and again at a retry
-- (070_push_retry.sql) — so device tokens, quiet hours and the badge are always current and
-- nothing but ids waits in a queue.
--
-- The push (jsonb):
--   { "tokens": [{ "device_id", "token", "platform" }],
--     "title_key", "body_key",
--     "args": { …the notification's data, "actor_display_name" },
--     "data": { "notification_id", "kind", "category", "entity": { "type", "id" } | null,
--               "group_count" },
--     "collapse_key": "<group key|null>",
--     "badge": <the member's unread notifications> }
-- The worker renders the text from the keys and chooses the platform fields from the kind's
-- row of the registry. For chat kinds `args.message_id` names the message; the worker reads
-- its preview itself (kc_private.notification_message_previews), so message text never
-- passes through a queue.

-- Whether p_at falls in the member's quiet hours (spec 07 §7.11): preferences
-- `quietHours { enabled, start, end, timezone }`, by default 22:00–08:00 Israel time once
-- enabled. A window may cross midnight. Values a client stored that cannot be read as a
-- time or a time zone mean "no quiet hours" rather than a failed delivery.
create function kc_private.notification_in_quiet_hours(p_preferences jsonb, p_at timestamptz default now())
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_quiet constant jsonb := p_preferences -> 'quietHours';
  v_start time;
  v_end time;
  v_local time;
begin
  if v_quiet -> 'enabled' is distinct from 'true'::jsonb then
    return false;
  end if;
  v_start := coalesce(v_quiet ->> 'start', '22:00')::time;
  v_end := coalesce(v_quiet ->> 'end', '08:00')::time;
  v_local := (p_at at time zone coalesce(v_quiet ->> 'timezone', 'Asia/Jerusalem'))::time;
  if v_start <= v_end then
    return v_local >= v_start and v_local < v_end;
  end if;
  return v_local >= v_start or v_local < v_end;
exception when others then
  return false;
end;
$$;
comment on function kc_private.notification_in_quiet_hours(jsonb, timestamptz) is
  'The moment falls inside the quiet hours of the given notification preferences.';

-- The push of one notification, or null when nothing may be pushed now: the kind is shown
-- in the centre only (S10), the member is in quiet hours and the kind does not pass them
-- (D95), or no device is registered. `p_device_ids` narrows the push to those devices — a
-- retry reaches only the devices the first attempt missed.
create function kc_private.notification_push(p_notification public.notifications, p_device_ids uuid[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_kind kc_private.notification_kinds;
  v_preferences jsonb;
  v_tokens jsonb;
begin
  select k.* into v_kind from kc_private.notification_kinds k where k.kind = p_notification.kind;
  if not found or not v_kind.sends_push then
    return null;
  end if;
  if not (v_kind.bypass_preferences or v_kind.bypass_quiet_hours) then
    select p.notification_preferences into v_preferences
      from public.user_private p where p.user_id = p_notification.user_id;
    if kc_private.notification_in_quiet_hours(v_preferences) then
      return null;
    end if;
  end if;

  -- Oldest registration first, so the order of the tokens is stable between attempts.
  select jsonb_agg(jsonb_build_object('device_id', d.id, 'token', d.push_token, 'platform', d.platform)
                   order by d.created_at, d.id)
    into v_tokens
    from public.user_devices d
   where d.user_id = p_notification.user_id
     and (p_device_ids is null or d.id = any (p_device_ids));
  if v_tokens is null then
    return null;
  end if;

  return jsonb_build_object(
    'tokens', v_tokens,
    'title_key', p_notification.title_key,
    'body_key', p_notification.body_key,
    'args', p_notification.data || jsonb_build_object('actor_display_name',
      (select u.display_name from public.users u where u.id = p_notification.actor_ids[1])),
    'data', jsonb_build_object(
      'notification_id', p_notification.id, 'kind', p_notification.kind,
      'category', p_notification.category,
      'entity', case when p_notification.entity_id is not null then jsonb_build_object(
        'type', p_notification.entity_type, 'id', p_notification.entity_id) end,
      'group_count', p_notification.group_count),
    'collapse_key', p_notification.group_key,
    -- The number on the app icon: everything the member has not read, this one included.
    'badge', (select count(*) from public.notifications n
               where n.user_id = p_notification.user_id and n.read_at is null));
end;
$$;
comment on function kc_private.notification_push(public.notifications, uuid[]) is
  'What the push worker sends for a notification (tokens, text keys, arguments, badge), or null when it may not be pushed now.';

-- >>> supabase/schemas/50_notifications/030_notification_delivery.sql
-- Notifications · delivery (the consumer of outbox topic `notification`)
--
-- A worker — the `dispatch-notification` Edge Function, running as the service role — asks
-- for a batch with kc_private.notifications_deliver_batch(). For each event the database
-- decides everything that needs data: whether the member wants the notification, whether
-- it merges into an existing one, and whether a push may be sent now. The worker only
-- renders the text and talks to the push provider.
--
-- Result of one event (jsonb):
--   { "event_id": 1, "status": "delivered" | "skipped", "reason": "<why skipped>",
--     "notification_id": "<uuid>", "group_count": 1,
--     "push": null | <the push of kc_private.notification_push, 025_notification_push.sql> }
-- `push` is null when nothing may be pushed: the kind is centre-only, the member is in
-- quiet hours, or has no device.
-- The event is confirmed in the same transaction as the notification row, so a notification
-- is written exactly once. A push the provider could not take is retried from its own
-- queue (070_push_retry.sql), never by delivering the event again.

-- Whether a member wants a kind: the switch of its category (FR-NOTIF-014) and the kind's
-- own switch, which falls back to the kind's default (FR-NOTIF-017). Only an explicit
-- JSON boolean counts, whatever else a client stored in the preferences.
create function kc_private.notification_kind_enabled(p_preferences jsonb, p_kind kc_private.notification_kinds)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_preferences -> p_kind.category is distinct from 'false'::jsonb
     and case p_preferences -> 'kinds' -> p_kind.kind
           when 'true'::jsonb then true
           when 'false'::jsonb then false
           else p_kind.default_enabled
         end;
$$;
comment on function kc_private.notification_kind_enabled(jsonb, kc_private.notification_kinds) is
  'A member''s preferences allow the kind: category switch and per-kind switch.';

-- Turns one outbox event into a notification and returns the result described above.
create function kc_private.notifications_deliver(p_event_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event kc_private.outbox_events;
  v_kind kc_private.notification_kinds;
  v_to uuid;
  v_actor_id uuid;
  v_entity jsonb;
  v_data jsonb;
  v_dedupe_key text;
  v_group_key text;
  v_preferences jsonb;
  v_is_active boolean;
  v_reason text;
  v_notification public.notifications;
begin
  select e.* into v_event
    from kc_private.outbox_events e
   where e.id = p_event_id and e.topic = 'notification' and e.processed_at is null
     for update;
  if not found then
    return jsonb_build_object('event_id', p_event_id, 'status', 'skipped', 'reason', 'already_processed');
  end if;

  select k.* into v_kind from kc_private.notification_kinds k where k.kind = v_event.payload ->> 'kind';
  if not found then
    raise exception 'unknown_notification_kind' using errcode = 'P0001', detail = v_event.payload ->> 'kind';
  end if;
  v_to := (v_event.payload ->> 'recipient_id')::uuid;
  v_actor_id := (v_event.payload ->> 'actor_id')::uuid;
  v_entity := nullif(v_event.payload -> 'entity', 'null'::jsonb);
  v_data := coalesce(nullif(v_event.payload -> 'data', 'null'::jsonb), '{}'::jsonb);
  v_dedupe_key := v_data ->> 'dedupe_key';
  v_data := v_data - 'dedupe_key';

  select u.is_active, p.notification_preferences into v_is_active, v_preferences
    from public.users u
    join public.user_private p on p.user_id = u.id
   where u.id = v_to;
  v_reason := case
    when not found then 'recipient_missing'
    when v_kind.bypass_preferences then null
    -- FR-NOTIF-011 AC2: a member whose account is not active is not notified.
    when not v_is_active then 'recipient_inactive'
    -- D105: nothing one member of a blocked pair does reaches the other.
    when kc_access.is_blocked_between(v_to, v_actor_id) then 'blocked'
    when not kc_private.notification_kind_enabled(v_preferences, v_kind) then 'preferences'
  end;

  if v_reason is null then
    -- One delivery at a time per member: the dedupe and the merge below read then write.
    perform pg_advisory_xact_lock(hashtextextended(v_to::text, 0));
    if v_dedupe_key is not null then
      insert into kc_private.notification_dedupe (user_id, dedupe_key)
      values (v_to, v_dedupe_key)
      on conflict do nothing;
      if not found then
        v_reason := 'duplicate';
      end if;
    end if;
  end if;
  if v_reason is not null then
    perform kc_private.outbox_complete(p_event_id);
    return jsonb_build_object('event_id', p_event_id, 'status', 'skipped', 'reason', v_reason);
  end if;

  -- Merge into the member's unread notification of the same kind and entity when its last
  -- event is inside the group window; the newest actor moves to the front.
  if v_kind.group_window is not null and v_entity ->> 'id' is not null then
    v_group_key := v_kind.kind || ':' || (v_entity ->> 'type') || ':' || (v_entity ->> 'id');
    update public.notifications n
       set group_count = n.group_count + 1,
           actor_ids = (array_remove(v_actor_id || array_remove(n.actor_ids, v_actor_id), null))[1:5],
           data = v_data,
           updated_at = now()
     where (n.id, n.created_at) = (
             select o.id, o.created_at
               from public.notifications o
              where o.user_id = v_to and o.group_key = v_group_key and o.read_at is null
                and o.updated_at > now() - v_kind.group_window
              order by o.created_at desc
              limit 1)
    returning n.* into v_notification;
  end if;
  if v_notification.id is null then
    insert into public.notifications (
      user_id, kind, category, world_slug, entity_type, entity_id, title_key, body_key, data,
      group_key, actor_ids)
    values (
      v_to, v_kind.kind, v_kind.category, v_data ->> 'world_slug', v_entity ->> 'type',
      (v_entity ->> 'id')::uuid, v_kind.title_key, v_kind.body_key, v_data, v_group_key,
      array_remove(array[v_actor_id], null))
    returning * into v_notification;
  end if;

  perform kc_private.outbox_complete(p_event_id);
  return jsonb_build_object(
    'event_id', p_event_id, 'status', 'delivered',
    'notification_id', v_notification.id, 'group_count', v_notification.group_count,
    'push', kc_private.notification_push(v_notification));
end;
$$;
comment on function kc_private.notifications_deliver(bigint) is
  'Consumer of outbox topic notification: writes or merges the notification and returns the push to send.';

-- Worker entry point: claims due `notification` events, delivers each and returns one
-- result per event. An event that fails is released for a retry with its error (status
-- "failed") and does not stop the batch.
create function kc_private.notifications_deliver_batch(p_limit integer default 50)
returns setof jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event_id bigint;
begin
  for v_event_id in
    select e.id from kc_private.outbox_claim('notification', p_limit) e order by e.id
  loop
    begin
      return next kc_private.notifications_deliver(v_event_id);
    exception when others then
      perform kc_private.outbox_complete(v_event_id, sqlerrm);
      return next jsonb_build_object('event_id', v_event_id, 'status', 'failed', 'reason', sqlerrm);
    end;
  end loop;
end;
$$;
comment on function kc_private.notifications_deliver_batch(integer) is
  'Claims a batch of notification events and delivers them; returns one result per event.';

-- >>> supabase/schemas/50_notifications/040_notification_rpcs.sql
-- Notifications · RPCs of the notification centre
--
-- Reading runs with the caller's rights (the row policy limits it to their own rows).
-- Marking read is the only change a member can make and goes through the two functions
-- below; the table itself is not writable from a device.

-- One page of the caller's notification centre, newest first, with the display fields of
-- the newest actor so the screen needs no second request. Keyset on (created_at, id):
-- pass the last row's values to get the next page. `p_category` filters to one group.
-- The actor's fields are null when that member is not visible to the caller any more.
create function public.notifications_page(
  p_limit integer default 30,
  p_before_created_at timestamptz default null,
  p_before_id uuid default null,
  p_category text default null
)
returns table (
  id uuid,
  kind text,
  category text,
  world_slug text,
  entity_type text,
  entity_id uuid,
  title_key text,
  body_key text,
  data jsonb,
  actor_ids uuid[],
  group_count integer,
  read_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz,
  actor_display_name text,
  actor_avatar_url text
)
language sql
stable
set search_path = ''
as $$
  select n.id, n.kind, n.category, n.world_slug, n.entity_type, n.entity_id, n.title_key,
         n.body_key, n.data, n.actor_ids, n.group_count, n.read_at, n.created_at, n.updated_at,
         u.display_name, u.avatar_url
    from public.notifications n
    left join public.users u on u.id = n.actor_ids[1]
   where n.user_id = (select auth.uid())
     and (p_category is null or n.category = p_category)
     and (p_before_created_at is null or (n.created_at, n.id) < (p_before_created_at, p_before_id))
   order by n.created_at desc, n.id desc
   limit least(greatest(coalesce(p_limit, 30), 1), 50);
$$;
comment on function public.notifications_page(integer, timestamptz, uuid, text) is
  'One page of the caller''s notification centre, newest first, with the newest actor''s display fields.';
grant execute on function public.notifications_page(integer, timestamptz, uuid, text) to authenticated;

-- Badge of the notification centre: the caller's unread notifications.
create function public.notifications_unread_count()
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
    from public.notifications n
   where n.user_id = (select auth.uid()) and n.read_at is null;
$$;
comment on function public.notifications_unread_count() is 'Number of the caller''s unread notifications.';
grant execute on function public.notifications_unread_count() to authenticated;

-- Marks the listed notifications of the caller read; returns how many changed. Ids of
-- other members' notifications and already read ones are ignored.
create function public.notifications_mark_read(p_ids uuid[])
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_changed integer;
begin
  update public.notifications n
     set read_at = now()
   where n.user_id = v_user_id and n.read_at is null and n.id = any (p_ids);
  get diagnostics v_changed = row_count;
  return v_changed;
end;
$$;
comment on function public.notifications_mark_read(uuid[]) is 'Marks the listed notifications of the caller read.';
grant execute on function public.notifications_mark_read(uuid[]) to authenticated;

-- Marks every unread notification of the caller read; returns how many changed.
create function public.notifications_mark_all_read()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_changed integer;
begin
  update public.notifications n
     set read_at = now()
   where n.user_id = v_user_id and n.read_at is null;
  get diagnostics v_changed = row_count;
  return v_changed;
end;
$$;
comment on function public.notifications_mark_all_read() is 'Marks all of the caller''s notifications read.';
grant execute on function public.notifications_mark_all_read() to authenticated;

-- >>> supabase/schemas/50_notifications/050_follow_notifications.sql
-- Notifications · follow events (FR-NOTIF-006, FR-NOTIF-007, FR-NOTIF-008)
--
-- The social graph module writes the rows; these triggers record the `notification` events
-- that follow from them. Each event carries a dedupe key, so a member is told once:
--   follow_request   follow_request:<request id>            the target, per request
--   follow_approved  follow_approved:<request id>           the requester, per request
--   follow_started   follow_started:<follower>:<followed>   the followed member, once per
--                    pair for as long as the key is kept — following again after an
--                    unfollow does not notify a second time

-- A new follower. An edge created by the approval of a request is not announced to the
-- member who just approved it: the requester gets `follow_approved` instead.
create function kc_private.follows_enqueue_notification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- The request was resolved in this transaction: its resolution time is this transaction's.
  if exists (select 1 from public.follow_requests r
              where r.requester_id = new.follower_id and r.target_id = new.followed_id
                and r.status = 'accepted' and r.resolved_at = now()) then
    return null;
  end if;
  perform kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', 'follow_started', 'recipient_id', new.followed_id, 'actor_id', new.follower_id,
    -- The entity is the followed member, so new followers merge into one notification.
    'entity', jsonb_build_object('type', 'user', 'id', new.followed_id),
    'data', jsonb_build_object(
      'dedupe_key', 'follow_started:' || new.follower_id || ':' || new.followed_id)));
  return null;
end;
$$;
comment on function kc_private.follows_enqueue_notification() is
  'AFTER INSERT on follows: enqueues follow_started for the followed member.';

create trigger follows_enqueue_notification
  after insert on public.follows
  for each row execute function kc_private.follows_enqueue_notification();

-- A new request reaches its target; an accepted one reaches its requester. A rejection and
-- a withdrawal are silent (FR-FOLLOW-006).
create function kc_private.follow_requests_enqueue_notification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_accepted constant boolean := tg_op = 'UPDATE';
begin
  perform kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', case when v_accepted then 'follow_approved' else 'follow_request' end,
    'recipient_id', case when v_accepted then new.requester_id else new.target_id end,
    'actor_id', case when v_accepted then new.target_id else new.requester_id end,
    'entity', jsonb_build_object('type', 'follow_request', 'id', new.id),
    'data', jsonb_build_object('dedupe_key',
      case when v_accepted then 'follow_approved:' else 'follow_request:' end || new.id)));
  return null;
end;
$$;
comment on function kc_private.follow_requests_enqueue_notification() is
  'AFTER INSERT (pending) or UPDATE to accepted on follow_requests: enqueues the notification.';

create trigger follow_requests_enqueue_request_notification
  after insert on public.follow_requests
  for each row
  when (new.status = 'pending')
  execute function kc_private.follow_requests_enqueue_notification();

create trigger follow_requests_enqueue_approval_notification
  after update of status on public.follow_requests
  for each row
  when (old.status = 'pending' and new.status = 'accepted')
  execute function kc_private.follow_requests_enqueue_notification();

-- >>> supabase/schemas/50_notifications/060_realtime.sql
-- Notifications · realtime
--
-- Topic `user:<user_id>:notifications`, event `badge`: the member's notification centre
-- changed; the payload is the new unread count and nothing else. Who may listen is decided
-- by the policy on the member's own topics in 40_messaging/060_realtime.sql, and the send
-- is a no-op where the platform's realtime schema is absent (kc_private.broadcast).
-- Per statement, so that "mark all read" sends one event, not one per row.

create function kc_private.notifications_broadcast_badge()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
begin
  for v_user_id in select distinct r.user_id from changed_rows r loop
    perform kc_private.broadcast('user:' || v_user_id || ':notifications', 'badge', jsonb_build_object(
      'unread_count', (select count(*) from public.notifications n
                        where n.user_id = v_user_id and n.read_at is null)));
  end loop;
  return null;
end;
$$;
comment on function kc_private.notifications_broadcast_badge() is
  'AFTER INSERT / UPDATE on notifications (per statement): broadcasts each affected member''s unread count.';

create trigger notifications_broadcast_badge_insert
  after insert on public.notifications
  referencing new table as changed_rows
  for each statement execute function kc_private.notifications_broadcast_badge();

create trigger notifications_broadcast_badge_update
  after update on public.notifications
  referencing new table as changed_rows
  for each statement execute function kc_private.notifications_broadcast_badge();

-- >>> supabase/schemas/50_notifications/070_push_retry.sql
-- Notifications · push worker queues (retries and provider receipts)
--
-- The inbox row of a notification is written exactly once by the delivery function. What
-- can fail afterwards is the hand-over to the push provider, and that has its own two
-- outbox topics, so that a retry never touches the inbox again:
--   notification_push          { "notification_id", "device_ids": [uuid] }
--       a push the provider did not take (rate limit, outage); retried with back-off for
--       the listed devices only, rebuilt from the notification at that time.
--   notification_push_receipt  { "tickets": [{ "id", "device_id" }] }
--       tickets the provider accepted; a while later the worker asks for their receipts
--       and forgets the devices the provider reports as gone (FR-NOTIF-015 AC3).
-- Neither payload carries a token or any text. The worker (`dispatch-notification`) calls
-- only the functions of this file, kc_private.notifications_deliver_batch and
-- kc_private.outbox_claim — one round trip each per run.

-- Previews of chat messages for the push of chat kinds: the first 80 characters of the
-- text (FR-NOTIF-001 AC1); null for a message without text (media, system).
create function kc_private.notification_message_previews(p_message_ids uuid[])
returns table (message_id uuid, preview text)
language sql
stable
security definer
set search_path = ''
as $$
  select m.id, left(m.body, 80)
    from public.messages m
   where m.id = any (p_message_ids);
$$;
comment on function kc_private.notification_message_previews(uuid[]) is
  'First 80 characters of the listed chat messages, read by the push worker at send time.';

-- Claims due `notification_push` events and returns, per event, the push to send again:
--   { "event_id", "status": "retry", "attempts", "notification_id", "push": {…} }
-- The event stays claimed until the worker settles it. An event whose notification is
-- gone, was read meanwhile, or may not be pushed now is confirmed here and reported as
--   { "event_id", "status": "skipped" }.
create function kc_private.notification_push_retry_batch(p_limit integer default 50)
returns setof jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event kc_private.outbox_events;
  v_notification public.notifications;
  v_push jsonb;
begin
  for v_event in
    select e.* from kc_private.outbox_claim('notification_push', p_limit) e order by e.id
  loop
    begin
      v_push := null;
      select n.* into v_notification
        from public.notifications n
       where n.id = (v_event.payload ->> 'notification_id')::uuid and n.read_at is null;
      if found then
        v_push := kc_private.notification_push(v_notification,
          array(select jsonb_array_elements_text(v_event.payload -> 'device_ids'))::uuid[]);
      end if;
      if v_push is null then
        perform kc_private.outbox_complete(v_event.id);
        return next jsonb_build_object('event_id', v_event.id, 'status', 'skipped');
      else
        return next jsonb_build_object(
          'event_id', v_event.id, 'status', 'retry', 'attempts', v_event.attempts,
          'notification_id', v_notification.id, 'push', v_push);
      end if;
    exception when others then
      -- An unreadable event must not spin: it waits an hour with its error recorded.
      perform kc_private.outbox_complete(v_event.id, sqlerrm, interval '1 hour');
      return next jsonb_build_object('event_id', v_event.id, 'status', 'skipped');
    end;
  end loop;
end;
$$;
comment on function kc_private.notification_push_retry_batch(integer) is
  'Claims due push retries and returns the push of each, rebuilt from its notification.';

-- Records everything one worker run learned, in one call:
--   { "forget_devices": [uuid],            devices the provider reports as gone
--     "defer":   [{ "notification_id", "device_ids", "retry_in_seconds" }],
--                                          first attempts that failed for now
--     "retry":   [{ "event_id", "device_ids", "error", "retry_in_seconds" }],
--                                          claimed events to try again later; `device_ids`
--                                          (optional) narrows the event to what still failed
--     "done":    [event_id],               claimed events that are finished
--     "receipts": [[{ "id", "device_id" }]],   accepted tickets, one event per inner list
--     "receipt_delay_seconds": 900 }
-- `retry` and `done` only ever touch events of the two topics of this file.
create function kc_private.notification_push_settle(p_outcome jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_retry record;
begin
  delete from public.user_devices d
   where d.id in (select x::uuid from jsonb_array_elements_text(p_outcome -> 'forget_devices') x);

  perform kc_private.outbox_enqueue('notification_push',
            jsonb_build_object('notification_id', x.notification_id, 'device_ids', x.device_ids),
            now() + make_interval(secs => coalesce(x.retry_in_seconds, 30)))
     from jsonb_to_recordset(p_outcome -> 'defer')
            as x (notification_id uuid, device_ids jsonb, retry_in_seconds integer);

  for v_retry in
    select x.*
      from jsonb_to_recordset(p_outcome -> 'retry')
             as x (event_id bigint, device_ids jsonb, error text, retry_in_seconds integer)
      join kc_private.outbox_events e on e.id = x.event_id
     where e.topic in ('notification_push', 'notification_push_receipt')
  loop
    if v_retry.device_ids is not null then
      update kc_private.outbox_events e
         set payload = e.payload || jsonb_build_object('device_ids', v_retry.device_ids)
       where e.id = v_retry.event_id and e.processed_at is null;
    end if;
    perform kc_private.outbox_complete(v_retry.event_id, coalesce(v_retry.error, 'retry'),
              make_interval(secs => coalesce(v_retry.retry_in_seconds, 60)));
  end loop;

  perform kc_private.outbox_complete(e.id)
     from kc_private.outbox_events e
    where e.id in (select x::bigint from jsonb_array_elements_text(p_outcome -> 'done') x)
      and e.topic in ('notification_push', 'notification_push_receipt');

  perform kc_private.outbox_enqueue('notification_push_receipt',
            jsonb_build_object('tickets', x.tickets),
            now() + make_interval(secs => coalesce((p_outcome ->> 'receipt_delay_seconds')::integer, 900)))
     from jsonb_array_elements(p_outcome -> 'receipts') as x (tickets)
    where jsonb_array_length(x.tickets) > 0;
end;
$$;
comment on function kc_private.notification_push_settle(jsonb) is
  'Push worker: forgets dead devices, schedules retries, confirms finished events and queues receipt checks.';

-- >>> supabase/schemas/58_audit/010_events.sql
-- Audit · events (append-only trail of privileged and sensitive actions)
--
-- One row per action: who acted, what they did and on what. Rows carry ids only — never a
-- name, a phone number or a message body (design §4) — and have no foreign keys, so they
-- outlive the accounts and content they describe. Nobody updates or deletes a row, the
-- service role and the table owner included; the only way data leaves is retention, which
-- drops a whole monthly partition (FR-MOD-012 AC3).
--
-- Partitioned by month with plain declarative partitions (no pg_partman): a scheduled job
-- calls kc_private.audit_ensure_partition ahead of time; the default partition catches a row
-- whose month was never prepared, so a missed job can never fail a member's write.

create sequence audit.events_id_seq;

create table audit.events (
  id          bigint not null default nextval('audit.events_id_seq'),
  occurred_at timestamptz not null default now(),
  -- The member who acted; null for sweeps, triggers of automatic rules and the service role.
  actor_id    uuid,
  -- Request context: the API role of the caller and the device address, when there is one.
  actor_role  text,
  request_ip  inet,
  -- Stable snake_case verb, e.g. 'ban_user', 'restore_target', 'account_status_changed'.
  action      text not null check (action ~ '^[a-z][a-z0-9_]{2,62}$'),
  target_type text check (target_type ~ '^[a-z][a-z0-9_]{1,30}$'),
  target_id   uuid,
  -- Ids, statuses and reason codes only. The key check is a tripwire for the commonest
  -- ways personal text could slip in; free text belongs in the module's own table.
  metadata    jsonb not null default '{}'::jsonb
                check (jsonb_typeof(metadata) = 'object'
                       and not metadata ?| array['name', 'display_name', 'phone', 'email', 'address',
                                                 'body', 'note', 'text', 'comment']),
  primary key (occurred_at, id),
  constraint events_target_pair_chk check (target_id is null or target_type is not null)
) partition by range (occurred_at);
comment on table audit.events is 'Append-only audit trail, one partition per month. Ids only; no updates, no deletes.';
alter sequence audit.events_id_seq owned by audit.events.id;

-- Admin screen "history of a member / a post": events about one target, newest first.
create index events_target_recent_idx on audit.events (target_id, occurred_at desc, id desc)
  where target_id is not null;
-- Admin screen "what did this staff member do": events by one actor, newest first.
create index events_actor_recent_idx on audit.events (actor_id, occurred_at desc, id desc)
  where actor_id is not null;
-- Admin screen filter by action, newest first.
create index events_action_recent_idx on audit.events (action, occurred_at desc, id desc);

alter table audit.events enable row level security;
alter table audit.events force row level security;

-- Refuses every change to audit data. Attached per row (UPDATE, DELETE) and per statement
-- (TRUNCATE); it has no exception for any role.
create function kc_private.audit_reject_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'append_only' using errcode = 'P0001',
    detail = format('%s on %s.%s', tg_op, tg_table_schema, tg_table_name);
end;
$$;
comment on function kc_private.audit_reject_change() is
  'Trigger: raises append_only on UPDATE, DELETE and TRUNCATE of audit data, for every role.';

-- Row triggers on the partitioned table are inherited by every partition, present and future.
create trigger events_append_only
  before update or delete on audit.events
  for each row execute function kc_private.audit_reject_change();
create trigger events_no_truncate
  before truncate on audit.events
  for each statement execute function kc_private.audit_reject_change();

-- The service role reads the trail and writes it only through kc_private.audit_record.
revoke all on audit.events from service_role;
grant select on audit.events to service_role;

-- Applies to one partition what the parent cannot pass down: forced RLS, no direct
-- privileges for the service role, and the TRUNCATE guard (statement triggers are not inherited).
create function kc_private.audit_secure_partition(p_partition text)
returns void
language plpgsql
set search_path = ''
as $$
begin
  execute format('alter table audit.%I enable row level security', p_partition);
  execute format('alter table audit.%I force row level security', p_partition);
  execute format('revoke all on audit.%I from service_role', p_partition);
  execute format(
    'create trigger %I before truncate on audit.%I for each statement '
    'execute function kc_private.audit_reject_change()', p_partition || '_no_truncate', p_partition);
end;
$$;

create table audit.events_default partition of audit.events default;
comment on table audit.events_default is 'Safety net for a month whose partition was not created in time.';
do $$ begin perform kc_private.audit_secure_partition('events_default'); end $$;

-- Creates the partition of the month containing p_month (UTC) unless it exists. Returns
-- whether it was created. Run monthly, a month ahead, by the scheduler; definer rights
-- because the service role may not create objects in `audit`. If the default partition
-- already holds rows of that month the server refuses the new partition; those rows stay
-- readable where they are, and the month keeps using the default partition.
create function kc_private.audit_ensure_partition(p_month date)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from constant timestamptz := date_trunc('month', p_month)::timestamp at time zone 'UTC';
  v_to constant timestamptz := (date_trunc('month', p_month) + interval '1 month')::timestamp at time zone 'UTC';
  v_name constant text := 'events_' || to_char(p_month, '"y"YYYY"m"MM');
begin
  if to_regclass(format('audit.%I', v_name)) is not null then
    return false;
  end if;
  begin
    execute format('create table audit.%I partition of audit.events for values from (%L) to (%L)',
                   v_name, v_from, v_to);
  exception when check_violation then
    return false;
  end;
  perform kc_private.audit_secure_partition(v_name);
  return true;
end;
$$;
comment on function kc_private.audit_ensure_partition(date) is
  'Creates the monthly partition of audit.events for the given date; idempotent.';

-- Retention, the one way audit data is ever removed: drops every monthly partition that
-- ends at or before the month of p_cutoff. The trail is kept for at least 24 months
-- (FR-MOD-012 AC3), so a more recent cutoff is refused.
create function kc_private.audit_drop_partitions_before(p_cutoff date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_partition text;
  v_dropped integer := 0;
begin
  if p_cutoff > (current_date - interval '24 months')::date then
    raise exception 'retention_too_short' using errcode = 'P0001', detail = 'audit rows are kept 24 months';
  end if;
  for v_partition in
    select c.relname
      from pg_catalog.pg_inherits i
      join pg_catalog.pg_class c on c.oid = i.inhrelid
     where i.inhparent = 'audit.events'::regclass
       and c.relname ~ '^events_y[0-9]{4}m[0-9]{2}$'
       and to_date(c.relname, '"events_y"YYYY"m"MM') + interval '1 month' <= date_trunc('month', p_cutoff)
  loop
    execute format('drop table audit.%I', v_partition);
    v_dropped := v_dropped + 1;
  end loop;
  return v_dropped;
end;
$$;
comment on function kc_private.audit_drop_partitions_before(date) is
  'Retention: drops whole monthly partitions older than the cutoff (never younger than 24 months).';

-- Partitions for the month the database is created in and the one after it.
do $$
begin
  perform kc_private.audit_ensure_partition(current_date);
  perform kc_private.audit_ensure_partition((current_date + interval '1 month')::date);
end $$;

-- >>> supabase/schemas/58_audit/020_recording.sql
-- Audit · writing the trail
--
-- kc_private.audit_record is the only writer of audit.events. Privileged RPCs call it in
-- their own transaction; modules created before this one enqueue an outbox event on topic
-- `audit` instead, which the consumer below turns into a row; and the triggers at the end
-- record the state changes that must never go unrecorded, whoever makes them.

-- Records one event and returns its id. The actor defaults to the signed-in caller; the
-- API role and device address are taken from the request, when there is one.
create function kc_private.audit_record(
  p_action text,
  p_target_type text default null,
  p_target_id uuid default null,
  p_metadata jsonb default '{}'::jsonb,
  p_actor_id uuid default auth.uid(),
  p_occurred_at timestamptz default now()
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_forwarded constant text := btrim(split_part(
    nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-forwarded-for', ',', 1));
  v_ip inet;
  v_id bigint;
begin
  begin
    v_ip := nullif(v_forwarded, '')::inet;
  exception when invalid_text_representation then
    v_ip := null;
  end;

  insert into audit.events (occurred_at, actor_id, actor_role, request_ip, action, target_type, target_id, metadata)
  values (
    coalesce(p_occurred_at, now()), p_actor_id,
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    v_ip, p_action, p_target_type, p_target_id, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;
$$;
comment on function kc_private.audit_record(text, text, uuid, jsonb, uuid, timestamptz) is
  'The only writer of audit.events: records one action with its actor, target and id-only metadata.';

-- Consumer of outbox topic `audit`. Payload contract:
--   { "action": text, "actor_id": uuid|null, "entity": { "type": text, "id": uuid }, "data": { ids… } }
-- The row is stamped with the time the event was enqueued. A payload that cannot be
-- recorded is released with its error and retried in an hour, so it stays visible to
-- operations and never blocks the events behind it. Returns the number of rows written.
create function kc_private.audit_consume_outbox(p_limit integer default 200)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event kc_private.outbox_events;
  v_written integer := 0;
begin
  for v_event in select * from kc_private.outbox_claim('audit', p_limit) loop
    begin
      perform kc_private.audit_record(
        v_event.payload ->> 'action',
        v_event.payload #>> '{entity,type}',
        (v_event.payload #>> '{entity,id}')::uuid,
        coalesce(v_event.payload -> 'data', '{}'::jsonb),
        (v_event.payload ->> 'actor_id')::uuid,
        v_event.created_at);
      perform kc_private.outbox_complete(v_event.id);
      v_written := v_written + 1;
    exception when others then
      perform kc_private.outbox_complete(v_event.id, sqlerrm, interval '1 hour');
    end;
  end loop;
  return v_written;
end;
$$;
comment on function kc_private.audit_consume_outbox(integer) is
  'Scheduled job: writes the queued `audit` outbox events to audit.events.';

-- ── State changes recorded by trigger ───────────────────────────────────────
-- Every change of an account status: sanctions, restores, deletion requests, activation.
-- The privileged RPC that caused it records its own event with the reason; this row is the
-- state fact, written even when a future writer forgets to. The actor is the signed-in
-- caller in whose request the change happened; a move made in the machine role `system`
-- (an automatic rule or a sweep) has none. The same holds for the post trigger below.
create function kc_private.audit_user_account_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.audit_record(
    'account_status_changed', 'user', new.user_id,
    jsonb_build_object('from', old.status, 'to', new.status, 'until', new.status_until),
    case when current_setting('kc.fsm_role', true) = 'system' then null else auth.uid() end);
  return null;
end;
$$;

create trigger user_account_audit_status
  after update of status on public.user_account
  for each row when (old.status is distinct from new.status)
  execute function kc_private.audit_user_account_status();

-- Moderation moves of a post: into or out of `hidden_pending_review` and `removed_admin`,
-- and any move made in the role `admin`. Owner moves are not audited.
create function kc_private.audit_post_moderation_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.audit_record(
    'post_status_moderated', 'post', new.id,
    jsonb_build_object('from', old.status, 'to', new.status,
                       'role', nullif(current_setting('kc.fsm_role', true), '')),
    case when current_setting('kc.fsm_role', true) = 'system' then null else auth.uid() end);
  return null;
end;
$$;

create trigger posts_audit_moderation_status
  after update of status on public.posts
  for each row
  when (old.status is distinct from new.status
        and ('removed_admin' in (old.status, new.status)
             or 'hidden_pending_review' in (old.status, new.status)
             or current_setting('kc.fsm_role', true) = 'admin'))
  execute function kc_private.audit_post_moderation_status();

-- >>> supabase/schemas/58_audit/030_deletion_tombstones.sql
-- Audit · deletion tombstones (design §4.1.4)
--
-- Proof that an account was deleted, without keeping the account: a salted hash of the
-- member id and the two dates. Given an id, operations can show that it was purged and
-- when; the table alone identifies nobody.

-- The salt of the hash: one random value per database, created on first use, readable by
-- no API role (the service role included).
create table kc_private.audit_tombstone_salt (
  singleton boolean primary key default true check (singleton),
  salt      bytea not null check (octet_length(salt) >= 32)
);
comment on table kc_private.audit_tombstone_salt is 'Per-database salt of deletion tombstone hashes. One row, never exposed.';
alter table kc_private.audit_tombstone_salt enable row level security;
alter table kc_private.audit_tombstone_salt force row level security;
revoke all on kc_private.audit_tombstone_salt from service_role;

create table audit.deletion_tombstones (
  -- sha256(salt || member id).
  user_hash    bytea primary key check (octet_length(user_hash) = 32),
  -- When the member asked for the deletion; null when the account was removed without a request.
  requested_at timestamptz,
  purged_at    timestamptz not null default now()
);
comment on table audit.deletion_tombstones is 'Salted hash and dates of each purged account. Append-only.';

alter table audit.deletion_tombstones enable row level security;
alter table audit.deletion_tombstones force row level security;
revoke all on audit.deletion_tombstones from service_role;
grant select on audit.deletion_tombstones to service_role;

create trigger deletion_tombstones_append_only
  before update or delete on audit.deletion_tombstones
  for each row execute function kc_private.audit_reject_change();
create trigger deletion_tombstones_no_truncate
  before truncate on audit.deletion_tombstones
  for each statement execute function kc_private.audit_reject_change();

-- The tombstone hash of a member id.
create function kc_private.audit_tombstone_hash(p_user_id uuid)
returns bytea
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_salt bytea;
begin
  insert into kc_private.audit_tombstone_salt (salt)
  values (uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()))
  on conflict (singleton) do nothing;
  select s.salt into strict v_salt from kc_private.audit_tombstone_salt s;
  return sha256(v_salt || uuid_send(p_user_id));
end;
$$;
comment on function kc_private.audit_tombstone_hash(uuid) is
  'Salted hash under which a purged member is remembered; also answers "was this id purged?".';

-- Called by the purge job for each account, in the transaction that removes it (before the
-- auth account is deleted, so the request date is still there). Idempotent: a purge that
-- is retried after a failed step leaves one tombstone. The audit event names the hash,
-- not the member.
create function kc_private.audit_record_deletion(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hash constant bytea := kc_private.audit_tombstone_hash(p_user_id);
begin
  insert into audit.deletion_tombstones (user_hash, requested_at)
  values (v_hash, (select a.deletion_requested_at from public.user_account a where a.user_id = p_user_id))
  on conflict (user_hash) do nothing;
  if found then
    perform kc_private.audit_record(
      'account_purged', 'user', null, jsonb_build_object('tombstone', encode(v_hash, 'hex')), null);
  end if;
end;
$$;
comment on function kc_private.audit_record_deletion(uuid) is
  'Purge job: leaves the tombstone of an account that is about to be removed.';

-- >>> supabase/schemas/60_moderation/010_admin_roles.sql
-- Moderation · admin roles (FR-ADMIN-006, FR-ADMIN-010, FR-ADMIN-027)
--
-- Who holds which staff role. A grant is a row; revoking stamps it, so the history stays.
-- Roles are ranked, platform roles (no organization) or organization roles (scoped to one),
-- and each grant may name the grant it reports to. Nothing here is writable from a device:
-- grants change through the RPCs of the next file, and the first super admin is created by
-- a direct database operation (FR-ADMIN-006 AC2).

-- The role vocabulary the app uses, with the three facts every rule derives from: seniority,
-- whether the role is platform-wide, and which roles its holder may hand out. A holder never
-- grants a role at or above their own rank (FR-ADMIN-027); `super_admin` is granted by nobody.
create table kc_private.admin_roles (
  role            text primary key,
  rank            smallint not null check (rank > 0),
  is_platform     boolean not null,
  grantable_roles text[] not null default '{}',
  unique (role, is_platform)
);
comment on table kc_private.admin_roles is 'Staff role vocabulary: rank, scope kind and the roles each one may grant.';
alter table kc_private.admin_roles enable row level security;
alter table kc_private.admin_roles force row level security;

insert into kc_private.admin_roles (role, rank, is_platform, grantable_roles) values
  ('super_admin', 100, true, array['admin', 'moderator', 'support', 'org_admin', 'org_manager',
     'operators_manager', 'volunteer_manager', 'org_employee', 'operator', 'org_volunteer']),
  ('admin', 90, true, array['moderator', 'support', 'org_admin', 'org_manager',
     'operators_manager', 'volunteer_manager', 'org_employee', 'operator', 'org_volunteer']),
  ('org_admin', 80, false, array['org_manager', 'operators_manager', 'volunteer_manager',
     'org_employee', 'operator', 'org_volunteer']),
  ('org_manager', 70, false, array['operators_manager', 'volunteer_manager', 'org_employee',
     'operator', 'org_volunteer']),
  ('moderator', 60, true, '{}'),
  ('operators_manager', 60, false, array['operator']),
  ('volunteer_manager', 60, false, array['org_volunteer']),
  ('support', 50, true, '{}'),
  ('org_employee', 40, false, '{}'),
  ('operator', 40, false, '{}'),
  ('org_volunteer', 30, false, '{}'),
  ('volunteer', 20, false, '{}');

create table public.admin_role_grants (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.users (id) on delete cascade,
  role             text not null,
  -- Organization the role applies to; null for a platform role. The foreign key is added by
  -- the organizations module, which creates the referenced table.
  scope_org_id     uuid,
  -- Derived, so the composite foreign key below can hold a platform role to "no
  -- organization" and an organization role to "exactly one".
  is_platform      boolean generated always as (scope_org_id is null) stored,
  -- The grant this one reports to; null at the top of a tree.
  manager_grant_id uuid references public.admin_role_grants (id) on delete set null,
  granted_by       uuid references public.users (id) on delete set null,
  granted_at       timestamptz not null default now(),
  -- Set when the grant ends; an active grant has none.
  revoked_at       timestamptz,
  revoked_by       uuid references public.users (id) on delete set null,
  constraint admin_role_grants_role_scope_fk foreign key (role, is_platform)
    references kc_private.admin_roles (role, is_platform),
  constraint admin_role_grants_not_own_manager_chk check (manager_grant_id <> id)
);
comment on table public.admin_role_grants is 'Staff role grants with their reporting line. Written only by server code.';

-- A member holds a role once per scope while it is active.
create unique index admin_role_grants_active_key on public.admin_role_grants
  (user_id, role, coalesce(scope_org_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where revoked_at is null;
-- At most one active super admin (FR-ADMIN-006 AC2).
create unique index admin_role_grants_single_super_admin_key on public.admin_role_grants (role)
  where role = 'super_admin' and revoked_at is null;
-- "Who are the moderators" (staff notifications) and the role foreign key.
create index admin_role_grants_role_idx on public.admin_role_grants (role) where revoked_at is null;
-- Direct reports of a grant (re-parenting on revoke); covers the manager foreign key.
create index admin_role_grants_manager_idx on public.admin_role_grants (manager_grant_id)
  where manager_grant_id is not null;
-- Team roster of an organization.
create index admin_role_grants_scope_idx on public.admin_role_grants (scope_org_id)
  where scope_org_id is not null;
-- Foreign keys to the members who granted and revoked.
create index admin_role_grants_granted_by_idx on public.admin_role_grants (granted_by)
  where granted_by is not null;
create index admin_role_grants_revoked_by_idx on public.admin_role_grants (revoked_by)
  where revoked_by is not null;

-- True when the caller holds, as an active member, an active platform grant of the named
-- role or of a more senior platform role. An unknown or organization role is never held.
-- Definer rights: it is evaluated inside policies of tables the caller cannot read freely.
create function kc_access.has_admin_role(p_role text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.admin_role_grants g
      join kc_private.admin_roles r on r.role = g.role and r.is_platform
      join public.users u on u.id = g.user_id and u.is_active
     where g.user_id = (select auth.uid())
       and g.revoked_at is null
       and r.rank >= (select t.rank from kc_private.admin_roles t where t.role = p_role and t.is_platform));
$$;
comment on function kc_access.has_admin_role(text) is
  'Policy predicate: the caller holds this platform role or a more senior one.';
grant execute on function kc_access.has_admin_role(text) to authenticated;

-- True for any platform staff member (support and above).
create function kc_access.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select kc_access.has_admin_role('support');
$$;
comment on function kc_access.is_admin() is 'Policy predicate: the caller is platform staff.';
grant execute on function kc_access.is_admin() to authenticated;

-- The signed-in caller, who must hold the role (or a more senior one). Every privileged
-- RPC starts here; FR-ADMIN-006 AC3 fixes the error.
create function kc_private.require_admin_role(p_role text)
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if not kc_access.has_admin_role(p_role) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return v_user_id;
end;
$$;
comment on function kc_private.require_admin_role(text) is
  'Returns auth.uid(); raises forbidden (42501) unless the caller holds the platform role.';

alter table public.admin_role_grants enable row level security;
alter table public.admin_role_grants force row level security;

-- A member reads their own grants; platform staff read the whole roster.
create policy admin_role_grants_select_own on public.admin_role_grants
  for select to authenticated
  using (user_id = (select auth.uid()));
create policy admin_role_grants_select_staff on public.admin_role_grants
  for select to authenticated
  using ((select kc_access.is_admin()));

grant select on public.admin_role_grants to authenticated;

-- The caller's active roles (FR-ADMIN-011 AC2); empty for an ordinary member. Runs with the
-- caller's rights: the rows are their own.
create function public.get_my_admin_roles()
returns text[]
language sql
stable
set search_path = ''
as $$
  select coalesce(array_agg(distinct g.role order by g.role), '{}')
    from public.admin_role_grants g
   where g.user_id = (select auth.uid()) and g.revoked_at is null;
$$;
comment on function public.get_my_admin_roles() is 'Active staff roles of the caller, or an empty array.';
grant execute on function public.get_my_admin_roles() to authenticated;

-- Every grant, revoke and change of reporting line is audited, whoever writes the row.
create function kc_private.audit_admin_role_grant()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.audit_record(
    case
      when tg_op = 'INSERT' then 'admin_role_grant'
      when new.revoked_at is not null and old.revoked_at is null then 'admin_role_revoke'
      else 'admin_role_set_manager'
    end,
    'user', new.user_id,
    jsonb_build_object('grant_id', new.id, 'role', new.role, 'scope_org_id', new.scope_org_id,
                       'manager_grant_id', new.manager_grant_id));
  return null;
end;
$$;

create trigger admin_role_grants_audit_insert
  after insert on public.admin_role_grants
  for each row execute function kc_private.audit_admin_role_grant();
create trigger admin_role_grants_audit_update
  after update of revoked_at, manager_grant_id on public.admin_role_grants
  for each row
  when (old.revoked_at is distinct from new.revoked_at
        or old.manager_grant_id is distinct from new.manager_grant_id)
  execute function kc_private.audit_admin_role_grant();

-- >>> supabase/schemas/60_moderation/020_admin_role_rpcs.sql
-- Moderation · managing staff roles (FR-ADMIN-015/016, FR-ADMIN-027, FR-ADMIN-030)
--
-- Authority follows rank and position: a member grants only roles their own role lists
-- (always strictly junior), an organization role only inside its own organization, and
-- revokes or moves only grants that sit below one of their own in the reporting tree.
-- The super admin manages everything except the super admin grant itself.
-- Errors: forbidden / forbidden_grant / forbidden_revoke (42501); P0001 — invalid_role,
-- invalid_scope, target_not_found, target_not_active, role_already_active, grant_not_found,
-- grant_already_revoked, invalid_manager.

-- True when grant p_ancestor is above grant p_node in the reporting tree. UNION (not UNION
-- ALL) ends the walk even if the data ever contained a loop.
create function kc_private.admin_grant_is_above(p_ancestor uuid, p_node uuid)
returns boolean
language sql
stable
set search_path = ''
as $$
  with recursive chain as (
    select g.manager_grant_id as id from public.admin_role_grants g where g.id = p_node
    union
    select g.manager_grant_id from public.admin_role_grants g join chain c on g.id = c.id)
  select exists (select 1 from chain c where c.id = p_ancestor);
$$;

-- The actor's active grant that entitles them to hand out p_role in p_scope, most senior
-- first; null when they may not. A new grant reports to it.
create function kc_private.admin_granting_grant(p_actor uuid, p_role text, p_scope uuid)
returns uuid
language sql
stable
set search_path = ''
as $$
  select g.id
    from public.admin_role_grants g
    join kc_private.admin_roles mine on mine.role = g.role
    join kc_private.admin_roles target on target.role = p_role
   where g.user_id = p_actor
     and g.revoked_at is null
     and p_role = any (mine.grantable_roles)
     and target.rank < mine.rank
     and target.is_platform = (p_scope is null)
     and (mine.is_platform or g.scope_org_id = p_scope)
   order by mine.rank desc
   limit 1;
$$;
comment on function kc_private.admin_granting_grant(uuid, text, uuid) is
  'The grant under which the actor may give a role in a scope; null when not entitled.';

-- True when the actor may revoke, change or move the grant: the super admin always (except
-- their own grant), anyone else when a more senior grant of theirs is above it.
create function kc_private.admin_can_manage_grant(p_actor uuid, p_grant_id uuid)
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (
    select 1
      from public.admin_role_grants t
      join kc_private.admin_roles tr on tr.role = t.role
      join public.admin_role_grants a on a.user_id = p_actor and a.revoked_at is null
      join kc_private.admin_roles ar on ar.role = a.role
     where t.id = p_grant_id
       and t.user_id <> p_actor
       and ar.rank > tr.rank
       and (a.role = 'super_admin' or kc_private.admin_grant_is_above(a.id, t.id)));
$$;

-- Locks an active grant the caller may manage and returns it.
create function kc_private.admin_lock_managed_grant(p_actor uuid, p_grant_id uuid)
returns public.admin_role_grants
language plpgsql
set search_path = ''
as $$
declare
  v_grant public.admin_role_grants;
begin
  select g.* into v_grant from public.admin_role_grants g where g.id = p_grant_id for update;
  if not found then
    raise exception 'grant_not_found' using errcode = 'P0001';
  end if;
  if v_grant.revoked_at is not null then
    raise exception 'grant_already_revoked' using errcode = 'P0001';
  end if;
  if not kc_private.admin_can_manage_grant(p_actor, p_grant_id) then
    raise exception 'forbidden_revoke' using errcode = '42501';
  end if;
  return v_grant;
end;
$$;

-- Gives a member a role. The new grant reports to the caller's grant that allowed it.
create function public.admin_grant_role(p_target_user_id uuid, p_role text, p_scope_org_id uuid default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_active_caller();
  v_role kc_private.admin_roles;
  v_manager_grant_id uuid;
  v_grant_id uuid;
begin
  select r.* into v_role from kc_private.admin_roles r where r.role = p_role;
  if not found then
    raise exception 'invalid_role' using errcode = 'P0001';
  end if;
  if v_role.is_platform <> (p_scope_org_id is null) then
    raise exception 'invalid_scope' using errcode = 'P0001';
  end if;
  v_manager_grant_id := kc_private.admin_granting_grant(v_actor, p_role, p_scope_org_id);
  if v_manager_grant_id is null then
    raise exception 'forbidden_grant' using errcode = '42501';
  end if;
  if not exists (select 1 from public.users u where u.id = p_target_user_id) then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.users u where u.id = p_target_user_id and u.is_active) then
    raise exception 'target_not_active' using errcode = 'P0001';
  end if;

  begin
    insert into public.admin_role_grants (user_id, role, scope_org_id, granted_by, manager_grant_id)
    values (p_target_user_id, p_role, p_scope_org_id, v_actor, v_manager_grant_id)
    returning id into v_grant_id;
  exception when unique_violation then
    raise exception 'role_already_active' using errcode = 'P0001';
  end;
  return v_grant_id;
end;
$$;
comment on function public.admin_grant_role(uuid, text, uuid) is
  'Grants a staff role the caller is entitled to hand out; returns the grant id.';
grant execute on function public.admin_grant_role(uuid, text, uuid) to authenticated;

-- Ends a grant. Its direct reports move, as a group, to the grant it reported to.
create function public.admin_revoke_role(p_grant_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_active_caller();
  v_grant constant public.admin_role_grants := kc_private.admin_lock_managed_grant(v_actor, p_grant_id);
begin
  update public.admin_role_grants g set revoked_at = now(), revoked_by = v_actor where g.id = p_grant_id;
  update public.admin_role_grants g
     set manager_grant_id = v_grant.manager_grant_id
   where g.manager_grant_id = p_grant_id;
end;
$$;
comment on function public.admin_revoke_role(uuid) is 'Revokes a grant below the caller and re-parents its direct reports.';
grant execute on function public.admin_revoke_role(uuid) to authenticated;

-- Replaces the role of a grant in one step: the member keeps their scope, their manager
-- and their reports. The caller must manage the grant and be entitled to give the new role;
-- a change never moves a member between the platform and an organization.
create function public.admin_change_role(p_grant_id uuid, p_new_role text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_active_caller();
  v_grant constant public.admin_role_grants := kc_private.admin_lock_managed_grant(v_actor, p_grant_id);
  v_new_grant_id uuid;
begin
  if not exists (select 1 from kc_private.admin_roles r where r.role = p_new_role) then
    raise exception 'invalid_role' using errcode = 'P0001';
  end if;
  if v_grant.role = p_new_role then
    raise exception 'role_already_active' using errcode = 'P0001';
  end if;
  if not exists (select 1 from kc_private.admin_roles r
                  where r.role = p_new_role and r.is_platform = v_grant.is_platform) then
    raise exception 'invalid_scope' using errcode = 'P0001';
  end if;
  if kc_private.admin_granting_grant(v_actor, p_new_role, v_grant.scope_org_id) is null then
    raise exception 'forbidden_grant' using errcode = '42501';
  end if;

  update public.admin_role_grants g set revoked_at = now(), revoked_by = v_actor where g.id = p_grant_id;
  begin
    insert into public.admin_role_grants (user_id, role, scope_org_id, granted_by, manager_grant_id)
    values (v_grant.user_id, p_new_role, v_grant.scope_org_id, v_actor, v_grant.manager_grant_id)
    returning id into v_new_grant_id;
  exception when unique_violation then
    raise exception 'role_already_active' using errcode = 'P0001';
  end;
  update public.admin_role_grants g set manager_grant_id = v_new_grant_id where g.manager_grant_id = p_grant_id;
  return v_new_grant_id;
end;
$$;
comment on function public.admin_change_role(uuid, text) is
  'Swaps the role of a grant, keeping its scope, manager and reports; returns the new grant id.';
grant execute on function public.admin_change_role(uuid, text) to authenticated;

-- Moves a grant under another manager. The new manager must be an active grant that is
-- more senior than the moved one, in the same organization or on the platform, not below
-- the moved grant (no loops), and either the caller's own grant or one the caller manages.
create function public.admin_set_manager(p_grant_id uuid, p_manager_grant_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_active_caller();
  v_grant constant public.admin_role_grants := kc_private.admin_lock_managed_grant(v_actor, p_grant_id);
begin
  if not exists (
       select 1
         from public.admin_role_grants m
         join kc_private.admin_roles mr on mr.role = m.role
         join kc_private.admin_roles tr on tr.role = v_grant.role
        where m.id = p_manager_grant_id
          and m.revoked_at is null
          and mr.rank > tr.rank
          and (m.scope_org_id is null or m.scope_org_id = v_grant.scope_org_id)
          and not kc_private.admin_grant_is_above(p_grant_id, m.id)
          and (m.user_id = v_actor or kc_private.admin_can_manage_grant(v_actor, m.id))) then
    raise exception 'invalid_manager' using errcode = 'P0001';
  end if;
  update public.admin_role_grants g set manager_grant_id = p_manager_grant_id where g.id = p_grant_id;
end;
$$;
comment on function public.admin_set_manager(uuid, uuid) is 'Moves a grant the caller manages under another, more senior grant.';
grant execute on function public.admin_set_manager(uuid, uuid) to authenticated;

-- >>> supabase/schemas/60_moderation/030_admin_access.sql
-- Moderation · what staff may read and manage
--
-- Additional policies only: nothing a member could not read before becomes readable to a
-- member, and no existing policy changes. Platform staff (support and above) read what
-- the admin screens show — members in every account state, every post, handoffs, ratings
-- and comments, removed ones included. Private details (user_private, exact addresses)
-- stay closed to staff as well. Each predicate is wrapped in a scalar subquery, so it is
-- evaluated once per statement, not per row.

-- Member search and member detail, including suspended, banned and deactivated accounts.
create policy users_select_staff on public.users
  for select to authenticated
  using ((select kc_access.is_admin()));
create policy user_account_select_staff on public.user_account
  for select to authenticated
  using ((select kc_access.is_admin()));

-- Content search and the report case screen: posts in every status and audience.
create policy posts_select_staff on public.posts
  for select to authenticated
  using ((select kc_access.is_admin()));
create policy post_handoffs_select_staff on public.post_handoffs
  for select to authenticated
  using ((select kc_access.is_admin()));
-- Comments, deleted ones included: the row is the evidence of a reported comment.
create policy post_comments_select_staff on public.post_comments
  for select to authenticated
  using ((select kc_access.is_admin()));

-- Ratings are read by staff only (D24): a member never sees a rating, their own included.
create policy post_ratings_select_staff on public.post_ratings
  for select to authenticated
  using ((select kc_access.is_admin()));
grant select on public.post_ratings to authenticated;

-- The super admin may edit the content of every post (design §12.1), in any status. Which
-- columns is decided by the grant of the posts module; status still moves only through RPCs.
create policy posts_update_super_admin on public.posts
  for update to authenticated
  using ((select kc_access.has_admin_role('super_admin')))
  with check ((select kc_access.has_admin_role('super_admin')));

-- Replaces the handoffs module's authorization of every post management action (publish,
-- pause, resume, delete, close, reopen): the owner, or the super admin for every post
-- (design §12.1).
create or replace function kc_private.can_manage_post(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.posts p
     where p.id = p_post_id
       and (p.owner_id = (select auth.uid())
            or kc_access.has_admin_role('super_admin')
            -- ORGANIZATIONS MODULE: add here "or the caller is an admin of p.beneficiary_org_id".
           ));
$$;
comment on function kc_private.can_manage_post(uuid) is
  'Authorization of every post management action: the owner, or the super admin.';

-- >>> supabase/schemas/60_moderation/040_reports.sql
-- Moderation · reports and the reporter's own hide (FR-MOD-001, FR-MOD-007, FR-MOD-011)
--
-- A member reports a post, a member, a comment or a chat. The report is a plain insert
-- under RLS; triggers do the rest. Its status moves open → confirmed_violation |
-- dismissed_no_violation, by staff only. The reporter stops seeing the target at once,
-- whatever staff later decide.

-- Every number the moderation rules use, in one row, so a product decision is a data change
-- and no function carries a literal (D33, D61, D134, FR-MOD-010).
create table kc_private.moderation_settings (
  singleton                      boolean primary key default true check (singleton),
  -- Distinct reporters with an open report, inside the window, that hide a post or a chat.
  content_hide_reporters         smallint not null default 3 check (content_hide_reporters > 0),
  content_hide_window            interval not null default interval '14 days',
  -- Distinct reporters that suspend a member; the same numbers lift the suspension (D134).
  user_suspend_reporters         smallint not null default 5 check (user_suspend_reporters > 0),
  user_suspend_window            interval not null default interval '30 days',
  -- Dismissed reports of one reporter, inside the window, that trigger a sanction.
  false_report_threshold         smallint not null default 5 check (false_report_threshold > 0),
  false_report_window            interval not null default interval '30 days',
  -- Length of the suspension at each sanction level; a level beyond the list is open-ended.
  false_report_suspension_days   integer[] not null default '{7,30}'
);
comment on table kc_private.moderation_settings is 'Thresholds and windows of the moderation rules. One row.';
alter table kc_private.moderation_settings enable row level security;
alter table kc_private.moderation_settings force row level security;
-- The one row, holding the approved defaults above.
insert into kc_private.moderation_settings default values;

insert into kc_private.fsm_state (machine_id, status) values
  ('report', 'open'),
  ('report', 'confirmed_violation'),
  ('report', 'dismissed_no_violation');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('report', 'open', 'confirmed_violation', 'admin'),
  ('report', 'open', 'dismissed_no_violation', 'admin');

create table public.reports (
  id                   uuid primary key default gen_random_uuid(),
  -- Null once the reporter's account is purged (design §4.1): the report stays.
  reporter_id          uuid references public.users (id) on delete set null,
  target_type          text not null check (target_type in ('post', 'user', 'comment', 'chat')),
  -- Id of the post, member, comment or chat. No foreign key: one column, four tables, and
  -- a report outlives a purged target.
  target_id            uuid not null,
  reason               text not null check (reason in ('Spam', 'Offensive', 'Misleading', 'Illegal', 'Other')),
  note                 text check (char_length(note) between 1 and 500),
  -- Lifecycle, machine `report`. Never written by a device.
  status               text not null default 'open',
  resolved_at          timestamptz,
  resolved_by          uuid references public.users (id) on delete set null,
  -- Set when a dismissed report has been counted into a false-report sanction (FR-MOD-010 AC1).
  sanction_consumed_at timestamptz,
  created_at           timestamptz not null default now(),
  constraint reports_resolution_chk check ((status = 'open') = (resolved_at is null))
);
comment on table public.reports is 'Reports by members about posts, members, comments and chats.';

-- One open report per reporter and target (FR-MOD-001 AC7); also "my reports".
create unique index reports_open_per_reporter_key on public.reports (reporter_id, target_type, target_id)
  where status = 'open';
-- Threshold count and the case screen: reports of one target, newest first.
create index reports_target_idx on public.reports (target_type, target_id, created_at desc);
-- Staff inbox: open reports, oldest first.
create index reports_open_inbox_idx on public.reports (created_at, id) where status = 'open';
-- False-report window of a reporter: their dismissed, not yet counted reports.
create index reports_reporter_dismissed_idx on public.reports (reporter_id, resolved_at)
  where status = 'dismissed_no_violation' and sanction_consumed_at is null;
-- Foreign key to the staff member who resolved.
create index reports_resolved_by_idx on public.reports (resolved_by) where resolved_by is not null;

create trigger reports_status_fsm
  before insert or update of status on public.reports
  for each row execute function kc_private.fsm_guard_status('report', 'status');

alter table public.reports enable row level security;
alter table public.reports force row level security;

create policy reports_select_own on public.reports
  for select to authenticated
  using (reporter_id = (select auth.uid()));
create policy reports_select_staff on public.reports
  for select to authenticated
  using ((select kc_access.is_admin()));
-- A member with an active account files a report as themselves; it always starts open.
create policy reports_insert_own on public.reports
  for insert to authenticated
  with check (
    reporter_id = (select auth.uid())
    and status = 'open'
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active));

grant select on public.reports to authenticated;
grant insert (id, reporter_id, target_type, target_id, reason, note) on public.reports to authenticated;

-- ── The reporter's hide (FR-MOD-001 AC5, FR-MOD-011) ────────────────────────
create table public.report_hides (
  reporter_id uuid not null references public.users (id) on delete cascade,
  target_type text not null check (target_type in ('post', 'user', 'comment', 'chat')),
  target_id   uuid not null,
  created_at  timestamptz not null default now(),
  primary key (reporter_id, target_type, target_id)
);
comment on table public.report_hides is 'Targets a member reported and therefore no longer sees. Permanent until they remove it.';

alter table public.report_hides enable row level security;
alter table public.report_hides force row level security;

-- Written by the report trigger; the reporter may read and lift their own hides (AC2).
create policy report_hides_select_own on public.report_hides
  for select to authenticated
  using (reporter_id = (select auth.uid()));
create policy report_hides_delete_own on public.report_hides
  for delete to authenticated
  using (reporter_id = (select auth.uid()));
grant select, delete on public.report_hides to authenticated;

-- A reported post, member or comment disappears for its reporter on every surface: the
-- policies are restrictive, so they narrow whatever any other policy allows, and each is one
-- primary-key probe that runs under the caller's own access to report_hides (their rows
-- only). Staff are exempt: a moderator who reported a post must still be able to review it.
-- Chats get the same policy from the messaging module.
create policy posts_hide_reported on public.posts
  as restrictive
  for select to authenticated
  using (
    not exists (select 1 from public.report_hides h
                 where h.reporter_id = (select auth.uid())
                   and h.target_type = 'post' and h.target_id = posts.id)
    or (select kc_access.is_admin()));
create policy users_hide_reported on public.users
  as restrictive
  for select to authenticated
  using (
    not exists (select 1 from public.report_hides h
                 where h.reporter_id = (select auth.uid())
                   and h.target_type = 'user' and h.target_id = users.id)
    or (select kc_access.is_admin()));
create policy post_comments_hide_reported on public.post_comments
  as restrictive
  for select to authenticated
  using (
    not exists (select 1 from public.report_hides h
                 where h.reporter_id = (select auth.uid())
                   and h.target_type = 'comment' and h.target_id = post_comments.id)
    or (select kc_access.is_admin()));

-- Checks a new report: the target must exist where this database can tell (a chat is
-- checked by the messaging module), must not be the reporter's own, and a post already
-- removed by staff is not reported again. Errors (P0001): report_target_not_found,
-- cannot_report_self, target_already_moderated.
create function kc_private.reports_validate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner_id uuid;
  v_status text;
begin
  if new.target_type = 'post' then
    select p.owner_id, p.status into v_owner_id, v_status from public.posts p where p.id = new.target_id;
  elsif new.target_type = 'user' then
    select u.id into v_owner_id from public.users u where u.id = new.target_id;
  elsif new.target_type = 'comment' then
    select c.author_id, c.status into v_owner_id, v_status
      from public.post_comments c where c.id = new.target_id;
  else
    return new;
  end if;

  if v_owner_id is null then
    raise exception 'report_target_not_found' using errcode = 'P0001';
  end if;
  if v_owner_id = new.reporter_id then
    raise exception 'cannot_report_self' using errcode = 'P0001';
  end if;
  if v_status in ('removed_admin', 'deleted', 'draft') then
    raise exception 'target_already_moderated' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger reports_validate
  before insert on public.reports
  for each row execute function kc_private.reports_validate();

-- >>> supabase/schemas/60_moderation/050_moderation_queue.sql
-- Moderation · the review queue (FR-MOD-008; design §8: replaces operator_cases and
-- moderation_queue_entries)
--
-- Work items for staff that are not a single report: a target the report threshold acted
-- on, a post reopened suspiciously often, a keyword hit, a manual flag, a post that needs
-- an operator. An entry is open until a staff member resolves it; it may be assigned on
-- the way. One open entry per target and reason.

insert into kc_private.fsm_state (machine_id, status) values
  ('moderation_queue', 'open'),
  ('moderation_queue', 'resolved');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('moderation_queue', 'open', 'resolved', 'admin');

create table public.moderation_queue (
  id          uuid primary key default gen_random_uuid(),
  target_type text not null check (target_type in ('post', 'user', 'comment', 'chat')),
  target_id   uuid not null,
  reason      text not null check (reason in (
                'report_threshold', 'excessive_reopens', 'forbidden_keyword', 'manual_flag', 'operator_case')),
  -- Lifecycle, machine `moderation_queue`.
  status      text not null default 'open',
  -- Staff member working on the entry, if any.
  assignee_id uuid references public.users (id) on delete set null,
  -- Ids and counters that explain the entry (for example the reopen count).
  metadata    jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object'),
  resolved_at timestamptz,
  resolved_by uuid references public.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  constraint moderation_queue_resolution_chk check ((status = 'open') = (resolved_at is null))
);
comment on table public.moderation_queue is 'Review work items for staff. Written only by server code.';

-- One open entry per target and reason; also "is this target queued".
create unique index moderation_queue_open_key on public.moderation_queue (target_type, target_id, reason)
  where status = 'open';
-- Staff queue: open entries, oldest first.
create index moderation_queue_open_idx on public.moderation_queue (created_at, id) where status = 'open';
-- "Assigned to me", and the assignee foreign key.
create index moderation_queue_assignee_idx on public.moderation_queue (assignee_id, created_at)
  where assignee_id is not null;
-- Foreign key to the staff member who resolved.
create index moderation_queue_resolved_by_idx on public.moderation_queue (resolved_by)
  where resolved_by is not null;

create trigger moderation_queue_status_fsm
  before insert or update of status on public.moderation_queue
  for each row execute function kc_private.fsm_guard_status('moderation_queue', 'status');

alter table public.moderation_queue enable row level security;
alter table public.moderation_queue force row level security;

create policy moderation_queue_select_staff on public.moderation_queue
  for select to authenticated
  using ((select kc_access.is_admin()));
grant select on public.moderation_queue to authenticated;

-- Opens an entry unless the same target is already queued for the same reason. Called by
-- the report threshold, by the outbox consumer below and by any later module.
create function kc_private.moderation_enqueue(
  p_target_type text, p_target_id uuid, p_reason text, p_metadata jsonb default '{}'::jsonb)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.moderation_queue (target_type, target_id, reason, metadata)
  values (p_target_type, p_target_id, p_reason, coalesce(p_metadata, '{}'::jsonb))
  on conflict (target_type, target_id, reason) where status = 'open' do nothing;
  return found;
end;
$$;
comment on function kc_private.moderation_enqueue(text, uuid, text, jsonb) is
  'Queues a target for staff review; returns false while the same entry is already open.';

-- Resolves the open entries of a target (all reasons, or one) in the name of a staff
-- member, or of the system when p_resolved_by is null.
create function kc_private.moderation_queue_close(
  p_target_type text, p_target_id uuid, p_resolved_by uuid, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
begin
  perform set_config('kc.fsm_role', 'admin', true);
  update public.moderation_queue q
     set status = 'resolved', resolved_at = now(), resolved_by = p_resolved_by
   where q.target_type = p_target_type and q.target_id = p_target_id and q.status = 'open'
     and (p_reason is null or q.reason = p_reason);
  perform set_config('kc.fsm_role', v_outer_role, true);
end;
$$;

-- Consumer of outbox topic `moderation`. Payload: { "kind": "excessive_reopens",
-- "post_id": uuid, "owner_id": uuid, "reopen_count": int } → a queue entry for the post
-- (FR-MOD-008 AC1). An unknown kind is released with an error and retried in an hour.
create function kc_private.moderation_consume_outbox(p_limit integer default 200)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event kc_private.outbox_events;
  v_queued integer := 0;
begin
  for v_event in select * from kc_private.outbox_claim('moderation', p_limit) loop
    if v_event.payload ->> 'kind' = 'excessive_reopens' and v_event.payload ? 'post_id' then
      perform kc_private.moderation_enqueue(
        'post', (v_event.payload ->> 'post_id')::uuid, 'excessive_reopens',
        jsonb_build_object('reopen_count', v_event.payload -> 'reopen_count'));
      perform kc_private.outbox_complete(v_event.id);
      v_queued := v_queued + 1;
    else
      perform kc_private.outbox_complete(v_event.id, 'unknown moderation kind', interval '1 hour');
    end if;
  end loop;
  return v_queued;
end;
$$;
comment on function kc_private.moderation_consume_outbox(integer) is
  'Scheduled job: turns queued `moderation` outbox events into review queue entries.';

-- A staff member takes an open entry, or hands it to another staff member.
create function public.admin_assign_queue_entry(p_entry_id uuid, p_assignee_id uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_assignee constant uuid := coalesce(p_assignee_id, v_actor);
begin
  if not exists (select 1 from public.admin_role_grants g
                  where g.user_id = v_assignee and g.revoked_at is null and g.is_platform) then
    raise exception 'assignee_not_staff' using errcode = 'P0001';
  end if;
  update public.moderation_queue q set assignee_id = v_assignee
   where q.id = p_entry_id and q.status = 'open';
  if not found then
    raise exception 'queue_entry_not_open' using errcode = 'P0001';
  end if;
  perform kc_private.audit_record('assign_queue_entry', 'moderation_queue', p_entry_id,
                                  jsonb_build_object('assignee_id', v_assignee));
end;
$$;
comment on function public.admin_assign_queue_entry(uuid, uuid) is
  'Assigns an open review entry to the caller or to another staff member.';
grant execute on function public.admin_assign_queue_entry(uuid, uuid) to authenticated;

-- A staff member closes an open entry. What was done about the target (remove, restore,
-- nothing) is its own action with its own audit row.
create function public.admin_resolve_queue_entry(p_entry_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
begin
  perform set_config('kc.fsm_role', 'admin', true);
  update public.moderation_queue q
     set status = 'resolved', resolved_at = now(), resolved_by = v_actor
   where q.id = p_entry_id and q.status = 'open';
  if not found then
    raise exception 'queue_entry_not_open' using errcode = 'P0001';
  end if;
  perform set_config('kc.fsm_role', '', true);
  perform kc_private.audit_record('resolve_queue_entry', 'moderation_queue', p_entry_id);
end;
$$;
comment on function public.admin_resolve_queue_entry(uuid) is 'Marks an open review entry resolved.';
grant execute on function public.admin_resolve_queue_entry(uuid) to authenticated;

-- >>> supabase/schemas/60_moderation/060_sanctions.sql
-- Moderation · sanctions (FR-MOD-010, FR-ADMIN-004, D61, D133, D135)
--
-- user_account.status says what a member's state is now; user_sanctions is the history of
-- how it got there: every suspension and ban, who issued it and why, when it ends and when
-- and by whom it was lifted. Both are written together by the two functions below, which
-- every sanctioning path uses — admin RPCs, the report threshold, the false-report ladder
-- and the expiry sweep.

create table public.user_sanctions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.users (id) on delete cascade,
  kind       text not null check (kind in ('suspension', 'ban')),
  reason     text not null check (reason in (
               'false_reports', 'report_threshold', 'spam', 'harassment', 'policy_violation', 'other')),
  -- Free text of the issuing staff member; read by staff only, never copied to the audit trail.
  note       text check (char_length(note) between 1 and 500),
  -- Null for a sanction applied by an automatic rule.
  issued_by  uuid references public.users (id) on delete set null,
  issued_at  timestamptz not null default now(),
  -- End of a temporary suspension; null = until lifted.
  until      timestamptz,
  lifted_at  timestamptz,
  lifted_by  uuid references public.users (id) on delete set null
);
comment on table public.user_sanctions is 'History of suspensions and bans. Written only by server code.';

-- A member has at most one sanction in force; also the member's history lookup.
create unique index user_sanctions_active_key on public.user_sanctions (user_id) where lifted_at is null;
-- Staff view of a member's history, newest first.
create index user_sanctions_user_recent_idx on public.user_sanctions (user_id, issued_at desc);
-- Foreign keys to staff members.
create index user_sanctions_issued_by_idx on public.user_sanctions (issued_by) where issued_by is not null;
create index user_sanctions_lifted_by_idx on public.user_sanctions (lifted_by) where lifted_by is not null;

alter table public.user_sanctions enable row level security;
alter table public.user_sanctions force row level security;

create policy user_sanctions_select_staff on public.user_sanctions
  for select to authenticated
  using ((select kc_access.is_admin()));
grant select on public.user_sanctions to authenticated;

-- Puts a member under a suspension or a ban: moves the account status (its machine decides
-- whether the move is legal), ends the sanction that was in force and records the new one.
-- p_issued_by is the staff member, or null for an automatic rule.
create function kc_private.account_sanction(
  p_user_id uuid, p_status text, p_reason text, p_until timestamptz, p_note text, p_issued_by uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
  v_sanction_id uuid;
begin
  -- The status trigger of the audit module records no actor for a move made as `system`.
  perform set_config('kc.fsm_role', case when p_issued_by is null then 'system' else 'admin' end, true);
  update public.user_account a set status = p_status, status_until = p_until where a.user_id = p_user_id;
  perform set_config('kc.fsm_role', v_outer_role, true);

  update public.user_sanctions s set lifted_at = now(), lifted_by = p_issued_by
   where s.user_id = p_user_id and s.lifted_at is null;
  insert into public.user_sanctions (user_id, kind, reason, note, issued_by, until)
  values (p_user_id, case p_status when 'banned' then 'ban' else 'suspension' end,
          p_reason, nullif(btrim(p_note), ''), p_issued_by, p_until)
  returning id into v_sanction_id;

  perform kc_private.audit_record(
    case p_status when 'banned' then 'ban_user' else 'suspend_user' end, 'user', p_user_id,
    jsonb_build_object('status', p_status, 'reason', p_reason, 'until', p_until, 'sanction_id', v_sanction_id),
    p_issued_by);
  return v_sanction_id;
end;
$$;
comment on function kc_private.account_sanction(uuid, text, text, timestamptz, text, uuid) is
  'Applies a suspension or ban: account status, sanction history and audit row together.';

-- Returns a suspended or banned member to active and closes the sanction in force.
-- p_cause: 'admin_restore', 'expired' or 'report_dismissed'.
create function kc_private.account_restore(p_user_id uuid, p_lifted_by uuid, p_cause text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
  v_from text;
begin
  select a.status into v_from from public.user_account a where a.user_id = p_user_id for update;
  perform set_config('kc.fsm_role', case when p_lifted_by is null then 'system' else 'admin' end, true);
  update public.user_account a set status = 'active', status_until = null where a.user_id = p_user_id;
  perform set_config('kc.fsm_role', v_outer_role, true);

  update public.user_sanctions s set lifted_at = now(), lifted_by = p_lifted_by
   where s.user_id = p_user_id and s.lifted_at is null;
  perform kc_private.audit_record(
    case v_from when 'banned' then 'unban_user' else 'unsuspend_user' end, 'user', p_user_id,
    jsonb_build_object('from', v_from, 'cause', p_cause), p_lifted_by);
end;
$$;
comment on function kc_private.account_restore(uuid, uuid, text) is
  'Lifts a suspension or ban: account back to active, sanction closed, audit row written.';

-- The false-report ladder (FR-MOD-010): called once for each report staff dismiss. When
-- the reporter's dismissed, not yet counted reports inside the window reach the threshold,
-- their sanction level rises by one (at most 3) and those reports are consumed. The
-- suspension length comes from the settings; a level without a length is open-ended and is
-- lifted by a staff restore. A heavier state — an admin suspension, a ban, a pending
-- deletion — is left as it is; the level still counts (D135).
create function kc_private.apply_false_report_sanction(p_reporter_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_settings constant kc_private.moderation_settings := (select s from kc_private.moderation_settings s);
  v_account public.user_account;
  v_level smallint;
  v_until timestamptz;
  v_suspends boolean;
begin
  -- The account row is the per-reporter lock: two dismissals cannot both count the same reports.
  select a.* into v_account from public.user_account a where a.user_id = p_reporter_id for update;
  if not found then
    return;
  end if;
  -- Informational running total; the window count below decides (FR-MOD-010 AC1).
  update public.user_account a set false_reports_count = a.false_reports_count + 1
   where a.user_id = p_reporter_id;

  if (select count(*) from public.reports r
       where r.reporter_id = p_reporter_id and r.status = 'dismissed_no_violation'
         and r.sanction_consumed_at is null
         and r.resolved_at > now() - v_settings.false_report_window) < v_settings.false_report_threshold then
    return;
  end if;

  v_level := least(v_account.false_report_sanction_count + 1, 3);
  v_until := now() + v_settings.false_report_suspension_days[v_level] * interval '1 day';
  v_suspends := v_account.status in ('active', 'pending_verification', 'suspended_for_false_reports');

  update public.user_account a set false_report_sanction_count = v_level where a.user_id = p_reporter_id;
  update public.reports r set sanction_consumed_at = now()
   where r.reporter_id = p_reporter_id and r.status = 'dismissed_no_violation'
     and r.sanction_consumed_at is null
     and r.resolved_at > now() - v_settings.false_report_window;

  if v_suspends then
    perform kc_private.account_sanction(
      p_reporter_id, 'suspended_for_false_reports', 'false_reports', v_until, null, null);
  end if;
  perform kc_private.audit_record(
    'false_report_sanction_applied', 'user', p_reporter_id,
    jsonb_build_object('level', v_level, 'until', v_until, 'suspended', v_suspends), null);
end;
$$;
comment on function kc_private.apply_false_report_sanction(uuid) is
  'Counts a dismissed report against its reporter and applies the next sanction level when due.';

-- Daily sweep: lifts every suspension whose end has passed, so a member who never signs in
-- again is not left suspended. Returns the number of accounts restored.
create function kc_private.lift_expired_suspensions()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
  v_lifted integer := 0;
begin
  for v_user_id in
    select a.user_id
      from public.user_account a
     where a.status_until <= now()
       and a.status in ('suspended_for_false_reports', 'suspended_admin')
       for update skip locked
  loop
    perform kc_private.account_restore(v_user_id, null, 'expired');
    v_lifted := v_lifted + 1;
  end loop;
  return v_lifted;
end;
$$;
comment on function kc_private.lift_expired_suspensions() is
  'Scheduled job: restores accounts whose temporary suspension has ended.';

-- >>> supabase/schemas/60_moderation/070_report_effects.sql
-- Moderation · what a new report does (FR-MOD-001 AC5, D33, D61, D134)
--
-- In the transaction of the report: the target is hidden from its reporter, the report is
-- audited, and when enough distinct members hold an open report on the same target the
-- automatic action runs — a post is hidden until a human reviews it, a member is suspended
-- from acting, a chat is handed to the messaging module to hide. Comments have no automatic
-- action: a reported comment waits for staff. The reporters are never told (FR-MOD-005 AC4).

-- True while the open reports on a target meet the threshold that acts on it. The same
-- rule imposes the action and, once a dismissal brings the count below it, lifts it (D134).
create function kc_private.report_threshold_reached(p_target_type text, p_target_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_target_type <> 'comment'
     and (select count(distinct r.reporter_id)
            from public.reports r
           where r.target_type = p_target_type and r.target_id = p_target_id and r.status = 'open'
             and r.created_at > now() - case p_target_type when 'user' then s.user_suspend_window
                                                           else s.content_hide_window end)
         >= case p_target_type when 'user' then s.user_suspend_reporters else s.content_hide_reporters end
    from kc_private.moderation_settings s;
$$;
comment on function kc_private.report_threshold_reached(text, uuid) is
  'Whether enough distinct reporters hold an open report on the target for the automatic action.';

-- Sends one notification event to every active moderator, admin and super admin.
create function kc_private.notify_moderators(p_kind text, p_entity_type text, p_entity_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  select kc_private.outbox_enqueue('notification', jsonb_build_object(
           'kind', p_kind, 'recipient_id', staff.user_id, 'actor_id', null,
           'entity', jsonb_build_object('type', p_entity_type, 'id', p_entity_id),
           'data', jsonb_build_object('dedupe_key', p_kind || ':' || p_entity_id || ':' || staff.user_id)))
    from (select distinct g.user_id
            from public.admin_role_grants g
            join kc_private.admin_roles r on r.role = g.role and r.is_platform
            join kc_private.admin_roles m on m.role = 'moderator'
           where g.revoked_at is null and r.rank >= m.rank) staff;
$$;
comment on function kc_private.notify_moderators(text, text, uuid) is
  'Enqueues a notification for each member of the moderation staff.';

-- Sends one notification event to a member about something staff or a rule did.
create function kc_private.notify_moderation_outcome(p_kind text, p_recipient_id uuid, p_post_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  select kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', p_kind, 'recipient_id', p_recipient_id, 'actor_id', null,
    'entity', jsonb_build_object('type', 'post', 'id', p_post_id),
    'data', jsonb_build_object('post_id', p_post_id)));
$$;

create function kc_private.reports_apply_effects()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
begin
  -- Reports on one target are processed one at a time, so two reports arriving together
  -- cannot both miss the threshold.
  perform pg_advisory_xact_lock(hashtextextended('report:' || new.target_type || ':' || new.target_id, 0));

  insert into public.report_hides (reporter_id, target_type, target_id)
  values (new.reporter_id, new.target_type, new.target_id)
  on conflict do nothing;
  perform kc_private.audit_record(
    'report_target', new.target_type, new.target_id,
    jsonb_build_object('report_id', new.id, 'reason', new.reason), new.reporter_id);

  if not kc_private.report_threshold_reached(new.target_type, new.target_id) then
    return null;
  end if;

  if new.target_type = 'post' then
    select p.* into v_post from public.posts p where p.id = new.target_id for update;
    if v_post.status not in ('open', 'paused', 'closed_delivered', 'expired') then
      return null;
    end if;
    perform kc_private.post_move(new.target_id, 'hidden_pending_review', 'system');
    perform kc_private.notify_moderation_outcome('post_hidden_for_review', v_post.owner_id, v_post.id);
  elsif new.target_type = 'user' then
    -- A member who is already suspended by staff, banned or leaving is not moved: the
    -- report still counts and the case still reaches staff.
    if exists (select 1 from public.user_account a
                where a.user_id = new.target_id
                  and a.status in ('active', 'pending_verification', 'suspended_for_false_reports')) then
      perform kc_private.account_sanction(new.target_id, 'suspended_admin', 'report_threshold', null, null, null);
    end if;
  end if;

  -- One review entry per case; staff are notified, and a chat is hidden, once per entry.
  if kc_private.moderation_enqueue(new.target_type, new.target_id, 'report_threshold') then
    perform kc_private.audit_record(
      'auto_remove_target', new.target_type, new.target_id,
      jsonb_build_object('outcome', case new.target_type when 'post' then 'hidden_pending_review'
                                                         when 'user' then 'suspended_admin'
                                                         else 'hide_requested' end), null);
    perform kc_private.notify_moderators('moderation_review_needed', new.target_type, new.target_id);
    if new.target_type = 'chat' then
      perform kc_private.outbox_enqueue('moderation_target', jsonb_build_object(
        'kind', 'hide', 'target_type', 'chat', 'target_id', new.target_id));
    end if;
  end if;
  return null;
end;
$$;
comment on function kc_private.reports_apply_effects() is
  'AFTER INSERT on reports: reporter hide, audit row and the automatic action at the threshold.';

create trigger reports_apply_effects
  after insert on public.reports
  for each row execute function kc_private.reports_apply_effects();

-- Notification kinds this module emits, registered so delivery accepts them
-- (kc_private.notification_kinds, 50_notifications). Hidden and removed notices bypass
-- preferences: a member must learn that their post is no longer shown (FR-MOD-005).
insert into kc_private.notification_kinds
  (kind, category, bypass_preferences, title_key, body_key)
values
  ('post_hidden_for_review', 'critical', true, 'notifications.postHiddenForReviewTitle', 'notifications.postHiddenForReviewBody'),
  ('post_removed', 'critical', true, 'notifications.postRemovedTitle', 'notifications.postRemovedBody'),
  ('post_restored', 'critical', false, 'notifications.postRestoredTitle', 'notifications.postRestoredBody'),
  ('moderation_review_needed', 'critical', false, 'notifications.moderationReviewNeededTitle', 'notifications.moderationReviewNeededBody');

-- >>> supabase/schemas/60_moderation/080_content_moderation.sql
-- Moderation · staff actions on content (FR-ADMIN-002, FR-ADMIN-005, FR-ADMIN-009, D129)
--
-- Removing a post is a status move to `removed_admin`; the post machine remembers the status
-- it left and a restore returns exactly there (a post hidden for review returns to open).
-- Nothing is destroyed. Moderators and above may act. Errors: forbidden (42501); P0001 —
-- target_not_found, invalid_target_state.

-- Removes a post in the name of a staff member. Returns false when it was already removed
-- (idempotent, no second audit row: FR-ADMIN-009 AC5). A draft was never published and
-- cannot be removed.
create function kc_private.moderation_remove_post(p_post_id uuid, p_actor uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
begin
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  if not found then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  if v_post.status = 'removed_admin' then
    return false;
  end if;
  if v_post.status = 'draft' then
    raise exception 'invalid_target_state' using errcode = 'P0001';
  end if;

  perform kc_private.post_move(p_post_id, 'removed_admin', 'admin');
  perform kc_private.moderation_queue_close('post', p_post_id, p_actor);
  perform kc_private.audit_record(
    'manual_remove_target', 'post', p_post_id, jsonb_build_object('from', v_post.status), p_actor);
  perform kc_private.notify_moderation_outcome('post_removed', v_post.owner_id, p_post_id);
  return true;
end;
$$;

-- Restores a removed post to the status it was removed from, or a post hidden for review
-- to open. Returns false for a post in any other status (idempotent).
create function kc_private.moderation_restore_post(p_post_id uuid, p_actor uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
  v_to text;
begin
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  if not found then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  v_to := case v_post.status
            when 'removed_admin' then v_post.status_before_removal
            when 'hidden_pending_review' then 'open'
          end;
  if v_to is null then
    return false;
  end if;

  perform kc_private.post_move(p_post_id, v_to, 'admin');
  perform kc_private.moderation_queue_close('post', p_post_id, p_actor);
  perform kc_private.audit_record(
    'restore_target', 'post', p_post_id, jsonb_build_object('from', v_post.status, 'to', v_to), p_actor);
  perform kc_private.notify_moderation_outcome('post_restored', v_post.owner_id, p_post_id);
  return true;
end;
$$;

create function public.admin_remove_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.moderation_remove_post(p_post_id, kc_private.require_admin_role('moderator'));
end;
$$;
comment on function public.admin_remove_post(uuid) is
  'Staff: removes a published post in any status (→ removed_admin); the owner is notified.';
grant execute on function public.admin_remove_post(uuid) to authenticated;

create function public.admin_restore_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.moderation_restore_post(p_post_id, kc_private.require_admin_role('moderator'));
end;
$$;
comment on function public.admin_restore_post(uuid) is
  'Staff: returns a removed post to its previous status, or a post hidden for review to open (D129).';
grant execute on function public.admin_restore_post(uuid) to authenticated;

-- Staff delete a comment (machine role `admin`), with the replies under it, as the author's
-- own delete does. The rows stay, readable to staff only. Idempotent on a deleted comment.
create function public.admin_delete_comment(p_comment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_comment public.post_comments;
begin
  select c.* into v_comment from public.post_comments c where c.id = p_comment_id for update;
  if not found then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  if v_comment.status = 'deleted' then
    return;
  end if;

  perform set_config('kc.fsm_role', 'admin', true);
  update public.post_comments c
     set status = 'deleted'
   where (c.id = p_comment_id or c.parent_comment_id = p_comment_id) and c.status = 'active';
  perform set_config('kc.fsm_role', '', true);
  perform kc_private.audit_record(
    'manual_remove_target', 'comment', p_comment_id, jsonb_build_object('post_id', v_comment.post_id), v_actor);
end;
$$;
comment on function public.admin_delete_comment(uuid) is 'Staff: deletes a comment and its replies; audited.';
grant execute on function public.admin_delete_comment(uuid) to authenticated;

-- Hook for the messaging module's admin delete of a chat message (FR-ADMIN-005 AC2). That
-- module owns the tables, so it owns the delete; it calls this first, in the same
-- transaction: the caller must be a moderator, and the deletion is audited with ids only.
-- Returns the acting staff member.
create function kc_private.moderation_authorize_message_delete(p_message_id uuid, p_chat_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
begin
  perform kc_private.audit_record(
    'delete_message', 'chat', p_chat_id, jsonb_build_object('message_id', p_message_id), v_actor);
  return v_actor;
end;
$$;
comment on function kc_private.moderation_authorize_message_delete(uuid, uuid) is
  'Messaging hook: checks the moderator role and audits the deletion of a chat message.';

-- >>> supabase/schemas/60_moderation/090_report_rpcs.sql
-- Moderation · resolving a report (FR-ADMIN-003, FR-ADMIN-013, FR-MOD-010, D134)
--
-- A moderator closes one report at a time; each case is independent (FR-ADMIN-013 AC3).
--   confirm   the report was right. A post hidden for review is removed; a suspension stands.
--   dismiss   the report was wrong. It counts against its reporter, and when the reports
--             still open no longer meet the threshold, the automatic action is undone.
-- Errors: forbidden (42501); P0001 — report_not_open.

-- Locks an open report, stamps the outcome and audits it.
create function kc_private.report_resolve(p_report_id uuid, p_status text, p_actor uuid)
returns public.reports
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_report public.reports;
begin
  select r.* into v_report from public.reports r where r.id = p_report_id and r.status = 'open' for update;
  if not found then
    raise exception 'report_not_open' using errcode = 'P0001';
  end if;
  -- Same lock as a new report on the target takes: the threshold is judged on settled data.
  perform pg_advisory_xact_lock(
    hashtextextended('report:' || v_report.target_type || ':' || v_report.target_id, 0));

  perform set_config('kc.fsm_role', 'admin', true);
  update public.reports r set status = p_status, resolved_at = now(), resolved_by = p_actor
   where r.id = p_report_id;
  perform set_config('kc.fsm_role', '', true);
  perform kc_private.audit_record(
    case p_status when 'confirmed_violation' then 'confirm_report' else 'dismiss_report' end,
    'report', p_report_id,
    jsonb_build_object('target_type', v_report.target_type, 'target_id', v_report.target_id), p_actor);
  return v_report;
end;
$$;

create function public.admin_confirm_report(p_report_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_report constant public.reports := kc_private.report_resolve(p_report_id, 'confirmed_violation', v_actor);
begin
  -- The review of a hidden post ends here: a confirmed violation removes it.
  if v_report.target_type = 'post' and exists (
       select 1 from public.posts p where p.id = v_report.target_id and p.status = 'hidden_pending_review') then
    perform kc_private.moderation_remove_post(v_report.target_id, v_actor);
  end if;
end;
$$;
comment on function public.admin_confirm_report(uuid) is
  'Staff: marks an open report as a confirmed violation; a post hidden for review is removed.';
grant execute on function public.admin_confirm_report(uuid) to authenticated;

create function public.admin_dismiss_report(p_report_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_report constant public.reports := kc_private.report_resolve(p_report_id, 'dismissed_no_violation', v_actor);
begin
  perform kc_private.apply_false_report_sanction(v_report.reporter_id);

  -- The automatic action stands while the rule that imposed it still holds (D134).
  if kc_private.report_threshold_reached(v_report.target_type, v_report.target_id) then
    return;
  end if;

  if v_report.target_type = 'post' then
    if exists (select 1 from public.posts p
                where p.id = v_report.target_id and p.status = 'hidden_pending_review') then
      perform kc_private.moderation_restore_post(v_report.target_id, v_actor);
    end if;
  elsif v_report.target_type = 'user' then
    -- Only the suspension the report rule imposed is lifted, never one a staff member issued.
    if exists (select 1 from public.user_account a
                 join public.user_sanctions s on s.user_id = a.user_id and s.lifted_at is null
                where a.user_id = v_report.target_id and a.status = 'suspended_admin'
                  and s.reason = 'report_threshold') then
      perform kc_private.account_restore(v_report.target_id, v_actor, 'report_dismissed');
    end if;
  elsif v_report.target_type = 'chat' then
    perform kc_private.outbox_enqueue('moderation_target', jsonb_build_object(
      'kind', 'restore', 'target_type', 'chat', 'target_id', v_report.target_id));
  end if;
  perform kc_private.moderation_queue_close(
    v_report.target_type, v_report.target_id, v_actor, 'report_threshold');
end;
$$;
comment on function public.admin_dismiss_report(uuid) is
  'Staff: dismisses an open report; counts it against the reporter and lifts an automatic action that no longer holds.';
grant execute on function public.admin_dismiss_report(uuid) to authenticated;

-- >>> supabase/schemas/60_moderation/100_admin_user_rpcs.sql
-- Moderation · staff actions on a member (FR-ADMIN-003 AC3, FR-ADMIN-004, D133, D135)
--
--   suspend   moderator and above; optionally until a date, after which the sweep lifts it
--   ban       super admin only; permanent
--   restore   a suspension by a moderator; a ban by the super admin only (D133)
-- A staff member cannot be sanctioned (revoke the role first) and nobody sanctions
-- themselves. An account under deletion is not sanctioned: the member is leaving, and a
-- sanction would cancel the deletion they asked for (FR-ADMIN-004 AC3).
-- Errors: forbidden (42501); P0001 — target_not_found, cannot_sanction_self,
-- cannot_sanction_admin, invalid_sanction_reason, account_pending_deletion,
-- invalid_target_state, invalid_restore_state.

-- Checks shared by suspend and ban; returns the member's locked account row.
create function kc_private.sanction_target(p_actor uuid, p_user_id uuid, p_reason text)
returns public.user_account
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_account public.user_account;
begin
  if p_user_id = p_actor then
    raise exception 'cannot_sanction_self' using errcode = 'P0001';
  end if;
  if p_reason is null or p_reason not in ('spam', 'harassment', 'policy_violation', 'other') then
    raise exception 'invalid_sanction_reason' using errcode = 'P0001';
  end if;
  select a.* into v_account from public.user_account a where a.user_id = p_user_id for update;
  if not found then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.admin_role_grants g
              where g.user_id = p_user_id and g.revoked_at is null and g.is_platform) then
    raise exception 'cannot_sanction_admin' using errcode = 'P0001';
  end if;
  if v_account.status = 'pending_deletion' then
    raise exception 'account_pending_deletion' using errcode = 'P0001';
  end if;
  return v_account;
end;
$$;

create function public.admin_suspend_user(
  p_user_id uuid, p_reason text, p_until timestamptz default null, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_account constant public.user_account := kc_private.sanction_target(v_actor, p_user_id, p_reason);
begin
  if v_account.status in ('suspended_admin', 'banned') or p_until <= now() then
    raise exception 'invalid_target_state' using errcode = 'P0001';
  end if;
  perform kc_private.account_sanction(p_user_id, 'suspended_admin', p_reason, p_until, p_note, v_actor);
end;
$$;
comment on function public.admin_suspend_user(uuid, text, timestamptz, text) is
  'Staff: suspends a member, open-ended or until a date.';
grant execute on function public.admin_suspend_user(uuid, text, timestamptz, text) to authenticated;

-- Idempotent on a member who is already banned (no second audit row).
create function public.admin_ban_user(p_user_id uuid, p_reason text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('super_admin');
  v_account constant public.user_account := kc_private.sanction_target(v_actor, p_user_id, p_reason);
begin
  if v_account.status = 'banned' then
    return;
  end if;
  perform kc_private.account_sanction(p_user_id, 'banned', p_reason, null, p_note, v_actor);
end;
$$;
comment on function public.admin_ban_user(uuid, text, text) is 'Super admin: bans a member permanently.';
grant execute on function public.admin_ban_user(uuid, text, text) to authenticated;

-- Idempotent on an active member.
create function public.admin_restore_user(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_status text;
begin
  select a.status into v_status from public.user_account a where a.user_id = p_user_id for update;
  if not found then
    raise exception 'target_not_found' using errcode = 'P0001';
  end if;
  if v_status = 'active' then
    return;
  end if;
  if v_status not in ('suspended_admin', 'suspended_for_false_reports', 'banned') then
    raise exception 'invalid_restore_state' using errcode = 'P0001';
  end if;
  if v_status = 'banned' then
    perform kc_private.require_admin_role('super_admin');
  end if;
  perform kc_private.account_restore(p_user_id, v_actor, 'admin_restore');
  perform kc_private.moderation_queue_close('user', p_user_id, v_actor);
end;
$$;
comment on function public.admin_restore_user(uuid) is
  'Staff: lifts a suspension; only the super admin lifts a ban.';
grant execute on function public.admin_restore_user(uuid) to authenticated;

-- >>> supabase/schemas/60_moderation/110_admin_audit_search.sql
-- Moderation · the audit screen (FR-ADMIN-007)
--
-- The audit trail is not exposed as a table: staff read it through this function, newest
-- first, one keyset page at a time. Rows carry ids only; the screen resolves names through
-- the profiles it may read.
--   super admin   every event
--   moderator     events they made and events about them
--   support       events they made

create function public.admin_audit_search(
  p_target_id uuid default null,
  p_actor_id uuid default null,
  p_action text default null,
  p_from timestamptz default null,
  p_to timestamptz default null,
  -- Keyset cursor: occurred_at and id of the last row of the previous page.
  p_before_occurred_at timestamptz default null,
  p_before_id bigint default null,
  p_limit integer default 50
)
returns table (
  id bigint,
  occurred_at timestamptz,
  actor_id uuid,
  action text,
  target_type text,
  target_id uuid,
  metadata jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('support');
  v_sees_all constant boolean := kc_access.has_admin_role('super_admin');
  v_sees_about_self constant boolean := kc_access.has_admin_role('moderator');
begin
  return query
  select e.id, e.occurred_at, e.actor_id, e.action, e.target_type, e.target_id, e.metadata
    from audit.events e
   where (p_target_id is null or e.target_id = p_target_id)
     and (p_actor_id is null or e.actor_id = p_actor_id)
     and (p_action is null or e.action = p_action)
     and (p_from is null or e.occurred_at >= p_from)
     and (p_to is null or e.occurred_at < p_to)
     and (p_before_occurred_at is null
          or (e.occurred_at, e.id) < (p_before_occurred_at, coalesce(p_before_id, 9223372036854775807)))
     and (v_sees_all or e.actor_id = v_actor or (v_sees_about_self and e.target_id = v_actor))
   order by e.occurred_at desc, e.id desc
   limit least(greatest(coalesce(p_limit, 50), 1), 200);
end;
$$;
comment on function public.admin_audit_search(uuid, uuid, text, timestamptz, timestamptz, timestamptz, bigint, integer) is
  'Staff: keyset-paginated search of the audit trail, scoped by the caller''s role.';
grant execute on function public.admin_audit_search(uuid, uuid, text, timestamptz, timestamptz, timestamptz, bigint, integer)
  to authenticated;

-- >>> supabase/schemas/70_worlds/010_world_shared.sql
-- Worlds · shared building blocks of the per-world flows
--
-- The worlds whose fields are filtered, constrained or scheduled get a 1:1 detail table on
-- top of `posts` and their own RPCs on top of `post_handoffs` (design §3.2):
--   transport (rides)  post_ride_details      housing  post_housing_details
--   time (events)      post_event_details     food     post_food_details
--   knowledge          post_knowledge_slots (bookable times only)
-- Items, animals, medical, money, democracy, employment and challenges keep their fields in
-- `posts.details` and use the generic handoff flow. Of this file only
-- public.accept_world_consent is callable from a device.

-- A recurring ride is published by the scheduler, not by its owner's request (D103).
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('post', 'draft', 'open', 'system');

-- Position of an official place (D71): a road junction, a street of a city (its centroid,
-- or the city centre until the street is geocoded) or a city. Exactly one shape is
-- accepted — junction alone, city alone, or city with street; null for anything else and
-- for a place that is not in the catalogs or has no position.
-- Reads only the public reference lists, with the caller's rights.
create function kc_access.place_point(p_city_id text, p_street_id integer, p_junction_id integer)
returns extensions.geography
language sql
stable
set search_path = ''
as $$
  select case
    when p_junction_id is not null and p_city_id is null and p_street_id is null then
      (select j.location from public.road_junctions j where j.junction_id = p_junction_id)
    when p_junction_id is null and p_street_id is not null then
      (select coalesce(s.location, c.location)
         from public.streets s join public.cities c on c.city_id = s.city_id
        where s.city_id = p_city_id and s.street_id = p_street_id)
    when p_junction_id is null then
      (select c.location from public.cities c where c.city_id = p_city_id)
  end;
$$;
comment on function kc_access.place_point(text, integer, integer) is
  'Position of an official place (city, city + street, or road junction); null when the place is unknown.';
grant execute on function kc_access.place_point(text, integer, integer) to authenticated;

-- Version of a world consent that is in force. The texts live in the app's legal bundle;
-- a new version is a one-line change here and asks every member again.
create function kc_private.world_consent_version(p_kind text)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case p_kind when 'driver_declaration' then 1 when 'housing_conduct' then 1 end;
$$;
comment on function kc_private.world_consent_version(text) is
  'Current version of the driver declaration (FR-RIDE-041) and of the housing code of conduct (S59).';

create function kc_private.world_consent_accepted(p_user_id uuid, p_kind text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.user_consents c
                  where c.user_id = p_user_id and c.consent_kind = p_kind
                    and c.version = kc_private.world_consent_version(p_kind));
$$;
comment on function kc_private.world_consent_accepted(uuid, text) is
  'The member accepted the current version of a world consent.';

-- The caller accepts the driver declaration or the housing code of conduct. Only the
-- version in force is accepted, so an old screen cannot record a stale consent.
create function public.accept_world_consent(
  p_kind text, p_version integer, p_locale text default null, p_user_agent text default null)
returns public.user_consents
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if kc_private.world_consent_version(p_kind) is null then
    raise exception 'unknown_consent_kind' using errcode = 'P0001';
  end if;
  if p_version is distinct from kc_private.world_consent_version(p_kind) then
    raise exception 'consent_version_stale' using errcode = 'P0001';
  end if;
  return kc_private.record_consent(v_user_id, p_kind, p_version, p_locale, p_user_agent);
end;
$$;
comment on function public.accept_world_consent(text, integer, text, text) is
  'Records the caller''s consent to the current driver declaration or housing code of conduct.';
grant execute on function public.accept_world_consent(text, integer, text, text) to authenticated;

-- Raises unless the member may act in a world that requires a verified identity (D30,
-- D116): an identity document or better (users.verification_level 2+).
create function kc_private.world_assert_verified(p_user_id uuid, p_world_slug text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if (select w.requires_verification from public.worlds w where w.slug = p_world_slug)
     and not exists (select 1 from public.users u where u.id = p_user_id and u.verification_level >= 2) then
    raise exception 'verification_required' using errcode = 'P0001';
  end if;
end;
$$;
comment on function kc_private.world_assert_verified(uuid, text) is
  'Raises verification_required when the world asks for a verified identity the member lacks.';

-- The post a detail row is being written for, when it is of the expected post type; raises
-- post_details_mismatch otherwise. Called by the BEFORE trigger of every detail table.
create function kc_private.post_for_details(p_post_id uuid, p_post_type text)
returns public.posts
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
begin
  select p.* into v_post from public.posts p where p.id = p_post_id;
  if not found or v_post.post_type <> p_post_type then
    raise exception 'post_details_mismatch' using errcode = 'P0001',
      detail = format('the post is not of type %s', p_post_type);
  end if;
  return v_post;
end;
$$;
comment on function kc_private.post_for_details(uuid, text) is
  'Returns the post of a detail row; raises post_details_mismatch unless it has the expected post type.';

-- May this member book the post, as far as seeing it goes? Asked before any world rule
-- is checked, so that a refusal (departed, started, full) never tells a member about a
-- post they cannot see. The owner passes here and is refused as own_listing by
-- kc_private.handoff_open.
create function kc_private.post_bookable_by(p_post public.posts, p_member_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_post.owner_id = p_member_id or kc_private.post_open_to_member(p_post, p_member_id);
$$;
comment on function kc_private.post_bookable_by(public.posts, uuid) is
  'The member owns the post or could open it; the first check of every world booking RPC.';

-- Locks a booking of the given machine for a move by the caller and returns it. One error
-- for "no such booking", "another world's booking" and "not yours", so nothing is revealed.
--   p_owner_only  the move belongs to the post owner (approve, complete, mark)
--   p_active      the caller needs an active account; a cancellation does not
create function kc_private.world_handoff_lock(
  p_handoff_id uuid, p_machine text, p_owner_only boolean default false, p_active boolean default true)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := case when p_active then kc_private.require_active_caller()
                                  else kc_private.require_caller() end;
  v_handoff constant public.post_handoffs := kc_private.handoff_lock(p_handoff_id);
begin
  if v_handoff.machine_id <> p_machine
     or v_user_id not in (v_handoff.owner_id, v_handoff.recipient_id)
     or (p_owner_only and v_user_id <> v_handoff.owner_id) then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  return v_handoff;
end;
$$;
comment on function kc_private.world_handoff_lock(uuid, text, boolean, boolean) is
  'Row-locks a booking of one machine for a move by one of its members (or its owner only).';

-- >>> supabase/schemas/70_worlds/020_ride_series.sql
-- Worlds · ride_series (a recurring ride, D103, FR-RIDE-046)
--
-- A series is a schedule plus the template of its rides. The scheduler publishes one
-- ordinary ride post per matching day, 30 days ahead (070_ride_series_rpcs.sql), so feed,
-- bookings, alerts and the emergency call treat an occurrence like any other ride. Table
-- and access only; the series RPCs come after the ride details they create.

insert into kc_private.fsm_state (machine_id, status) values
  ('ride_series', 'active'), ('ride_series', 'paused'), ('ride_series', 'cancelled');

-- Cancelling is terminal: a cancelled series is never resumed (publish a new one).
insert into kc_private.fsm_edge (machine_id, from_status, to_status) values
  ('ride_series', 'active', 'paused'),
  ('ride_series', 'paused', 'active'),
  ('ride_series', 'active', 'cancelled'),
  ('ride_series', 'paused', 'cancelled');

create table public.ride_series (
  id               uuid primary key default gen_random_uuid(),
  owner_id         uuid not null references public.users (id) on delete cascade,
  -- The two payloads of public.create_post_with_details for one occurrence, without its
  -- times: the post (kind, direction, title, city, audience) and the ride (route, seats,
  -- flags). Checked by publishing the first occurrence when the series is created.
  post_template    jsonb not null check (jsonb_typeof(post_template) = 'object'),
  ride_template    jsonb not null check (jsonb_typeof(ride_template) = 'object'),
  -- Departure time of every occurrence, Israel local time.
  depart_time      time not null,
  -- Days the ride runs, as a bit set: bit 0 = Sunday … bit 6 = Saturday.
  weekdays         smallint not null check (weekdays between 1 and 127),
  -- Estimated length of the ride; null = no estimated end.
  duration_minutes integer check (duration_minutes between 1 and 1440),
  starts_on        date not null default ((now() at time zone 'Asia/Jerusalem')::date),
  ends_on          date,
  -- Machine `ride_series`. Never written by a device.
  status           text not null default 'active',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint ride_series_dates_chk check (ends_on >= starts_on)
);
comment on table public.ride_series is
  'Recurring ride: weekdays, departure time and the template of its occurrences. Written only by server code.';

-- "My recurring rides", oldest first; covers the owner foreign key.
create index ride_series_owner_idx on public.ride_series (owner_id, created_at);
-- Materialisation sweep: the active series, oldest first.
create index ride_series_active_idx on public.ride_series (created_at) where status = 'active';

create trigger ride_series_status_fsm
  before insert or update of status on public.ride_series
  for each row execute function kc_private.fsm_guard_status('ride_series', 'status');

create trigger ride_series_set_updated_at
  before update on public.ride_series
  for each row execute function kc_private.set_updated_at();

alter table public.ride_series enable row level security;
alter table public.ride_series force row level security;

-- A series is its owner's alone; others see its occurrences, which are ordinary posts.
create policy ride_series_select_owner on public.ride_series
  for select to authenticated
  using (owner_id = (select auth.uid()));

grant select on public.ride_series to authenticated;

-- >>> supabase/schemas/70_worlds/030_post_ride_details.sql
-- Worlds · post_ride_details (the ride behind a post of type `ride`, D70)
--
-- One row per ride offer or ride request: the two ends of the route as official places
-- (D71), up to three meeting points, the schedule, seats and the cost model. Created with
-- its post by public.create_post_with_details; the owner edits it while the post is
-- editable. Positions, the cost cap and the post's expiry are derived here, never taken
-- from a device. Private house numbers of the two ends live in post_private_locations.

create table public.post_ride_details (
  post_id            uuid primary key references public.posts (id) on delete cascade,
  -- Each end is a road junction, a city, or a street of a city (D71).
  origin_city_id     text references public.cities (city_id),
  origin_street_id   integer,
  origin_junction_id integer references public.road_junctions (junction_id),
  -- Derived from the place by trigger; what route search and alerts measure against.
  origin_point       extensions.geography(Point, 4326) not null,
  dest_city_id       text references public.cities (city_id),
  dest_street_id     integer,
  dest_junction_id   integer references public.road_junctions (junction_id),
  dest_point         extensions.geography(Point, 4326) not null,
  -- Official places along the way, in order: [{city_id, street_id, junction_id, lat, lng}].
  -- The device sends the ids; positions are written by trigger.
  meeting_points     jsonb not null default '[]'::jsonb
                       check (jsonb_typeof(meeting_points) = 'array' and jsonb_array_length(meeting_points) <= 3),
  departs_at         timestamptz not null,
  -- Estimated end of the ride; null = not stated.
  arrives_at         timestamptz,
  -- Seats offered by a driver, or passengers travelling on a request.
  seats              smallint not null default 1 check (seats between 1 and 8),
  luggage            boolean not null default false,
  cargo_items        boolean not null default false,
  cargo_food         boolean not null default false,
  -- Cost sharing is symbolic and capped by trigger (spec 5.3 rules); never a profit.
  reward_model       text not null default 'free' check (reward_model in ('free', 'expense_share')),
  cost_share_ils     numeric(6, 2) check (cost_share_ils >= 0),
  notes              text check (char_length(notes) <= 280),
  -- Occurrence of a recurring ride (D103): its series and the day it stands for.
  series_id          uuid references public.ride_series (id) on delete set null,
  series_on          date,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint post_ride_details_origin_fk foreign key (origin_city_id, origin_street_id)
    references public.streets (city_id, street_id),
  constraint post_ride_details_dest_fk foreign key (dest_city_id, dest_street_id)
    references public.streets (city_id, street_id),
  constraint post_ride_details_origin_place_chk
    check (num_nonnulls(origin_city_id, origin_junction_id) = 1 and num_nonnulls(origin_street_id, origin_junction_id) <= 1),
  constraint post_ride_details_dest_place_chk
    check (num_nonnulls(dest_city_id, dest_junction_id) = 1 and num_nonnulls(dest_street_id, dest_junction_id) <= 1),
  constraint post_ride_details_arrival_chk check (arrives_at > departs_at),
  constraint post_ride_details_cost_chk check ((reward_model = 'expense_share') = (cost_share_ils is not null)),
  constraint post_ride_details_series_chk check ((series_id is null) or (series_on is not null)),
  -- One occurrence per series and day; also covers the series foreign key.
  constraint post_ride_details_series_day_key unique (series_id, series_on)
);
comment on table public.post_ride_details is
  'Route, schedule, seats and cost model of a ride post. Positions and the post expiry are derived by trigger.';

-- Rides feed: upcoming rides by departure (keyset on departs_at, post_id).
create index post_ride_details_departs_idx on public.post_ride_details (departs_at, post_id);
-- Route search and saved-route alerts: rides that start / end near a point.
create index post_ride_details_origin_gist_idx on public.post_ride_details using gist (origin_point);
create index post_ride_details_dest_gist_idx on public.post_ride_details using gist (dest_point);
-- Foreign keys to the place catalogs (a catalog refresh retiring a place).
create index post_ride_details_origin_place_idx on public.post_ride_details (origin_city_id, origin_street_id)
  where origin_city_id is not null;
create index post_ride_details_origin_junction_idx on public.post_ride_details (origin_junction_id)
  where origin_junction_id is not null;
create index post_ride_details_dest_place_idx on public.post_ride_details (dest_city_id, dest_street_id)
  where dest_city_id is not null;
create index post_ride_details_dest_junction_idx on public.post_ride_details (dest_junction_id)
  where dest_junction_id is not null;

-- Everything the server decides about a ride on every write:
--   places     both ends and every meeting point must be official places; their positions
--              are (re)written from the catalogs (ride_place_invalid)
--   schedule   a new or moved departure lies in the future and the estimated end after
--              it (ride_time_invalid)
--   cost       an expense share is at most 20 ILS inside one city and 70 ILS between
--              cities (ride_cost_share_cap_exceeded)
--   driver     an offer needs the owner's current driver declaration (declaration_required)
--   seats      never fewer than the seats already booked (ride_seats_below_bookings)
--   post       its time window, and its expiry: an offer 30 minutes after the estimated
--              end (or the departure), an occurrence of a recurring request at departure,
--              a one-off request never (D21)
create function kc_private.post_ride_details_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_for_details(new.post_id, 'ride');
  v_invalid boolean;
begin
  new.origin_point := kc_access.place_point(new.origin_city_id, new.origin_street_id, new.origin_junction_id);
  new.dest_point := kc_access.place_point(new.dest_city_id, new.dest_street_id, new.dest_junction_id);
  select coalesce(jsonb_agg(jsonb_build_object(
           'city_id', m.city_id, 'street_id', m.street_id, 'junction_id', m.junction_id,
           'lat', extensions.st_y(g.point::extensions.geometry),
           'lng', extensions.st_x(g.point::extensions.geometry)) order by e.ordinal), '[]'::jsonb),
         coalesce(bool_or(g.point is null), false)
    into new.meeting_points, v_invalid
    from jsonb_array_elements(new.meeting_points) with ordinality as e (place, ordinal)
   cross join lateral jsonb_to_record(e.place) as m (city_id text, street_id integer, junction_id integer)
   cross join lateral (select kc_access.place_point(m.city_id, m.street_id, m.junction_id) as point) g;
  if v_invalid or new.origin_point is null or new.dest_point is null then
    raise exception 'ride_place_invalid' using errcode = 'P0001';
  end if;

  if ((tg_op = 'INSERT' or new.departs_at <> old.departs_at) and new.departs_at <= now())
     or new.arrives_at <= new.departs_at then
    raise exception 'ride_time_invalid' using errcode = 'P0001';
  end if;
  if new.cost_share_ils > (case when new.origin_city_id = new.dest_city_id then 20 else 70 end) then
    raise exception 'ride_cost_share_cap_exceeded' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT' and v_post.direction = 'offer'
     and not kc_private.world_consent_accepted(v_post.owner_id, 'driver_declaration') then
    raise exception 'declaration_required' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' and new.seats < old.seats
     and kc_private.handoff_seats_taken(new.post_id) > new.seats then
    raise exception 'ride_seats_below_bookings' using errcode = 'P0001';
  end if;

  update public.posts p
     set time_window = tstzrange(new.departs_at, new.arrives_at),
         expires_at = case
           when v_post.direction = 'offer' then coalesce(new.arrives_at, new.departs_at) + interval '30 minutes'
           when new.series_id is not null then new.departs_at
         end
   where p.id = new.post_id;
  return new;
end;
$$;
comment on function kc_private.post_ride_details_prepare() is
  'BEFORE INSERT OR UPDATE on post_ride_details: official places and positions, schedule, cost cap, driver declaration, seats, post expiry.';

create trigger post_ride_details_prepare
  before insert or update on public.post_ride_details
  for each row execute function kc_private.post_ride_details_prepare();

create trigger post_ride_details_set_updated_at
  before update on public.post_ride_details
  for each row execute function kc_private.set_updated_at();

alter table public.post_ride_details enable row level security;
alter table public.post_ride_details force row level security;

-- A ride's details are visible exactly when its post is: the subquery runs under the
-- caller's own access to `posts`.
create policy post_ride_details_select_visible on public.post_ride_details
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_ride_details.post_id));

-- The owner edits the ride while the post's content is editable (draft, open, paused).
create policy post_ride_details_update_owner on public.post_ride_details
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_ride_details.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_ride_details.post_id and p.owner_id = (select auth.uid())));

grant select on public.post_ride_details to authenticated;
-- Not writable: the post, the derived positions and the series link. No insert or delete:
-- the row is created with its post and leaves with it.
grant update (
  origin_city_id, origin_street_id, origin_junction_id, dest_city_id, dest_street_id, dest_junction_id,
  meeting_points, departs_at, arrives_at, seats, luggage, cargo_items, cargo_food,
  reward_model, cost_share_ils, notes
) on public.post_ride_details to authenticated;

-- >>> supabase/schemas/70_worlds/040_ride_bookings.sql
-- Worlds · ride bookings (machine `ride_booking` on post_handoffs, D70, D73, D96)
--
-- A passenger books seats on a ride offer; the driver approves or declines each booking;
-- either side cancels; the driver may bring back a booking they declined or cancelled;
-- the trip is completed per booking or for the whole ride. Seats held by reserved,
-- confirmed and completed bookings never exceed the seats of the ride: every writer holds
-- the post row lock. Pushes, counters and karma events follow from the status change
-- (25_handoffs/030). Errors: SQLSTATE P0001 — listing_not_available, own_listing,
-- item_already_reserved, not_ride_offer, ride_departed, ride_not_started, seats_exhausted,
-- ride_seats_exhausted, ride_place_invalid, handoff_not_found, invalid_status.

-- Books seats on a ride offer. The booking waits for the driver and lapses 12 hours after
-- it was made or at departure, whichever is earlier (D96). The passenger may ask for one
-- of the ride's places as their meeting point (FR-RIDE-030).
create function public.book_ride_seat(
  p_post_id uuid, p_seats integer default 1, p_requested_meeting_point jsonb default null)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_post public.posts;
  v_ride public.post_ride_details;
begin
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  select r.* into v_ride from public.post_ride_details r where r.post_id = p_post_id;
  if not found or not kc_private.post_bookable_by(v_post, v_user_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  if v_post.direction <> 'offer' then
    raise exception 'not_ride_offer' using errcode = 'P0001';
  end if;
  if v_ride.departs_at <= now() then
    raise exception 'ride_departed' using errcode = 'P0001';
  end if;
  if p_seats is null or p_seats not between 1 and 8 then
    raise exception 'seats_exhausted' using errcode = 'P0001';
  end if;
  if p_requested_meeting_point is not null
     and not coalesce(p_requested_meeting_point ?& array['kind', 'id', 'label'], false) then
    raise exception 'ride_place_invalid' using errcode = 'P0001';
  end if;

  return kc_private.handoff_open(
    p_post_id, v_user_id, 'reserved', v_ride.seats, p_seats,
    jsonb_strip_nulls(jsonb_build_object(
      'confirm_by', least(now() + interval '12 hours', v_ride.departs_at),
      'requested_meeting_point', p_requested_meeting_point)));
end;
$$;
comment on function public.book_ride_seat(uuid, integer, jsonb) is
  'The caller books seats on a ride offer; the driver approves within 12 hours or by departure.';
grant execute on function public.book_ride_seat(uuid, integer, jsonb) to authenticated;

-- The driver approves a waiting booking. Its seats were held when it was made, so an
-- approval can never overbook the ride.
create function public.confirm_ride_booking(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff constant public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'ride_booking', true);
begin
  if v_handoff.status <> 'reserved' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if (select r.departs_at from public.post_ride_details r where r.post_id = v_handoff.post_id) <= now() then
    raise exception 'ride_departed' using errcode = 'P0001';
  end if;
  return kc_private.handoff_move(p_handoff_id, 'confirmed', 'owner');
end;
$$;
comment on function public.confirm_ride_booking(uuid) is 'The driver approves a waiting ride booking.';
grant execute on function public.confirm_ride_booking(uuid) to authenticated;

-- Either side cancels a waiting or approved booking; its seats are free at once. The
-- reason records who and when: the driver declining a request (`declined`), the driver
-- withdrawing an approval (`driver_cancelled`), or the passenger (`passenger_cancelled`).
create function public.cancel_ride_booking(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff constant public.post_handoffs :=
    kc_private.world_handoff_lock(p_handoff_id, 'ride_booking', false, false);
  v_by_owner constant boolean := v_handoff.owner_id = (select auth.uid());
begin
  if v_handoff.status not in ('reserved', 'confirmed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  return kc_private.handoff_move(
    p_handoff_id, 'cancelled',
    case when v_by_owner then 'owner' else 'recipient' end,
    case when not v_by_owner then 'passenger_cancelled'
         when v_handoff.status = 'reserved' then 'declined'
         else 'driver_cancelled' end);
end;
$$;
comment on function public.cancel_ride_booking(uuid) is
  'Either side cancels a ride booking; a driver cancelling a waiting booking declines it.';
grant execute on function public.cancel_ride_booking(uuid) to authenticated;

-- The driver brings back a booking they declined (it waits again, with a fresh deadline)
-- or cancelled after approving it (it is approved again). Refused once the ride departed,
-- when the passenger can no longer take the ride or holds another booking on it, and when
-- the seats were given away meanwhile.
create function public.reinstate_ride_booking(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'ride_booking', true);
  v_post public.posts;
  v_ride public.post_ride_details;
begin
  if v_handoff.status <> 'cancelled' or v_handoff.cancel_reason not in ('declined', 'driver_cancelled') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  select p.* into v_post from public.posts p where p.id = v_handoff.post_id;
  select r.* into v_ride from public.post_ride_details r where r.post_id = v_handoff.post_id;
  if not kc_private.post_open_to_member(v_post, v_handoff.recipient_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  if v_ride.departs_at <= now() then
    raise exception 'ride_departed' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.post_handoffs h
              where h.post_id = v_handoff.post_id and h.recipient_id = v_handoff.recipient_id
                and h.status in ('reserved', 'confirmed')) then
    raise exception 'item_already_reserved' using errcode = 'P0001';
  end if;
  if kc_private.handoff_seats_taken(v_handoff.post_id) + v_handoff.seats > v_ride.seats then
    raise exception 'ride_seats_exhausted' using errcode = 'P0001';
  end if;

  if v_handoff.cancel_reason = 'driver_cancelled' then
    return kc_private.handoff_move(p_handoff_id, 'confirmed', 'owner');
  end if;
  perform kc_private.handoff_move(p_handoff_id, 'reserved', 'owner');
  update public.post_handoffs h
     set confirm_by = least(now() + interval '12 hours', v_ride.departs_at)
   where h.id = p_handoff_id
  returning h.* into v_handoff;
  return v_handoff;
end;
$$;
comment on function public.reinstate_ride_booking(uuid) is
  'The driver reinstates a ride booking they declined or cancelled, if the ride still has room.';
grant execute on function public.reinstate_ride_booking(uuid) to authenticated;

-- Marks one booking as travelled, from one hour before departure: the passenger for an
-- approved booking, the driver also for one still waiting. The ride closes as delivered
-- once no booking is live and every seat was used.
create function public.complete_ride_trip(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'ride_booking');
  v_by_owner constant boolean := v_handoff.owner_id = (select auth.uid());
  v_ride public.post_ride_details;
begin
  if v_handoff.status <> 'confirmed' and not (v_by_owner and v_handoff.status = 'reserved') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  select r.* into v_ride from public.post_ride_details r where r.post_id = v_handoff.post_id;
  if v_ride.departs_at > now() + interval '1 hour' then
    raise exception 'ride_not_started' using errcode = 'P0001';
  end if;

  v_handoff := kc_private.handoff_move(
    p_handoff_id, 'handed_over', case when v_by_owner then 'owner' else 'recipient' end);
  if exists (select 1 from public.posts p where p.id = v_handoff.post_id and p.status = 'open')
     and not exists (select 1 from public.post_handoffs h
                      where h.post_id = v_handoff.post_id and h.status in ('reserved', 'confirmed'))
     and kc_private.handoff_seats_taken(v_handoff.post_id) >= v_ride.seats then
    perform kc_private.post_move(v_handoff.post_id, 'closed_delivered', 'system');
  end if;
  return v_handoff;
end;
$$;
comment on function public.complete_ride_trip(uuid) is
  'Marks one ride booking as travelled; a full ride with nothing left open closes as delivered.';
grant execute on function public.complete_ride_trip(uuid) to authenticated;

-- "Ride completed" (spec 5.3 step 7): the driver finishes the whole ride once, from one
-- hour before departure. Approved bookings complete together, the offer closes as
-- delivered and bookings still waiting end with it (cancelled as superseded by the
-- closure, 25_handoffs/050). Returns the number of bookings completed.
create function public.complete_ride(p_post_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
  v_handoff_id uuid;
  v_completed integer := 0;
begin
  if v_post.post_type <> 'ride' or v_post.direction <> 'offer' then
    raise exception 'not_ride_offer' using errcode = 'P0001';
  end if;
  if v_post.status <> 'open' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if (select r.departs_at from public.post_ride_details r where r.post_id = p_post_id)
     > now() + interval '1 hour' then
    raise exception 'ride_not_started' using errcode = 'P0001';
  end if;

  for v_handoff_id in
    select h.id from public.post_handoffs h where h.post_id = p_post_id and h.status = 'confirmed'
  loop
    perform kc_private.handoff_move(v_handoff_id, 'handed_over', 'owner');
    v_completed := v_completed + 1;
  end loop;
  perform kc_private.post_move(p_post_id, 'closed_delivered', 'owner');
  return v_completed;
end;
$$;
comment on function public.complete_ride(uuid) is
  'The driver completes a ride: approved bookings are marked travelled and the offer closes as delivered.';
grant execute on function public.complete_ride(uuid) to authenticated;

-- >>> supabase/schemas/70_worlds/050_ride_saved_routes.sql
-- Worlds · ride_saved_routes and ride_route_alerts (D74, D95)
--
-- A member follows a route (from → to, optionally only some weekdays and hours) and is
-- told about each new ride along it. The alert itself is a `notification` outbox event;
-- `ride_route_alerts` is the ledger that keeps it to one alert per follower and ride — or
-- per recurring series — and to ten alerts per follower a day.

create table public.ride_saved_routes (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null default auth.uid() references public.users (id) on delete cascade,
  -- Which rides the member wants to hear about.
  wants              text not null default 'offers' check (wants in ('offers', 'requests')),
  origin_city_id     text references public.cities (city_id),
  origin_street_id   integer,
  origin_junction_id integer references public.road_junctions (junction_id),
  origin_point       extensions.geography(Point, 4326) not null,
  dest_city_id       text references public.cities (city_id),
  dest_street_id     integer,
  dest_junction_id   integer references public.road_junctions (junction_id),
  dest_point         extensions.geography(Point, 4326) not null,
  -- A ride matches when both of its ends lie within this distance of the route's ends.
  radius_km          integer not null default 10 check (radius_km between 1 and 50),
  -- Optional filter, Israel local time: weekday bit set (bit 0 = Sunday) and departure hours.
  weekdays           smallint check (weekdays between 1 and 127),
  time_from          time,
  time_to            time,
  created_at         timestamptz not null default now(),
  constraint ride_saved_routes_origin_fk foreign key (origin_city_id, origin_street_id)
    references public.streets (city_id, street_id),
  constraint ride_saved_routes_dest_fk foreign key (dest_city_id, dest_street_id)
    references public.streets (city_id, street_id),
  constraint ride_saved_routes_hours_chk check ((time_from is null) = (time_to is null)),
  -- A route is saved once per member; also "my routes" and the member foreign key.
  constraint ride_saved_routes_member_route_key unique nulls not distinct (
    user_id, wants, origin_city_id, origin_street_id, origin_junction_id,
    dest_city_id, dest_street_id, dest_junction_id)
);
comment on table public.ride_saved_routes is
  'Routes a member follows to hear about new rides along them (D74). Places are official; positions are derived.';

-- Alert matching: routes that start near the origin or a meeting point of a new ride.
create index ride_saved_routes_origin_gist_idx on public.ride_saved_routes using gist (origin_point);
-- Foreign keys to the place catalogs.
create index ride_saved_routes_origin_place_idx on public.ride_saved_routes (origin_city_id, origin_street_id)
  where origin_city_id is not null;
create index ride_saved_routes_origin_junction_idx on public.ride_saved_routes (origin_junction_id)
  where origin_junction_id is not null;
create index ride_saved_routes_dest_place_idx on public.ride_saved_routes (dest_city_id, dest_street_id)
  where dest_city_id is not null;
create index ride_saved_routes_dest_junction_idx on public.ride_saved_routes (dest_junction_id)
  where dest_junction_id is not null;

-- Both ends must be official places; their positions are written from the catalogs. A
-- member keeps at most ten routes.
create function kc_private.ride_saved_routes_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.origin_point := kc_access.place_point(new.origin_city_id, new.origin_street_id, new.origin_junction_id);
  new.dest_point := kc_access.place_point(new.dest_city_id, new.dest_street_id, new.dest_junction_id);
  if new.origin_point is null or new.dest_point is null then
    raise exception 'ride_place_invalid' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT'
     and (select count(*) from public.ride_saved_routes r where r.user_id = new.user_id) >= 10 then
    raise exception 'saved_routes_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
comment on function kc_private.ride_saved_routes_prepare() is
  'BEFORE INSERT OR UPDATE on ride_saved_routes: official places, derived positions, ten routes per member.';

create trigger ride_saved_routes_prepare
  before insert or update on public.ride_saved_routes
  for each row execute function kc_private.ride_saved_routes_prepare();

alter table public.ride_saved_routes enable row level security;
alter table public.ride_saved_routes force row level security;

-- A member's routes are private: read, written and removed by the member alone.
create policy ride_saved_routes_all_owner on public.ride_saved_routes
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select, delete on public.ride_saved_routes to authenticated;
grant insert (
  user_id, wants, origin_city_id, origin_street_id, origin_junction_id,
  dest_city_id, dest_street_id, dest_junction_id, radius_km, weekdays, time_from, time_to
) on public.ride_saved_routes to authenticated;
grant update (radius_km, weekdays, time_from, time_to) on public.ride_saved_routes to authenticated;

create table public.ride_route_alerts (
  route_id   uuid not null references public.ride_saved_routes (id) on delete cascade,
  post_id    uuid not null references public.posts (id) on delete cascade,
  user_id    uuid not null references public.users (id) on delete cascade,
  -- Series of the ride, when it is an occurrence of a recurring ride.
  series_id  uuid references public.ride_series (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (route_id, post_id),
  -- A follower hears about a recurring ride once (D103); covers the series foreign key.
  constraint ride_route_alerts_series_member_key unique (series_id, user_id)
);
comment on table public.ride_route_alerts is
  'Ledger of saved-route alerts: one per follower and ride or series, ten per follower a day. Written only by server code.';

-- Daily cap of a follower and "alerts I received"; covers the member foreign key.
create index ride_route_alerts_member_recent_idx on public.ride_route_alerts (user_id, created_at desc);
-- Covers the post foreign key (cascade when a ride is purged).
create index ride_route_alerts_post_idx on public.ride_route_alerts (post_id);

alter table public.ride_route_alerts enable row level security;
alter table public.ride_route_alerts force row level security;

create policy ride_route_alerts_select_self on public.ride_route_alerts
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.ride_route_alerts to authenticated;

-- Alerts the followers of every saved route a newly published ride runs along: the route
-- wants this side (offers or requests), its destination and its origin lie within the
-- route's radius of the ride's destination and of the ride's origin or one of its meeting
-- points, the departure falls on a followed weekday and hour, and the follower could open
-- the ride. One alert per follower; none for a series the follower already heard about,
-- none beyond ten a day (D95). The notification carries the departure so that delivery
-- can decide about quiet hours.
create function kc_private.ride_route_alerts_emit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ride public.post_ride_details;
  v_local timestamp;
  v_route record;
begin
  select r.* into v_ride from public.post_ride_details r where r.post_id = new.id;
  if not found or v_ride.departs_at <= now() then
    return null;
  end if;
  v_local := v_ride.departs_at at time zone 'Asia/Jerusalem';

  for v_route in
    select distinct on (r.user_id) r.id, r.user_id
      from public.ride_saved_routes r
     where r.user_id <> new.owner_id
       and r.wants = case new.direction when 'offer' then 'offers' else 'requests' end
       and (r.weekdays is null or (r.weekdays & (1 << extract(dow from v_local)::integer)) <> 0)
       and (r.time_from is null or v_local::time between r.time_from and r.time_to)
       and extensions.st_dwithin(r.dest_point, v_ride.dest_point, r.radius_km * 1000)
       and (extensions.st_dwithin(r.origin_point, v_ride.origin_point, r.radius_km * 1000)
            or exists (select 1 from jsonb_array_elements(v_ride.meeting_points) m
                        where extensions.st_dwithin(
                                r.origin_point,
                                extensions.st_setsrid(extensions.st_makepoint((m ->> 'lng')::float8, (m ->> 'lat')::float8), 4326)::extensions.geography,
                                r.radius_km * 1000)))
       and kc_private.post_open_to_member(new, r.user_id)
     order by r.user_id, r.created_at
  loop
    continue when (select count(*) from public.ride_route_alerts a
                    where a.user_id = v_route.user_id and a.created_at >= now() - interval '24 hours') >= 10;
    insert into public.ride_route_alerts (route_id, post_id, user_id, series_id)
    values (v_route.id, new.id, v_route.user_id, v_ride.series_id)
    on conflict do nothing;
    continue when not found;
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'ride_route_match', 'recipient_id', v_route.user_id, 'actor_id', new.owner_id,
      'entity', jsonb_build_object('type', 'post', 'id', new.id),
      'data', jsonb_build_object(
        'route_id', v_route.id, 'direction', new.direction, 'departs_at', v_ride.departs_at,
        'series_id', v_ride.series_id,
        'dedupe_key', 'ride_route_match:' || coalesce(v_ride.series_id, new.id) || ':' || v_route.user_id)));
  end loop;
  return null;
end;
$$;
comment on function kc_private.ride_route_alerts_emit() is
  'AFTER UPDATE OF status on posts (a ride is published): saved-route alerts as notification events.';

-- A ride post always has its details before it is published (160_world_post_create.sql),
-- so the route is known at this moment.
create trigger posts_ride_route_alerts
  after update of status on public.posts
  for each row
  when (new.post_type = 'ride' and new.status = 'open' and old.status = 'draft')
  execute function kc_private.ride_route_alerts_emit();

-- >>> supabase/schemas/70_worlds/060_rides_feed.sql
-- Worlds · rides feed and route search (D72, D75)
--
-- One query for the rides world: upcoming ride offers and requests, soonest first,
-- optionally only those running along a route. Candidates are found through the departure
-- and GiST indexes by a definer function (a distance test is not leak-proof, so under row
-- security it could not use an index); the rows themselves are then read with the caller's
-- rights, so RLS on `posts` decides what comes back.

-- Display name of an official place: the junction, "street, city", or the city.
create function kc_access.place_name(p_city_id text, p_street_id integer, p_junction_id integer)
returns text
language sql
stable
set search_path = ''
as $$
  select case
    when p_junction_id is not null then
      (select j.name_he from public.road_junctions j where j.junction_id = p_junction_id)
    else
      (select coalesce(s.name_he || ', ', '') || c.name_he
         from public.cities c
         left join public.streets s on s.city_id = c.city_id and s.street_id = p_street_id
        where c.city_id = p_city_id)
  end;
$$;
comment on function kc_access.place_name(text, integer, integer) is 'Hebrew display name of an official place.';
grant execute on function kc_access.place_name(text, integer, integer) to authenticated;

-- Ids of open rides departing after the cursor, soonest first, with what only the server
-- can count: free seats of an offer, and for a recurring ride the number of later dates
-- folded into this row. Filters: direction, departure before p_before, and a route — the
-- ride's origin or one of its meeting points within p_radius_m of p_origin and its
-- destination within p_radius_m of p_dest. Occurrences of one series beyond tomorrow
-- (Israel time) fold into the soonest of them (D103). The audience test here only keeps
-- pages full; the caller's own row access is the real gate.
create function kc_access.ride_candidates(
  p_direction text,
  p_origin extensions.geography,
  p_dest extensions.geography,
  p_radius_m double precision,
  p_after timestamptz,
  p_after_id uuid,
  p_before timestamptz,
  p_limit integer
)
returns table (post_id uuid, seats_left integer, series_more integer)
language sql
stable
security definer
set search_path = ''
as $$
  with horizon as (
    -- Midnight that starts the day after tomorrow, Israel time.
    select (((now() at time zone 'Asia/Jerusalem')::date + 2)::timestamp at time zone 'Asia/Jerusalem') as at
  )
  select r.post_id,
         case p.direction when 'offer' then greatest(r.seats - kc_private.handoff_seats_taken(r.post_id), 0) end,
         case when r.series_id is not null and r.departs_at >= h.at then
           (select count(*)::integer
              from public.post_ride_details o join public.posts op on op.id = o.post_id
             where o.series_id = r.series_id and o.departs_at > r.departs_at and op.status = 'open')
         else 0 end
    from public.post_ride_details r
    join public.posts p on p.id = r.post_id
   cross join horizon h
   where p.status = 'open'
     and (r.departs_at, r.post_id) > (p_after, p_after_id)
     and (p_before is null or r.departs_at < p_before)
     and (p_direction is null or p.direction = p_direction)
     and (p_dest is null or extensions.st_dwithin(r.dest_point, p_dest, p_radius_m))
     and (p_origin is null
          or extensions.st_dwithin(r.origin_point, p_origin, p_radius_m)
          or exists (select 1 from jsonb_array_elements(r.meeting_points) m
                      where extensions.st_dwithin(
                              extensions.st_setsrid(extensions.st_makepoint(
                                (m ->> 'lng')::float8, (m ->> 'lat')::float8), 4326)::extensions.geography,
                              p_origin, p_radius_m)))
     and (p.owner_id = (select auth.uid())
          or p.visibility = 'Public'
          or (p.visibility = 'FollowersOnly'
              and exists (select 1 from public.follows f
                           where f.follower_id = (select auth.uid()) and f.followed_id = p.owner_id)))
     and (r.series_id is null or r.departs_at < h.at
          or not exists (select 1 from public.post_ride_details o join public.posts op on op.id = o.post_id
                          where o.series_id = r.series_id and o.departs_at >= h.at
                            and o.departs_at < r.departs_at and op.status = 'open'))
   order by r.departs_at, r.post_id
   limit p_limit;
$$;
comment on function kc_access.ride_candidates(
  text, extensions.geography, extensions.geography, double precision, timestamptz, uuid, timestamptz, integer) is
  'Ids of upcoming open rides matching a direction, time window and route, with free seats and folded series dates.';
grant execute on function kc_access.ride_candidates(
  text, extensions.geography, extensions.geography, double precision, timestamptz, uuid, timestamptz, integer)
  to authenticated;

-- One page of the rides feed, soonest departure first. p_filters (every key optional):
--   direction                 'offer' | 'request'
--   origin, dest              an official place each: {city_id, street_id, junction_id};
--                             with either, only rides along that route are returned
--   radius_km                 distance of a ride's ends from the route's ends, default 15
--   departs_after / _before   departure window; the feed never shows a departed ride
-- Keyset on (departs_at, post_id): pass the last row's next_cursor to continue.
--   ride_place_invalid  a route end that is not an official place
create function public.rides_feed(
  p_cursor jsonb default null,
  p_limit integer default 30,
  p_filters jsonb default '{}'::jsonb
)
returns table (
  post_id uuid, owner_id uuid, direction text, title text, departs_at timestamptz, arrives_at timestamptz,
  origin_name text, dest_name text, meeting_points jsonb, seats integer, seats_left integer,
  reward_model text, series_id uuid, series_more integer, next_cursor jsonb)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_f constant jsonb := coalesce(p_filters, '{}'::jsonb);
  v_origin extensions.geography;
  v_dest extensions.geography;
begin
  select kc_access.place_point(o.city_id, o.street_id, o.junction_id) into v_origin
    from jsonb_to_record(v_f -> 'origin') as o (city_id text, street_id integer, junction_id integer);
  select kc_access.place_point(d.city_id, d.street_id, d.junction_id) into v_dest
    from jsonb_to_record(v_f -> 'dest') as d (city_id text, street_id integer, junction_id integer);
  if (v_f ? 'origin' and v_origin is null) or (v_f ? 'dest' and v_dest is null) then
    raise exception 'ride_place_invalid' using errcode = 'P0001';
  end if;

  return query
  select p.id, p.owner_id, p.direction, p.title, r.departs_at, r.arrives_at,
         kc_access.place_name(r.origin_city_id, r.origin_street_id, r.origin_junction_id),
         kc_access.place_name(r.dest_city_id, r.dest_street_id, r.dest_junction_id),
         r.meeting_points, r.seats::integer, c.seats_left, r.reward_model, r.series_id, c.series_more,
         jsonb_build_object('t', r.departs_at, 'id', p.id)
    from kc_access.ride_candidates(
           v_f ->> 'direction', v_origin, v_dest,
           least(greatest(coalesce((v_f ->> 'radius_km')::double precision, 15), 1), 100) * 1000,
           greatest(now(), coalesce((p_cursor ->> 't')::timestamptz, (v_f ->> 'departs_after')::timestamptz, now())),
           coalesce((p_cursor ->> 'id')::uuid, '00000000-0000-0000-0000-000000000000'),
           (v_f ->> 'departs_before')::timestamptz,
           least(greatest(coalesce(p_limit, 30), 1), 100)) c
    join public.posts p on p.id = c.post_id
    join public.post_ride_details r on r.post_id = c.post_id
   order by r.departs_at, p.id;
end;
$$;
comment on function public.rides_feed(jsonb, integer, jsonb) is
  'One page of upcoming rides the caller can read, soonest first, optionally along a route.';
grant execute on function public.rides_feed(jsonb, integer, jsonb) to authenticated;

-- >>> supabase/schemas/70_worlds/070_ride_series_rpcs.sql
-- Worlds · recurring rides: create, reschedule, pause / resume / cancel, materialise (D103)
--
-- Occurrences are ordinary ride posts created through kc_private.post_create
-- (160_world_post_create.sql) in the role `system`, so they do not count against the
-- owner's open-post limit at publish time and pass every rule of a ride. Errors: SQLSTATE
-- P0001 — ride_series_not_found, ride_series_schedule_invalid, ride_series_no_occurrence,
-- and whatever a ride itself refuses (ride_place_invalid, declaration_required, …).

-- Publishes the occurrence of a series on one day, unless that day is not a ride day, its
-- departure already passed, or the occurrence exists. Returns the number created (0 or 1).
create function kc_private.ride_series_materialize_day(p_series public.ride_series, p_on date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_departs constant timestamptz := (p_on + p_series.depart_time) at time zone 'Asia/Jerusalem';
begin
  if (p_series.weekdays & (1 << extract(dow from p_on)::integer)) = 0 or v_departs <= now()
     or exists (select 1 from public.post_ride_details r
                 where r.series_id = p_series.id and r.series_on = p_on) then
    return 0;
  end if;
  perform kc_private.post_create(
    p_series.owner_id,
    p_series.post_template || jsonb_build_object('post_type', 'ride'),
    p_series.ride_template || jsonb_build_object(
      'departs_at', v_departs,
      'arrives_at', v_departs + make_interval(mins => p_series.duration_minutes),
      'series_id', p_series.id, 'series_on', p_on),
    'system');
  return 1;
exception when unique_violation then
  return 0;  -- a concurrent run published this day first
end;
$$;
comment on function kc_private.ride_series_materialize_day(public.ride_series, date) is
  'Publishes one occurrence of a recurring ride; idempotent per series and day.';

-- Publishes the missing occurrences of active series — one series, or all of them — from
-- today to 30 days ahead (Israel dates). A series whose owner's account is not active is
-- skipped until it is. Run by the scheduler and by the series RPCs.
create function kc_private.ride_series_materialize(p_series_id uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_today constant date := (now() at time zone 'Asia/Jerusalem')::date;
  v_series public.ride_series;
  v_count integer := 0;
begin
  for v_series in
    select s.* from public.ride_series s
      join public.users u on u.id = s.owner_id and u.is_active
     where s.status = 'active' and (p_series_id is null or s.id = p_series_id)
     order by s.created_at
  loop
    select v_count + coalesce(sum(kc_private.ride_series_materialize_day(v_series, d.day::date)), 0)
      into v_count
      from generate_series(greatest(v_series.starts_on, v_today),
                           least(coalesce(v_series.ends_on, v_today + 30), v_today + 30),
                           interval '1 day') as d (day);
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.ride_series_materialize(uuid) is
  'Publishes the missing occurrences of active recurring rides for the next 30 days; returns how many.';

-- Removes the upcoming occurrences of a series that nobody booked. A ride somebody booked
-- (in any state but cancelled) stays: it is an agreed ride (D103).
create function kc_private.ride_series_drop_unbooked(p_series_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.posts p
   using public.post_ride_details r
   where r.post_id = p.id and r.series_id = p_series_id and r.departs_at > now()
     and p.status in ('open', 'paused')
     and not exists (select 1 from public.post_handoffs h where h.post_id = p.id and h.status <> 'cancelled');
$$;
comment on function kc_private.ride_series_drop_unbooked(uuid) is
  'Deletes the upcoming, never-booked occurrences of a recurring ride.';

-- Locks a series of the caller; one error for "no such series" and "not yours".
create function kc_private.ride_series_lock(p_series_id uuid)
returns public.ride_series
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_series public.ride_series;
begin
  select s.* into v_series from public.ride_series s
   where s.id = p_series_id and s.owner_id = v_user_id for update;
  if not found then
    raise exception 'ride_series_not_found' using errcode = 'P0001';
  end if;
  return v_series;
end;
$$;
comment on function kc_private.ride_series_lock(uuid) is 'Row-locks a recurring ride owned by the caller.';

-- Creates a recurring ride and publishes its occurrences. p_post and p_ride are the
-- payloads of public.create_post_with_details for one ride, without departure and arrival.
-- The first occurrence proves the template: a series that publishes nothing is refused.
create function public.create_ride_series(
  p_post jsonb, p_ride jsonb, p_depart_time time, p_weekdays integer,
  p_duration_minutes integer default null, p_ends_on date default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_series_id uuid;
begin
  begin
    insert into public.ride_series (
      owner_id, post_template, ride_template, depart_time, weekdays, duration_minutes, ends_on)
    values (
      v_user_id, p_post - 'id' - 'status', p_ride - 'departs_at' - 'arrives_at' - 'series_id' - 'series_on',
      p_depart_time, p_weekdays, p_duration_minutes, p_ends_on)
    returning id into v_series_id;
  exception when check_violation or not_null_violation then
    raise exception 'ride_series_schedule_invalid' using errcode = 'P0001';
  end;
  if kc_private.ride_series_materialize(v_series_id) = 0 then
    raise exception 'ride_series_no_occurrence' using errcode = 'P0001';
  end if;
  return v_series_id;
end;
$$;
comment on function public.create_ride_series(jsonb, jsonb, time, integer, integer, date) is
  'Creates a recurring ride for the caller and publishes its occurrences for the next 30 days.';
grant execute on function public.create_ride_series(jsonb, jsonb, time, integer, integer, date) to authenticated;

-- Changes the schedule of a series. The route is not editable (publish a new series):
-- upcoming unbooked occurrences are replaced by the new schedule, booked ones stay.
create function public.update_ride_series(
  p_series_id uuid, p_depart_time time, p_weekdays integer,
  p_duration_minutes integer default null, p_ends_on date default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_series constant public.ride_series := kc_private.ride_series_lock(p_series_id);
begin
  if v_series.status = 'cancelled' then
    raise exception 'ride_series_not_found' using errcode = 'P0001';
  end if;
  begin
    update public.ride_series s
       set depart_time = p_depart_time, weekdays = p_weekdays,
           duration_minutes = p_duration_minutes, ends_on = p_ends_on
     where s.id = p_series_id;
  exception when check_violation or not_null_violation then
    raise exception 'ride_series_schedule_invalid' using errcode = 'P0001';
  end;
  perform kc_private.ride_series_drop_unbooked(p_series_id);
  perform kc_private.ride_series_materialize(p_series_id);
end;
$$;
comment on function public.update_ride_series(uuid, time, integer, integer, date) is
  'Reschedules a recurring ride: unbooked upcoming occurrences follow the new schedule.';
grant execute on function public.update_ride_series(uuid, time, integer, integer, date) to authenticated;

-- Pauses, resumes or cancels a series (machine `ride_series`). Pausing and cancelling
-- remove the upcoming unbooked occurrences; cancelling is terminal and detaches the rides
-- that stay, which live on as one-off rides; resuming publishes the next 30 days again.
create function public.set_ride_series_status(p_series_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_series constant public.ride_series := kc_private.ride_series_lock(p_series_id);
begin
  if p_status = v_series.status then
    return;
  end if;
  update public.ride_series s set status = p_status where s.id = p_series_id;
  if p_status = 'active' then
    perform kc_private.ride_series_materialize(p_series_id);
    return;
  end if;
  perform kc_private.ride_series_drop_unbooked(p_series_id);
  if p_status = 'cancelled' then
    update public.post_ride_details r set series_id = null where r.series_id = p_series_id;
  end if;
end;
$$;
comment on function public.set_ride_series_status(uuid, text) is
  'Pauses, resumes or cancels a recurring ride of the caller.';
grant execute on function public.set_ride_series_status(uuid, text) to authenticated;

-- >>> supabase/schemas/70_worlds/080_post_emergencies.sql
-- Worlds · post_emergencies (the emergency button of a ride or a stay)
--
-- A member taking part in an active ride (spec 5.3 step 6) or stay (FR-HOUSING-024) calls
-- for help. The call is recorded, everyone else taking part is notified at once, and the
-- safety team is told through a `moderation` event. KC is not an emergency service: the
-- app shows the emergency numbers first; this is the record and the alert.

create table public.post_emergencies (
  id          uuid primary key default gen_random_uuid(),
  post_id     uuid not null references public.posts (id) on delete cascade,
  reporter_id uuid not null references public.users (id) on delete cascade,
  note        text check (char_length(note) <= 500),
  -- Where the caller was, when they chose to share it.
  location    extensions.geography(Point, 4326),
  created_at  timestamptz not null default now()
);
comment on table public.post_emergencies is
  'Emergency calls made from an active ride or stay. Written only by server code.';

-- Calls of a post, newest first; covers the post foreign key.
create index post_emergencies_post_recent_idx on public.post_emergencies (post_id, created_at desc);
-- Throttle of a caller, and the reporter foreign key.
create index post_emergencies_reporter_recent_idx on public.post_emergencies (reporter_id, created_at desc);

alter table public.post_emergencies enable row level security;
alter table public.post_emergencies force row level security;

-- The caller and the owner of the post see that a call was made. Extension point: the
-- moderation module adds the policy that lets the safety team read every call.
create policy post_emergencies_select_party on public.post_emergencies
  for select to authenticated
  using (reporter_id = (select auth.uid())
         or exists (select 1 from public.posts p
                     where p.id = post_emergencies.post_id and p.owner_id = (select auth.uid())));

-- Existence only: the note and the location are for the safety team (FR-HOUSING-024 AC3).
grant select (id, post_id, reporter_id, created_at) on public.post_emergencies to authenticated;

-- Members taking part in a post right now, for the emergency call:
--   ride   the driver and every passenger with an approved or completed booking, from one
--          hour before departure until two hours after the estimated end (six hours after
--          departure when no end was stated)
--   stay   the host and every guest whose approved or completed booking is under way,
--          from one hour before its start until two hours after its end
create function kc_private.post_active_participants(p_post_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.owner_id
    from public.posts p
    join public.post_ride_details r on r.post_id = p.id
   where p.id = p_post_id
     and now() between r.departs_at - interval '1 hour'
                   and coalesce(r.arrives_at, r.departs_at + interval '6 hours') + interval '2 hours'
  union
  select h.recipient_id
    from public.post_handoffs h
    join public.post_ride_details r on r.post_id = h.post_id
   where h.post_id = p_post_id and h.status in ('confirmed', 'handed_over')
     and now() between r.departs_at - interval '1 hour'
                   and coalesce(r.arrives_at, r.departs_at + interval '6 hours') + interval '2 hours'
  union
  select unnest(array[h.owner_id, h.recipient_id])
    from public.post_handoffs h
   where h.post_id = p_post_id and h.machine_id = 'housing_booking'
     and h.status in ('confirmed', 'handed_over')
     and now() between h.slot_starts_at - interval '1 hour' and h.slot_ends_at + interval '2 hours';
$$;
comment on function kc_private.post_active_participants(uuid) is
  'Members of a ride or stay that is under way: who may call for help and who is alerted.';

-- Records an emergency call and alerts the other participants and the safety team.
--   emergency_not_active  the caller takes no part in the post, or it is not under way
--                         (one answer for both, so a post is not probed)
--   emergency_throttled   the caller already called on this post in the last five minutes
create function public.report_post_emergency(
  p_post_id uuid, p_note text default null,
  p_lat double precision default null, p_lng double precision default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_participants constant uuid[] := array(select kc_private.post_active_participants(p_post_id));
  v_emergency_id uuid;
  v_to uuid;
begin
  if not v_user_id = any (v_participants) then
    raise exception 'emergency_not_active' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.post_emergencies e
              where e.post_id = p_post_id and e.reporter_id = v_user_id
                and e.created_at > now() - interval '5 minutes') then
    raise exception 'emergency_throttled' using errcode = 'P0001';
  end if;

  insert into public.post_emergencies (post_id, reporter_id, note, location)
  values (p_post_id, v_user_id, nullif(btrim(p_note), ''),
          extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography)
  returning id into v_emergency_id;

  foreach v_to in array v_participants loop
    continue when v_to = v_user_id;
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'post_emergency', 'recipient_id', v_to, 'actor_id', v_user_id,
      'entity', jsonb_build_object('type', 'post', 'id', p_post_id),
      'data', jsonb_build_object(
        'emergency_id', v_emergency_id,
        'dedupe_key', 'post_emergency:' || v_emergency_id || ':' || v_to)));
  end loop;
  -- The safety team (support, super admins) is alerted by the moderation module.
  perform kc_private.outbox_enqueue('moderation', jsonb_build_object(
    'kind', 'post_emergency', 'emergency_id', v_emergency_id, 'post_id', p_post_id,
    'reporter_id', v_user_id));
  return v_emergency_id;
end;
$$;
comment on function public.report_post_emergency(uuid, text, double precision, double precision) is
  'The caller, taking part in an active ride or stay, calls for help; the other participants and the safety team are alerted.';
grant execute on function public.report_post_emergency(uuid, text, double precision, double precision)
  to authenticated;

-- >>> supabase/schemas/70_worlds/100_post_housing_details.sql
-- Worlds · post_housing_details (the stay offered by a post of type `housing_stay`)
--
-- The public, bookable side of a stay offer (FR-HOUSING-005, FR-HOUSING-011): what the
-- booking engine constrains — capacity per night, nights per booking, check-in times,
-- availability and blackout dates. Descriptive fields (amenities, accessibility, house
-- rules) stay in `posts.details`. The exact address is never here: it lives in
-- post_private_locations and reaches a guest only once their booking is approved (S53).

create table public.post_housing_details (
  post_id            uuid primary key references public.posts (id) on delete cascade,
  place_type         text not null check (place_type in (
                       'private_room', 'shared_room', 'couch', 'whole_unit', 'secondary_unit', 'tent_pitch')),
  -- Guests the place sleeps on one night, over all bookings of that night.
  capacity           smallint not null check (capacity between 1 and 20),
  -- One booking per night, whatever its size.
  exclusive          boolean not null default false,
  min_nights         smallint not null default 1,
  max_nights         smallint not null default 3,
  -- Israel local times. A check-in that ends after midnight is written as an earlier time
  -- than check_in_from (for example 16:00 to 01:00).
  check_in_from      time not null default '16:00',
  check_in_until     time not null default '22:00',
  check_out_by       time not null default '10:00',
  children_ok        boolean not null default false,
  pets_ok            boolean not null default false,
  -- Availability (FR-HOUSING-011): a window of dates, and / or only some weekdays (bit 0 =
  -- Sunday, the night that starts on that day). All null = ongoing.
  available_from     date,
  available_until    date,
  available_weekdays smallint check (available_weekdays between 1 and 127),
  -- Single nights the host blocked.
  blackout_dates     date[] not null default '{}' check (coalesce(array_length(blackout_dates, 1), 0) <= 60),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  -- Community stays last 1 to 30 nights (D120).
  constraint post_housing_details_nights_chk check (min_nights >= 1 and max_nights >= min_nights and max_nights <= 30),
  constraint post_housing_details_window_chk check (available_until >= available_from),
  -- A shared room or a couch is never exclusive (FR-HOUSING-005 AC2).
  constraint post_housing_details_shared_chk check (not (exclusive and place_type in ('shared_room', 'couch')))
);
comment on table public.post_housing_details is
  'Bookable terms of a stay offer: capacity, nights, check-in times, availability. The address is in post_private_locations.';

-- Stay search by date: offers whose window covers the dates asked for.
create index post_housing_details_window_idx on public.post_housing_details (available_from, available_until);

-- Rules of a stay offer on every write:
--   post      a stay offer (post_details_mismatch)
--   host      on creation, a verified identity where the world asks for one and the
--             current code of conduct (verification_required, housing_conduct_required)
--   capacity  never below the guests of an approved booking on any night ahead
--             (housing_active_booking_conflict, FR-HOUSING-035 AC3)
--   post      an offer with a closing date expires when that date ends (FR-HOUSING-011 AC5)
create function kc_private.post_housing_details_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_for_details(new.post_id, 'housing_stay');
begin
  if v_post.direction <> 'offer' then
    raise exception 'post_details_mismatch' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT' then
    perform kc_private.housing_assert_eligible(v_post.owner_id, v_post.world_slug);
  elsif (new.capacity < old.capacity or (new.exclusive and not old.exclusive))
        and exists (
          select 1 from public.post_handoffs h
            join public.handoff_booking_details d on d.handoff_id = h.id
           cross join lateral generate_series(d.check_in_date, d.check_out_date - 1, interval '1 day') n (night)
           where h.post_id = new.post_id and h.status = 'confirmed'
           group by n.night
          having sum(h.seats) > new.capacity or (new.exclusive and count(*) > 1)) then
    raise exception 'housing_active_booking_conflict' using errcode = 'P0001';
  end if;

  update public.posts p
     set expires_at = ((new.available_until + 1)::timestamp at time zone 'Asia/Jerusalem')
   where p.id = new.post_id;
  return new;
end;
$$;
comment on function kc_private.post_housing_details_prepare() is
  'BEFORE INSERT OR UPDATE on post_housing_details: stay offer, eligible host, capacity against bookings, post expiry.';

-- Raises unless the member may host or book in the housing world: a verified identity
-- where the world requires one (D30, D116) and the current code of conduct (S59).
create function kc_private.housing_assert_eligible(p_user_id uuid, p_world_slug text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform kc_private.world_assert_verified(p_user_id, p_world_slug);
  if not kc_private.world_consent_accepted(p_user_id, 'housing_conduct') then
    raise exception 'housing_conduct_required' using errcode = 'P0001';
  end if;
end;
$$;
comment on function kc_private.housing_assert_eligible(uuid, text) is
  'Raises verification_required or housing_conduct_required unless the member may host or book.';

create trigger post_housing_details_prepare
  before insert or update on public.post_housing_details
  for each row execute function kc_private.post_housing_details_prepare();

create trigger post_housing_details_set_updated_at
  before update on public.post_housing_details
  for each row execute function kc_private.set_updated_at();

alter table public.post_housing_details enable row level security;
alter table public.post_housing_details force row level security;

-- Visible exactly when the post is.
create policy post_housing_details_select_visible on public.post_housing_details
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_housing_details.post_id));

-- The host edits the terms while the post's content is editable.
create policy post_housing_details_update_owner on public.post_housing_details
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_housing_details.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_housing_details.post_id and p.owner_id = (select auth.uid())));

grant select on public.post_housing_details to authenticated;
grant update (
  place_type, capacity, exclusive, min_nights, max_nights, check_in_from, check_in_until, check_out_by,
  children_ok, pets_ok, available_from, available_until, available_weekdays, blackout_dates
) on public.post_housing_details to authenticated;

-- Raises unless a party of p_party can stay every night from p_check_in to the night
-- before p_check_out: each night is open (inside the window, on an offered weekday, not
-- blacked out — housing_dates_unavailable) and has room beside the approved and completed
-- bookings of that night, p_exclude aside (housing_capacity_exceeded). The caller holds
-- the post row lock, so two approvals cannot both take the last bed.
create function kc_private.housing_assert_bookable(
  p_stay public.post_housing_details, p_check_in date, p_check_out date, p_party integer, p_exclude uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_night record;
begin
  for v_night in
    select n.night::date as night,
           (select coalesce(sum(h.seats), 0)
              from public.post_handoffs h
              join public.handoff_booking_details d on d.handoff_id = h.id
             where h.post_id = p_stay.post_id and h.status in ('confirmed', 'handed_over')
               and h.id is distinct from p_exclude
               and d.check_in_date <= n.night and d.check_out_date > n.night) as taken
      from generate_series(p_check_in, p_check_out - 1, interval '1 day') n (night)
  loop
    if v_night.night < p_stay.available_from or v_night.night > p_stay.available_until
       or (p_stay.available_weekdays & (1 << extract(dow from v_night.night)::integer)) = 0
       or v_night.night = any (p_stay.blackout_dates) then
      raise exception 'housing_dates_unavailable' using errcode = 'P0001';
    end if;
    if (p_stay.exclusive and v_night.taken > 0) or v_night.taken + p_party > p_stay.capacity then
      raise exception 'housing_capacity_exceeded' using errcode = 'P0001';
    end if;
  end loop;
end;
$$;
comment on function kc_private.housing_assert_bookable(public.post_housing_details, date, date, integer, uuid) is
  'Checks availability and per-night capacity of a stay for a party and a date range.';

-- >>> supabase/schemas/70_worlds/110_housing_bookings.sql
-- Worlds · stay bookings (machine `housing_booking` on post_handoffs + handoff_booking_details)
--
-- request → the host approves or declines → the stay → the host completes it or reports a
-- guest who did not arrive (FR-HOUSING-015 … 020). Overlap protection is a locked check,
-- not an exclusion constraint: capacity is a sum of guests per night, which no constraint
-- can express. Two locks serialize the writers — the post row for the place (capacity per
-- night) and an advisory lock per guest (pending cap, no two overlapping stays) — always
-- taken guest first, post second. Errors: SQLSTATE P0001 — listing_not_available,
-- own_listing, item_already_reserved, verification_required, housing_conduct_required,
-- housing_dates_invalid, housing_dates_unavailable, housing_nights_out_of_range,
-- housing_capacity_exceeded, housing_policy_mismatch, housing_minor_unaccompanied,
-- housing_message_required, housing_pending_cap, housing_booking_overlap,
-- housing_note_too_long, housing_booking_started, housing_cancel_reason_required,
-- housing_not_in_window, handoff_not_found, invalid_status.

-- Serializes everything that depends on the set of one guest's stay bookings.
create function kc_private.housing_guest_lock(p_guest_id uuid)
returns void
language sql
set search_path = ''
as $$
  select pg_advisory_xact_lock(hashtextextended('housing_guest:' || p_guest_id, 0));
$$;
comment on function kc_private.housing_guest_lock(uuid) is
  'Transaction-scoped lock on one guest''s stay bookings.';

-- Does the guest hold an approved or completed stay that overlaps the dates (FR-HOUSING-015 AC4)?
create function kc_private.housing_guest_has_overlap(p_guest_id uuid, p_check_in date, p_check_out date)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.post_handoffs h
      join public.handoff_booking_details d on d.handoff_id = h.id
     where h.recipient_id = p_guest_id and h.machine_id = 'housing_booking'
       and h.status in ('confirmed', 'handed_over')
       and d.check_in_date < p_check_out and d.check_out_date > p_check_in);
$$;
comment on function kc_private.housing_guest_has_overlap(uuid, date, date) is
  'The guest already holds an approved stay overlapping the dates.';

-- A verified guest who accepted the code of conduct asks to stay. The request waits for
-- the host and lapses 24 hours after it was made or at the end of the check-in time of
-- its first day, whichever is earlier (S52). A guest holds at most three waiting requests.
create function public.request_housing_booking(
  p_post_id uuid, p_check_in date, p_check_out date, p_adults integer, p_minors integer default 0,
  p_message text default null, p_minors_guardian_ack boolean default false)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_today constant date := (now() at time zone 'Asia/Jerusalem')::date;
  v_party constant integer := coalesce(p_adults, 0) + coalesce(p_minors, 0);
  v_post public.posts;
  v_stay public.post_housing_details;
  v_deadline timestamptz;
  v_handoff public.post_handoffs;
begin
  perform kc_private.housing_guest_lock(v_user_id);
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  select s.* into v_stay from public.post_housing_details s where s.post_id = p_post_id;
  if not found or not kc_private.post_bookable_by(v_post, v_user_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  perform kc_private.housing_assert_eligible(v_user_id, v_post.world_slug);

  -- Last moment to arrive on the first day; a check-in that ends after midnight belongs
  -- to the next calendar day.
  v_deadline := (p_check_in + (v_stay.check_in_until <= v_stay.check_in_from)::integer + v_stay.check_in_until)
                at time zone 'Asia/Jerusalem';
  if p_check_in is null or p_check_out is null or p_check_in < v_today or p_check_in > v_today + 180
     or now() > v_deadline then
    raise exception 'housing_dates_invalid' using errcode = 'P0001';
  end if;
  if p_check_out - p_check_in not between v_stay.min_nights and v_stay.max_nights then
    raise exception 'housing_nights_out_of_range' using errcode = 'P0001';
  end if;
  if coalesce(p_adults, 0) < 1 or coalesce(p_minors, 0) < 0 or v_party > 8 then
    raise exception 'housing_capacity_exceeded' using errcode = 'P0001';
  end if;
  if p_minors > 0 and not v_stay.children_ok then
    raise exception 'housing_policy_mismatch' using errcode = 'P0001';
  end if;
  if p_minors > 0 and not coalesce(p_minors_guardian_ack, false) then
    raise exception 'housing_minor_unaccompanied' using errcode = 'P0001';
  end if;
  if char_length(btrim(coalesce(p_message, ''))) not between 1 and 500 then
    raise exception 'housing_message_required' using errcode = 'P0001';
  end if;
  if (select count(*) from public.post_handoffs h
       where h.recipient_id = v_user_id and h.machine_id = 'housing_booking' and h.status = 'reserved') >= 3 then
    raise exception 'housing_pending_cap' using errcode = 'P0001';
  end if;
  if kc_private.housing_guest_has_overlap(v_user_id, p_check_in, p_check_out) then
    raise exception 'housing_booking_overlap' using errcode = 'P0001';
  end if;
  perform kc_private.housing_assert_bookable(v_stay, p_check_in, p_check_out, v_party, null);

  -- Capacity is per night and was checked above, so no post-wide limit is passed.
  v_handoff := kc_private.handoff_open(
    p_post_id, v_user_id, 'reserved', null, v_party,
    jsonb_build_object(
      'slot_starts_at', (p_check_in + v_stay.check_in_from) at time zone 'Asia/Jerusalem',
      'slot_ends_at', (p_check_out + v_stay.check_out_by) at time zone 'Asia/Jerusalem',
      'confirm_by', least(now() + interval '24 hours', v_deadline)));
  insert into public.handoff_booking_details (
    handoff_id, check_in_date, check_out_date, adults, minors, message, minors_guardian_ack)
  values (v_handoff.id, p_check_in, p_check_out, p_adults, coalesce(p_minors, 0), btrim(p_message),
          coalesce(p_minors_guardian_ack, false));
  return v_handoff;
end;
$$;
comment on function public.request_housing_booking(uuid, date, date, integer, integer, text, boolean) is
  'The caller asks to stay at a stay offer for a date range; the host approves within 24 hours.';
grant execute on function public.request_housing_booking(uuid, date, date, integer, integer, text, boolean)
  to authenticated;

-- The host approves or declines a waiting request, with an optional note to the guest.
-- Approval re-checks both members and the nights under the locks, then withdraws the
-- guest's other waiting requests that overlap it (`superseded`, S54).
create function public.decide_housing_booking(p_handoff_id uuid, p_approve boolean, p_note text default null)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs;
  v_post public.posts;
  v_stay public.post_housing_details;
  v_booking public.handoff_booking_details;
  v_other uuid;
begin
  perform kc_private.housing_guest_lock(
    (select h.recipient_id from public.post_handoffs h where h.id = p_handoff_id));
  v_handoff := kc_private.world_handoff_lock(p_handoff_id, 'housing_booking', true);
  if v_handoff.status <> 'reserved' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if char_length(p_note) > 300 then
    raise exception 'housing_note_too_long' using errcode = 'P0001';
  end if;
  update public.handoff_booking_details d set decision_note = nullif(btrim(p_note), '')
   where d.handoff_id = p_handoff_id
  returning d.* into v_booking;
  if not coalesce(p_approve, false) then
    return kc_private.handoff_move(p_handoff_id, 'cancelled', 'owner', 'declined');
  end if;

  select p.* into v_post from public.posts p where p.id = v_handoff.post_id;
  select s.* into v_stay from public.post_housing_details s where s.post_id = v_handoff.post_id;
  if v_post.status <> 'open' then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  perform kc_private.housing_assert_eligible(v_handoff.owner_id, v_post.world_slug);
  perform kc_private.housing_assert_eligible(v_handoff.recipient_id, v_post.world_slug);
  if kc_private.housing_guest_has_overlap(v_handoff.recipient_id, v_booking.check_in_date, v_booking.check_out_date) then
    raise exception 'housing_booking_overlap' using errcode = 'P0001';
  end if;
  perform kc_private.housing_assert_bookable(
    v_stay, v_booking.check_in_date, v_booking.check_out_date, v_handoff.seats, p_handoff_id);
  v_handoff := kc_private.handoff_move(p_handoff_id, 'confirmed', 'owner');

  for v_other in
    select h.id from public.post_handoffs h
      join public.handoff_booking_details d on d.handoff_id = h.id
     where h.recipient_id = v_handoff.recipient_id and h.machine_id = 'housing_booking'
       and h.status = 'reserved'
       and d.check_in_date < v_booking.check_out_date and d.check_out_date > v_booking.check_in_date
  loop
    perform kc_private.handoff_move(v_other, 'cancelled', 'system', 'superseded');
  end loop;
  return v_handoff;
end;
$$;
comment on function public.decide_housing_booking(uuid, boolean, text) is
  'The host approves or declines a stay request; an approval withdraws the guest''s overlapping requests.';
grant execute on function public.decide_housing_booking(uuid, boolean, text) to authenticated;

-- Either side cancels before the stay starts (FR-HOUSING-018). A host cancelling an
-- approved stay must say why. A late cancellation of an approved stay — a guest inside
-- 24 hours of the start, a host inside 48 — is flagged for the trust engine, never shown.
create function public.cancel_housing_booking(p_handoff_id uuid, p_note text default null)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff constant public.post_handoffs :=
    kc_private.world_handoff_lock(p_handoff_id, 'housing_booking', false, false);
  v_by_host constant boolean := v_handoff.owner_id = (select auth.uid());
  v_note constant text := nullif(btrim(p_note), '');
begin
  if v_handoff.status not in ('reserved', 'confirmed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if char_length(v_note) > 300 then
    raise exception 'housing_note_too_long' using errcode = 'P0001';
  end if;
  -- After check-in a stay is ended by completing it, not cancelled (FR-HOUSING-018 AC4).
  if now() >= v_handoff.slot_starts_at then
    raise exception 'housing_booking_started' using errcode = 'P0001';
  end if;
  if v_by_host and v_handoff.status = 'confirmed' and v_note is null then
    raise exception 'housing_cancel_reason_required' using errcode = 'P0001';
  end if;

  update public.handoff_booking_details d
     set cancel_note = v_note,
         late_cancel = v_handoff.status = 'confirmed' and now() > v_handoff.slot_starts_at
           - case when v_by_host then interval '48 hours' else interval '24 hours' end
   where d.handoff_id = p_handoff_id;
  return kc_private.handoff_move(
    p_handoff_id, 'cancelled',
    case when v_by_host then 'owner' else 'recipient' end,
    case when not v_by_host then 'guest_cancelled'
         when v_handoff.status = 'reserved' then 'declined'
         else 'host_cancelled' end);
end;
$$;
comment on function public.cancel_housing_booking(uuid, text) is
  'Either side cancels a stay booking before it starts; late cancellations of approved stays are flagged.';
grant execute on function public.cancel_housing_booking(uuid, text) to authenticated;

-- The host closes an approved stay: completed (from check-in until seven days after the
-- end, FR-HOUSING-019 AC2) or the guest did not arrive (from three to twenty-four hours
-- after check-in, FR-HOUSING-020 AC1). A stay offer serves many bookings, so the post
-- stays open.
create function public.close_housing_booking(p_handoff_id uuid, p_outcome text)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff constant public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'housing_booking', true);
begin
  if v_handoff.status <> 'confirmed' or p_outcome is null or p_outcome not in ('completed', 'no_show') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if not (case p_outcome
       when 'completed' then now() between v_handoff.slot_starts_at and v_handoff.slot_ends_at + interval '7 days'
       else now() between v_handoff.slot_starts_at + interval '3 hours'
                      and v_handoff.slot_starts_at + interval '24 hours'
     end) then
    raise exception 'housing_not_in_window' using errcode = 'P0001';
  end if;
  return kc_private.handoff_move(
    p_handoff_id, case p_outcome when 'completed' then 'handed_over' else 'no_show' end, 'owner');
end;
$$;
comment on function public.close_housing_booking(uuid, text) is
  'The host marks an approved stay as completed or as a no-show, each inside its time window.';
grant execute on function public.close_housing_booking(uuid, text) to authenticated;

-- >>> supabase/schemas/70_worlds/120_post_event_details.sql
-- Worlds · post_event_details (the event behind a post of type `event`, G18)
--
-- An event is a post with a time window, an optional capacity and a registration policy.
-- A volunteering shift is an event too (design §12 Q3): an opportunity with several shifts
-- is several event posts, one per shift, because capacity, the waiting list, attendance
-- and expiry (D128) all belong to one time window. Extension point: the organizations
-- module restricts who may publish an event for an organization (posts.beneficiary_org_id).

create table public.post_event_details (
  post_id                uuid primary key references public.posts (id) on delete cascade,
  starts_at              timestamptz not null,
  ends_at                timestamptz not null,
  -- Places; null = unlimited. A full event puts new registrations on the waiting list.
  capacity               integer check (capacity between 1 and 5000),
  -- automatic: registered at once · manual: the organizer approves each registration ·
  -- verified_only: automatic, for members with a verified identity.
  registration_policy    text not null default 'automatic'
                           check (registration_policy in ('automatic', 'manual', 'verified_only')),
  -- Where the event takes place, as shown to everyone who can see the post.
  address_label          text check (char_length(btrim(address_label)) between 2 and 160),
  -- A volunteering shift: attendance adds the length of the event to the attendee's
  -- volunteering hours (spec 5.4, D32).
  counts_volunteer_hours boolean not null default false,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint post_event_details_window_chk check (ends_at > starts_at)
);
comment on table public.post_event_details is
  'Time window, capacity and registration policy of an event post; volunteering shifts are events.';

-- Upcoming events by start: the events list of the time world and of an organization.
create index post_event_details_starts_idx on public.post_event_details (starts_at, post_id);

-- Moves the head of an event's waiting list into free places, while the event has not
-- started: to `confirmed`, or to `reserved` with the start as its deadline when the
-- organizer approves by hand. Called whenever a place may have become free.
create function kc_private.event_promote_waitlist(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.post_event_details;
begin
  select e.* into v_event from public.post_event_details e where e.post_id = p_post_id;
  if not found or v_event.starts_at <= now() then
    return;
  end if;
  -- Without a capacity nobody waits; the largest capacity stands in for "unlimited".
  perform kc_private.handoff_promote_waitlist(
    p_post_id, coalesce(v_event.capacity, 2147483647),
    case v_event.registration_policy when 'manual' then 'reserved' else 'confirmed' end);
  update public.post_handoffs h set confirm_by = v_event.starts_at
   where h.post_id = p_post_id and h.status = 'reserved' and h.confirm_by is null;
end;
$$;
comment on function kc_private.event_promote_waitlist(uuid) is
  'Promotes waiting registrations of an event that has not started into its free places.';

-- Rules of an event on every write:
--   window    a new event starts in the future and ends after it starts (event_time_invalid)
--   capacity  never below the places already taken (event_capacity_below_registrations)
--   post      its time window and its expiry at the end of the event (D128); the closure
--             rules of a post read the window (D131)
--   bookings  live registrations follow a moved window
create function kc_private.post_event_details_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.post_for_details(new.post_id, 'event');
  if (tg_op = 'INSERT' and new.starts_at <= now()) or new.ends_at <= new.starts_at then
    raise exception 'event_time_invalid' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' and new.capacity < kc_private.handoff_seats_taken(new.post_id) then
    raise exception 'event_capacity_below_registrations' using errcode = 'P0001';
  end if;
  update public.posts p
     set time_window = tstzrange(new.starts_at, new.ends_at), expires_at = new.ends_at
   where p.id = new.post_id;
  if tg_op = 'UPDATE' and (new.starts_at, new.ends_at) is distinct from (old.starts_at, old.ends_at) then
    update public.post_handoffs h
       set slot_starts_at = new.starts_at, slot_ends_at = new.ends_at,
           confirm_by = case when h.status = 'reserved' then new.starts_at end
     where h.post_id = new.post_id and h.status in ('waitlisted', 'reserved', 'confirmed');
  end if;
  return new;
end;
$$;
comment on function kc_private.post_event_details_prepare() is
  'BEFORE INSERT OR UPDATE on post_event_details: start, capacity, the post''s window and expiry, live registrations.';

create trigger post_event_details_prepare
  before insert or update on public.post_event_details
  for each row execute function kc_private.post_event_details_prepare();

-- More places, or no limit any more: the waiting list moves up.
create function kc_private.post_event_details_capacity_raised()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.event_promote_waitlist(new.post_id);
  return null;
end;
$$;

create trigger post_event_details_capacity_raised
  after update of capacity on public.post_event_details
  for each row
  when (new.capacity is null or new.capacity > old.capacity)
  execute function kc_private.post_event_details_capacity_raised();

create trigger post_event_details_set_updated_at
  before update on public.post_event_details
  for each row execute function kc_private.set_updated_at();

alter table public.post_event_details enable row level security;
alter table public.post_event_details force row level security;

-- Visible exactly when the post is.
create policy post_event_details_select_visible on public.post_event_details
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_event_details.post_id));

-- The organizer edits the event while the post's content is editable.
create policy post_event_details_update_owner on public.post_event_details
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_event_details.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_event_details.post_id and p.owner_id = (select auth.uid())));

grant select on public.post_event_details to authenticated;
grant update (starts_at, ends_at, capacity, registration_policy, address_label, counts_volunteer_hours)
  on public.post_event_details to authenticated;

-- >>> supabase/schemas/70_worlds/130_event_registrations.sql
-- Worlds · event registrations (machine `event_registration` on post_handoffs, G18)
--
-- register → registered at once, waiting for the organizer, or on the waiting list of a
-- full event; a freed place promotes the list in order of registration; from the start
-- the organizer marks who came. Volunteering shifts use the same flow, and attendance
-- adds their length to the attendee's volunteering hours. Errors: SQLSTATE P0001 —
-- listing_not_available, own_listing, item_already_reserved, slot_started,
-- verification_required, event_not_started, event_message_invalid, post_not_found,
-- handoff_not_found, invalid_status.

-- Registers the caller for an event that has not started. Returns the registration:
-- `waitlisted` when the event is full, `reserved` when the organizer approves by hand
-- (the request lapses at the start), `confirmed` otherwise.
create function public.register_for_event(p_post_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_post public.posts;
  v_event public.post_event_details;
  v_status text;
begin
  -- The post row lock serializes registrations, so the last place is given once.
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  select e.* into v_event from public.post_event_details e where e.post_id = p_post_id;
  if not found or not kc_private.post_bookable_by(v_post, v_user_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  if v_event.starts_at <= now() then
    raise exception 'slot_started' using errcode = 'P0001';
  end if;
  if v_event.registration_policy = 'verified_only'
     and not exists (select 1 from public.users u where u.id = v_user_id and u.verification_level >= 2) then
    raise exception 'verification_required' using errcode = 'P0001';
  end if;

  v_status := case
    when kc_private.handoff_seats_taken(p_post_id) >= v_event.capacity then 'waitlisted'
    when v_event.registration_policy = 'manual' then 'reserved'
    else 'confirmed'
  end;
  return kc_private.handoff_open(
    p_post_id, v_user_id, v_status, v_event.capacity, 1,
    jsonb_strip_nulls(jsonb_build_object(
      'slot_starts_at', v_event.starts_at, 'slot_ends_at', v_event.ends_at,
      'confirm_by', case v_status when 'reserved' then v_event.starts_at end)));
end;
$$;
comment on function public.register_for_event(uuid) is
  'Registers the caller for an event: confirmed, waiting for approval, or on the waiting list when full.';
grant execute on function public.register_for_event(uuid) to authenticated;

-- The organizer approves or declines a registration that waits for them. A declined
-- place goes to the waiting list.
create function public.decide_event_registration(p_handoff_id uuid, p_approve boolean)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'event_registration', true);
begin
  if v_handoff.status <> 'reserved' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if coalesce(p_approve, false) then
    return kc_private.handoff_move(p_handoff_id, 'confirmed', 'owner');
  end if;
  v_handoff := kc_private.handoff_move(p_handoff_id, 'cancelled', 'owner', 'declined');
  perform kc_private.event_promote_waitlist(v_handoff.post_id);
  return v_handoff;
end;
$$;
comment on function public.decide_event_registration(uuid, boolean) is
  'The organizer approves or declines a registration awaiting approval.';
grant execute on function public.decide_event_registration(uuid, boolean) to authenticated;

-- The member leaves an event or its waiting list, or the organizer removes a
-- registration. Before the start, the freed place goes to the waiting list.
create function public.cancel_event_registration(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs :=
    kc_private.world_handoff_lock(p_handoff_id, 'event_registration', false, false);
  v_by_owner constant boolean := v_handoff.owner_id = (select auth.uid());
begin
  if v_handoff.status not in ('waitlisted', 'reserved', 'confirmed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  v_handoff := kc_private.handoff_move(
    p_handoff_id, 'cancelled',
    case when v_by_owner then 'owner' else 'recipient' end,
    case when not v_by_owner then 'recipient_cancelled'
         when v_handoff.status = 'reserved' then 'declined'
         else 'owner_cancelled' end);
  perform kc_private.event_promote_waitlist(v_handoff.post_id);
  return v_handoff;
end;
$$;
comment on function public.cancel_event_registration(uuid) is
  'Cancels an event registration (by its member or the organizer) and promotes the waiting list.';
grant execute on function public.cancel_event_registration(uuid) to authenticated;

-- From the start of the event the organizer marks a confirmed registrant as attended or
-- absent; an absence can be corrected to attended, an attendance is final. Attending a
-- volunteering shift adds the length of the event, in hours, to the attendee's
-- volunteering hours — once, since nothing leaves `handed_over`.
create function public.mark_event_attendance(p_handoff_id uuid, p_attended boolean)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs := kc_private.world_handoff_lock(p_handoff_id, 'event_registration', true);
  v_event public.post_event_details;
begin
  -- The event's own start, not the copy on the registration.
  select e.* into v_event from public.post_event_details e where e.post_id = v_handoff.post_id;
  if not found or v_event.starts_at > now() then
    raise exception 'event_not_started' using errcode = 'P0001';
  end if;
  if p_attended is null
     or not (v_handoff.status = 'confirmed' or (v_handoff.status = 'no_show' and p_attended)) then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if not p_attended then
    return kc_private.handoff_move(p_handoff_id, 'no_show', 'owner');
  end if;

  v_handoff := kc_private.handoff_move(p_handoff_id, 'handed_over', 'owner');
  if v_event.counts_volunteer_hours then
    update public.user_stats s
       set volunteer_hours_total = s.volunteer_hours_total
             + round((extract(epoch from v_event.ends_at - v_event.starts_at) / 3600)::numeric, 2)
     where s.user_id = v_handoff.recipient_id;
  end if;
  return v_handoff;
end;
$$;
comment on function public.mark_event_attendance(uuid, boolean) is
  'The organizer records attendance or absence once the event started; a shift adds volunteering hours.';
grant execute on function public.mark_event_attendance(uuid, boolean) to authenticated;

-- The organizer sends a short message to everyone registered for the event (approved,
-- awaiting approval or waiting for a place). Each member receives a notification; the
-- text travels in the event and is not stored anywhere else. Returns how many were told.
create function public.message_event_registrants(p_post_id uuid, p_body text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
  v_body constant text := btrim(coalesce(p_body, ''));
  v_event_id constant uuid := gen_random_uuid();
  v_to uuid;
  v_count integer := 0;
begin
  if v_post.post_type <> 'event' then
    raise exception 'post_not_found' using errcode = 'P0001';
  end if;
  if char_length(v_body) not between 1 and 500 then
    raise exception 'event_message_invalid' using errcode = 'P0001';
  end if;
  for v_to in
    select h.recipient_id from public.post_handoffs h
     where h.post_id = p_post_id and h.status in ('waitlisted', 'reserved', 'confirmed')
  loop
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'event_organizer_message', 'recipient_id', v_to, 'actor_id', (select auth.uid()),
      'entity', jsonb_build_object('type', 'post', 'id', p_post_id),
      'data', jsonb_build_object(
        'body', v_body, 'dedupe_key', 'event_organizer_message:' || v_event_id || ':' || v_to)));
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function public.message_event_registrants(uuid, text) is
  'The organizer notifies every registered member of an event with a short message.';
grant execute on function public.message_event_registrants(uuid, text) to authenticated;

-- >>> supabase/schemas/70_worlds/140_post_food_details.sql
-- Worlds · post_food_details (what a food offer must state, D21, D28)
--
-- One row per food offer: when the food itself stops being good, what it is and what it
-- contains. The expiry drives the post — it closes by itself at that time and its urgency
-- follows from how close that is. A food request has no row and never expires (D21). The
-- generic claim flow (public.claim_food_giving) hands the food over.

create table public.post_food_details (
  post_id           uuid primary key references public.posts (id) on delete cascade,
  -- Until when the food is good to eat, as stated by the giver.
  expires_at        timestamptz not null,
  food_type         text check (food_type in ('cooked', 'packaged', 'fresh', 'frozen', 'dry', 'beverage')),
  -- Declared allergens; an empty list is the giver's statement that there are none (D28).
  allergens         text[] not null default '{}' check (coalesce(array_length(allergens, 1), 0) <= 20),
  -- Null = not stated.
  kosher            boolean,
  dietary_tags      text[] not null default '{}' check (coalesce(array_length(dietary_tags, 1), 0) <= 20),
  -- When the owner was told the offer is about to expire (S4); set by the sweep.
  expiry_alerted_at timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
comment on table public.post_food_details is
  'Expiry, type and declared contents of a food offer; the expiry closes the post and sets its urgency.';

-- Expiry alert sweep and urgency refresh: offers nearing their expiry, soonest first.
create index post_food_details_expiry_idx on public.post_food_details (expires_at);

-- Urgency of a food offer from its expiry: high inside 72 hours, medium otherwise.
create function kc_private.food_urgency_level(p_expires_at timestamptz)
returns smallint
language sql
stable
set search_path = ''
as $$
  select case when p_expires_at <= now() + interval '72 hours' then 3 else 2 end::smallint;
$$;
comment on function kc_private.food_urgency_level(timestamptz) is
  'Urgency level of a food offer: 3 when it expires within 72 hours, else 2.';

-- Rules of a food offer on every write:
--   post     a food offer (post_details_mismatch)
--   expiry   stated (food_expiry_required) and, when new or changed, in the future
--            (food_expiry_in_past); a moved expiry may be alerted again
--   post     expires with the food; urgency derived from the expiry
create function kc_private.post_food_details_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_for_details(new.post_id, 'standard');
begin
  if v_post.world_slug <> 'food' or v_post.direction <> 'offer' then
    raise exception 'post_details_mismatch' using errcode = 'P0001';
  end if;
  if new.expires_at is null then
    raise exception 'food_expiry_required' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT' or new.expires_at <> old.expires_at then
    if new.expires_at <= now() then
      raise exception 'food_expiry_in_past' using errcode = 'P0001';
    end if;
    new.expiry_alerted_at := null;
  end if;
  update public.posts p
     set expires_at = new.expires_at, urgency_level = kc_private.food_urgency_level(new.expires_at)
   where p.id = new.post_id;
  return new;
end;
$$;
comment on function kc_private.post_food_details_prepare() is
  'BEFORE INSERT OR UPDATE on post_food_details: food offer, stated future expiry, post expiry and urgency.';

create trigger post_food_details_prepare
  before insert or update on public.post_food_details
  for each row execute function kc_private.post_food_details_prepare();

create trigger post_food_details_set_updated_at
  before update on public.post_food_details
  for each row execute function kc_private.set_updated_at();

alter table public.post_food_details enable row level security;
alter table public.post_food_details force row level security;

-- Visible exactly when the post is.
create policy post_food_details_select_visible on public.post_food_details
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_food_details.post_id));

-- The giver edits the details while the post's content is editable.
create policy post_food_details_update_owner on public.post_food_details
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_food_details.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_food_details.post_id and p.owner_id = (select auth.uid())));

-- The alert stamp is the sweep's own bookkeeping and is not readable.
grant select (post_id, expires_at, food_type, allergens, kosher, dietary_tags, created_at, updated_at)
  on public.post_food_details to authenticated;
grant update (expires_at, food_type, allergens, kosher, dietary_tags) on public.post_food_details to authenticated;

-- >>> supabase/schemas/70_worlds/150_post_knowledge_slots.sql
-- Worlds · post_knowledge_slots (bookable times of a lesson or consulting offer, FR-KNOW-004)
--
-- The knowledge world needs one thing the generic flow does not have: several bookable
-- times on one post, each with its own places. Everything else of a knowledge post stays
-- in `posts.details`, and a booking is an ordinary handoff of the giving machine: the
-- giver approves it with public.confirm_item_handoff, either side cancels with
-- public.cancel_giving_handoff, and public.mark_giving_handed_over completes the session.
-- A booking is tied to its slot by (post_id, slot_starts_at): slots of a post never
-- overlap, so the start identifies the slot.

create table public.post_knowledge_slots (
  id         uuid primary key default gen_random_uuid(),
  post_id    uuid not null references public.posts (id) on delete cascade,
  starts_at  timestamptz not null,
  ends_at    timestamptz not null,
  -- Learners per slot.
  capacity   smallint not null default 1 check (capacity between 1 and 20),
  created_at timestamptz not null default now(),
  -- A session lasts 15 minutes to 8 hours.
  constraint post_knowledge_slots_length_chk
    check (ends_at - starts_at between interval '15 minutes' and interval '8 hours'),
  -- Slots of one post never overlap. The constraint's index also serves "slots of a post"
  -- and the post foreign key.
  constraint post_knowledge_slots_no_overlap_excl
    exclude using gist (post_id with =, tstzrange(starts_at, ends_at) with &&)
);
comment on table public.post_knowledge_slots is
  'Bookable times of a knowledge offer, each with its own places; bookings are handoffs keyed by the slot start.';

-- Places of a slot held by waiting, approved and completed bookings.
create function kc_private.knowledge_slot_seats_taken(p_post_id uuid, p_starts_at timestamptz)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(h.seats), 0)::integer
    from public.post_handoffs h
   where h.post_id = p_post_id and h.slot_starts_at = p_starts_at
     and h.status in ('reserved', 'confirmed', 'handed_over');
$$;
comment on function kc_private.knowledge_slot_seats_taken(uuid, timestamptz) is
  'Places of a knowledge slot held by live or completed bookings.';

-- Rules of a slot on every write:
--   post      a knowledge offer (post_details_mismatch); whose, the policies below decide
--   new slot  starts in the future, at most 20 per post (slot_started, knowledge_slots_limit)
--   booked    a slot somebody holds is not moved or removed, and its places are not cut
--             below its bookings (knowledge_slot_has_booking); it leaves with its post
create function kc_private.post_knowledge_slots_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_taken constant integer := case when tg_op <> 'INSERT'
    then kc_private.knowledge_slot_seats_taken(old.post_id, old.starts_at) else 0 end;
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.posts p
                    where p.id = new.post_id and p.world_slug = 'knowledge' and p.direction = 'offer') then
      raise exception 'post_details_mismatch' using errcode = 'P0001';
    end if;
    if new.starts_at <= now() then
      raise exception 'slot_started' using errcode = 'P0001';
    end if;
    if (select count(*) from public.post_knowledge_slots s where s.post_id = new.post_id) >= 20 then
      raise exception 'knowledge_slots_limit' using errcode = 'P0001';
    end if;
  -- When the post itself is being removed its row is already gone, and the slot follows.
  elsif v_taken > 0 and exists (select 1 from public.posts p where p.id = old.post_id)
        and (tg_op = 'DELETE' or (new.starts_at, new.ends_at) is distinct from (old.starts_at, old.ends_at)
             or new.capacity < v_taken) then
    raise exception 'knowledge_slot_has_booking' using errcode = 'P0001';
  end if;
  return case tg_op when 'DELETE' then old else new end;
end;
$$;
comment on function kc_private.post_knowledge_slots_guard() is
  'BEFORE INSERT OR UPDATE OR DELETE on post_knowledge_slots: knowledge offer, future start, slot limit, booked slots stay.';

create trigger post_knowledge_slots_guard
  before insert or update or delete on public.post_knowledge_slots
  for each row execute function kc_private.post_knowledge_slots_guard();

-- The offer expires 30 minutes after its last slot ends (FR-KNOW-003 AC3); an offer
-- without slots does not expire.
create function kc_private.post_knowledge_slots_sync_expiry()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post_id constant uuid := case tg_op when 'DELETE' then old.post_id else new.post_id end;
begin
  update public.posts p
     set expires_at = (select max(s.ends_at) + interval '30 minutes'
                         from public.post_knowledge_slots s where s.post_id = v_post_id)
   where p.id = v_post_id;
  return null;
end;
$$;
comment on function kc_private.post_knowledge_slots_sync_expiry() is
  'AFTER write on post_knowledge_slots: the post expires 30 minutes after its last slot.';

create trigger post_knowledge_slots_sync_expiry
  after insert or delete or update of ends_at on public.post_knowledge_slots
  for each row execute function kc_private.post_knowledge_slots_sync_expiry();

alter table public.post_knowledge_slots enable row level security;
alter table public.post_knowledge_slots force row level security;

-- Visible exactly when the post is.
create policy post_knowledge_slots_select_visible on public.post_knowledge_slots
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_knowledge_slots.post_id));

-- The giver adds, changes and removes slots while the post's content is editable.
create policy post_knowledge_slots_insert_owner on public.post_knowledge_slots
  for insert to authenticated
  with check (exists (select 1 from public.posts p
                       where p.id = post_knowledge_slots.post_id and p.owner_id = (select auth.uid())
                         and p.status in ('draft', 'open', 'paused')));
create policy post_knowledge_slots_update_owner on public.post_knowledge_slots
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_knowledge_slots.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')));
create policy post_knowledge_slots_delete_owner on public.post_knowledge_slots
  for delete to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_knowledge_slots.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')));

grant select, delete on public.post_knowledge_slots to authenticated;
grant insert (post_id, starts_at, ends_at, capacity) on public.post_knowledge_slots to authenticated;
-- The slot cannot be moved to another post.
grant update (starts_at, ends_at, capacity) on public.post_knowledge_slots to authenticated;

-- Books a place in a slot that has not started. The booking waits for the giver and
-- lapses 24 hours after it was made or at the start of the slot, whichever is earlier.
--   listing_not_available  no such slot, or its post is not open to the caller
--   slot_started · slots_exhausted · own_listing · item_already_reserved
create function public.book_knowledge_seat(p_slot_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_post public.posts;
  v_slot public.post_knowledge_slots;
begin
  -- The post row lock serializes bookings, so the last place is given once.
  select p.* into v_post from public.posts p
   where p.id = (select s.post_id from public.post_knowledge_slots s where s.id = p_slot_id)
     for update;
  select s.* into v_slot from public.post_knowledge_slots s where s.id = p_slot_id;
  if not found or not kc_private.post_bookable_by(v_post, v_user_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  if v_slot.starts_at <= now() then
    raise exception 'slot_started' using errcode = 'P0001';
  end if;
  if kc_private.knowledge_slot_seats_taken(v_slot.post_id, v_slot.starts_at) >= v_slot.capacity then
    raise exception 'slots_exhausted' using errcode = 'P0001';
  end if;
  return kc_private.handoff_open(
    v_slot.post_id, v_user_id, 'reserved', null, 1,
    jsonb_build_object(
      'slot_starts_at', v_slot.starts_at, 'slot_ends_at', v_slot.ends_at,
      'confirm_by', least(now() + interval '24 hours', v_slot.starts_at)));
end;
$$;
comment on function public.book_knowledge_seat(uuid) is
  'The caller books a place in a knowledge slot; the giver approves within 24 hours or by the start.';
grant execute on function public.book_knowledge_seat(uuid) to authenticated;

-- >>> supabase/schemas/70_worlds/160_world_post_create.sql
-- Worlds · creating a post together with its detail row
--
-- A ride, a stay offer, an event and a food offer are only meaningful with their detail
-- row, so the two are created in one call and one transaction (quick publish, D75): the
-- post is inserted as a draft, the details are checked by their table, and only then is
-- the post published — route alerts and every other consequence of publishing see a
-- complete post. One RPC for the four worlds rather than one per world: the post part is
-- identical, and each world's rules live in its detail table, not in the RPC. Later edits
-- need no RPC: the owner updates `posts` and the detail table directly, under their grants.
-- Worlds without a detail table keep using a plain insert into `posts`.

-- Inserts the post of p_owner_id from p_post (the columns a device may set on `posts`),
-- its detail row from p_details, and publishes it in p_publish_role (`owner`, or `system`
-- for a scheduled occurrence); null leaves a draft. Returns the post id.
--   post_details_not_supported  the post is not of a kind that has a detail table
create function kc_private.post_create(p_owner_id uuid, p_post jsonb, p_details jsonb, p_publish_role text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
begin
  insert into public.posts (
    owner_id, world_slug, kind_id, post_type, direction, status, visibility, title, description,
    item_subcategory_id, details, city_id, location_display_level, urgency_level)
  select p_owner_id, r.world_slug, r.kind_id, coalesce(r.post_type, 'standard'), r.direction, 'draft',
         coalesce(r.visibility, 'Public'), r.title, r.description, r.item_subcategory_id,
         coalesce(r.details, '{}'::jsonb), r.city_id,
         coalesce(r.location_display_level, 'CityAndStreet'), r.urgency_level
    from jsonb_populate_record(null::public.posts, coalesce(p_post, '{}'::jsonb)) r
  returning * into v_post;

  if v_post.post_type = 'ride' then
    insert into public.post_ride_details (
      post_id, origin_city_id, origin_street_id, origin_junction_id, dest_city_id, dest_street_id,
      dest_junction_id, meeting_points, departs_at, arrives_at, seats, luggage, cargo_items, cargo_food,
      reward_model, cost_share_ils, notes, series_id, series_on)
    select v_post.id, r.origin_city_id, r.origin_street_id, r.origin_junction_id, r.dest_city_id,
           r.dest_street_id, r.dest_junction_id, coalesce(r.meeting_points, '[]'::jsonb), r.departs_at,
           r.arrives_at, coalesce(r.seats, 1), coalesce(r.luggage, false), coalesce(r.cargo_items, false),
           coalesce(r.cargo_food, false), coalesce(r.reward_model, 'free'), r.cost_share_ils, r.notes,
           -- Only the scheduler links an occurrence to its series.
           case p_publish_role when 'system' then r.series_id end,
           case p_publish_role when 'system' then r.series_on end
      from jsonb_populate_record(null::public.post_ride_details, p_details) r;
  elsif v_post.post_type = 'housing_stay' then
    insert into public.post_housing_details (
      post_id, place_type, capacity, exclusive, min_nights, max_nights, check_in_from, check_in_until,
      check_out_by, children_ok, pets_ok, available_from, available_until, available_weekdays, blackout_dates)
    select v_post.id, r.place_type, r.capacity, coalesce(r.exclusive, false), coalesce(r.min_nights, 1),
           coalesce(r.max_nights, 3), coalesce(r.check_in_from, '16:00'), coalesce(r.check_in_until, '22:00'),
           coalesce(r.check_out_by, '10:00'), coalesce(r.children_ok, false), coalesce(r.pets_ok, false),
           r.available_from, r.available_until, r.available_weekdays, coalesce(r.blackout_dates, '{}')
      from jsonb_populate_record(null::public.post_housing_details, p_details) r;
  elsif v_post.post_type = 'event' then
    insert into public.post_event_details (
      post_id, starts_at, ends_at, capacity, registration_policy, address_label, counts_volunteer_hours)
    select v_post.id, r.starts_at, r.ends_at, r.capacity, coalesce(r.registration_policy, 'automatic'),
           r.address_label, coalesce(r.counts_volunteer_hours, false)
      from jsonb_populate_record(null::public.post_event_details, p_details) r;
  elsif v_post.post_type = 'standard' and v_post.world_slug = 'food' and v_post.direction = 'offer' then
    insert into public.post_food_details (post_id, expires_at, food_type, allergens, kosher, dietary_tags)
    select v_post.id, r.expires_at, r.food_type, coalesce(r.allergens, '{}'), r.kosher,
           coalesce(r.dietary_tags, '{}')
      from jsonb_populate_record(null::public.post_food_details, p_details) r;
  else
    raise exception 'post_details_not_supported' using errcode = 'P0001';
  end if;

  if p_publish_role is not null then
    perform kc_private.post_move(v_post.id, 'open', p_publish_role);
  end if;
  return v_post.id;
end;
$$;
comment on function kc_private.post_create(uuid, jsonb, jsonb, text) is
  'Creates a post with its ride, stay, event or food details in one transaction and optionally publishes it.';

-- Creates the caller's ride, stay offer, event or food offer.
--   p_post     world_slug, kind_id, post_type ('ride' | 'housing_stay' | 'event', or absent
--              for a food offer), direction, title, city_id and optionally description,
--              visibility, item_subcategory_id, details, location_display_level,
--              urgency_level; "status": "draft" keeps the post unpublished
--   p_details  the columns of the world's detail table
-- Errors: whatever the post and the detail table refuse — post_kind_not_allowed,
-- post_limit_exceeded, post_details_not_supported, ride_place_invalid, declaration_required,
-- verification_required, food_expiry_required, … — plus SQLSTATE 23xxx / 22xxx for a
-- missing or malformed field.
create function public.create_post_with_details(p_post jsonb, p_details jsonb)
returns uuid
language sql
security definer
set search_path = ''
as $$
  select kc_private.post_create(
    kc_private.require_active_caller(), p_post, p_details,
    case when p_post ->> 'status' = 'draft' then null else 'owner' end);
$$;
comment on function public.create_post_with_details(jsonb, jsonb) is
  'Creates and publishes (or drafts) the caller''s ride, stay offer, event or food offer with its details.';
grant execute on function public.create_post_with_details(jsonb, jsonb) to authenticated;

-- A post of a kind that has a detail table never exists without its row. Checked at
-- commit, so the post and its details can be written in either order inside one
-- transaction; a bare insert of such a post from a device fails (post_details_required).
create function kc_private.posts_require_details()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.posts p where p.id = new.id)
     and not (case
       when new.post_type = 'ride' then
         exists (select 1 from public.post_ride_details d where d.post_id = new.id)
       when new.post_type = 'housing_stay' then
         exists (select 1 from public.post_housing_details d where d.post_id = new.id)
       when new.post_type = 'event' then
         exists (select 1 from public.post_event_details d where d.post_id = new.id)
       else
         exists (select 1 from public.post_food_details d where d.post_id = new.id)
     end) then
    raise exception 'post_details_required' using errcode = 'P0001';
  end if;
  return null;
end;
$$;
comment on function kc_private.posts_require_details() is
  'Deferred check: a ride, stay, event or food offer post has its detail row when the transaction commits.';

create constraint trigger posts_require_details
  after insert on public.posts
  deferrable initially deferred
  for each row
  when (new.post_type in ('ride', 'housing_stay', 'event')
        or (new.post_type = 'standard' and new.world_slug = 'food' and new.direction = 'offer'))
  execute function kc_private.posts_require_details();

-- >>> supabase/schemas/70_worlds/170_world_sweeps.sql
-- Worlds · sweeps (run by the scheduler as the service role; scheduled by the ops module)
--
-- Time-driven moves of the worlds, all in the machine role `system`. Rows are claimed with
-- SKIP LOCKED and re-checked by the machines, so each sweep is safe to run concurrently
-- with itself and with member actions. What each world needs, and where it lives:
--   ride / event / food / stay-offer / lesson expiry   kc_private.post_expiry_sweep (here):
--       every detail table writes its own `posts.expires_at`, so one sweep serves them all
--   unanswered ride, stay, event and lesson bookings   kc_private.handoff_reservation_expiry_sweep
--       (25_handoffs/080), on `confirm_by`
--   recurring rides                                    kc_private.ride_series_materialize (070)
--   stays nobody closed                                kc_private.housing_not_completed_sweep (here)
--   food about to expire                               kc_private.food_expiry_alert_sweep (here)

-- Expires open and paused posts whose time has come (D21, D128), in every world. Before
-- the post leaves the air its bookings are ended with an honest reason: a request nobody
-- answered `expired`, an approved booking nobody completed `not_completed` — never
-- completed automatically, so no karma is earned without a member saying so. Registrations
-- of an event that took place stay for attendance marking (25_handoffs/050). The owner is
-- told. Before, the ride sweep left bookings live and each world had its own writer.
create function kc_private.post_expiry_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post record;
  v_handoff record;
  v_count integer := 0;
begin
  for v_post in
    select p.id, p.owner_id, p.world_slug from public.posts p
     where p.expires_at <= now() and p.status in ('open', 'paused')
     order by p.expires_at
     limit least(greatest(p_limit, 1), 5000)
       for update skip locked
  loop
    for v_handoff in
      select h.id, h.status from public.post_handoffs h
       where h.post_id = v_post.id and h.status in ('reserved', 'confirmed')
         and h.machine_id <> 'event_registration'
    loop
      perform kc_private.handoff_move(
        v_handoff.id, 'cancelled', 'system',
        case v_handoff.status when 'reserved' then 'expired' else 'not_completed' end);
    end loop;
    perform kc_private.post_move(v_post.id, 'expired', 'system');
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'post_expired', 'recipient_id', v_post.owner_id, 'actor_id', null,
      'entity', jsonb_build_object('type', 'post', 'id', v_post.id),
      'data', jsonb_build_object('world_slug', v_post.world_slug, 'dedupe_key', 'post_expired:' || v_post.id)));
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.post_expiry_sweep(integer) is
  'Expires due posts of every world, ending their open bookings first; returns how many.';

-- Housing sweep: approved stays whose end passed more than seven days ago.
create index post_handoffs_stay_close_due_idx on public.post_handoffs (slot_ends_at)
  where status = 'confirmed' and machine_id = 'housing_booking';

-- An approved stay that nobody closed within seven days of its end is cancelled as
-- `not_completed`: nothing completes by itself and no karma follows (FR-HOUSING-019 AC5).
create function kc_private.housing_not_completed_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff_id uuid;
  v_count integer := 0;
begin
  for v_handoff_id in
    select h.id from public.post_handoffs h
     where h.status = 'confirmed' and h.machine_id = 'housing_booking'
       and h.slot_ends_at < now() - interval '7 days'
     order by h.slot_ends_at
     limit least(greatest(p_limit, 1), 5000)
       for update skip locked
  loop
    perform kc_private.handoff_move(v_handoff_id, 'cancelled', 'system', 'not_completed');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.housing_not_completed_sweep(integer) is
  'Cancels approved stays left unclosed seven days after their end; returns how many.';

-- Food offers nearing their expiry: the urgency of an open offer rises to high inside 72
-- hours, and inside 24 hours its owner is told once that it is about to close (S4,
-- FR-NOTIF-005). Returns the number of owners told.
create function kc_private.food_expiry_alert_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_food record;
  v_count integer := 0;
begin
  update public.posts p
     set urgency_level = 3
    from public.post_food_details f
   where f.post_id = p.id and f.expires_at <= now() + interval '72 hours'
     and p.status = 'open' and p.urgency_level is distinct from 3;

  for v_food in
    select f.post_id, f.expires_at, p.owner_id
      from public.post_food_details f
      join public.posts p on p.id = f.post_id
     where f.expires_at > now() and f.expires_at <= now() + interval '24 hours'
       and f.expiry_alerted_at is null and p.status = 'open'
     order by f.expires_at
     limit least(greatest(p_limit, 1), 5000)
       for update of f skip locked
  loop
    update public.post_food_details f set expiry_alerted_at = now() where f.post_id = v_food.post_id;
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'post_expiring', 'recipient_id', v_food.owner_id, 'actor_id', null,
      'entity', jsonb_build_object('type', 'post', 'id', v_food.post_id),
      'data', jsonb_build_object(
        'world_slug', 'food', 'expires_at', v_food.expires_at,
        'dedupe_key', 'post_expiring:' || v_food.post_id || ':' || v_food.expires_at)));
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.food_expiry_alert_sweep(integer) is
  'Raises the urgency of food offers inside 72 hours of expiry and alerts owners inside 24 hours.';

-- >>> supabase/schemas/70_worlds/900_world_notification_kinds.sql
-- Worlds · notification kinds emitted by this module
--
-- Booking changes of rides, stays and events need no rows here: they are the
-- `<machine>_<change>` kinds registered with the registry (50_notifications/010), and
-- `post_expiring` (food about to expire) is registered there too. These are the kinds
-- only this module emits.

insert into kc_private.notification_kinds
  (kind, category, bypass_preferences, bypass_quiet_hours, title_key, body_key)
values
  -- A new ride along a saved route (D74). Held during quiet hours unless delivery decides
  -- otherwise from `data.departs_at` (D95).
  ('ride_route_match', 'critical', false, false,
   'notifications.rideRouteMatchTitle', 'notifications.rideRouteMatchBody'),
  -- An emergency call on a ride or stay the member takes part in: a safety notice,
  -- delivered whatever the member switched off and at any hour.
  ('post_emergency', 'critical', true, true,
   'notifications.postEmergencyTitle', 'notifications.postEmergencyBody'),
  -- A message from the organizer of an event the member registered for.
  ('event_organizer_message', 'critical', false, false,
   'notifications.eventOrganizerMessageTitle', 'notifications.eventOrganizerMessageBody'),
  -- The member's own post expired (S4: "and at expiry").
  ('post_expired', 'critical', false, false,
   'notifications.postExpiredTitle', 'notifications.postExpiredBody');

-- >>> supabase/schemas/72_karma/010_karma_values.sql
-- Karma · point values (spec 07 §7.6, D12, D29)
--
-- Every number of the karma system is configuration, not code: one row per rewarded event,
-- optionally per context (a giving world, a post type, a challenge scope). The consumer of
-- outbox topic `karma` (030_karma_consumer.sql) looks the value up when it performs an
-- event, so a value is tuned by changing a row. An event with no row earns nothing.

create table kc_private.karma_values (
  event_type text not null check (event_type ~ '^[a-z][a-z0-9_]{1,40}$'),
  -- What the value depends on; '' = the same value everywhere.
  --   handoff_*            post type for rides, stays and events, else the giving world
  --   challenge_*          personal | community | community_large (50+ participants)
  context    text not null default '',
  -- Points per unit. Negative values are penalties.
  points     integer not null check (points <> 0),
  -- What one unit is. `once` pays the points one time; the others multiply them by a
  -- quantity the emitter measured: nights of a stay, started half hours of a session,
  -- started 50 ILS of an item's estimated value (FR-KARMA-003), full 10 ILS of a donation.
  unit       text not null default 'once'
               check (unit in ('once', 'night', 'half_hour', 'value_50_ils', 'ils_10')),
  -- Cap on the quantity of one award ("7 nights", "up to 20 bonus points").
  max_units  integer not null default 1 check (max_units >= 1),
  -- At most this many awards of the event type per member per Israel calendar day.
  daily_cap  integer check (daily_cap > 0),
  updated_at timestamptz not null default now(),
  primary key (event_type, context),
  constraint karma_values_units_chk check (unit <> 'once' or max_units = 1)
);
comment on table kc_private.karma_values is
  'Configuration of karma: points per rewarded event and context, unit, caps. Changed by server code only.';

create trigger karma_values_set_updated_at
  before update on kc_private.karma_values
  for each row execute function kc_private.set_updated_at();

alter table kc_private.karma_values enable row level security;
alter table kc_private.karma_values force row level security;

-- Values of the events this baseline emits, as approved in spec 07 §7.6. Like the edges of
-- a state machine these rows are vocabulary: without them the consumer has nothing to pay.
insert into kc_private.karma_values (event_type, context, points, unit, max_units, daily_cap) values
  -- A completed handoff: the member who gave and the member who received.
  ('handoff_giver', 'items', 20, 'once', 1, null),
  ('handoff_receiver', 'items', 15, 'once', 1, null),
  ('item_value_bonus', 'items', 1, 'value_50_ils', 20, null),
  ('handoff_giver', 'food', 20, 'once', 1, null),
  ('handoff_receiver', 'food', 10, 'once', 1, null),
  ('handoff_giver', 'ride', 25, 'once', 1, null),
  ('handoff_receiver', 'ride', 10, 'once', 1, null),
  ('handoff_giver', 'housing_stay', 30, 'night', 7, null),
  ('handoff_receiver', 'housing_stay', 10, 'once', 1, null),
  -- Attending an event; organizing one earns nothing by itself.
  ('handoff_receiver', 'event', 10, 'once', 1, null),
  -- A knowledge session: 10 an hour for the giver, at most 8 hours (D32, S72).
  ('handoff_giver', 'knowledge', 5, 'half_hour', 16, null),
  ('handoff_receiver', 'knowledge', 5, 'once', 1, null),
  ('rating_given', '', 2, 'once', 1, null),
  -- Challenges (D52). The daily cap of an event type is counted across its contexts.
  ('challenge_opened', 'personal', 2, 'once', 1, 2),
  ('challenge_opened', 'community', 3, 'once', 1, 2),
  ('challenge_report', 'personal', 1, 'once', 1, null),
  ('challenge_report', 'community', 2, 'once', 1, null),
  ('challenge_report', 'community_large', 3, 'once', 1, null),
  ('challenge_completed', 'personal', 10, 'once', 1, null),
  ('challenge_completed', 'community', 15, 'once', 1, null),
  ('challenge_completed', 'community_large', 20, 'once', 1, null),
  -- Donations to the community: 1 point per full 10 ILS, at most 100 per donation, and 10
  -- per month of a standing order. Emitted by the billing module as `award` events:
  --   { kind: award, event_type: donation, user_id, subject: 'donation:<payment id>',
  --     quantity: { ils_10: <amount in agorot / 1000, rounded down> } }
  --   { kind: award, event_type: standing_order_month, user_id,
  --     subject: 'standing_order:<id>:<YYYY-MM>' }
  -- and, for a refund, { kind: revoke, user_id, subject_prefix: 'donation:<payment id>' }.
  ('donation', '', 1, 'ils_10', 100, null),
  ('standing_order_month', '', 10, 'once', 1, null);

-- The value of an event in a context: the row of that context, else the row of every
-- context; no row = the event is not rewarded.
create function kc_private.karma_value(p_event_type text, p_context text)
returns kc_private.karma_values
language sql
stable
security definer
set search_path = ''
as $$
  select v.*
    from kc_private.karma_values v
   where v.event_type = p_event_type and v.context in (coalesce(p_context, ''), '')
   order by (v.context <> '') desc
   limit 1;
$$;
comment on function kc_private.karma_value(text, text) is
  'Configured value of a karma event in a context, falling back to the context-free row.';

-- >>> supabase/schemas/72_karma/020_karma_ledger.sql
-- Karma · ledger (FR-KARMA-001, spec 07 §7.6)
--
-- Every point a member holds is a row here: the ledger is append-only and
-- `user_stats.karma_points` is its running sum, never below zero. A row names what the
-- points are for (`subject`) and the event that wrote it (`reference`); the pair is unique
-- per member, so performing the same event twice writes nothing. Undoing an award (a handoff
-- taken back, a challenge left) appends a negative row for the same subject (S20).

create table public.karma_ledger (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references public.users (id) on delete cascade,
  -- The rewarded event (a karma_values.event_type), or `reversal`.
  event_type text not null check (event_type ~ '^[a-z][a-z0-9_]{1,40}$'),
  points     integer not null check (points <> 0),
  -- What the points are for, e.g. `handoff:<id>:giver`, `challenge:<id>:report:2026-11-08`.
  subject    text not null check (char_length(subject) between 1 and 200),
  -- The event that wrote the row, e.g. `event:<outbox id>`.
  reference  text not null check (char_length(reference) between 1 and 100),
  created_at timestamptz not null default now(),
  -- Idempotency of the consumer, and the lookup of what a subject currently holds.
  constraint karma_ledger_once_key unique (user_id, subject, reference)
);
comment on table public.karma_ledger is
  'Append-only karma entries; user_stats.karma_points is their sum. Written only by server code.';

-- "My karma history" newest first (keyset on created_at, id) and the daily-cap count of an
-- event type; covers the member foreign key.
create index karma_ledger_user_recent_idx on public.karma_ledger (user_id, created_at desc, id desc);

-- No update at all; a delete only as part of removing the member (the cascade runs after
-- the profile row is gone, a direct delete does not).
create function kc_private.karma_ledger_append_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and not exists (select 1 from public.users u where u.id = old.user_id) then
    return old;
  end if;
  raise exception 'append_only' using errcode = 'P0001', detail = 'karma_ledger';
end;
$$;

create trigger karma_ledger_append_only
  before update or delete on public.karma_ledger
  for each row execute function kc_private.karma_ledger_append_only();

alter table public.karma_ledger enable row level security;
alter table public.karma_ledger force row level security;

-- Karma is private: a member reads only their own entries (FR-KARMA-008, D29).
create policy karma_ledger_select_own on public.karma_ledger
  for select to authenticated
  using (user_id = (select auth.uid()));
-- The main admin sees everyone's karma (D29).
create policy karma_ledger_select_super_admin on public.karma_ledger
  for select to authenticated
  using ((select kc_access.has_admin_role('super_admin')));

grant select on public.karma_ledger to authenticated;

-- The karma total is its owner's alone (FR-KARMA-008 AC1): the identity module's column
-- grant on user_stats let every member read it on any visible profile. It is withdrawn here
-- and the owner reads the total through my_karma_points().
revoke select (karma_points) on public.user_stats from authenticated;

create function public.my_karma_points()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select s.karma_points from public.user_stats s where s.user_id = (select auth.uid());
$$;
comment on function public.my_karma_points() is 'The caller''s karma total (FR-KARMA-007).';
grant execute on function public.my_karma_points() to authenticated;

-- Appends one entry and moves the member's total. The counter row is the per-member lock.
-- A penalty never takes the total below zero: the entry records what was actually taken.
-- Returns the points applied; 0 when the same subject and reference were already written,
-- or when the member no longer exists.
create function kc_private.karma_apply(
  p_user_id uuid, p_event_type text, p_points integer, p_subject text, p_reference text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total integer;
  v_points integer;
begin
  select s.karma_points into v_total from public.user_stats s where s.user_id = p_user_id for update;
  if not found then
    return 0;
  end if;
  v_points := greatest(p_points, -v_total);
  if v_points = 0 then
    return 0;
  end if;

  insert into public.karma_ledger (user_id, event_type, points, subject, reference)
  values (p_user_id, p_event_type, v_points, p_subject, p_reference)
  on conflict on constraint karma_ledger_once_key do nothing;
  if not found then
    return 0;
  end if;
  update public.user_stats s set karma_points = s.karma_points + v_points where s.user_id = p_user_id;
  return v_points;
end;
$$;
comment on function kc_private.karma_apply(uuid, text, integer, text, text) is
  'Appends a karma entry once per (member, subject, reference) and updates the member''s total.';

-- Awards an event at its configured value. Nothing is paid when the event has no value, the
-- subject already holds points, or the member reached the event's daily cap.
--   p_quantity   what the emitter measured, by unit: { "night": 3 } — the value's own unit
--                picks the number, capped at max_units; a value of unit `once` ignores it
create function kc_private.karma_award(
  p_user_id uuid, p_event_type text, p_context text, p_subject text, p_reference text,
  p_quantity jsonb default '{}'::jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_value constant kc_private.karma_values := kc_private.karma_value(p_event_type, p_context);
  v_units integer := 1;
  -- Start of the current Israel calendar day.
  v_day_start constant timestamptz :=
    date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem';
begin
  if v_value.points is null or p_user_id is null then
    return 0;
  end if;
  if v_value.unit <> 'once' then
    v_units := least(coalesce((p_quantity ->> v_value.unit)::integer, 0), v_value.max_units);
    if v_units < 1 then
      return 0;
    end if;
  end if;

  -- Serialises the checks below with every other award of this member.
  perform 1 from public.user_stats s where s.user_id = p_user_id for update;
  if (select coalesce(sum(l.points), 0) from public.karma_ledger l
       where l.user_id = p_user_id and l.subject = p_subject) > 0 then
    return 0;
  end if;
  if v_value.daily_cap is not null
     and (select count(*) from public.karma_ledger l
           where l.user_id = p_user_id and l.created_at >= v_day_start
             and l.event_type = p_event_type and l.points > 0) >= v_value.daily_cap then
    return 0;
  end if;
  return kc_private.karma_apply(p_user_id, p_event_type, v_value.points * v_units, p_subject, p_reference);
end;
$$;
comment on function kc_private.karma_award(uuid, text, text, text, text, jsonb) is
  'Awards a karma event at its configured value, once per subject and within the daily cap.';

-- Takes back whatever the member still holds for every subject starting with the prefix
-- (S20: undo reverses the points). Returns the points taken, as a negative number.
create function kc_private.karma_revoke(p_user_id uuid, p_subject_prefix text, p_reference text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_held record;
  v_taken integer := 0;
begin
  perform 1 from public.user_stats s where s.user_id = p_user_id for update;
  for v_held in
    select l.subject, sum(l.points)::integer as points
      from public.karma_ledger l
     where l.user_id = p_user_id and starts_with(l.subject, p_subject_prefix)
     group by l.subject
    having sum(l.points) > 0
  loop
    v_taken := v_taken + kc_private.karma_apply(
      p_user_id, 'reversal', -v_held.points, v_held.subject, p_reference);
  end loop;
  return v_taken;
end;
$$;
comment on function kc_private.karma_revoke(uuid, text, text) is
  'Reverses the points a member holds for the subjects under a prefix.';

-- >>> supabase/schemas/72_karma/030_karma_consumer.sql
-- Karma · consumer of outbox topic `karma`
--
-- No write path computes karma. A module records what happened on topic `karma` and this
-- consumer turns it into ledger entries, so a member's request never waits for it and a
-- failed award never rolls back a handoff. Events (payload.kind):
--   handoff_completed   { handoff_id, post_id, owner_id, recipient_id, world_slug, post_type,
--                         direction, seats }                       (25_handoffs/030)
--   handoff_reverted    the same payload: the delivery was taken back
--   rating_given        { handoff_id, post_id, rater_id }         (25_handoffs/110)
--   award               { event_type, context?, user_id, subject, quantity? } — any module:
--                       pays karma_values(event_type, context) once for the subject
--   revoke              { user_id, subject_prefix } — reverses what the member holds
-- Performing an event twice changes nothing: every entry carries the event's id as its
-- reference, and an award is skipped while its subject still holds points.

-- Performs one event. Returns the net points written (negative for a reversal).
create function kc_private.karma_deliver(p_event_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payload jsonb;
  v_reference constant text := 'event:' || p_event_id;
  v_subject text;
  v_context text;
  v_giver_id uuid;
  v_receiver_id uuid;
  v_quantity jsonb;
begin
  select e.payload into v_payload
    from kc_private.outbox_events e
   where e.id = p_event_id and e.topic = 'karma';
  if not found then
    raise exception 'outbox_event_not_found' using errcode = 'P0001';
  end if;

  case v_payload ->> 'kind'
  when 'handoff_completed' then
    v_subject := 'handoff:' || (v_payload ->> 'handoff_id') || ':';
    v_context := case when v_payload ->> 'post_type' in ('ride', 'housing_stay', 'event')
                      then v_payload ->> 'post_type' else v_payload ->> 'world_slug' end;
    -- On an offer the owner gives and the other member receives; on a request the reverse.
    if v_payload ->> 'direction' = 'offer' then
      v_giver_id := (v_payload ->> 'owner_id')::uuid;
      v_receiver_id := (v_payload ->> 'recipient_id')::uuid;
    else
      v_giver_id := (v_payload ->> 'recipient_id')::uuid;
      v_receiver_id := (v_payload ->> 'owner_id')::uuid;
    end if;
    -- What was given, in every unit a value may be configured in. The estimated value of
    -- an item is a field of the post's details (FR-KARMA-004), capped at 1,000 ILS.
    select jsonb_strip_nulls(jsonb_build_object(
             'night', ceil(extract(epoch from h.slot_ends_at - h.slot_starts_at) / 86400),
             'half_hour', ceil(extract(epoch from h.slot_ends_at - h.slot_starts_at) / 1800),
             'value_50_ils', case when p.details ->> 'estimated_value' ~ '^\d{1,6}$'
               then round(least((p.details ->> 'estimated_value')::integer, 1000) / 50.0) end))
      into v_quantity
      from public.post_handoffs h
      join public.posts p on p.id = h.post_id
     where h.id = (v_payload ->> 'handoff_id')::uuid;

    return kc_private.karma_award(
             v_giver_id, 'handoff_giver', v_context, v_subject || 'giver', v_reference, v_quantity)
         + kc_private.karma_award(
             v_giver_id, 'item_value_bonus', v_context, v_subject || 'value_bonus', v_reference, v_quantity)
         + kc_private.karma_award(
             v_receiver_id, 'handoff_receiver', v_context, v_subject || 'receiver', v_reference, v_quantity);

  when 'handoff_reverted' then
    v_subject := 'handoff:' || (v_payload ->> 'handoff_id') || ':';
    return kc_private.karma_revoke((v_payload ->> 'owner_id')::uuid, v_subject, v_reference)
         + kc_private.karma_revoke((v_payload ->> 'recipient_id')::uuid, v_subject, v_reference);

  when 'rating_given' then
    return kc_private.karma_award(
      (v_payload ->> 'rater_id')::uuid, 'rating_given', '',
      'rating:' || (v_payload ->> 'handoff_id'), v_reference);

  when 'award' then
    return kc_private.karma_award(
      (v_payload ->> 'user_id')::uuid, v_payload ->> 'event_type', v_payload ->> 'context',
      v_payload ->> 'subject', v_reference, coalesce(v_payload -> 'quantity', '{}'::jsonb));

  when 'revoke' then
    return kc_private.karma_revoke(
      (v_payload ->> 'user_id')::uuid, v_payload ->> 'subject_prefix', v_reference);

  else
    raise exception 'invalid_karma_event' using errcode = 'P0001';
  end case;
end;
$$;
comment on function kc_private.karma_deliver(bigint) is
  'Consumer of outbox topic karma: writes the ledger entries of one event; safe to repeat.';

-- Worker entry point: claims due events of the topic, performs each and confirms it. A
-- failing event is released for a retry with its error and does not stop the batch.
-- Returns the number of events performed. Needs no service outside the database, so it is
-- run by a scheduled job.
create function kc_private.karma_process(p_limit integer default 200)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event_id bigint;
  v_done integer := 0;
begin
  for v_event_id in
    select e.id from kc_private.outbox_claim('karma', p_limit) e order by e.id
  loop
    begin
      perform kc_private.karma_deliver(v_event_id);
      perform kc_private.outbox_complete(v_event_id);
      v_done := v_done + 1;
    exception when others then
      perform kc_private.outbox_complete(v_event_id, sqlerrm);
    end;
  end loop;
  return v_done;
end;
$$;
comment on function kc_private.karma_process(integer) is
  'Claims and performs a batch of karma events; run by a scheduled job.';

-- ── Nightly reconciliation (FR-KARMA-001 AC3, design §5 "Counters") ─────────────────────

-- One row per total that did not match its ledger. Ids only; kept for diagnosis.
create table ops.karma_drift (
  id          bigint generated always as identity primary key,
  user_id     uuid not null,
  stored      integer not null,
  computed    integer not null,
  detected_at timestamptz not null default now()
);
comment on table ops.karma_drift is 'Karma totals that differed from the ledger sum when the nightly job corrected them.';

alter table ops.karma_drift enable row level security;
alter table ops.karma_drift force row level security;

-- Sets every member's total to the sum of their ledger (never below zero) and records each
-- total it had to correct. Returns the number of corrections.
create function kc_private.karma_reconcile()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_fixed integer;
begin
  with ledger as (
    select l.user_id, greatest(sum(l.points), 0)::integer as points
      from public.karma_ledger l
     group by l.user_id
  ), fixed as (
    update public.user_stats s
       set karma_points = coalesce(g.points, 0)
      from public.user_stats c
      left join ledger g on g.user_id = c.user_id
     where s.user_id = c.user_id and s.karma_points <> coalesce(g.points, 0)
    returning s.user_id, c.karma_points as stored, s.karma_points as computed
  )
  insert into ops.karma_drift (user_id, stored, computed)
  select f.user_id, f.stored, f.computed from fixed f;
  get diagnostics v_fixed = row_count;
  return v_fixed;
end;
$$;
comment on function kc_private.karma_reconcile() is
  'Nightly: corrects karma totals from the ledger and records every drift in ops.karma_drift.';

-- >>> supabase/schemas/74_challenges/010_challenges.sql
-- Challenges · tables (spec 10_challenges, D43, D46, D52, D100)
--
-- A challenge is a post of `post_type = 'challenge'` in the `challenges` giving world plus
-- the row here: opening one is "giving" in that world, joining is "taking". The post carries
-- what every post has (title, description, audience, feed, comments, reports, moderation);
-- this module adds the rules of the challenge, who takes part and their reports. Writes
-- happen only through the RPCs of this module.

-- Lifecycle, machine `challenge`: active ─► ended. Ending is final.
--   manager   whoever may manage the challenge's post (its owner; design §12.1)
--   admin     a moderator
insert into kc_private.fsm_state (machine_id, status) values
  ('challenge', 'active'),
  ('challenge', 'ended');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('challenge', 'active', 'ended', 'manager'),
  ('challenge', 'active', 'ended', 'admin');

create table public.challenges (
  id                 uuid primary key default gen_random_uuid(),
  -- The challenge's post; removing the post removes the challenge.
  post_id            uuid not null unique references public.posts (id) on delete cascade,
  creator_id         uuid not null references public.users (id) on delete cascade,
  -- personal: only the creator sees and joins it; community: anyone may join. The
  -- invite-only `group` scope of the spec is not built.
  scope              text not null check (scope in ('personal', 'community')),
  measurement        text not null check (measurement in ('yes_no', 'count', 'duration_minutes')),
  -- weekly = Sunday-to-Saturday Israel week; flexible keeps no streak.
  cadence            text not null check (cadence in ('daily', 'weekly', 'flexible')),
  goal_value         numeric(10, 2) check (goal_value >= 0),
  goal_direction     text check (goal_direction in ('at_least', 'at_most')),
  difficulty         text check (difficulty in ('easy', 'medium', 'hard', 'expert')),
  -- Free-text subject of the challenge; not a giving world and not a post type.
  topic_label        text check (char_length(topic_label) between 1 and 50),
  -- Deadline; a challenge past it reads as ended and takes no more reports.
  ends_at            timestamptz,
  -- Successful cycles that complete the challenge for a participant.
  target_cycles      integer check (target_cycles between 1 and 366),
  -- Lifecycle, machine `challenge`. Never written by a device.
  status             text not null default 'active',
  participants_count integer not null default 0 check (participants_count >= 0),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  -- A yes/no challenge has no numeric goal; a numeric goal is a value with a direction.
  constraint challenges_goal_shape_chk check (
    (measurement = 'yes_no' and goal_value is null and goal_direction is null)
    or (measurement <> 'yes_no' and (goal_value is null) = (goal_direction is null)))
);
comment on table public.challenges is 'Rules and state of a challenge; its title and audience live on its post.';

-- Discover list: open community challenges, most joined first (keyset on the three columns).
create index challenges_discover_idx on public.challenges (participants_count desc, created_at desc, id desc)
  where scope = 'community' and status = 'active';
-- "Challenges I opened", newest first; covers the creator foreign key.
create index challenges_creator_recent_idx on public.challenges (creator_id, created_at desc, id desc);

create trigger challenges_status_fsm
  before insert or update of status on public.challenges
  for each row execute function kc_private.fsm_guard_status('challenge', 'status');
create trigger challenges_set_updated_at
  before update on public.challenges
  for each row execute function kc_private.set_updated_at();

create table public.challenge_participations (
  challenge_id       uuid not null references public.challenges (id) on delete cascade,
  user_id            uuid not null references public.users (id) on delete cascade,
  joined_at          timestamptz not null default now(),
  -- Streak as of `last_success_cycle`; readers apply challenge_live_streak() for today.
  current_streak     integer not null default 0 check (current_streak >= 0),
  best_streak        integer not null default 0 check (best_streak >= 0),
  successful_cycles  integer not null default 0 check (successful_cycles >= 0),
  last_success_cycle date,
  -- Set when the successful cycles reach the challenge's target.
  completed_at       timestamptz,
  primary key (challenge_id, user_id)
);
comment on table public.challenge_participations is 'Who takes part in a challenge, with their streak and progress.';

-- "Challenges I joined", newest first; covers the member foreign key.
create index challenge_participations_user_recent_idx
  on public.challenge_participations (user_id, joined_at desc, challenge_id desc);

create table public.challenge_progress_entries (
  challenge_id uuid not null,
  user_id      uuid not null,
  -- First day of the reported cycle: the day itself, or the Sunday that opened its week.
  cycle_start  date not null,
  value        numeric(10, 2) not null check (value >= 0),
  note         text check (char_length(note) between 1 and 500),
  goal_met     boolean not null,
  reported_at  timestamptz not null default now(),
  -- One report per participant per cycle; filing again overwrites it.
  primary key (challenge_id, user_id, cycle_start),
  -- Leaving a challenge withdraws the member's reports.
  constraint challenge_progress_entries_participation_fk foreign key (challenge_id, user_id)
    references public.challenge_participations (challenge_id, user_id) on delete cascade
);
comment on table public.challenge_progress_entries is 'One self-report per participant per cycle of a challenge.';

alter table public.challenges enable row level security;
alter table public.challenges force row level security;
alter table public.challenge_participations enable row level security;
alter table public.challenge_participations force row level security;
alter table public.challenge_progress_entries enable row level security;
alter table public.challenge_progress_entries force row level security;

-- A community challenge is readable exactly when its post is: the subquery runs under the
-- caller's own access to `posts` (audience, blocks, moderation). A creator always reads
-- their own. Participants of a challenge that left the feed read it through get_challenge.
create policy challenges_select_visible on public.challenges
  for select to authenticated
  using (creator_id = (select auth.uid())
         or exists (select 1 from public.posts p where p.id = challenges.post_id));
-- Progress is personal: a member reads their own participation and reports; standings of
-- others come from the leaderboard RPC only.
create policy challenge_participations_select_own on public.challenge_participations
  for select to authenticated
  using (user_id = (select auth.uid()));
create policy challenge_progress_entries_select_own on public.challenge_progress_entries
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.challenges to authenticated;
grant select on public.challenge_participations to authenticated;
grant select on public.challenge_progress_entries to authenticated;

-- Keeps challenges.participants_count in step with the participation rows.
create function kc_private.challenge_participations_sync_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.challenges c
     set participants_count = greatest(c.participants_count + case tg_op when 'INSERT' then 1 else -1 end, 0)
   where c.id = case tg_op when 'INSERT' then new.challenge_id else old.challenge_id end;
  return null;
end;
$$;
comment on function kc_private.challenge_participations_sync_count() is
  'AFTER INSERT OR DELETE on challenge_participations: maintains the participant counter.';

create trigger challenge_participations_sync_count
  after insert or delete on public.challenge_participations
  for each row execute function kc_private.challenge_participations_sync_count();

-- A challenge post never exists without its challenge. Checked at commit, so the RPC can
-- write the two in either order; a bare insert of such a post from a device fails.
create function kc_private.posts_require_challenge()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.posts p where p.id = new.id)
     and not exists (select 1 from public.challenges c where c.post_id = new.id) then
    raise exception 'post_details_required' using errcode = 'P0001';
  end if;
  return null;
end;
$$;
comment on function kc_private.posts_require_challenge() is
  'Deferred check: a challenge post has its challenge row when the transaction commits.';

create constraint trigger posts_require_challenge
  after insert on public.posts
  deferrable initially deferred
  for each row
  when (new.post_type = 'challenge')
  execute function kc_private.posts_require_challenge();

-- >>> supabase/schemas/74_challenges/020_challenge_cycles.sql
-- Challenges · cycles, goals and streaks (mirrored by challengeCycles.ts in @kc/domain)
--
-- A report belongs to a cycle: a day, or a Sunday-to-Saturday week. All dates are Israel
-- calendar dates decided by the server, whatever the device or session time zone says.

-- Today in Israel.
create function kc_private.challenge_today()
returns date
language sql
stable
set search_path = ''
as $$
  select (now() at time zone 'Asia/Jerusalem')::date;
$$;
comment on function kc_private.challenge_today() is 'The current Israel calendar date.';

-- First day of the cycle a date belongs to: itself, or the Sunday that opened its week.
create function kc_private.challenge_cycle_start(p_date date, p_cadence text)
returns date
language sql
immutable
set search_path = ''
as $$
  select case p_cadence when 'weekly' then p_date - extract(dow from p_date)::integer else p_date end;
$$;
comment on function kc_private.challenge_cycle_start(date, text) is
  'First day of the cycle of a date: the day, or the Sunday of its week for a weekly challenge.';

-- Whether one reported value is a success for its cycle. Yes/no: 1 = done. A numeric
-- challenge without a goal succeeds by being reported.
create function kc_private.challenge_goal_met(p_challenge public.challenges, p_value numeric)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select case
    when p_challenge.measurement = 'yes_no' then p_value >= 1
    when p_challenge.goal_value is null then true
    when p_challenge.goal_direction = 'at_least' then p_value >= p_challenge.goal_value
    else p_value <= p_challenge.goal_value
  end;
$$;
comment on function kc_private.challenge_goal_met(public.challenges, numeric) is
  'A reported value meets the goal of the challenge.';

-- The streak a member still holds today: the stored one while the last success is in the
-- current or the previous cycle, zero once a full cycle was skipped. Flexible challenges
-- keep no streak.
create function kc_private.challenge_live_streak(p_streak integer, p_last_success date, p_cadence text)
returns integer
language sql
stable
set search_path = ''
as $$
  select case
    when p_cadence = 'flexible' or p_last_success is null then 0
    when p_last_success >= kc_private.challenge_cycle_start(kc_private.challenge_today(), p_cadence)
                           - case p_cadence when 'weekly' then 7 else 1 end then p_streak
    else 0
  end;
$$;
comment on function kc_private.challenge_live_streak(integer, date, text) is
  'The streak as it stands today: the stored streak, or zero after a skipped cycle.';

-- Streaks of one participant from their stored reports. Successful cycles are grouped into
-- runs of consecutive cycles (gaps and islands over the cycle index, counted from a
-- Sunday); the current streak is the run that holds the latest success.
create function kc_private.challenge_compute_streaks(p_challenge public.challenges, p_user_id uuid)
returns table (current_streak integer, best_streak integer, successful_cycles integer, last_success_cycle date)
language sql
stable
security definer
set search_path = ''
as $$
  with wins as (
    select e.cycle_start,
           (e.cycle_start - date '2000-01-02') / case p_challenge.cadence when 'weekly' then 7 else 1 end as idx
      from public.challenge_progress_entries e
     where e.challenge_id = p_challenge.id and e.user_id = p_user_id and e.goal_met
  ),
  runs as (
    select count(*)::integer as len, max(i.cycle_start) as last_cycle
      from (select w.cycle_start, w.idx - row_number() over (order by w.idx) as grp from wins w) i
     group by i.grp
  )
  select case p_challenge.cadence when 'flexible' then 0
           else coalesce((select r.len from runs r order by r.last_cycle desc limit 1), 0) end,
         case p_challenge.cadence when 'flexible' then 0
           else coalesce((select max(r.len) from runs r), 0) end,
         (select count(*)::integer from wins),
         (select max(w.cycle_start) from wins w);
$$;
comment on function kc_private.challenge_compute_streaks(public.challenges, uuid) is
  'Current and best streak, successful cycles and last success of a participant, from their reports.';

-- May the member see the challenge? Its creator always; anyone else only while the creator
-- is an active member not in a blocked pair with them, and then a participant always and
-- everyone else while the challenge is a community one whose post is on the air.
create function kc_private.challenge_visible_to(p_challenge public.challenges, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_challenge.creator_id = p_user_id
      or (exists (select 1 from public.users u where u.id = p_challenge.creator_id and u.is_active)
          and not kc_access.is_blocked_between(p_user_id, p_challenge.creator_id)
          and (exists (select 1 from public.challenge_participations cp
                        where cp.challenge_id = p_challenge.id and cp.user_id = p_user_id)
               or (p_challenge.scope = 'community'
                   and exists (select 1 from public.posts p
                                where p.id = p_challenge.post_id and p.status = 'open'))));
$$;
comment on function kc_private.challenge_visible_to(public.challenges, uuid) is
  'Visibility of a challenge to a member inside the definer RPCs of this module.';

-- >>> supabase/schemas/74_challenges/030_challenge_rpcs.sql
-- Challenges · write RPCs (spec 10_challenges "Behaviour")
--
-- Every action runs as the signed-in caller; no function takes a member id. Karma is never
-- computed here: each rewarded step records an `award` event on outbox topic `karma`
-- (72_karma/030), whose values and caps are configuration (spec 07 §7.6, D52).

-- Records the karma event of a challenge step for the caller's subject under the challenge.
create function kc_private.challenge_award(
  p_user_id uuid, p_event_type text, p_challenge public.challenges, p_subject_suffix text)
returns void
language sql
security definer
set search_path = ''
as $$
  select kc_private.outbox_enqueue('karma', jsonb_build_object(
    'kind', 'award', 'event_type', p_event_type, 'user_id', p_user_id,
    -- "Large" is 50 participants or more.
    'context', case when p_challenge.scope = 'personal' then 'personal'
                    when p_challenge.participants_count >= 50 then 'community_large'
                    else 'community' end,
    'subject', 'challenge:' || p_challenge.id || ':' || p_subject_suffix));
$$;
comment on function kc_private.challenge_award(uuid, text, public.challenges, text) is
  'Enqueues the karma award of a challenge step (opened, report, completed).';

-- Opens a challenge: its post in the challenges world (Public for a community challenge,
-- OnlyMe for a personal one), the challenge row, and the creator as first participant.
--   invalid_input                    title outside 3–80 characters, or a deadline in the past
--   city_required                    no city given and none on the caller's profile
--   challenge_world_not_configured   the catalog has no active post kind for challenges
-- plus what the post and the challenge tables refuse (post_limit_exceeded, SQLSTATE 23514).
create function public.create_challenge(
  p_title text, p_scope text, p_measurement text, p_cadence text,
  p_description text default null, p_goal_value numeric default null, p_goal_direction text default null,
  p_difficulty text default null, p_topic_label text default null, p_ends_at timestamptz default null,
  p_target_cycles integer default null, p_city_id text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_id constant uuid := gen_random_uuid();
  v_kind_id uuid;
  v_city_id text;
  v_post_id uuid;
  v_challenge public.challenges;
begin
  if char_length(btrim(coalesce(p_title, ''))) not between 3 and 80 or p_ends_at <= now() then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;
  select k.id into v_kind_id
    from public.post_kinds k
   where k.world_slug = 'challenges' and k.is_active and k.direction in ('offer', 'either')
   order by k.sort_order, k.id
   limit 1;
  if not found then
    raise exception 'challenge_world_not_configured' using errcode = 'P0001';
  end if;
  v_city_id := coalesce(p_city_id, (select u.city_id from public.users u where u.id = v_user_id));
  if v_city_id is null then
    raise exception 'city_required' using errcode = 'P0001';
  end if;

  -- The rules a card shows are copied into the post's details; they never change.
  insert into public.posts (
    owner_id, world_slug, kind_id, post_type, direction, status, visibility, title, description,
    details, city_id, location_display_level, expires_at)
  values (
    v_user_id, 'challenges', v_kind_id, 'challenge', 'offer', 'draft',
    case p_scope when 'personal' then 'OnlyMe' else 'Public' end,
    btrim(p_title), nullif(btrim(p_description), ''),
    jsonb_build_object('challenge_id', v_id, 'scope', p_scope, 'measurement', p_measurement,
                       'cadence', p_cadence),
    v_city_id, 'CityOnly', p_ends_at)
  returning id into v_post_id;

  insert into public.challenges (
    id, post_id, creator_id, scope, measurement, cadence, goal_value, goal_direction, difficulty,
    topic_label, ends_at, target_cycles)
  values (
    v_id, v_post_id, v_user_id, p_scope, p_measurement, p_cadence, p_goal_value, p_goal_direction,
    p_difficulty, nullif(btrim(p_topic_label), ''), p_ends_at, p_target_cycles)
  returning * into v_challenge;
  insert into public.challenge_participations (challenge_id, user_id) values (v_id, v_user_id);

  perform kc_private.post_move(v_post_id, 'open', 'owner');
  perform kc_private.challenge_award(v_user_id, 'challenge_opened', v_challenge, 'opened');
  return v_id;
end;
$$;
comment on function public.create_challenge(text, text, text, text, text, numeric, text, text, text, timestamptz, integer, text) is
  'Opens a personal or community challenge with its post and joins the caller to it.';
grant execute on function public.create_challenge(text, text, text, text, text, numeric, text, text, text, timestamptz, integer, text) to authenticated;

-- Joins a community challenge.
--   challenge_not_found    no such challenge, a personal one, or one the caller cannot see
--   challenge_not_active   ended, or past its deadline
--   already_joined
create function public.join_challenge(p_challenge_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_challenge public.challenges;
begin
  select c.* into v_challenge from public.challenges c where c.id = p_challenge_id;
  if not found or v_challenge.scope <> 'community'
     or not kc_private.challenge_visible_to(v_challenge, v_user_id) then
    raise exception 'challenge_not_found' using errcode = 'P0001';
  end if;
  if v_challenge.status <> 'active' or v_challenge.ends_at <= now() then
    raise exception 'challenge_not_active' using errcode = 'P0001';
  end if;
  insert into public.challenge_participations (challenge_id, user_id)
  values (p_challenge_id, v_user_id)
  on conflict do nothing;
  if not found then
    raise exception 'already_joined' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.join_challenge(uuid) is 'The caller joins a community challenge.';
grant execute on function public.join_challenge(uuid) to authenticated;

-- Leaves a challenge: the caller's reports go with the participation and the karma they
-- earned in it is reversed (S20). The creator ends the challenge instead.
--   challenge_not_found · creator_cannot_leave · not_participant
create function public.leave_challenge(p_challenge_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_creator_id uuid;
begin
  select c.creator_id into v_creator_id from public.challenges c where c.id = p_challenge_id;
  if not found then
    raise exception 'challenge_not_found' using errcode = 'P0001';
  end if;
  if v_creator_id = v_user_id then
    raise exception 'creator_cannot_leave' using errcode = 'P0001';
  end if;
  delete from public.challenge_participations cp
   where cp.challenge_id = p_challenge_id and cp.user_id = v_user_id;
  if not found then
    raise exception 'not_participant' using errcode = 'P0001';
  end if;
  perform kc_private.outbox_enqueue('karma', jsonb_build_object(
    'kind', 'revoke', 'user_id', v_user_id, 'subject_prefix', 'challenge:' || p_challenge_id || ':'));
end;
$$;
comment on function public.leave_challenge(uuid) is 'The caller leaves a challenge; their reports and its karma are withdrawn.';
grant execute on function public.leave_challenge(uuid) to authenticated;

-- Ends a challenge: no more joins or reports; participants keep their history. Its post is
-- paused, so it leaves the feed. Allowed to whoever may manage the post. Repeating is a no-op.
--   challenge_not_found   no such challenge, or not the caller's to manage
create function public.end_challenge(p_challenge_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_challenge public.challenges;
begin
  perform kc_private.require_active_caller();
  select c.* into v_challenge from public.challenges c where c.id = p_challenge_id for update;
  if not found or not kc_private.can_manage_post(v_challenge.post_id) then
    raise exception 'challenge_not_found' using errcode = 'P0001';
  end if;
  perform set_config('kc.fsm_role', 'manager', true);
  update public.challenges c set status = 'ended' where c.id = p_challenge_id;
  perform set_config('kc.fsm_role', '', true);
  if exists (select 1 from public.posts p where p.id = v_challenge.post_id and p.status = 'open') then
    perform kc_private.post_move(v_challenge.post_id, 'paused', 'owner');
  end if;
end;
$$;
comment on function public.end_challenge(uuid) is 'Ends a challenge and pauses its post.';
grant execute on function public.end_challenge(uuid) to authenticated;

-- Files, or overwrites, the caller's report for the cycle of p_report_date (default today;
-- at most two days back, never ahead). Recomputes the streak; the first report of a cycle
-- and reaching the target number of successful cycles are rewarded.
--   challenge_not_found · not_participant · challenge_not_active (ended, past its deadline,
--   or its post off the air) · report_date_out_of_window · invalid_input (value)
-- Returns { cycle_start, goal_met, current_streak, best_streak, successful_cycles, completed }.
create function public.report_challenge_progress(
  p_challenge_id uuid, p_value numeric, p_note text default null, p_report_date date default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_today constant date := kc_private.challenge_today();
  v_date constant date := coalesce(p_report_date, v_today);
  v_challenge public.challenges;
  v_participation public.challenge_participations;
  v_cycle date;
  v_goal_met boolean;
  v_is_new boolean;
  v_streaks record;
  v_completed boolean;
begin
  select c.* into v_challenge from public.challenges c where c.id = p_challenge_id;
  if not found then
    raise exception 'challenge_not_found' using errcode = 'P0001';
  end if;
  -- The participation row lock serialises this member's reports.
  select cp.* into v_participation from public.challenge_participations cp
   where cp.challenge_id = p_challenge_id and cp.user_id = v_user_id for update;
  if not found then
    raise exception 'not_participant' using errcode = 'P0001';
  end if;
  if v_challenge.status <> 'active' or v_challenge.ends_at <= now()
     or not exists (select 1 from public.posts p where p.id = v_challenge.post_id and p.status = 'open') then
    raise exception 'challenge_not_active' using errcode = 'P0001';
  end if;
  if v_date > v_today or v_date < v_today - 2 then
    raise exception 'report_date_out_of_window' using errcode = 'P0001';
  end if;
  if p_value is null or p_value < 0 or p_value > 99999999.99
     or (v_challenge.measurement = 'yes_no' and p_value not in (0, 1)) then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  v_cycle := kc_private.challenge_cycle_start(v_date, v_challenge.cadence);
  v_goal_met := kc_private.challenge_goal_met(v_challenge, p_value);
  insert into public.challenge_progress_entries as e (challenge_id, user_id, cycle_start, value, note, goal_met)
  values (p_challenge_id, v_user_id, v_cycle, p_value, nullif(btrim(p_note), ''), v_goal_met)
  on conflict (challenge_id, user_id, cycle_start) do update
    set value = excluded.value, note = excluded.note, goal_met = excluded.goal_met, reported_at = now()
  returning (e.xmax = 0) into v_is_new;

  select s.* into v_streaks from kc_private.challenge_compute_streaks(v_challenge, v_user_id) s;
  v_completed := v_challenge.target_cycles is not null
    and v_streaks.successful_cycles >= v_challenge.target_cycles;
  update public.challenge_participations cp
     set current_streak = v_streaks.current_streak,
         best_streak = greatest(cp.best_streak, v_streaks.best_streak),
         successful_cycles = v_streaks.successful_cycles,
         last_success_cycle = v_streaks.last_success_cycle,
         completed_at = case when v_completed then coalesce(cp.completed_at, now()) end
   where cp.challenge_id = p_challenge_id and cp.user_id = v_user_id;

  if v_is_new then
    perform kc_private.challenge_award(v_user_id, 'challenge_report', v_challenge, 'report:' || v_cycle);
  end if;
  if v_completed and v_participation.completed_at is null then
    -- Paid once even when a corrected report completes the challenge a second time: the
    -- karma consumer skips a subject that already holds points.
    perform kc_private.challenge_award(v_user_id, 'challenge_completed', v_challenge, 'completed');
  end if;

  return jsonb_build_object(
    'cycle_start', v_cycle, 'goal_met', v_goal_met,
    'current_streak', kc_private.challenge_live_streak(
      v_streaks.current_streak, v_streaks.last_success_cycle, v_challenge.cadence),
    'best_streak', greatest(v_participation.best_streak, v_streaks.best_streak),
    'successful_cycles', v_streaks.successful_cycles, 'completed', v_completed);
end;
$$;
comment on function public.report_challenge_progress(uuid, numeric, text, date) is
  'Files the caller''s report for a cycle of a challenge and returns their updated progress.';
grant execute on function public.report_challenge_progress(uuid, numeric, text, date) to authenticated;

-- >>> supabase/schemas/74_challenges/040_challenge_reads.sql
-- Challenges · read RPCs
--
-- One row shape for every challenge screen: the challenge, its title from its post, and the
-- caller's own progress. These run with definer rights because a participant keeps reading
-- a challenge after its post left the feed (ended = paused post), which the post's own
-- policy cannot express; each function applies kc_private.challenge_visible_to itself.
-- A member's own reports are read from challenge_progress_entries directly, under RLS.

create type public.challenge_summary as (
  id                   uuid,
  post_id              uuid,
  creator_id           uuid,
  creator_display_name text,
  title                text,
  description          text,
  scope                text,
  measurement          text,
  cadence              text,
  goal_value           numeric,
  goal_direction       text,
  difficulty           text,
  topic_label          text,
  ends_at              timestamptz,
  target_cycles        integer,
  -- `ended` also once the deadline passed, without waiting for anyone to end it.
  status               text,
  participants_count   integer,
  created_at           timestamptz,
  joined               boolean,
  my_current_streak    integer,
  my_best_streak       integer,
  my_successful_cycles integer,
  my_completed         boolean
);
comment on type public.challenge_summary is 'A challenge with the caller''s own progress, as every challenge screen shows it.';

-- The summary of one challenge for a viewer. Visibility is the caller's business.
create function kc_private.challenge_summary_of(p_challenge public.challenges, p_viewer_id uuid)
returns public.challenge_summary
language sql
stable
security definer
set search_path = ''
as $$
  select row(
    p_challenge.id, p_challenge.post_id, p_challenge.creator_id, u.display_name, p.title, p.description,
    p_challenge.scope, p_challenge.measurement, p_challenge.cadence, p_challenge.goal_value,
    p_challenge.goal_direction, p_challenge.difficulty, p_challenge.topic_label, p_challenge.ends_at,
    p_challenge.target_cycles,
    case when p_challenge.ends_at <= now() then 'ended' else p_challenge.status end,
    p_challenge.participants_count, p_challenge.created_at,
    cp.user_id is not null,
    coalesce(kc_private.challenge_live_streak(cp.current_streak, cp.last_success_cycle, p_challenge.cadence), 0),
    coalesce(cp.best_streak, 0), coalesce(cp.successful_cycles, 0),
    cp.completed_at is not null)::public.challenge_summary
    from public.posts p
    join public.users u on u.id = p_challenge.creator_id
    left join public.challenge_participations cp
      on cp.challenge_id = p_challenge.id and cp.user_id = p_viewer_id
   where p.id = p_challenge.post_id;
$$;
comment on function kc_private.challenge_summary_of(public.challenges, uuid) is
  'Builds the summary row of a challenge for a viewer.';

-- One challenge, or no row when it does not exist or the caller may not see it.
create function public.get_challenge(p_challenge_id uuid)
returns setof public.challenge_summary
language sql
stable
security definer
set search_path = ''
as $$
  select (kc_private.challenge_summary_of(c, kc_private.require_caller())).*
    from public.challenges c
   where c.id = p_challenge_id
     and kc_private.challenge_visible_to(c, kc_private.require_caller());
$$;
comment on function public.get_challenge(uuid) is 'A challenge with the caller''s progress, when the caller may see it.';
grant execute on function public.get_challenge(uuid) to authenticated;

-- One keyset page of challenges. Pass the last row's next_cursor to continue.
--   discover   open community challenges, most joined first (challenges_discover_idx)
--   joined     the caller's participations, newest first
--   created    the challenges the caller opened, newest first
create function public.list_challenges(
  p_view text default 'discover', p_cursor jsonb default null, p_limit integer default 20)
returns table (challenge public.challenge_summary, next_cursor jsonb)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_limit constant integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_t constant timestamptz := (p_cursor ->> 't')::timestamptz;
  v_id constant uuid := (p_cursor ->> 'id')::uuid;
begin
  if p_view = 'discover' then
    return query
    select kc_private.challenge_summary_of(c, v_user_id),
           jsonb_build_object('n', c.participants_count, 't', c.created_at, 'id', c.id)
      from public.challenges c
     where c.scope = 'community' and c.status = 'active' and (c.ends_at is null or c.ends_at > now())
       and kc_private.challenge_visible_to(c, v_user_id)
       and exists (select 1 from public.posts p where p.id = c.post_id and p.status = 'open')
       and (p_cursor is null
            or (c.participants_count, c.created_at, c.id) < ((p_cursor ->> 'n')::integer, v_t, v_id))
     order by c.participants_count desc, c.created_at desc, c.id desc
     limit v_limit;
  elsif p_view = 'joined' then
    return query
    select kc_private.challenge_summary_of(c, v_user_id),
           jsonb_build_object('t', cp.joined_at, 'id', c.id)
      from public.challenge_participations cp
      join public.challenges c on c.id = cp.challenge_id
     where cp.user_id = v_user_id
       and kc_private.challenge_visible_to(c, v_user_id)
       and (p_cursor is null or (cp.joined_at, cp.challenge_id) < (v_t, v_id))
     order by cp.joined_at desc, cp.challenge_id desc
     limit v_limit;
  elsif p_view = 'created' then
    return query
    select kc_private.challenge_summary_of(c, v_user_id),
           jsonb_build_object('t', c.created_at, 'id', c.id)
      from public.challenges c
     where c.creator_id = v_user_id
       and (p_cursor is null or (c.created_at, c.id) < (v_t, v_id))
     order by c.created_at desc, c.id desc
     limit v_limit;
  else
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.list_challenges(text, jsonb, integer) is
  'One keyset page of challenges to discover, joined by the caller, or opened by the caller.';
grant execute on function public.list_challenges(text, jsonb, integer) to authenticated;

-- Standing of a challenge, for its participants only: streaks and successful cycles, never
-- karma (spec 10). Members in a blocked pair with the caller, and members whose account is
-- not active, are left out. Bounded: the top p_limit (at most 100).
create function public.list_challenge_leaderboard(p_challenge_id uuid, p_limit integer default 20)
returns table (
  user_id uuid, display_name text, avatar_url text, current_streak integer, best_streak integer,
  successful_cycles integer, completed boolean, is_me boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select cp.user_id, u.display_name, u.avatar_url,
         kc_private.challenge_live_streak(cp.current_streak, cp.last_success_cycle, c.cadence),
         cp.best_streak, cp.successful_cycles, cp.completed_at is not null,
         cp.user_id = (select auth.uid())
    from public.challenges c
    join public.challenge_participations cp on cp.challenge_id = c.id
    join public.users u on u.id = cp.user_id and u.is_active
   where c.id = p_challenge_id
     and exists (select 1 from public.challenge_participations me
                  where me.challenge_id = c.id and me.user_id = (select auth.uid()))
     and not kc_access.is_blocked_between((select auth.uid()), cp.user_id)
   order by 4 desc, cp.successful_cycles desc, cp.joined_at, cp.user_id
   limit least(greatest(coalesce(p_limit, 20), 1), 100);
$$;
comment on function public.list_challenge_leaderboard(uuid, integer) is
  'Top participants of a challenge by streak, visible to its participants only.';
grant execute on function public.list_challenge_leaderboard(uuid, integer) to authenticated;

-- >>> supabase/schemas/76_matching/010_matching_config.sql
-- Matching · configuration (docs/SSOT/MATCHING_V2.md "Tuning", design §3.10)
--
-- The knobs of the matching engine and the weights of its score. Both are read by server
-- code only and tuned by changing a row; nothing here is reachable from a device.

-- Engine settings: exactly one row.
create table kc_private.matching_settings (
  id                      boolean primary key default true check (id),
  -- Off = no new pairs are computed and none are announced.
  enabled                 boolean not null default true,
  -- A pair below this score is not kept.
  min_score               numeric(5, 4) not null default 0.4500 check (min_score between 0 and 1),
  -- A pair is announced to its two owners from this score up (spec 07 §7.3).
  notify_min_score        numeric(5, 4) not null default 0.6000 check (notify_min_score between 0 and 1),
  max_candidates_per_post integer not null default 10 check (max_candidates_per_post between 1 and 50),
  -- How many of the newest opposite posts of the world one run looks at.
  scan_limit              integer not null default 500 check (scan_limit between 10 and 5000),
  -- At most this many match announcements per member per Israel day (spec 07 §7.11).
  max_notify_per_user_day integer not null default 3 check (max_notify_per_user_day between 0 and 50),
  -- A pair older than this is no longer announced.
  notify_max_age_hours    integer not null default 72 check (notify_max_age_hours > 0),
  -- Optional language-model second opinion (Edge Function `match-rerank`).
  llm_rerank_enabled      boolean not null default false,
  llm_weight              numeric(4, 3) not null default 0.300 check (llm_weight between 0 and 1),
  updated_at              timestamptz not null default now()
);
comment on table kc_private.matching_settings is 'Settings of the matching engine (one row).';

create trigger matching_settings_set_updated_at
  before update on kc_private.matching_settings
  for each row execute function kc_private.set_updated_at();

-- Share of each component in the score of a pair, per giving world; '' = every world
-- without a row of its own. A component that cannot be measured for a pair (no embedding
-- yet, no time window) is left out and the rest is re-normalised.
create table kc_private.match_weights (
  world_slug text primary key,
  -- Same item subcategory.
  w_category numeric(4, 3) not null default 0.150 check (w_category between 0 and 1),
  -- Words in common (full-text tokens and trigram similarity of the titles).
  w_text     numeric(4, 3) not null default 0.300 check (w_text between 0 and 1),
  -- Meaning in common (cosine similarity of the post embeddings).
  w_vector   numeric(4, 3) not null default 0.250 check (w_vector between 0 and 1),
  -- Closeness, within the world's radius.
  w_geo      numeric(4, 3) not null default 0.200 check (w_geo between 0 and 1),
  -- Overlapping time windows.
  w_time     numeric(4, 3) not null default 0.100 check (w_time between 0 and 1),
  -- Two posts are paired only when their words or their meaning agree at least this much:
  -- being close by is never enough on its own (MATCHING_V2 "text gate").
  min_relevance numeric(4, 3) not null default 0.300 check (min_relevance between 0 and 1),
  updated_at timestamptz not null default now(),
  constraint match_weights_sum_chk check (w_category + w_text + w_vector + w_geo + w_time = 1)
);
comment on table kc_private.match_weights is 'Weights of the match score per giving world; the row with an empty slug is the default.';

create trigger match_weights_set_updated_at
  before update on kc_private.match_weights
  for each row execute function kc_private.set_updated_at();

alter table kc_private.matching_settings enable row level security;
alter table kc_private.matching_settings force row level security;
alter table kc_private.match_weights enable row level security;
alter table kc_private.match_weights force row level security;

-- The engine's defaults. Configuration, not data: the engine reads exactly these two rows
-- until an operator tunes them or adds a world's own weights.
insert into kc_private.matching_settings default values;
insert into kc_private.match_weights (world_slug) values ('');

-- A pair's score as shown and ranked: the engine's score, blended with the language
-- model's opinion when that is switched on and has been given.
create function kc_private.match_effective_score(p_score numeric, p_llm_score numeric)
returns numeric
language sql
stable
security definer
set search_path = ''
as $$
  select case when s.llm_rerank_enabled and p_llm_score is not null
              then round((1 - s.llm_weight) * p_score + s.llm_weight * p_llm_score, 4)
              else p_score end
    from kc_private.matching_settings s;
$$;
comment on function kc_private.match_effective_score(numeric, numeric) is
  'Score of a pair after the optional language-model blend.';

-- >>> supabase/schemas/76_matching/020_post_embeddings.sql
-- Matching · post embeddings and their job queue (design §3.10)
--
-- An embedding is the meaning of a post's text as a vector; matching, similar posts and
-- recommendations compare posts by it. The vector is computed outside the database: a post
-- that needs one records an outbox event on topic `embedding` (050_match_processing.sql),
-- the `embed-worker` Edge Function claims jobs, calls the model and stores the result.
-- One job per post however often it was edited, with attempts and the last error.

create table public.post_embeddings (
  post_id         uuid primary key references public.posts (id) on delete cascade,
  embedding       extensions.vector(1536) not null,
  embedding_model text not null check (char_length(embedding_model) between 1 and 100),
  updated_at      timestamptz not null default now()
);
comment on table public.post_embeddings is
  'Embedding of a post''s text. Readable by nobody from a device; used by server code only.';

-- Nearest posts by cosine distance: match candidates, similar posts, recommendations.
create index post_embeddings_hnsw_idx on public.post_embeddings
  using hnsw (embedding extensions.vector_cosine_ops);

create trigger post_embeddings_set_updated_at
  before update on public.post_embeddings
  for each row execute function kc_private.set_updated_at();

-- No policy and no grant: a vector reveals the text it was made from.
alter table public.post_embeddings enable row level security;
alter table public.post_embeddings force row level security;

create table kc_private.embedding_jobs (
  post_id      uuid primary key references public.posts (id) on delete cascade,
  status       text not null default 'pending' check (status in ('pending', 'processing', 'done', 'failed')),
  model        text not null default 'text-embedding-3-small' check (char_length(model) between 1 and 100),
  attempts     integer not null default 0 check (attempts >= 0),
  -- When the post last asked for a fresh embedding; the queue is served oldest first.
  requested_at timestamptz not null default now(),
  -- Set while a worker holds the job; a claim older than ten minutes is taken over.
  claimed_at   timestamptz,
  last_error   text
);
comment on table kc_private.embedding_jobs is 'One embedding job per post: queue state, attempts, last error.';

-- Claim query: waiting jobs, and jobs whose worker went silent, oldest request first.
create index embedding_jobs_due_idx on kc_private.embedding_jobs (requested_at)
  where status in ('pending', 'processing');

alter table kc_private.embedding_jobs enable row level security;
alter table kc_private.embedding_jobs force row level security;

-- Worker call 1 of 3. Turns the waiting `embedding` outbox events into jobs (a post edited
-- five times is one job), then hands the worker up to p_limit jobs with the text to embed.
-- Concurrent workers never receive the same job (SKIP LOCKED); a job whose worker died is
-- handed out again after ten minutes, at most five times.
create function public.embedding_jobs_claim(p_limit integer default 20)
returns table (job_id uuid, post_id uuid, model text, title text, summary text, details jsonb)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event record;
begin
  for v_event in
    select e.id, (e.payload ->> 'post_id')::uuid as post_id from kc_private.outbox_claim('embedding', 500) e
  loop
    insert into kc_private.embedding_jobs as j (post_id)
    select p.id from public.posts p where p.id = v_event.post_id
    on conflict on constraint embedding_jobs_pkey do update
      set status = 'pending', attempts = 0, requested_at = now(), claimed_at = null, last_error = null;
    perform kc_private.outbox_complete(v_event.id);
  end loop;

  return query
  with claimed as (
    update kc_private.embedding_jobs j
       set status = 'processing', attempts = j.attempts + 1, claimed_at = now()
     where j.post_id in (
             select c.post_id
               from kc_private.embedding_jobs c
              where (c.status = 'pending'
                     or (c.status = 'processing' and c.claimed_at <= now() - interval '10 minutes'))
                and c.attempts < 5
              order by c.requested_at
              limit least(greatest(coalesce(p_limit, 20), 1), 50)
                for update skip locked)
    returning j.post_id, j.model, j.requested_at
  )
  select c.post_id, c.post_id, c.model, p.title, p.description, p.details
    from claimed c
    join public.posts p on p.id = c.post_id
   order by c.requested_at, c.post_id;
end;
$$;
comment on function public.embedding_jobs_claim(integer) is
  'embed-worker: claims embedding jobs and returns the post text to embed. Service role only.';

-- Worker call 2 of 3. Stores the embedding of a claimed job and closes the job — unless the
-- post asked for a fresh embedding since the claim, in which case the job stays waiting.
-- The post is queued for matching again, now that its meaning can be compared.
-- Returns whether the job was closed.
create function public.embedding_job_store(p_job_id uuid, p_embedding extensions.vector, p_model text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_closed integer;
begin
  if not exists (select 1 from kc_private.embedding_jobs j where j.post_id = p_job_id) then
    raise exception 'embedding_job_not_found' using errcode = 'P0001';
  end if;
  insert into public.post_embeddings as e (post_id, embedding, embedding_model)
  values (p_job_id, p_embedding, p_model)
  on conflict (post_id) do update
    set embedding = excluded.embedding, embedding_model = excluded.embedding_model;

  update kc_private.embedding_jobs j
     set status = 'done', claimed_at = null, last_error = null
   where j.post_id = p_job_id and j.status = 'processing';
  get diagnostics v_closed = row_count;
  perform kc_private.outbox_enqueue('match', jsonb_build_object('post_id', p_job_id));
  return v_closed > 0;
end;
$$;
comment on function public.embedding_job_store(uuid, extensions.vector, text) is
  'embed-worker: stores a post''s embedding and closes its job. Service role only.';

-- Worker call 3 of 3. Marks a claimed job failed with its error; a job re-queued since the
-- claim stays waiting.
create function public.embedding_job_fail(p_job_id uuid, p_error text)
returns void
language sql
security definer
set search_path = ''
as $$
  update kc_private.embedding_jobs j
     set status = 'failed', claimed_at = null, last_error = left(p_error, 1000)
   where j.post_id = p_job_id and j.status = 'processing';
$$;
comment on function public.embedding_job_fail(uuid, text) is
  'embed-worker: records the failure of a claimed embedding job. Service role only.';

-- >>> supabase/schemas/76_matching/030_match_candidates.sql
-- Matching · pairs (docs/SSOT/MATCHING_V2.md, design §3.10)
--
-- A pair is an open offer and an open request of the same giving world that the engine
-- scored as fitting each other. Both owners are told (above a score threshold), each
-- answers, and a decline closes the pair for good. Pairs are internal: a member reads
-- their own through my_matches() and answers through match_respond().

-- Lifecycle, machine `match`:
--   suggested ─► accepted    both owners accepted            (member)
--   suggested ─► declined    either owner declined            (member)
--   suggested ◄─► expired    a post went off the air or the pair no longer scores, and
--                            back when it does again          (system)
insert into kc_private.fsm_state (machine_id, status) values
  ('match', 'suggested'),
  ('match', 'accepted'),
  ('match', 'declined'),
  ('match', 'expired');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('match', 'suggested', 'accepted', 'member'),
  ('match', 'suggested', 'declined', 'member'),
  ('match', 'suggested', 'expired', 'system'),
  ('match', 'expired', 'suggested', 'system');

create table kc_private.match_candidates (
  id                   uuid primary key default gen_random_uuid(),
  offer_post_id        uuid not null references public.posts (id) on delete cascade,
  request_post_id      uuid not null references public.posts (id) on delete cascade,
  -- Owners copied from the posts, so "my matches" never joins to find them.
  offer_owner_id       uuid not null references public.users (id) on delete cascade,
  request_owner_id     uuid not null references public.users (id) on delete cascade,
  world_slug           text not null references public.worlds (slug) on update cascade,
  score                numeric(5, 4) not null check (score between 0 and 1),
  -- The measured components, each 0..1: category, text, vector, geo, time.
  components           jsonb not null default '{}'::jsonb check (jsonb_typeof(components) = 'object'),
  distance_km          numeric(9, 2) check (distance_km >= 0),
  -- Lifecycle, machine `match`.
  status               text not null default 'suggested',
  offer_response       text check (offer_response in ('accepted', 'declined')),
  request_response     text check (request_response in ('accepted', 'declined')),
  offer_responded_at   timestamptz,
  request_responded_at timestamptz,
  -- When each owner was told about the pair; null = not yet.
  notified_offer_at    timestamptz,
  notified_request_at  timestamptz,
  -- The language model's opinion (Edge Function `match-rerank`).
  llm_score            numeric(5, 4) check (llm_score between 0 and 1),
  llm_reason           text check (char_length(llm_reason) <= 280),
  llm_scored_at        timestamptz,
  -- Last time the engine scored the pair.
  computed_at          timestamptz not null default now(),
  created_at           timestamptz not null default now(),
  -- One pair per two posts; also covers the offer post foreign key.
  constraint match_candidates_pair_key unique (offer_post_id, request_post_id),
  constraint match_candidates_distinct_owners_chk check (offer_owner_id <> request_owner_id)
);
comment on table kc_private.match_candidates is 'Scored offer and request pairs with each owner''s answer. Written only by the matching engine.';

-- Pairs of a request post (recompute, expiry); covers its foreign key.
create index match_candidates_request_post_idx on kc_private.match_candidates (request_post_id);
-- "My matches", the daily announcement cap and "these two owners declined before", from
-- either side; cover the owner foreign keys.
create index match_candidates_offer_owner_idx on kc_private.match_candidates (offer_owner_id, status);
create index match_candidates_request_owner_idx on kc_private.match_candidates (request_owner_id, status);
-- Announcement run: live pairs with an owner still to be told, best first.
create index match_candidates_unannounced_idx on kc_private.match_candidates (score desc)
  where status = 'suggested' and (notified_offer_at is null or notified_request_at is null);
-- Language-model run: live pairs without an opinion yet, newest first.
create index match_candidates_llm_pending_idx on kc_private.match_candidates (computed_at desc)
  where status = 'suggested' and llm_scored_at is null;
-- Covers the world foreign key (a world being renamed).
create index match_candidates_world_idx on kc_private.match_candidates (world_slug);

create trigger match_candidates_status_fsm
  before insert or update of status on kc_private.match_candidates
  for each row execute function kc_private.fsm_guard_status('match', 'status');

-- When the engine last looked at a post, and what came of it.
create table kc_private.match_state (
  post_id     uuid primary key references public.posts (id) on delete cascade,
  computed_at timestamptz not null default now(),
  -- Live pairs kept by the last run.
  candidates  integer not null default 0 check (candidates >= 0),
  last_error  text
);
comment on table kc_private.match_state is 'Per post: last matching run, pairs kept, last error.';

alter table kc_private.match_candidates enable row level security;
alter table kc_private.match_candidates force row level security;
alter table kc_private.match_state enable row level security;
alter table kc_private.match_state force row level security;

-- >>> supabase/schemas/76_matching/040_match_scoring.sql
-- Matching · scoring a pair and computing the pairs of a post (docs/SSOT/MATCHING_V2.md)
--
-- All of it is SQL over indexes that already exist: recent posts of the world, full-text
-- tokens, PostGIS distance and the embedding index. Only plain (`standard`) posts are
-- paired here: rides are matched along saved routes by the worlds module (D74), and events,
-- stays, jobs and challenges are joined, not paired.

-- The words of a title as an OR query for the full-text index; null without any word.
create function kc_private.title_tsquery(p_title text)
returns tsquery
language sql
immutable
set search_path = ''
as $$
  select to_tsquery('simple', string_agg(quote_literal(l.lexeme), ' | '))
    from unnest(tsvector_to_array(to_tsvector('simple', coalesce(p_title, '')))) as l (lexeme);
$$;
comment on function kc_private.title_tsquery(text) is 'Full-text query matching any word of the title.';

-- How far apart two posts of a world may be to be paired: twice the world's radius, and at
-- least 30 km. Null for a world where distance does not matter.
create function kc_private.match_distance_limit_m(p_world public.worlds)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select case when p_world.geo_mode <> 'remote'
              then greatest(p_world.default_radius_km * 2, 30)::double precision * 1000 end;
$$;
comment on function kc_private.match_distance_limit_m(public.worlds) is
  'Largest distance in metres at which two posts of the world are paired; null = any.';

-- Scores an offer against a request. Null when the two must never be paired:
--   the same owner · an owner whose account is not active · a block between the owners ·
--   either post not shown to the other owner (not open, "only me", or followers-only
--   without the follow) · the owners declined a pair before · too far apart · neither
--   their words nor their meaning agree (match_weights.min_relevance)
-- Otherwise { score, distance_km, components }: each measurable component is 0..1 and the
-- score is their weighted mean over the components that could be measured.
create function kc_private.match_score_pair(
  p_offer public.posts, p_request public.posts, p_weights kc_private.match_weights, p_world public.worlds)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit_m constant double precision := kc_private.match_distance_limit_m(p_world);
  v_tokens constant text[] := tsvector_to_array(to_tsvector('simple', p_request.title));
  v_distance_m double precision;
  v_text numeric;
  v_vector numeric;
  v_geo numeric;
  v_score numeric;
begin
  if p_offer.owner_id = p_request.owner_id
     or p_offer.status <> 'open' or p_request.status <> 'open'
     or (select count(*) from public.users u
          where u.id in (p_offer.owner_id, p_request.owner_id) and u.is_active) < 2
     or kc_access.is_blocked_between(p_offer.owner_id, p_request.owner_id)
     or not (p_offer.visibility = 'Public' or (p_offer.visibility = 'FollowersOnly' and exists (
               select 1 from public.follows f
                where f.follower_id = p_request.owner_id and f.followed_id = p_offer.owner_id)))
     or not (p_request.visibility = 'Public' or (p_request.visibility = 'FollowersOnly' and exists (
               select 1 from public.follows f
                where f.follower_id = p_offer.owner_id and f.followed_id = p_request.owner_id)))
     or exists (select 1 from kc_private.match_candidates m
                 where m.status = 'declined'
                   and ((m.offer_owner_id = p_offer.owner_id and m.request_owner_id = p_request.owner_id)
                     or (m.offer_owner_id = p_request.owner_id and m.request_owner_id = p_offer.owner_id))) then
    return null;
  end if;

  if p_offer.geo_approx is not null and p_request.geo_approx is not null then
    v_distance_m := extensions.st_distance(p_offer.geo_approx, p_request.geo_approx);
  end if;
  if v_limit_m is null then
    v_geo := 1;
  elsif v_distance_m > v_limit_m then
    return null;
  else
    v_geo := 1 - v_distance_m / v_limit_m;
  end if;

  -- Words: the closer of "the titles look alike" and "the offer mentions what is asked for".
  v_text := greatest(
    extensions.similarity(lower(p_offer.title), lower(p_request.title))::numeric,
    case when cardinality(v_tokens) > 0 then
      (select count(*) from unnest(v_tokens) as t (lexeme)
        where t.lexeme = any (tsvector_to_array(p_offer.search_vector)))::numeric / cardinality(v_tokens)
    else 0 end);
  -- Meaning: cosine similarity, when both posts have their embedding.
  select least(greatest(1 - (o.embedding operator(extensions.<=>) r.embedding), 0), 1)::numeric
    into v_vector
    from public.post_embeddings o, public.post_embeddings r
   where o.post_id = p_offer.id and r.post_id = p_request.id;
  if greatest(v_text, coalesce(v_vector, 0)) < p_weights.min_relevance then
    return null;
  end if;

  select sum(c.weight * c.value) / nullif(sum(c.weight), 0) into v_score
    from (values
      (p_weights.w_category, (p_offer.item_subcategory_id = p_request.item_subcategory_id)::integer::numeric),
      (p_weights.w_text, v_text),
      (p_weights.w_vector, v_vector),
      (p_weights.w_geo, v_geo),
      (p_weights.w_time, (p_offer.time_window && p_request.time_window)::integer::numeric)
    ) as c (weight, value)
   where c.value is not null;

  return jsonb_build_object(
    'score', round(coalesce(v_score, 0), 4),
    'distance_km', round((v_distance_m / 1000)::numeric, 2),
    'components', jsonb_strip_nulls(jsonb_build_object(
      'category', (p_offer.item_subcategory_id = p_request.item_subcategory_id)::integer,
      'text', round(v_text, 4), 'vector', round(v_vector, 4), 'geo', round(v_geo, 4),
      'time', (p_offer.time_window && p_request.time_window)::integer)));
end;
$$;
comment on function kc_private.match_score_pair(public.posts, public.posts, kc_private.match_weights, public.worlds) is
  'Score and components of an offer and request pair, or null when they must not be paired.';

-- Recomputes the pairs of one post and returns how many it holds afterwards.
--   candidates   the newest opposite posts of the world within reach, posts sharing a word
--                with the title, and the posts nearest in meaning — then scored and the
--                best kept (settings: scan_limit, min_score, max_candidates_per_post)
--   upsert       a pair nobody answered is re-scored; an answered pair is never touched
--   expiry       unanswered pairs the run did not keep, and every open pair of a post
--                that is no longer on the air, become `expired`
-- Safe to repeat: the same input gives the same rows.
create function kc_private.match_compute_for_post(p_post_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
  v_run_at constant timestamptz := clock_timestamp();
  v_settings kc_private.matching_settings;
  v_post public.posts;
  v_weights kc_private.match_weights;
  v_world public.worlds;
  v_embedding extensions.vector;
  v_is_offer boolean;
  v_live boolean;
  v_kept integer := 0;
begin
  select s.* into v_settings from kc_private.matching_settings s;
  select p.* into v_post from public.posts p where p.id = p_post_id;
  if not found or not v_settings.enabled then
    return 0;
  end if;
  v_live := v_post.status = 'open' and v_post.post_type = 'standard';
  v_is_offer := v_post.direction = 'offer';
  perform set_config('kc.fsm_role', 'system', true);

  if v_live then
    select w.* into v_weights from kc_private.match_weights w
     where w.world_slug in (v_post.world_slug, '') order by (w.world_slug <> '') desc limit 1;
    select w.* into v_world from public.worlds w where w.slug = v_post.world_slug;
    select e.embedding into v_embedding from public.post_embeddings e where e.post_id = p_post_id;

    with pool as (
      (select c.id from public.posts c
        where c.status = 'open' and c.world_slug = v_post.world_slug
          and (v_post.geo_approx is null or kc_private.match_distance_limit_m(v_world) is null
               or extensions.st_dwithin(c.geo_approx, v_post.geo_approx, kc_private.match_distance_limit_m(v_world)))
        order by c.published_at desc
        limit v_settings.scan_limit)
      union
      (select c.id from public.posts c
        where c.status = 'open' and c.search_vector @@ kc_private.title_tsquery(v_post.title)
        order by c.published_at desc
        limit 100)
      union
      (select e.post_id from public.post_embeddings e
        where v_embedding is not null
        order by e.embedding operator(extensions.<=>) v_embedding
        limit 100)
    ), scored as (
      select c.id as other_post_id, c.owner_id as other_owner_id, s.pair
        from pool
        join public.posts c on c.id = pool.id
       cross join lateral (
         select case when v_is_offer then kc_private.match_score_pair(v_post, c, v_weights, v_world)
                     else kc_private.match_score_pair(c, v_post, v_weights, v_world) end as pair) s
       where c.world_slug = v_post.world_slug and c.post_type = 'standard'
         and c.direction <> v_post.direction
         and (s.pair ->> 'score')::numeric >= v_settings.min_score
       order by (s.pair ->> 'score')::numeric desc, c.id
       limit v_settings.max_candidates_per_post
    )
    insert into kc_private.match_candidates as m (
      offer_post_id, request_post_id, offer_owner_id, request_owner_id, world_slug,
      score, components, distance_km, computed_at)
    select case when v_is_offer then v_post.id else s.other_post_id end,
           case when v_is_offer then s.other_post_id else v_post.id end,
           case when v_is_offer then v_post.owner_id else s.other_owner_id end,
           case when v_is_offer then s.other_owner_id else v_post.owner_id end,
           v_post.world_slug, (s.pair ->> 'score')::numeric, s.pair -> 'components',
           (s.pair ->> 'distance_km')::numeric, v_run_at
      from scored s
    on conflict on constraint match_candidates_pair_key do update
      set score = excluded.score, components = excluded.components,
          distance_km = excluded.distance_km, computed_at = excluded.computed_at, status = 'suggested'
      where m.status in ('suggested', 'expired')
        and m.offer_response is null and m.request_response is null;
    get diagnostics v_kept = row_count;
  end if;

  update kc_private.match_candidates m
     set status = 'expired'
   where (m.offer_post_id = p_post_id or m.request_post_id = p_post_id)
     and m.status = 'suggested'
     and (not v_live
          or (m.offer_response is null and m.request_response is null and m.computed_at < v_run_at));
  perform set_config('kc.fsm_role', v_outer_role, true);

  insert into kc_private.match_state as s (post_id, computed_at, candidates)
  values (p_post_id, v_run_at, v_kept)
  on conflict (post_id) do update
    set computed_at = excluded.computed_at, candidates = excluded.candidates, last_error = null;
  return v_kept;
end;
$$;
comment on function kc_private.match_compute_for_post(uuid) is
  'Recomputes the matching pairs of one post; returns the number of live pairs it holds.';

-- >>> supabase/schemas/76_matching/050_match_processing.sql
-- Matching · triggering, the consumer of outbox topic `match`, announcements, re-rank
--
-- Nothing is matched or embedded while a member waits: a post write only records what has
-- to happen (design §5 "Trigger budget") and the work is done here, by a scheduled job, and
-- by the embed and re-rank Edge Functions.

-- Records the follow-up work of a post write:
--   topic `embedding`  { post_id }  the published text is new or changed
--   topic `match`      { post_id }  the post went on or off the air, or a field the score
--                                   reads changed while it is on the air
-- Two inserts at most, and none for a write that changes nothing either consumer reads.
create function kc_private.posts_enqueue_indexing()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_was_open constant boolean := tg_op = 'UPDATE' and old.status = 'open';
  v_text_changed constant boolean := tg_op = 'INSERT' or old.status = 'draft'
    or new.title is distinct from old.title or new.description is distinct from old.description;
begin
  if new.status <> 'draft' and v_text_changed then
    perform kc_private.outbox_enqueue('embedding', jsonb_build_object('post_id', new.id));
  end if;
  if new.post_type = 'standard'
     and ((new.status = 'open') <> v_was_open
          or (v_was_open and (v_text_changed
               or row(new.item_subcategory_id, new.time_window, new.visibility, new.geo_approx::text)
                  is distinct from
                  row(old.item_subcategory_id, old.time_window, old.visibility, old.geo_approx::text)))) then
    perform kc_private.outbox_enqueue('match', jsonb_build_object('post_id', new.id));
  end if;
  return null;
end;
$$;
comment on function kc_private.posts_enqueue_indexing() is
  'AFTER trigger on posts: enqueues the embedding refresh and the matching run a write calls for.';

create trigger posts_enqueue_indexing
  after insert or update of status, title, description, item_subcategory_id, time_window, visibility,
    city_id, location_display_level, geo_approx
  on public.posts
  for each row execute function kc_private.posts_enqueue_indexing();

-- Tells the owners of fresh, good pairs about them: one `match_suggested` notification per
-- owner per pair, best pairs first, at most `max_notify_per_user_day` per member per Israel
-- day (spec 07 §7.11). An owner who already answered is not told. Quiet hours and the
-- member's own switch for this kind are the notification module's business. Returns the
-- number of notifications recorded.
create function kc_private.match_announce(p_limit integer default 200)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_settings kc_private.matching_settings;
  v_day_start constant timestamptz :=
    date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem';
  v_pair kc_private.match_candidates;
  v_side record;
  v_sent integer := 0;
begin
  select s.* into v_settings from kc_private.matching_settings s;
  if not v_settings.enabled then
    return 0;
  end if;
  for v_pair in
    select m.* from kc_private.match_candidates m
     where m.status = 'suggested' and (m.notified_offer_at is null or m.notified_request_at is null)
       and m.computed_at > now() - make_interval(hours => v_settings.notify_max_age_hours)
       and kc_private.match_effective_score(m.score, m.llm_score) >= v_settings.notify_min_score
     order by m.score desc
     limit least(greatest(p_limit, 1), 1000)
       for update skip locked
  loop
    for v_side in
      select * from (values
        ('offer', v_pair.offer_owner_id, v_pair.request_post_id,
         v_pair.notified_offer_at is null and v_pair.offer_response is null),
        ('request', v_pair.request_owner_id, v_pair.offer_post_id,
         v_pair.notified_request_at is null and v_pair.request_response is null)
      ) as s (side, owner_id, other_post_id, due)
    loop
      continue when not v_side.due
        or (select count(*) from kc_private.match_candidates x
             where (x.offer_owner_id = v_side.owner_id and x.notified_offer_at >= v_day_start)
                or (x.request_owner_id = v_side.owner_id and x.notified_request_at >= v_day_start))
           >= v_settings.max_notify_per_user_day;
      perform kc_private.outbox_enqueue('notification', jsonb_build_object(
        'kind', 'match_suggested', 'recipient_id', v_side.owner_id, 'actor_id', null,
        'entity', jsonb_build_object('type', 'match', 'id', v_pair.id),
        'data', jsonb_build_object('post_id', v_side.other_post_id, 'world_slug', v_pair.world_slug,
                                   'dedupe_key', 'match_suggested:' || v_pair.id || ':' || v_side.side)));
      update kc_private.match_candidates m
         set notified_offer_at = case v_side.side when 'offer' then now() else m.notified_offer_at end,
             notified_request_at = case v_side.side when 'request' then now() else m.notified_request_at end
       where m.id = v_pair.id;
      v_sent := v_sent + 1;
    end loop;
  end loop;
  return v_sent;
end;
$$;
comment on function kc_private.match_announce(integer) is
  'Enqueues match_suggested notifications for unannounced pairs above the announce score, within the daily cap.';

-- Worker entry point: claims due `match` events, recomputes each named post once, confirms
-- the events, then announces. A failing post is released for a retry with its error and
-- does not stop the batch. Returns the number of events performed. Needs no service
-- outside the database, so it is run by a scheduled job.
create function kc_private.match_process(p_limit integer default 100)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event record;
  v_seen uuid[] := '{}';
  v_done integer := 0;
begin
  for v_event in
    select e.id, (e.payload ->> 'post_id')::uuid as post_id
      from kc_private.outbox_claim('match', p_limit) e order by e.id
  loop
    begin
      if v_event.post_id <> all (v_seen) then
        perform kc_private.match_compute_for_post(v_event.post_id);
        v_seen := v_seen || v_event.post_id;
      end if;
      perform kc_private.outbox_complete(v_event.id);
      v_done := v_done + 1;
    exception when others then
      perform kc_private.outbox_complete(v_event.id, sqlerrm);
      update kc_private.match_state s set last_error = sqlerrm where s.post_id = v_event.post_id;
    end;
  end loop;
  perform kc_private.match_announce();
  return v_done;
end;
$$;
comment on function kc_private.match_process(integer) is
  'Claims and performs a batch of match events, then announces new pairs; run by a scheduled job.';

-- ── Language-model re-rank (Edge Function `match-rerank`) ───────────────────────────────

-- Pairs waiting for an opinion, newest first; empty while the re-rank is switched off.
create function public.api_match_llm_pending(p_limit integer default 20)
returns table (
  candidate_id uuid, world_slug text, score numeric,
  offer_title text, offer_summary text, request_title text, request_summary text)
language sql
stable
security definer
set search_path = ''
as $$
  select m.id, m.world_slug, m.score, o.title, o.description, r.title, r.description
    from kc_private.match_candidates m
    join public.posts o on o.id = m.offer_post_id
    join public.posts r on r.id = m.request_post_id
   where m.status = 'suggested' and m.llm_scored_at is null
     and (select s.llm_rerank_enabled from kc_private.matching_settings s)
   order by m.computed_at desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;
comment on function public.api_match_llm_pending(integer) is
  'match-rerank: pairs without a language-model opinion. Service role only.';

-- Stores the opinion of a pair: a score 0..1 and a short reason.
--   invalid_input · match_not_found
create function public.api_match_llm_store(p_candidate_id uuid, p_score numeric, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_score is null or p_score not between 0 and 1 then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;
  update kc_private.match_candidates m
     set llm_score = p_score, llm_reason = left(nullif(btrim(p_reason), ''), 280), llm_scored_at = now()
   where m.id = p_candidate_id;
  if not found then
    raise exception 'match_not_found' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.api_match_llm_store(uuid, numeric, text) is
  'match-rerank: stores the language-model score and reason of a pair. Service role only.';

-- >>> supabase/schemas/76_matching/060_match_rpcs.sql
-- Matching · member RPCs: my matches, answering, similar posts, recommendations
--
-- The lists run with the caller's rights and return post cards, so RLS on `posts` decides
-- what comes back. Pairs and embeddings are not readable by a member, and a nearest-vector
-- search cannot run under RLS as an index scan (30_social/075), so three helpers in
-- `kc_access` resolve ids with definer rights; the caller then re-reads the posts under
-- RLS. A device cannot address `kc_access`, so unfiltered ids never leave the database.

-- The caller's live pairs: the ones they did not decline, mutual accepts first, then by
-- score. At most 50.
create function kc_access.my_match_rows(p_limit integer)
returns table (
  match_id uuid, status text, score numeric, distance_km numeric, world_slug text, my_role text,
  my_post_id uuid, other_post_id uuid, my_response text, other_response text, llm_reason text,
  created_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select m.id, m.status, kc_private.match_effective_score(m.score, m.llm_score), m.distance_km,
         m.world_slug, s.my_role,
         case s.my_role when 'offer' then m.offer_post_id else m.request_post_id end,
         case s.my_role when 'offer' then m.request_post_id else m.offer_post_id end,
         case s.my_role when 'offer' then m.offer_response else m.request_response end,
         case s.my_role when 'offer' then m.request_response else m.offer_response end,
         m.llm_reason, m.created_at
    from kc_private.match_candidates m
   cross join lateral (
     select case when m.offer_owner_id = (select auth.uid()) then 'offer' else 'request' end as my_role) s
   where m.status in ('suggested', 'accepted')
     and (m.offer_owner_id = (select auth.uid()) or m.request_owner_id = (select auth.uid()))
   order by (m.status = 'accepted') desc, 3 desc, m.id
   limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;
comment on function kc_access.my_match_rows(integer) is
  'The caller''s own matching pairs. The caller re-reads the posts under RLS.';
grant execute on function kc_access.my_match_rows(integer) to authenticated;

-- The caller's matches with the other member's post as a card. A pair whose other post
-- the caller can no longer read (closed, hidden, blocked) is left out; a pair both accepted
-- stays as long as the post is readable.
create function public.my_matches(p_limit integer default 20)
returns table (
  match_id uuid, status text, score numeric, distance_km numeric, world_slug text, my_role text,
  my_post_id uuid, my_post_title text, my_response text, other_response text, llm_reason text,
  created_at timestamptz, other_post public.post_card)
language sql
stable
security invoker
set search_path = ''
as $$
  with mine as materialized (select r.* from kc_access.my_match_rows(p_limit) r)
  select m.match_id, m.status, m.score, m.distance_km, m.world_slug, m.my_role, m.my_post_id, p.title,
         m.my_response, m.other_response, m.llm_reason, m.created_at, c
    from mine m
    join public.posts p on p.id = m.my_post_id
    join public.post_cards((select array_agg(x.other_post_id) from mine x)) c on c.id = m.other_post_id
   where m.status = 'accepted' or (p.status = 'open' and c.status = 'open')
   order by (m.status = 'accepted') desc, m.score desc, m.match_id;
$$;
comment on function public.my_matches(integer) is
  'The caller''s matching pairs, best first, each with the other member''s post as a card.';
grant execute on function public.my_matches(integer) to authenticated;

-- The caller answers a pair. A decline closes it for good and the two owners are not
-- paired again; an accept tells the other owner (`match_interest`), and the second accept
-- makes the pair `accepted` (`match_accepted`). Returns the pair's status.
--   match_not_found   no such pair, or not the caller's
--   match_not_open    the pair is already accepted, declined or expired
create function public.match_respond(p_match_id uuid, p_accept boolean)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_pair kc_private.match_candidates;
  v_is_offer boolean;
  v_other_id uuid;
  v_status text;
begin
  select m.* into v_pair from kc_private.match_candidates m
   where m.id = p_match_id and v_user_id in (m.offer_owner_id, m.request_owner_id)
     for update;
  if not found then
    raise exception 'match_not_found' using errcode = 'P0001';
  end if;
  if v_pair.status <> 'suggested' or p_accept is null then
    raise exception 'match_not_open' using errcode = 'P0001';
  end if;
  v_is_offer := v_user_id = v_pair.offer_owner_id;
  v_other_id := case when v_is_offer then v_pair.request_owner_id else v_pair.offer_owner_id end;
  v_status := case
    when not p_accept then 'declined'
    when (case when v_is_offer then v_pair.request_response else v_pair.offer_response end) = 'accepted'
      then 'accepted'
    else 'suggested' end;

  perform set_config('kc.fsm_role', 'member', true);
  update kc_private.match_candidates m
     set status = v_status,
         offer_response = case when v_is_offer then
           case when p_accept then 'accepted' else 'declined' end else m.offer_response end,
         offer_responded_at = case when v_is_offer then now() else m.offer_responded_at end,
         request_response = case when v_is_offer then m.request_response else
           case when p_accept then 'accepted' else 'declined' end end,
         request_responded_at = case when v_is_offer then m.request_responded_at else now() end
   where m.id = p_match_id;
  perform set_config('kc.fsm_role', '', true);

  if p_accept then
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', case v_status when 'accepted' then 'match_accepted' else 'match_interest' end,
      'recipient_id', v_other_id, 'actor_id', v_user_id,
      'entity', jsonb_build_object('type', 'match', 'id', p_match_id),
      'data', jsonb_build_object(
        'post_id', case when v_is_offer then v_pair.offer_post_id else v_pair.request_post_id end,
        'dedupe_key', 'match_response:' || p_match_id || ':' || v_user_id)));
  end if;
  return v_status;
end;
$$;
comment on function public.match_respond(uuid, boolean) is
  'The caller accepts or declines one of their matching pairs; returns the pair''s status.';
grant execute on function public.match_respond(uuid, boolean) to authenticated;

-- Open posts of the same giving world nearest in meaning to the post, nearest first; when
-- the post has no embedding yet, the newest ones sharing a word with its title.
create function kc_access.similar_post_ids(p_post_id uuid, p_limit integer)
returns uuid[]
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
  v_embedding extensions.vector;
  v_limit constant integer := least(greatest(coalesce(p_limit, 10), 1), 30);
begin
  select p.* into v_post from public.posts p where p.id = p_post_id;
  select e.embedding into v_embedding from public.post_embeddings e where e.post_id = p_post_id;
  if v_embedding is null then
    return array(
      select c.id from public.posts c
       where c.status = 'open' and c.world_slug = v_post.world_slug and c.id <> p_post_id
         and c.search_vector @@ kc_private.title_tsquery(v_post.title)
       order by c.published_at desc
       limit v_limit);
  end if;
  return array(
    select n.post_id
      from (select e.post_id, e.embedding operator(extensions.<=>) v_embedding as distance
              from public.post_embeddings e
             order by e.embedding operator(extensions.<=>) v_embedding
             limit 200) n
      join public.posts c on c.id = n.post_id
     where c.status = 'open' and c.world_slug = v_post.world_slug and c.id <> p_post_id
     order by n.distance
     limit v_limit);
end;
$$;
comment on function kc_access.similar_post_ids(uuid, integer) is
  'Candidate ids of posts similar to a post. The caller re-reads them under RLS.';
grant execute on function kc_access.similar_post_ids(uuid, integer) to authenticated;

-- "More like this" under a post: up to p_limit (at most 30) cards, most similar first.
-- Nothing is returned for a post the caller cannot read.
create function public.similar_posts(p_post_id uuid, p_limit integer default 10)
returns setof public.post_card
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_post_ids uuid[];
begin
  if not exists (select 1 from public.posts p where p.id = p_post_id) then
    return;
  end if;
  v_post_ids := kc_access.similar_post_ids(p_post_id, p_limit);
  return query
  select c.* from public.post_cards(v_post_ids) c order by array_position(v_post_ids, c.id);
end;
$$;
comment on function public.similar_posts(uuid, integer) is 'Posts similar to a post the caller can read, as cards.';
grant execute on function public.similar_posts(uuid, integer) to authenticated;

-- Open public posts nearest in meaning to what the caller recently saved or reacted to
-- (their last 20 of each), leaving out their own posts and the ones already saved or
-- reacted to. Empty until the caller has engaged with a post that has an embedding.
create function kc_access.recommended_post_ids(p_limit integer)
returns uuid[]
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
  v_taste extensions.vector;
begin
  select extensions.avg(e.embedding) into v_taste
    from ((select s.post_id from public.saved_posts s
            where s.user_id = v_user_id order by s.saved_at desc limit 20)
          union
          (select r.post_id from public.post_reactions r
            where r.user_id = v_user_id order by r.created_at desc limit 20)) liked
    join public.post_embeddings e on e.post_id = liked.post_id;
  if v_taste is null then
    return '{}';
  end if;
  return array(
    select n.post_id
      from (select e.post_id, e.embedding operator(extensions.<=>) v_taste as distance
              from public.post_embeddings e
             order by e.embedding operator(extensions.<=>) v_taste
             limit 200) n
      join public.posts c on c.id = n.post_id
     where c.status = 'open' and c.visibility = 'Public' and c.owner_id <> v_user_id
       and not exists (select 1 from public.saved_posts s where s.user_id = v_user_id and s.post_id = c.id)
       and not exists (select 1 from public.post_reactions r where r.user_id = v_user_id and r.post_id = c.id)
     order by n.distance
     limit least(greatest(coalesce(p_limit, 10), 1), 30));
end;
$$;
comment on function kc_access.recommended_post_ids(integer) is
  'Candidate ids of posts recommended to the caller. The caller re-reads them under RLS.';
grant execute on function kc_access.recommended_post_ids(integer) to authenticated;

-- "Recommended for you": up to p_limit (at most 30) cards, closest to the caller's taste first.
create function public.recommended_posts(p_limit integer default 10)
returns setof public.post_card
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_post_ids constant uuid[] := kc_access.recommended_post_ids(p_limit);
begin
  return query
  select c.* from public.post_cards(v_post_ids) c order by array_position(v_post_ids, c.id);
end;
$$;
comment on function public.recommended_posts(integer) is 'Posts recommended to the caller from what they saved and reacted to, as cards.';
grant execute on function public.recommended_posts(integer) to authenticated;

-- >>> supabase/schemas/76_matching/900_match_notification_kinds.sql
-- Matching · notification kinds emitted by this module
--
-- `match_suggested` (a new pair, kc_private.match_announce) is registered with the
-- registry itself (50_notifications/010). These are the two kinds of an answer
-- (public.match_respond): the other owner is interested, and both owners accepted. Both
-- are "important" like the suggestion itself (docs/SSOT/MATCHING_V2.md "Client").

insert into kc_private.notification_kinds (kind, category, title_key, body_key)
values
  ('match_interest', 'critical', 'notifications.matchInterestTitle', 'notifications.matchInterestBody'),
  ('match_accepted', 'critical', 'notifications.matchAcceptedTitle', 'notifications.matchAcceptedBody');

-- >>> supabase/schemas/78_translation/010_content_translations.sql
-- Translation · cache of translated user content (FR-TRANSLATE-002/003, docs/SSOT/UGC_TRANSLATION.md)
--
-- A text is translated only when a reader asks for it in a language, by the `translate`
-- Edge Function, and the result is kept here: one row per content, field and target
-- language. The function writes with the service role; a concurrent second writer of the
-- same key loses on the primary key (single flight). The cache never outlives its source:
-- an edit or a removal of the source row purges its translations.

create table public.content_translations (
  -- What was translated. The id is the source row's id; there is no foreign key because
  -- the source is one of four tables — the triggers below keep the cache in step.
  content_type    text not null check (content_type in ('post', 'comment', 'message', 'user')),
  content_id      uuid not null,
  field           text not null check (field in ('title', 'description', 'body', 'biography')),
  -- BCP 47 tag the text was translated into.
  target_language text not null check (char_length(target_language) between 2 and 35),
  source_language text check (char_length(source_language) between 2 and 35),
  translated_text text not null check (char_length(translated_text) between 1 and 8000),
  -- Provider model that produced the text.
  model           text check (char_length(model) between 1 and 100),
  confidence      real check (confidence between 0 and 1),
  created_at      timestamptz not null default now(),
  -- The cache key; its prefix serves the purge of one source row and the batched read.
  primary key (content_type, content_id, field, target_language),
  -- Each kind of content has its own translatable fields.
  constraint content_translations_field_chk check (case content_type
    when 'post' then field in ('title', 'description')
    when 'user' then field = 'biography'
    else field = 'body' end)
);
comment on table public.content_translations is
  'Demand-driven cache of translated posts, comments, messages and biographies. Written by the service role.';

alter table public.content_translations enable row level security;
alter table public.content_translations force row level security;

-- A translation is readable exactly when its source row is: each subquery runs under the
-- caller's own access to the source table (audience, blocks, moderation). One policy per
-- kind of content. Message translations have no policy: chat translation is opt-in per
-- sender and not released yet (FR-TRANSLATE-004), so they are readable by nobody.
create policy content_translations_select_post on public.content_translations
  for select to authenticated
  using (content_type = 'post'
         and exists (select 1 from public.posts p where p.id = content_translations.content_id));
create policy content_translations_select_comment on public.content_translations
  for select to authenticated
  using (content_type = 'comment'
         and exists (select 1 from public.post_comments c
                      where c.id = content_translations.content_id and c.status = 'active'));
create policy content_translations_select_user on public.content_translations
  for select to authenticated
  using (content_type = 'user'
         and exists (select 1 from public.users u where u.id = content_translations.content_id));

grant select on public.content_translations to authenticated;
-- The translate function reads, inserts and (to replace a bad row) deletes.
grant select, insert, delete on public.content_translations to service_role;

-- Removes the cached translations of the source row. The content type is the trigger's
-- argument; the row's id is `id` in all four source tables.
create function kc_private.content_translations_purge()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.content_translations t
   where t.content_type = tg_argv[0] and t.content_id = old.id;
  return null;
end;
$$;
comment on function kc_private.content_translations_purge() is
  'AFTER trigger on a source table: drops the cached translations of an edited or removed row.';

-- Posts: an edit of the text (FR-TRANSLATE-003 AC10), a removal by moderation and the
-- deletion of the row (FR-TRANSLATE-002 AC3). The condition keeps ordinary writes free.
create trigger posts_purge_translations_on_edit
  after update of title, description, status on public.posts
  for each row
  when (new.title is distinct from old.title or new.description is distinct from old.description
        or (new.status = 'removed_admin' and old.status <> 'removed_admin'))
  execute function kc_private.content_translations_purge('post');
create trigger posts_purge_translations_on_delete
  after delete on public.posts
  for each row execute function kc_private.content_translations_purge('post');

-- Comments: an edit of the body, any move out of `active`, and the deletion of the row.
create trigger post_comments_purge_translations_on_edit
  after update of body, status on public.post_comments
  for each row
  when (new.body is distinct from old.body or (new.status <> 'active' and old.status = 'active'))
  execute function kc_private.content_translations_purge('comment');
create trigger post_comments_purge_translations_on_delete
  after delete on public.post_comments
  for each row execute function kc_private.content_translations_purge('comment');

-- Messages are immutable, so only their deletion purges.
create trigger messages_purge_translations_on_delete
  after delete on public.messages
  for each row execute function kc_private.content_translations_purge('message');

-- Biographies: an edit, and the removal of the member.
create trigger users_purge_translations_on_edit
  after update of biography on public.users
  for each row
  when (new.biography is distinct from old.biography)
  execute function kc_private.content_translations_purge('user');
create trigger users_purge_translations_on_delete
  after delete on public.users
  for each row execute function kc_private.content_translations_purge('user');

-- Cached translations of the listed posts in one language, in one round trip (cache hits
-- only; a missing row means "not translated yet"). Runs with the caller's rights: the
-- policy above leaves out every post the caller cannot read. At most 100 posts.
create function public.get_post_translations(p_post_ids uuid[], p_target_language text)
returns table (
  post_id uuid, field text, translated_text text, source_language text, confidence real)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.content_id, t.field, t.translated_text, t.source_language, t.confidence
    from public.content_translations t
   where t.content_type = 'post'
     and t.content_id = any (p_post_ids[1:100])
     and t.target_language = p_target_language;
$$;
comment on function public.get_post_translations(uuid[], text) is
  'Cached translations of posts the caller can read, for one target language.';
grant execute on function public.get_post_translations(uuid[], text) to authenticated;

-- >>> supabase/schemas/79_activity_stats/010_user_active_days.sql
-- Activity · active days (FR-SETTINGS-016 AC10)
--
-- One row per member per Israel calendar day on which they opened the app signed in. It
-- feeds survey prompt eligibility ("active on 2 of the last 14 days") and retention
-- reports; nothing reads it from a device, so it lives outside the API schema.
--
-- Recording is its own call, not part of bootstrap_session(): the app marks the day on
-- every return to the foreground, long after the session started, and bootstrap_session
-- stays a read-only (STABLE) function that is safe to retry and to serve from a replica.

create table kc_private.user_active_days (
  user_id   uuid not null references public.users (id) on delete cascade,
  active_on date not null,
  -- Also the range read "days of a member in the last 14".
  primary key (user_id, active_on)
);
comment on table kc_private.user_active_days is
  'Israel calendar days on which a member opened the app while signed in.';

-- Retention job: rows older than the retention window.
create index user_active_days_day_idx on kc_private.user_active_days (active_on);

alter table kc_private.user_active_days enable row level security;
alter table kc_private.user_active_days force row level security;

-- Marks the caller active today. Called on app open and on every return to the
-- foreground; repeating it within the day writes nothing.
create function public.record_active_day()
returns void
language sql
security definer
set search_path = ''
as $$
  insert into kc_private.user_active_days (user_id, active_on)
  select u.id, (now() at time zone 'Asia/Jerusalem')::date
    from public.users u
   where u.id = kc_private.require_caller()
  on conflict do nothing;
$$;
comment on function public.record_active_day() is 'Marks the caller active on the current Israel calendar day.';
grant execute on function public.record_active_day() to authenticated;

-- Distinct active days of a member in the 14 days ending today (Israel time).
create function kc_private.user_active_days_14d(p_user_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
    from kc_private.user_active_days d
   where d.user_id = p_user_id
     and d.active_on > (now() at time zone 'Asia/Jerusalem')::date - 14;
$$;
comment on function kc_private.user_active_days_14d(uuid) is
  'Number of days a member was active in the last 14 Israel calendar days.';

-- Deletes rows older than 400 days; returns how many. Run by a scheduled job.
create function kc_private.user_active_days_purge()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_deleted integer;
begin
  delete from kc_private.user_active_days d
   where d.active_on < (now() at time zone 'Asia/Jerusalem')::date - 400;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;
comment on function kc_private.user_active_days_purge() is 'Retention of active days: removes rows older than 400 days.';

-- >>> supabase/schemas/79_activity_stats/020_activity_and_community.sql
-- Activity · personal timeline and community numbers (FR-STATS-003, FR-STATS-004)

-- ── Personal activity timeline ───────────────────────────────────────────────────────────
-- The caller's recent activity, newest first (FR-STATS-003: up to 30 entries). It is read
-- from the rows that already record what happened — the caller's posts and the handoffs
-- they received — instead of a second log table: a log would repeat that state, need one
-- more trigger on every post write (design §5 "Trigger budget") and its own purge on
-- deletion. The price: each post shows its history as it stands — a closure that was later
-- reopened is no longer listed, and there is no separate "reopened" entry.
--   post_created               the caller published the post
--   post_closed_delivered      … closed it as delivered
--   post_closed_no_recipient   … closed it without a recipient
--   post_expired · post_removed_admin
--   marked_as_recipient        the owner (actor) handed the post over to the caller
--   unmarked_as_recipient      the caller removed their recipient mark
-- Runs with the caller's rights: every row is one the caller may already read. A handoff
-- whose post the caller can no longer read is listed without a title.
create function public.my_activity_timeline(p_limit integer default 30)
returns table (
  kind text, post_id uuid, post_title text, actor_id uuid, actor_display_name text,
  occurred_at timestamptz)
language sql
stable
security invoker
set search_path = ''
as $$
  with me as (select (select auth.uid()) as id, least(greatest(coalesce(p_limit, 30), 1), 100) as n),
  entries as (
    (select 'post_created' as kind, p.id as post_id, null::uuid as actor_id, p.published_at as occurred_at
       from public.posts p, me
      where p.owner_id = me.id and p.published_at is not null
      order by p.published_at desc
      limit (select n from me))
    union all
    -- A closed, expired or removed post is locked, so its last update is the status move;
    -- a post closed without a recipient carries the exact time in its purge deadline.
    (select case p.status when 'closed_delivered' then 'post_closed_delivered'
                          when 'deleted_no_recipient' then 'post_closed_no_recipient'
                          when 'expired' then 'post_expired'
                          else 'post_removed_admin' end,
            p.id, null::uuid, coalesce(c.purge_after - interval '7 days', p.updated_at)
       from public.posts p
       cross join me
       left join public.post_closures c on c.post_id = p.id and p.status = 'deleted_no_recipient'
      where p.owner_id = me.id
        and p.status in ('closed_delivered', 'deleted_no_recipient', 'expired', 'removed_admin')
      order by p.updated_at desc
      limit (select n from me))
    union all
    (select case h.status when 'handed_over' then 'marked_as_recipient' else 'unmarked_as_recipient' end,
            h.post_id, case h.status when 'handed_over' then h.owner_id end,
            coalesce(h.handed_over_at, h.cancelled_at)
       from public.post_handoffs h, me
      where h.recipient_id = me.id
        and (h.status = 'handed_over' or (h.status = 'cancelled' and h.cancel_reason = 'unmarked'))
      order by h.created_at desc
      limit (select n from me))
  )
  select e.kind, e.post_id, p.title, e.actor_id, u.display_name, e.occurred_at
    from entries e
    left join public.posts p on p.id = e.post_id
    left join public.users u on u.id = e.actor_id
   order by e.occurred_at desc, e.post_id
   limit (select n from me);
$$;
comment on function public.my_activity_timeline(integer) is
  'The caller''s recent activity (posts published and closed, handoffs received), newest first.';
grant execute on function public.my_activity_timeline(integer) to authenticated;

-- ── Community numbers ────────────────────────────────────────────────────────────────────
-- Three numbers for the whole community (FR-STATS-004 AC1). Counting them is a job's work,
-- once a minute, not a reader's: every reader gets the one stored row.
create table kc_private.community_stats (
  id                   boolean primary key default true check (id),
  -- Members with an active account.
  registered_users     bigint not null default 0 check (registered_users >= 0),
  -- Open posts shown to everyone.
  open_public_posts    bigint not null default 0 check (open_public_posts >= 0),
  -- Posts closed as delivered, all time.
  delivered_posts      bigint not null default 0 check (delivered_posts >= 0),
  refreshed_at         timestamptz not null default now()
);
comment on table kc_private.community_stats is 'Community-wide counters (one row), refreshed by a scheduled job.';

alter table kc_private.community_stats enable row level security;
alter table kc_private.community_stats force row level security;

-- Recounts the three numbers. The first two are index-only counts over partial indexes
-- (users_city_idx, posts_feed_recent_idx). Run by a scheduled job.
create function kc_private.community_stats_refresh()
returns void
language sql
security definer
set search_path = ''
as $$
  insert into kc_private.community_stats as s (id, registered_users, open_public_posts, delivered_posts)
  values (
    true,
    (select count(*) from public.users u where u.is_active),
    (select count(*) from public.posts p where p.status = 'open' and p.visibility = 'Public'),
    (select count(*) from public.posts p where p.status = 'closed_delivered'))
  on conflict (id) do update
    set registered_users = excluded.registered_users, open_public_posts = excluded.open_public_posts,
        delivered_posts = excluded.delivered_posts, refreshed_at = now();
$$;
comment on function kc_private.community_stats_refresh() is 'Recounts the community counters into their single row.';

-- The community numbers for any signed-in member: counts only, nobody is identified
-- (FR-STATS-006 AC2). Zeros with a null `refreshed_at` until the first refresh.
create function public.community_stats()
returns table (registered_users bigint, open_public_posts bigint, delivered_posts bigint, refreshed_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(s.registered_users, 0), coalesce(s.open_public_posts, 0),
         coalesce(s.delivered_posts, 0), s.refreshed_at
    from (select kc_private.require_caller()) caller
    left join kc_private.community_stats s on true;
$$;
comment on function public.community_stats() is 'Community-wide counters: active members, open public posts, delivered posts.';
grant execute on function public.community_stats() to authenticated;

-- >>> supabase/schemas/80_organizations/010_organizations.sql
-- Organizations · organizations (spec 08, requirements/20 FR-ORG-001, requirements/19 FR-FIN-007/022)
--
-- One row per organization; Karma Community itself is the platform organization (D76).
-- The row is the public profile: nothing on it is private, so every signed-in member may
-- read an active organization. Three independent facts live here and are written only by
-- server code: the lifecycle status, the verification (D53) and the Section 46(a) approval
-- the organization holds (D77 — recorded, never decided by the product).
-- Not part of this baseline (FR-ORG phase 1–3, not built): organization sign-in accounts,
-- acting as an organization, following organizations, claiming catalog entries.

insert into kc_private.fsm_state (machine_id, status) values
  ('organization', 'active'), ('organization', 'suspended');
-- Only platform staff suspend and reinstate an organization (FR-ORG roles).
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('organization', 'active', 'suspended', 'admin'),
  ('organization', 'suspended', 'active', 'admin');

create table public.organizations (
  id                    uuid primary key default gen_random_uuid(),
  -- Stable identifier of the public page link.
  slug                  text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+){0,9}$' and char_length(slug) <= 60),
  name                  text not null check (char_length(btrim(name)) between 2 and 120),
  -- The organization that runs the product; exactly one row.
  is_platform           boolean not null default false,
  -- D57 / D89: a private person may register; the registration number is optional.
  org_type              text check (org_type in ('nonprofit_association', 'public_benefit_company', 'public_body',
                                                 'informal_initiative', 'private_venture')),
  registration_number   text check (registration_number ~ '^[0-9]{5,12}$'),
  -- Lifecycle, machine `organization`. A suspended organization is hidden from members.
  status                text not null default 'active',
  -- D53: 1 basic (the registration condition) … 5 effectiveness. Set by platform staff.
  verification_level    smallint not null default 1 check (verification_level between 1 and 5),
  verification_method   text check (verification_method in ('manual', 'document', 'registrar')),
  verified_at           timestamptz,
  verified_by           uuid references public.users (id) on delete set null,
  -- A verified nonprofit may receive donations through the product (D4, D20).
  is_verified_nonprofit boolean not null default false,
  -- Public profile texts, Hebrew and English.
  public_tagline_he     text check (char_length(public_tagline_he) <= 160),
  public_tagline_en     text check (char_length(public_tagline_en) <= 160),
  public_about_he       text check (char_length(public_about_he) <= 4000),
  public_about_en       text check (char_length(public_about_en) <= 4000),
  website_url           text check (website_url ~* '^https://' and char_length(website_url) <= 2000),
  contact_email         text check (char_length(contact_email) <= 320),
  city_id               text references public.cities (city_id),
  -- Section 46(a) approval held by the organization (FR-FIN-007). `active` needs the
  -- approval number and both dates; a receipt is tax-eligible only inside the validity.
  sec46_status          text not null default 'none'
                          check (sec46_status in ('none', 'pending', 'active', 'expired', 'revoked')),
  sec46_approval_number text check (char_length(sec46_approval_number) between 1 and 40),
  sec46_valid_from      date,
  sec46_valid_until     date,
  -- Which live finance blocks the public page shows (FR-FIN-022, D111). All off by default.
  show_totals             boolean not null default false,
  show_donations_count    boolean not null default false,
  show_program_ratio      boolean not null default false,
  show_category_breakdown boolean not null default false,
  show_monthly_trend      boolean not null default false,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint organizations_sec46_active_chk check (
    sec46_status <> 'active'
    or (sec46_approval_number is not null and sec46_valid_from is not null
        and sec46_valid_until >= sec46_valid_from)),
  constraint organizations_verified_chk check ((verified_at is null) = (verification_method is null))
);
comment on table public.organizations is
  'Organizations and their public profile, verification and Section 46(a) record. Karma Community is the platform organization.';

-- There is one platform organization.
create unique index organizations_single_platform_key on public.organizations (is_platform) where is_platform;
-- FR-ORG-002 AC3: a registration number belongs to one organization.
create unique index organizations_registration_number_key on public.organizations (registration_number)
  where registration_number is not null;
-- Money hub list of verified nonprofits, by name (keyset on name, id).
create index organizations_verified_nonprofit_idx on public.organizations (name, id)
  where is_verified_nonprofit and status = 'active';
-- Organization search by name (substring match).
create index organizations_name_trgm_idx on public.organizations using gin (name extensions.gin_trgm_ops);
-- Foreign keys.
create index organizations_city_idx on public.organizations (city_id) where city_id is not null;
create index organizations_verified_by_idx on public.organizations (verified_by) where verified_by is not null;

create trigger organizations_set_updated_at
  before update on public.organizations
  for each row execute function kc_private.set_updated_at();
create trigger organizations_status_fsm
  before insert or update of status on public.organizations
  for each row execute function kc_private.fsm_guard_status('organization', 'status');

alter table public.organizations enable row level security;
alter table public.organizations force row level security;

-- Every signed-in member reads active organizations. Members of a suspended organization
-- and platform staff read it too (policies in 020_org_memberships.sql). Nothing for
-- signed-out callers (design §12.1).
create policy organizations_select_active on public.organizations
  for select to authenticated
  using (status = 'active');

grant select on public.organizations to authenticated;
-- Profile texts only; who may edit them is decided by the policy of the memberships file.
-- Name, slug, type, status, verification, Section 46(a) and the finance switches change
-- through RPCs.
grant update (public_tagline_he, public_tagline_en, public_about_he, public_about_en, website_url,
              contact_email, city_id)
  on public.organizations to authenticated;

-- The privileged facts of an organization are audited whoever writes them: its creation,
-- status, verification and Section 46(a) record.
create function kc_private.audit_organization()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.audit_record(
    case when tg_op = 'INSERT' then 'org_create'
         when old.status <> new.status then 'org_status_changed'
         when old.sec46_status <> new.sec46_status then 'finance_sec46_set'
         else 'org_verification_set' end,
    'organization', new.id,
    jsonb_build_object('status', new.status, 'verification_level', new.verification_level,
                       'is_verified_nonprofit', new.is_verified_nonprofit, 'sec46_status', new.sec46_status));
  return null;
end;
$$;

create trigger organizations_audit_insert
  after insert on public.organizations
  for each row execute function kc_private.audit_organization();
create trigger organizations_audit_update
  after update of status, verification_level, is_verified_nonprofit, sec46_status, sec46_valid_until
  on public.organizations
  for each row
  when ((old.status, old.verification_level, old.is_verified_nonprofit, old.sec46_status, old.sec46_valid_until)
        is distinct from
        (new.status, new.verification_level, new.is_verified_nonprofit, new.sec46_status, new.sec46_valid_until))
  execute function kc_private.audit_organization();

-- >>> supabase/schemas/80_organizations/020_org_memberships.sql
-- Organizations · memberships and the organization predicates
--
-- Who belongs to which organization, and in which roles. The roles themselves have one
-- writer: the organization-scoped grants of public.admin_role_grants (hierarchy, granting
-- rules and audit live there — FR-ADMIN-016, D85, D86). This table is their projection,
-- one row per member and organization, kept by trigger: it is what policies and RPCs read,
-- and it carries the one membership setting that is not a role (`can_post`).
--
-- Roles and what they allow (requirements/20 § Roles, requirements/19 § Roles):
--   manage the organization — edit its profile, edit and delete its posts (design §12.1):
--       org_admin, org_manager
--   publish in its name: org_admin, org_manager, org_employee, volunteer_manager, and an
--       org_volunteer whose `can_post` is on
--   finance: org_admin and org_treasurer keep the books, org_accountant reads them

-- Finance roles of an organization (FR-FIN-002). A holder grants only roles below their
-- own rank (FR-ADMIN-027), so a treasurer grants accountants, not other treasurers.
insert into kc_private.admin_roles (role, rank, is_platform, grantable_roles) values
  ('org_treasurer', 60, false, array['org_accountant']),
  ('org_accountant', 35, false, '{}');
update kc_private.admin_roles
   set grantable_roles = grantable_roles || array['org_treasurer', 'org_accountant']
 where role in ('super_admin', 'admin', 'org_admin');

-- The open foreign key of the grants table (see 60_moderation/010_admin_roles.sql; its
-- index is admin_role_grants_scope_idx). A grant has no meaning without its organization.
alter table public.admin_role_grants
  add constraint admin_role_grants_scope_org_fk
  foreign key (scope_org_id) references public.organizations (id) on delete cascade;

create table public.org_memberships (
  org_id     uuid not null references public.organizations (id) on delete cascade,
  user_id    uuid not null references public.users (id) on delete cascade,
  -- Active organization roles of the member, most senior first. Written by trigger only.
  roles      text[] not null check (cardinality(roles) >= 1),
  -- Lets a volunteer publish in the organization's name (FR-ORG roles table).
  can_post   boolean not null default false,
  joined_at  timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (org_id, user_id)
);
comment on table public.org_memberships is
  'Members of an organization with their active roles; a projection of the organization-scoped role grants.';

-- "My organizations" and every predicate below; covers the member foreign key.
create index org_memberships_user_idx on public.org_memberships (user_id);

create trigger org_memberships_set_updated_at
  before update on public.org_memberships
  for each row execute function kc_private.set_updated_at();

-- Rebuilds the membership of one member in one organization from their active grants.
create function kc_private.org_membership_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_grant constant public.admin_role_grants := case when tg_op = 'DELETE' then old else new end;
  v_roles text[];
begin
  select array_agg(g.role order by r.rank desc, g.role) into v_roles
    from public.admin_role_grants g
    join kc_private.admin_roles r on r.role = g.role
   where g.user_id = v_grant.user_id and g.scope_org_id = v_grant.scope_org_id and g.revoked_at is null;

  if v_roles is null then
    delete from public.org_memberships m where m.org_id = v_grant.scope_org_id and m.user_id = v_grant.user_id;
  -- A cascade from a removed organization or member must not re-create the row.
  elsif exists (select 1 from public.organizations o where o.id = v_grant.scope_org_id)
        and exists (select 1 from public.users u where u.id = v_grant.user_id) then
    insert into public.org_memberships (org_id, user_id, roles)
    values (v_grant.scope_org_id, v_grant.user_id, v_roles)
    on conflict (org_id, user_id) do update set roles = excluded.roles;
  end if;
  return null;
end;
$$;

create trigger admin_role_grants_sync_membership
  after insert or delete or update of revoked_at on public.admin_role_grants
  for each row execute function kc_private.org_membership_sync();

-- ── Predicates ──────────────────────────────────────────────────────────────
-- Each returns the caller's organizations as an array, so a policy compares a column with
-- one value computed once per statement. Definer rights: they are evaluated inside
-- policies of tables the caller cannot read freely. An inactive account holds nothing.

create function kc_access.member_org_ids()
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(m.org_id), '{}')
    from public.org_memberships m
    join public.users u on u.id = m.user_id and u.is_active
   where m.user_id = (select auth.uid());
$$;
comment on function kc_access.member_org_ids() is 'Policy predicate: organizations the caller is a member of.';
grant execute on function kc_access.member_org_ids() to authenticated;

create function kc_access.managed_org_ids()
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(m.org_id), '{}')
    from public.org_memberships m
    join public.users u on u.id = m.user_id and u.is_active
   where m.user_id = (select auth.uid())
     and m.roles && array['org_admin', 'org_manager'];
$$;
comment on function kc_access.managed_org_ids() is
  'Policy predicate: organizations the caller administers (org_admin or org_manager).';
grant execute on function kc_access.managed_org_ids() to authenticated;

-- May the caller publish in the organization's name (`org.act_as`)? The organization must
-- be active.
create function kc_private.can_act_as_org(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.org_memberships m
      join public.users u on u.id = m.user_id and u.is_active
      join public.organizations o on o.id = m.org_id and o.status = 'active'
     where m.org_id = p_org_id and m.user_id = (select auth.uid())
       and (m.roles && array['org_admin', 'org_manager', 'org_employee', 'volunteer_manager']
            or (m.can_post and 'org_volunteer' = any (m.roles))));
$$;
comment on function kc_private.can_act_as_org(uuid) is
  'The caller may publish in the name of this active organization.';

-- ── Access ──────────────────────────────────────────────────────────────────
alter table public.org_memberships enable row level security;
alter table public.org_memberships force row level security;

-- A member reads their own memberships; the administrators of an organization and
-- platform staff read its roster. Other members never see who belongs to an organization.
create policy org_memberships_select_own on public.org_memberships
  for select to authenticated
  using (user_id = (select auth.uid()));
create policy org_memberships_select_managers on public.org_memberships
  for select to authenticated
  using (org_id = any ((select kc_access.managed_org_ids())::uuid[]) or (select kc_access.is_admin()));
-- The administrators switch a volunteer's publishing right; the column grant allows nothing else.
create policy org_memberships_update_managers on public.org_memberships
  for update to authenticated
  using (org_id = any ((select kc_access.managed_org_ids())::uuid[]))
  with check (org_id = any ((select kc_access.managed_org_ids())::uuid[]));

grant select on public.org_memberships to authenticated;
grant update (can_post) on public.org_memberships to authenticated;

-- Organizations: members and platform staff also read a suspended organization; the
-- administrators and platform admins edit the profile texts (`org.profile.edit`).
create policy organizations_select_member_or_staff on public.organizations
  for select to authenticated
  using (id = any ((select kc_access.member_org_ids())::uuid[]) or (select kc_access.is_admin()));
create policy organizations_update_managers on public.organizations
  for update to authenticated
  using (id = any ((select kc_access.managed_org_ids())::uuid[]) or (select kc_access.has_admin_role('admin')))
  with check (id = any ((select kc_access.managed_org_ids())::uuid[]) or (select kc_access.has_admin_role('admin')));

-- >>> supabase/schemas/80_organizations/030_org_applications.sql
-- Organizations · registration applications and their review (FR-ORG-002, D53, D57, D89)
--
-- A member applies to register an organization; platform staff approve or reject. The
-- approval creates the organization (verified at level 1, D53) and makes the applicant its
-- first org_admin, in one transaction. A decision is final; after a rejection the member
-- may file a new application.

insert into kc_private.fsm_state (machine_id, status) values
  ('org_application', 'pending'), ('org_application', 'approved'), ('org_application', 'rejected');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('org_application', 'pending', 'approved', 'admin'),
  ('org_application', 'pending', 'rejected', 'admin');

create table public.org_applications (
  id                  uuid primary key default gen_random_uuid(),
  applicant_id        uuid not null references public.users (id) on delete cascade,
  org_name            text not null check (char_length(btrim(org_name)) between 2 and 120),
  org_type            text not null check (org_type in ('nonprofit_association', 'public_benefit_company',
                                                        'public_body', 'informal_initiative', 'private_venture')),
  -- Optional (D89): any non-profit organization may register.
  registration_number text check (registration_number ~ '^[0-9]{5,12}$'),
  org_description     text check (char_length(org_description) <= 4000),
  contact_email       text check (char_length(contact_email) <= 320),
  contact_phone       text check (char_length(contact_phone) <= 20),
  website_url         text check (website_url ~* '^https://' and char_length(website_url) <= 2000),
  -- FR-ORG-002 AC2: the applicant declares that the organization is not for profit.
  declared_nonprofit  boolean not null check (declared_nonprofit),
  -- Lifecycle, machine `org_application`. Never written by a device.
  status              text not null default 'pending',
  reviewed_by         uuid references public.users (id) on delete set null,
  reviewed_at         timestamptz,
  -- Shown to the applicant as written (requirements/20 O4).
  review_note         text check (char_length(review_note) <= 2000),
  -- The organization an approval created.
  organization_id     uuid references public.organizations (id) on delete set null,
  created_at          timestamptz not null default now(),
  constraint org_applications_decision_chk check ((status = 'pending') = (reviewed_at is null))
);
comment on table public.org_applications is 'Applications to register an organization and their review.';

-- A member has one application waiting at a time; also "my applications".
create unique index org_applications_one_pending_key on public.org_applications (applicant_id)
  where status = 'pending';
create index org_applications_applicant_idx on public.org_applications (applicant_id, created_at desc);
-- Staff review queue: by status, oldest first (keyset on created_at, id).
create index org_applications_queue_idx on public.org_applications (status, created_at, id);
-- Foreign keys.
create index org_applications_reviewed_by_idx on public.org_applications (reviewed_by) where reviewed_by is not null;
create index org_applications_organization_idx on public.org_applications (organization_id)
  where organization_id is not null;

create trigger org_applications_status_fsm
  before insert or update of status on public.org_applications
  for each row execute function kc_private.fsm_guard_status('org_application', 'status');

alter table public.org_applications enable row level security;
alter table public.org_applications force row level security;

-- The applicant reads their own applications; platform admins read the queue.
create policy org_applications_select_own on public.org_applications
  for select to authenticated
  using (applicant_id = (select auth.uid()));
create policy org_applications_select_reviewers on public.org_applications
  for select to authenticated
  using ((select kc_access.has_admin_role('admin')));
-- A member with an active account files their own application; the column grant leaves the
-- status and the review fields to the server.
create policy org_applications_insert_own on public.org_applications
  for insert to authenticated
  with check (applicant_id = (select auth.uid())
              and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active));

grant select on public.org_applications to authenticated;
grant insert (id, applicant_id, org_name, org_type, registration_number, org_description, contact_email,
              contact_phone, website_url, declared_nonprofit)
  on public.org_applications to authenticated;

insert into kc_private.notification_kinds (kind, category, title_key, body_key) values
  -- requirements/20 § Data model: the applicant learns the decision.
  ('org_application_decided', 'critical', 'notifications.orgApplicationDecidedTitle',
   'notifications.orgApplicationDecidedBody');

-- Decides a pending application as a platform admin (`org.review_applications`: super
-- admin and admin). Approving needs the slug of the new organization's page. Returns the
-- new organization's id, or null for a rejection.
-- Errors: forbidden (42501); P0001 application_not_found, application_already_decided,
-- slug_required, slug_taken, org_registration_number_taken.
create function kc_private.org_application_decide(p_application_id uuid, p_approve boolean, p_slug text, p_note text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('admin');
  v_application public.org_applications;
  v_org_id uuid;
begin
  select a.* into v_application from public.org_applications a where a.id = p_application_id for update;
  if not found then
    raise exception 'application_not_found' using errcode = 'P0001';
  elsif v_application.status <> 'pending' then
    raise exception 'application_already_decided' using errcode = 'P0001';
  end if;

  if p_approve then
    if nullif(btrim(p_slug), '') is null then
      raise exception 'slug_required' using errcode = 'P0001';
    end if;
    begin
      insert into public.organizations (slug, name, org_type, registration_number, public_about_he, website_url,
                                        contact_email, verification_method, verified_at, verified_by)
      values (btrim(p_slug), btrim(v_application.org_name), v_application.org_type,
              v_application.registration_number, v_application.org_description, v_application.website_url,
              v_application.contact_email, 'manual', now(), v_actor)
      returning id into v_org_id;
    exception when unique_violation then
      raise exception '%', case when exists (select 1 from public.organizations o where o.slug = btrim(p_slug))
                                then 'slug_taken' else 'org_registration_number_taken' end
        using errcode = 'P0001';
    end;
    -- The applicant administers the new organization; the membership row follows the grant.
    insert into public.admin_role_grants (user_id, role, scope_org_id, granted_by, manager_grant_id)
    values (v_application.applicant_id, 'org_admin', v_org_id, v_actor,
            kc_private.admin_granting_grant(v_actor, 'org_admin', v_org_id));
  end if;

  perform set_config('kc.fsm_role', 'admin', true);
  update public.org_applications a
     set status = case when p_approve then 'approved' else 'rejected' end,
         reviewed_by = v_actor, reviewed_at = now(), review_note = nullif(btrim(p_note), ''),
         organization_id = v_org_id
   where a.id = p_application_id;
  perform set_config('kc.fsm_role', '', true);

  perform kc_private.audit_record(
    case when p_approve then 'org_application_approve' else 'org_application_reject' end,
    'org_application', p_application_id,
    jsonb_build_object('applicant_id', v_application.applicant_id, 'organization_id', v_org_id));
  perform kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', 'org_application_decided', 'recipient_id', v_application.applicant_id, 'actor_id', null,
    'entity', jsonb_build_object('type', 'org_application', 'id', p_application_id),
    'data', jsonb_build_object('approved', p_approve, 'organization_id', v_org_id,
                               'dedupe_key', 'org_application_decided:' || p_application_id)));
  return v_org_id;
end;
$$;

create function public.admin_org_application_approve(p_application_id uuid, p_slug text, p_note text default null)
returns uuid
language sql
security definer
set search_path = ''
as $$
  select kc_private.org_application_decide(p_application_id, true, p_slug, p_note);
$$;
comment on function public.admin_org_application_approve(uuid, text, text) is
  'Platform admin: approves an application, creating the organization and its first org_admin; returns the organization id.';
grant execute on function public.admin_org_application_approve(uuid, text, text) to authenticated;

create function public.admin_org_application_reject(p_application_id uuid, p_note text default null)
returns void
language sql
security definer
set search_path = ''
as $$
  select kc_private.org_application_decide(p_application_id, false, null, p_note);
$$;
comment on function public.admin_org_application_reject(uuid, text) is
  'Platform admin: rejects an application; the note is shown to the applicant.';
grant execute on function public.admin_org_application_reject(uuid, text) to authenticated;

-- Sets the verification of an organization (FR-ORG-019: levels are set by platform admins)
-- and whether it is a verified nonprofit that may receive donations.
-- Errors: forbidden (42501); P0001 org_not_found; 23514 for a level outside 1–5.
create function public.admin_set_org_verification(
  p_org_id uuid,
  p_level smallint,
  p_is_verified_nonprofit boolean,
  p_method text default 'manual'
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('admin');
begin
  update public.organizations o
     set verification_level = p_level, is_verified_nonprofit = p_is_verified_nonprofit,
         verification_method = p_method, verified_at = now(), verified_by = v_actor
   where o.id = p_org_id;
  if not found then
    raise exception 'org_not_found' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.admin_set_org_verification(uuid, smallint, boolean, text) is
  'Platform admin: sets the verification level and the verified-nonprofit mark of an organization.';
grant execute on function public.admin_set_org_verification(uuid, smallint, boolean, text) to authenticated;

-- Suspends or reinstates an organization (FR-ORG roles: platform admins).
-- Errors: forbidden (42501); P0001 org_not_found, unknown_state, illegal_transition.
create function public.admin_set_org_status(p_org_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.require_admin_role('admin');
  perform set_config('kc.fsm_role', 'admin', true);
  update public.organizations o set status = p_status where o.id = p_org_id;
  if not found then
    raise exception 'org_not_found' using errcode = 'P0001';
  end if;
  perform set_config('kc.fsm_role', '', true);
end;
$$;
comment on function public.admin_set_org_status(uuid, text) is 'Platform admin: suspends or reinstates an organization.';
grant execute on function public.admin_set_org_status(uuid, text) to authenticated;

-- >>> supabase/schemas/80_organizations/040_org_posts.sql
-- Organizations · posts of an organization (FR-ORG-007, D22, D31, D91; design §12.1)
--
-- `posts.beneficiary_org_id` names the organization a post is published for. This file
-- closes the foreign keys earlier modules left open, decides who may publish for an
-- organization, and gives the administrators of an organization (org_admin, org_manager)
-- the right to edit and delete its posts. The owner's and the super admin's rights are
-- unchanged.

-- Removing an organization releases its posts to their owners.
alter table public.posts
  add constraint posts_beneficiary_org_fk
  foreign key (beneficiary_org_id) references public.organizations (id) on delete set null;
-- Posts of an organization, newest first: its page, its administrators' list, the foreign key.
create index posts_beneficiary_org_idx on public.posts (beneficiary_org_id, created_at desc, id desc)
  where beneficiary_org_id is not null;

-- A self-declared affiliation (D110) names a registered organization; every registered
-- organization is verified (D53). The row has no meaning without its organization. Index:
-- user_profile_fields_affiliated_org_idx (social graph module).
alter table public.user_profile_fields
  add constraint user_profile_fields_affiliated_org_fk
  foreign key (affiliated_org_id) references public.organizations (id) on delete cascade;

-- ── Publishing for an organization ──────────────────────────────────────────
-- Whoever writes the column — a plain insert, a world's create RPC, the RPC below — a
-- signed-in caller may name only an organization they may publish for (`org.act_as`).
-- Server code without a member session (imports, jobs) is not restricted.
create function kc_private.posts_guard_beneficiary_org()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and not kc_private.can_act_as_org(new.beneficiary_org_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger posts_guard_beneficiary_org_insert
  before insert on public.posts
  for each row when (new.beneficiary_org_id is not null)
  execute function kc_private.posts_guard_beneficiary_org();
create trigger posts_guard_beneficiary_org_update
  before update of beneficiary_org_id on public.posts
  for each row when (new.beneficiary_org_id is not null and new.beneficiary_org_id is distinct from old.beneficiary_org_id)
  execute function kc_private.posts_guard_beneficiary_org();

-- A member may create a post directly in an organization's name; the trigger decides.
grant insert (beneficiary_org_id) on public.posts to authenticated;

-- Replaces the authorization of every post management action (publish, pause, resume,
-- delete, close, reopen): the owner, the super admin, or an administrator of the post's
-- organization (design §12.1).
create or replace function kc_private.can_manage_post(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.posts p
     where p.id = p_post_id
       and (p.owner_id = (select auth.uid())
            or kc_access.has_admin_role('super_admin')
            or p.beneficiary_org_id = any (kc_access.managed_org_ids())));
$$;
comment on function kc_private.can_manage_post(uuid) is
  'Authorization of every post management action: the owner, the super admin, or an administrator of the post''s organization.';

-- Attaches a post to an organization, or detaches it with null. The caller must manage
-- the post and, to attach, may publish for the organization.
-- Errors: post_not_found (P0001), forbidden (42501).
create function public.set_post_organization(p_post_id uuid, p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.post_lock_managed(p_post_id);
  update public.posts p set beneficiary_org_id = p_org_id where p.id = p_post_id;
end;
$$;
comment on function public.set_post_organization(uuid, uuid) is
  'Publishes an existing post in the name of an organization the caller may act for, or detaches it.';
grant execute on function public.set_post_organization(uuid, uuid) to authenticated;

-- ── Editing ─────────────────────────────────────────────────────────────────
-- May the caller edit the content of a post that is not their own? The super admin: every
-- post, in any status. An administrator of the post's organization: while the content is
-- editable (draft, open, paused — the owner's own rule, D104). One predicate for `posts`
-- and every detail table. Definer rights: it must see the post whatever its audience.
create function kc_access.can_edit_post(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.posts p
     where p.id = p_post_id
       and (kc_access.has_admin_role('super_admin')
            or (p.status in ('draft', 'open', 'paused')
                and p.beneficiary_org_id = any (kc_access.managed_org_ids()))));
$$;
comment on function kc_access.can_edit_post(uuid) is
  'Policy predicate: the caller edits this post as super admin or as an administrator of its organization.';
grant execute on function kc_access.can_edit_post(uuid) to authenticated;

-- The administrators read every post of their organization, whatever its status or audience.
create policy posts_select_org_admin on public.posts
  for select to authenticated
  using (beneficiary_org_id = any ((select kc_access.managed_org_ids())::uuid[]));
-- Which columns is decided by the grants of each table; status still moves through RPCs.
create policy posts_update_editor on public.posts
  for update to authenticated
  using (kc_access.can_edit_post(id)) with check (kc_access.can_edit_post(id));
create policy post_ride_details_update_editor on public.post_ride_details
  for update to authenticated
  using (kc_access.can_edit_post(post_id)) with check (kc_access.can_edit_post(post_id));
create policy post_housing_details_update_editor on public.post_housing_details
  for update to authenticated
  using (kc_access.can_edit_post(post_id)) with check (kc_access.can_edit_post(post_id));
create policy post_event_details_update_editor on public.post_event_details
  for update to authenticated
  using (kc_access.can_edit_post(post_id)) with check (kc_access.can_edit_post(post_id));
create policy post_food_details_update_editor on public.post_food_details
  for update to authenticated
  using (kc_access.can_edit_post(post_id)) with check (kc_access.can_edit_post(post_id));
-- Bookable times of a knowledge post: an editor adds, changes and removes them like the giver.
create policy post_knowledge_slots_insert_editor on public.post_knowledge_slots
  for insert to authenticated
  with check (kc_access.can_edit_post(post_id));
create policy post_knowledge_slots_update_editor on public.post_knowledge_slots
  for update to authenticated
  using (kc_access.can_edit_post(post_id)) with check (kc_access.can_edit_post(post_id));
create policy post_knowledge_slots_delete_editor on public.post_knowledge_slots
  for delete to authenticated
  using (kc_access.can_edit_post(post_id));

-- ── Directory of verified nonprofits (money hub; FR-ORG-010 AC2) ────────────
-- Active verified nonprofits by name, for signed-in members; the platform organization is
-- not listed. Keyset: pass the name and id of the last row. Runs with the caller's rights.
create function public.list_verified_nonprofits(
  p_limit integer default 50,
  p_after_name text default null,
  p_after_id uuid default null
)
returns table (id uuid, slug text, name text, tagline_he text, tagline_en text, verification_level smallint)
language sql
stable
set search_path = ''
as $$
  select o.id, o.slug, o.name, o.public_tagline_he, o.public_tagline_en, o.verification_level
    from public.organizations o
   where o.is_verified_nonprofit and o.status = 'active' and not o.is_platform
     and (p_after_name is null or (o.name, o.id) > (p_after_name, p_after_id))
   order by o.name, o.id
   limit least(greatest(coalesce(p_limit, 50), 1), 100);
$$;
comment on function public.list_verified_nonprofits(integer, text, uuid) is
  'Verified nonprofits that may receive donations, by name (keyset).';
grant execute on function public.list_verified_nonprofits(integer, text, uuid) to authenticated;

-- >>> supabase/schemas/80_organizations/050_donation_links.sql
-- Organizations · community donation links (FR-DONATE-007/009, D9, D36)
--
-- Any member may suggest a link to an organization's own donation or volunteering page;
-- it goes live after a moderator approves it (D9). Rows are written by the
-- `validate-donation-link` Edge Function (service role) after it checked that the address
-- is reachable; a device only reads, reports and deletes. Editing the content of a link
-- sends it back to review.

-- The lists a link can belong to (one per giving world that shows links). Reference data:
-- the rows are loaded from supabase/seed, labels live in the app's locale files.
create table public.donation_link_categories (
  slug       text primary key check (slug ~ '^[a-z][a-z0-9_]{1,30}$'),
  icon_name  text not null,
  sort_order integer not null,
  is_active  boolean not null default true
);
comment on table public.donation_link_categories is 'Lists of community donation links, one per giving world.';

alter table public.donation_link_categories enable row level security;
alter table public.donation_link_categories force row level security;
create policy donation_link_categories_select on public.donation_link_categories
  for select to authenticated
  using (true);
grant select on public.donation_link_categories to authenticated;

insert into kc_private.fsm_state (machine_id, status) values
  ('donation_link_review', 'pending'), ('donation_link_review', 'approved'), ('donation_link_review', 'rejected');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('donation_link_review', 'pending', 'approved', 'reviewer'),
  ('donation_link_review', 'pending', 'rejected', 'reviewer'),
  -- An edited link returns to the queue, whoever edits it.
  ('donation_link_review', 'approved', 'pending', ''),
  ('donation_link_review', 'rejected', 'pending', '');

create table public.donation_links (
  id            uuid primary key default gen_random_uuid(),
  category_slug text not null references public.donation_link_categories (slug) on update cascade,
  url           text not null check (url ~* '^https?://' and char_length(url) <= 2000),
  display_name  text not null check (char_length(display_name) between 2 and 80),
  description   text check (char_length(description) <= 280),
  submitted_by  uuid not null references public.users (id) on delete cascade,
  -- When the Edge Function last confirmed that the address answers.
  validated_at  timestamptz not null,
  -- Review, machine `donation_link_review`.
  review_status text not null default 'pending',
  reviewed_by   uuid references public.users (id) on delete set null,
  reviewed_at   timestamptz,
  -- Why the link was not approved; shown to its submitter.
  review_note   text check (char_length(review_note) <= 280),
  -- Search document; `simple` keeps Hebrew tokens unstemmed.
  search_vector tsvector generated always as (
                  to_tsvector('simple', display_name || ' ' || coalesce(description, ''))) stored,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
comment on table public.donation_links is 'Community-suggested links to organizations; visible to others once approved.';

-- The list of one giving world: approved links, newest first.
create index donation_links_category_idx on public.donation_links (category_slug, created_at desc, id desc)
  where review_status = 'approved';
-- "My links" and the hourly submission limit of the Edge Function; covers the submitter foreign key.
create index donation_links_submitted_by_idx on public.donation_links (submitted_by, created_at desc);
-- Review queue: by status, oldest first.
create index donation_links_review_queue_idx on public.donation_links (review_status, created_at, id)
  where review_status <> 'approved';
-- Universal search over approved links.
create index donation_links_search_gin_idx on public.donation_links using gin (search_vector)
  where review_status = 'approved';
create index donation_links_reviewed_by_idx on public.donation_links (reviewed_by) where reviewed_by is not null;

-- A new link always starts in the queue, and a change of its content returns it there
-- with the previous decision cleared. Runs before the machine guard (trigger name order).
create function kc_private.donation_links_requeue()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT'
     or (new.url, new.display_name, new.description, new.category_slug)
        is distinct from (old.url, old.display_name, old.description, old.category_slug) then
    new.review_status := 'pending';
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.review_note := null;
  end if;
  return new;
end;
$$;

create trigger donation_links_a_requeue
  before insert or update on public.donation_links
  for each row execute function kc_private.donation_links_requeue();
create trigger donation_links_review_fsm
  before insert or update on public.donation_links
  for each row execute function kc_private.fsm_guard_status('donation_link_review', 'review_status');
create trigger donation_links_set_updated_at
  before update on public.donation_links
  for each row execute function kc_private.set_updated_at();

alter table public.donation_links enable row level security;
alter table public.donation_links force row level security;

-- Members see approved links; the submitter also sees their own with its status
-- (FR-DONATE-007 AC1); moderators see the queue.
create policy donation_links_select on public.donation_links
  for select to authenticated
  using (review_status = 'approved'
         or submitted_by = (select auth.uid())
         or (select kc_access.has_admin_role('moderator')));
-- The submitter or the super admin removes a link for good (FR-DONATE-009 AC4/AC5).
create policy donation_links_delete on public.donation_links
  for delete to authenticated
  using (submitted_by = (select auth.uid()) or (select kc_access.has_admin_role('super_admin')));

grant select, delete on public.donation_links to authenticated;
-- The Edge Function adds and edits links after validating the address.
grant select, insert, update on public.donation_links to service_role;

-- Approves or rejects a link waiting in the queue (D9: super admin, admin or moderator).
-- Returns the new status. Errors: forbidden (42501); P0001 donation_link_not_pending.
create function public.admin_review_donation_link(p_link_id uuid, p_approve boolean, p_note text default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('moderator');
  v_status constant text := case when p_approve then 'approved' else 'rejected' end;
begin
  perform set_config('kc.fsm_role', 'reviewer', true);
  update public.donation_links l
     set review_status = v_status, reviewed_by = v_actor, reviewed_at = now(),
         review_note = case when p_approve then null else nullif(btrim(p_note), '') end
   where l.id = p_link_id and l.review_status = 'pending';
  if not found then
    raise exception 'donation_link_not_pending' using errcode = 'P0001';
  end if;
  perform set_config('kc.fsm_role', '', true);
  perform kc_private.audit_record('donation_link_review', 'donation_link', p_link_id,
                                  jsonb_build_object('decision', v_status));
  return v_status;
end;
$$;
comment on function public.admin_review_donation_link(uuid, boolean, text) is
  'Moderator: approves or rejects a pending donation link.';
grant execute on function public.admin_review_donation_link(uuid, boolean, text) to authenticated;

-- Reports a link to the support team (FR-DONATE-009 AC2): a system line in the caller's
-- support thread naming the link. Errors: unauthenticated (42501); P0001 donation_link_not_found.
create function public.report_donation_link(p_link_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_url text;
begin
  select l.url into v_url
    from public.donation_links l
   where l.id = p_link_id and (l.review_status = 'approved' or l.submitted_by = v_user_id);
  if not found then
    raise exception 'donation_link_not_found' using errcode = 'P0001';
  end if;
  perform kc_private.chat_post_system_message(
    (public.open_support_thread()).id,
    jsonb_build_object('kind', 'donation_link_reported', 'donation_link_id', p_link_id, 'url', v_url));
end;
$$;
comment on function public.report_donation_link(uuid) is
  'Reports a donation link: writes a system message into the caller''s support thread.';
grant execute on function public.report_donation_link(uuid) to authenticated;

-- >>> supabase/schemas/85_billing/010_settings_and_providers.sql
-- Billing · settings, payment providers, payment methods
--
-- Everything about money lives in the schema `billing`, which the API does not expose: a
-- device reaches it only through the `public` RPCs of this module, each of which checks
-- the caller and returns the caller's own data; provider webhooks and jobs reach it through
-- service-role functions (design §2.1, §3.8). No client role holds any privilege here, and
-- the service role only reads: every write goes through a function, so a money move and
-- its ledger lines are always one transaction.
--
-- Conventions of the module:
--   amounts      integer agorot (`bigint`) with a currency code; shekels only for now (D78)
--   statuses     one vocabulary on the FSM kernel: a completed money move is `succeeded`,
--                a withdrawn one `cancelled` (state-machines §7 Q4)
--   idempotency  every table that a retried request or webhook can write has its own
--                unique idempotency key
--   members      a money row names its member as `user_id`, or — after the account was
--                purged — as `user_tombstone`, the salted hash of audit.deletion_tombstones
--                (design §4.1.4). The rows themselves are never removed with the account.
--   service RPCs `public.api_*` and `public.provider_webhook_apply` are executable by the
--                service role only (no grant to a client role).

-- One row of module-wide settings.
create table billing.settings (
  singleton boolean primary key default true check (singleton),
  -- How long money records of a purged account are kept before they may be erased.
  -- Null = indefinitely: the period is an open legal question (design §12 Q5), and
  -- nothing is purged automatically until it is answered.
  retention_after_account_deletion interval check (retention_after_account_deletion > interval '0'),
  -- Smallest donation, in agorot (5 shekels).
  min_donation_agorot bigint not null default 500 check (min_donation_agorot > 0),
  updated_at timestamptz not null default now()
);
comment on table billing.settings is 'Module-wide billing settings; exactly one row.';
alter table billing.settings enable row level security;
alter table billing.settings force row level security;
-- Operations change a setting; the row itself is permanent.
revoke insert, delete, truncate on billing.settings from service_role;
-- The row is structure, not data: the functions of the module read it.
insert into billing.settings default values;

create trigger settings_set_updated_at
  before update on billing.settings
  for each row execute function kc_private.set_updated_at();

-- Payment providers the product can clear through. Swappable without code (D20): the
-- default active provider takes new donations. Rows are configuration, loaded per environment.
create table billing.payment_providers (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z][a-z0-9_]{1,30}$'),
  display_name  text not null check (char_length(display_name) between 1 and 80),
  is_active     boolean not null default true,
  is_default    boolean not null default false,
  -- Settings the app may see (hosted-fields flags and the like). Never a credential:
  -- provider secrets belong to the Edge Functions' environment.
  config_public jsonb not null default '{}'::jsonb check (jsonb_typeof(config_public) = 'object'),
  created_at    timestamptz not null default now(),
  constraint payment_providers_default_active_chk check (is_active or not is_default)
);
comment on table billing.payment_providers is 'Payment providers; the default active one receives new donations.';
create unique index payment_providers_single_default_key on billing.payment_providers (is_default) where is_default;
alter table billing.payment_providers enable row level security;
alter table billing.payment_providers force row level security;

-- A member's saved way to pay, as the provider's token. Card data is never stored: at most
-- the last four digits and the brand the provider reports for display.
create table billing.payment_methods (
  id             uuid primary key default gen_random_uuid(),
  -- A token is the member's own and leaves with the account.
  user_id        uuid not null references public.users (id) on delete cascade,
  provider_id    uuid not null references billing.payment_providers (id),
  provider_token text not null check (char_length(provider_token) between 1 and 500),
  last4          text check (last4 ~ '^[0-9]{4}$'),
  brand          text check (char_length(brand) <= 30),
  is_default     boolean not null default false,
  created_at     timestamptz not null default now(),
  unique (provider_id, provider_token)
);
comment on table billing.payment_methods is 'Provider tokens of a member''s saved payment methods. No card data.';
-- A member's methods; one default per member.
create index payment_methods_user_idx on billing.payment_methods (user_id);
create unique index payment_methods_single_default_key on billing.payment_methods (user_id) where is_default;
alter table billing.payment_methods enable row level security;
alter table billing.payment_methods force row level security;
revoke insert, update, delete, truncate on billing.payment_methods from service_role;

-- The provider that takes a new donation; raises when clearing is not available.
create function kc_private.billing_default_provider()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  select p.id into v_id from billing.payment_providers p where p.is_default and p.is_active;
  if not found then
    raise exception 'payments_unavailable' using errcode = 'P0001';
  end if;
  return v_id;
end;
$$;
comment on function kc_private.billing_default_provider() is
  'The default active payment provider; raises payments_unavailable when there is none.';

-- Stores the token of a payment method the provider created for a member at a hosted
-- checkout and returns its id; repeating the call returns the same row. A member's first
-- method becomes their default.
create function public.api_payment_method_save(
  p_user_id uuid,
  p_provider_slug text,
  p_provider_token text,
  p_last4 text default null,
  p_brand text default null
)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into billing.payment_methods (user_id, provider_id, provider_token, last4, brand, is_default)
  select p_user_id, p.id, p_provider_token, p_last4, p_brand,
         not exists (select 1 from billing.payment_methods m where m.user_id = p_user_id)
    from billing.payment_providers p
   where p.slug = p_provider_slug
  on conflict (provider_id, provider_token) do update set last4 = excluded.last4, brand = excluded.brand
  returning id;
$$;
comment on function public.api_payment_method_save(uuid, text, text, text, text) is
  'Service role: stores the provider token of a member''s payment method.';

-- >>> supabase/schemas/85_billing/020_donations.sql
-- Billing · standing orders, donation intents, payments (D4, D20; spec 08 "Money and donations")
--
-- Money moves only from a member to an organization, never between members (D4).
--   standing order   the member's mandate for a recurring donation
--   donation intent  one wish to donate an amount: created by the member (or by the charger
--                    for a standing order), sent to the provider's checkout, then settled
--                    by a provider event
--   payment          what the provider actually did with an intent; created only from a
--                    provider event, together with its ledger lines

insert into kc_private.fsm_state (machine_id, status) values
  ('standing_order', 'pending'), ('standing_order', 'active'), ('standing_order', 'paused'),
  ('standing_order', 'cancelled'),
  ('donation_intent', 'created'), ('donation_intent', 'checkout'), ('donation_intent', 'succeeded'),
  ('donation_intent', 'failed'), ('donation_intent', 'cancelled'),
  ('payment', 'succeeded'), ('payment', 'failed'), ('payment', 'refunded');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  -- A mandate is live once the provider confirmed it; the member pauses, resumes and cancels.
  ('standing_order', 'pending', 'active', 'provider'),
  ('standing_order', 'pending', 'cancelled', ''),
  ('standing_order', 'active', 'paused', ''),
  ('standing_order', 'paused', 'active', ''),
  ('standing_order', 'active', 'cancelled', ''),
  ('standing_order', 'paused', 'cancelled', ''),
  ('donation_intent', 'created', 'checkout', ''),
  ('donation_intent', 'created', 'cancelled', ''),
  ('donation_intent', 'checkout', 'cancelled', ''),
  ('donation_intent', 'checkout', 'succeeded', 'provider'),
  ('donation_intent', 'checkout', 'failed', 'provider'),
  -- The donor tried again on the same checkout page and the charge went through.
  ('donation_intent', 'failed', 'succeeded', 'provider'),
  -- Fully refunded; a partial refund keeps the payment `succeeded`.
  ('payment', 'succeeded', 'refunded', 'provider');

create table billing.standing_orders (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid references public.users (id) on delete set null,
  user_tombstone  bytea check (octet_length(user_tombstone) = 32),
  org_id          uuid not null references public.organizations (id) on delete restrict,
  amount_agorot   bigint not null check (amount_agorot > 0),
  currency        text not null default 'ILS' check (currency = 'ILS'),
  cadence         text not null default 'monthly' check (cadence in ('monthly', 'quarterly', 'yearly')),
  -- Lifecycle, machine `standing_order`.
  status          text not null default 'pending',
  provider_id     uuid not null references billing.payment_providers (id),
  -- The provider's reference of the mandate, once confirmed.
  provider_ref    text,
  method_id       uuid references billing.payment_methods (id) on delete set null,
  idempotency_key text not null unique check (char_length(idempotency_key) between 8 and 200),
  -- When the next charge is opened; null unless the order is active.
  next_charge_at  timestamptz,
  cancelled_at    timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint standing_orders_party_chk check (num_nonnulls(user_id, user_tombstone) = 1),
  constraint standing_orders_next_charge_chk check ((status = 'active') = (next_charge_at is not null))
);
comment on table billing.standing_orders is 'Recurring donation mandates of members to organizations.';

-- "My standing orders", newest first; covers the member foreign key.
create index standing_orders_user_idx on billing.standing_orders (user_id, created_at desc) where user_id is not null;
-- Charger: active orders that are due, oldest first.
create index standing_orders_due_idx on billing.standing_orders (next_charge_at) where status = 'active';
-- Foreign keys.
create index standing_orders_org_idx on billing.standing_orders (org_id);
create index standing_orders_provider_idx on billing.standing_orders (provider_id);
create index standing_orders_method_idx on billing.standing_orders (method_id) where method_id is not null;

create table billing.donation_intents (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid references public.users (id) on delete set null,
  user_tombstone    bytea check (octet_length(user_tombstone) = 32),
  org_id            uuid not null references public.organizations (id) on delete restrict,
  -- The campaign post the donation was made on, if any.
  post_id           uuid references public.posts (id) on delete set null,
  -- Set when the intent is one charge of a standing order.
  standing_order_id uuid references billing.standing_orders (id) on delete restrict,
  amount_agorot     bigint not null check (amount_agorot > 0),
  currency          text not null default 'ILS' check (currency = 'ILS'),
  -- Lifecycle, machine `donation_intent`.
  status            text not null default 'created',
  provider_id       uuid not null references billing.payment_providers (id),
  -- The provider's checkout session: its reference and the page the donor is sent to.
  provider_ref      text,
  checkout_url      text check (checkout_url ~* '^https://'),
  idempotency_key   text not null unique check (char_length(idempotency_key) between 8 and 200),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint donation_intents_party_chk check (num_nonnulls(user_id, user_tombstone) = 1)
);
comment on table billing.donation_intents is 'One wish to donate an amount to an organization, from creation to settlement.';

-- A member's intents, newest first; covers the member foreign key.
create index donation_intents_user_idx on billing.donation_intents (user_id, created_at desc) where user_id is not null;
-- Money raised by a campaign post.
create index donation_intents_post_idx on billing.donation_intents (post_id) where post_id is not null;
-- Charges of a standing order (history, failed-charge handling).
create index donation_intents_standing_order_idx on billing.donation_intents (standing_order_id, created_at desc)
  where standing_order_id is not null;
-- Foreign keys.
create index donation_intents_org_idx on billing.donation_intents (org_id);
create index donation_intents_provider_idx on billing.donation_intents (provider_id);

create table billing.payments (
  id              uuid primary key default gen_random_uuid(),
  intent_id       uuid not null references billing.donation_intents (id) on delete restrict,
  user_id         uuid references public.users (id) on delete set null,
  user_tombstone  bytea check (octet_length(user_tombstone) = 32),
  org_id          uuid not null references public.organizations (id) on delete restrict,
  amount_agorot   bigint not null check (amount_agorot > 0),
  currency        text not null default 'ILS' check (currency = 'ILS'),
  -- Outcome, machine `payment`.
  status          text not null,
  -- Sum of the settled refunds of this payment.
  refunded_agorot bigint not null default 0 check (refunded_agorot >= 0),
  provider_id     uuid not null references billing.payment_providers (id),
  provider_ref    text,
  method_id       uuid references billing.payment_methods (id) on delete set null,
  -- The provider event that reported the payment.
  idempotency_key text not null unique check (char_length(idempotency_key) between 8 and 200),
  created_at      timestamptz not null default now(),
  constraint payments_party_chk check (num_nonnulls(user_id, user_tombstone) = 1),
  constraint payments_refunded_chk check (
    refunded_agorot <= amount_agorot and (status = 'refunded') = (refunded_agorot = amount_agorot))
);
comment on table billing.payments is 'Payments reported by the provider; written only together with their ledger lines.';

-- An intent is paid once.
create unique index payments_one_settled_per_intent_key on billing.payments (intent_id)
  where status in ('succeeded', 'refunded');
-- Failed attempts of an intent; covers the intent foreign key.
create index payments_intent_idx on billing.payments (intent_id);
-- "My donations", newest first (keyset on created_at, id); covers the member foreign key.
create index payments_user_idx on billing.payments (user_id, created_at desc, id desc) where user_id is not null;
-- Money raised by an organization; covers the organization foreign key.
create index payments_org_idx on billing.payments (org_id, created_at desc) where status = 'succeeded';
-- A provider reference names one payment (refund and dispute lookups).
create unique index payments_provider_ref_key on billing.payments (provider_id, provider_ref)
  where provider_ref is not null;
create index payments_method_idx on billing.payments (method_id) where method_id is not null;

create trigger standing_orders_status_fsm
  before insert or update of status on billing.standing_orders
  for each row execute function kc_private.fsm_guard_status('standing_order', 'status');
create trigger standing_orders_set_updated_at
  before update on billing.standing_orders
  for each row execute function kc_private.set_updated_at();
create trigger donation_intents_status_fsm
  before insert or update of status on billing.donation_intents
  for each row execute function kc_private.fsm_guard_status('donation_intent', 'status');
create trigger donation_intents_set_updated_at
  before update on billing.donation_intents
  for each row execute function kc_private.set_updated_at();
create trigger payments_status_fsm
  before insert or update of status on billing.payments
  for each row execute function kc_private.fsm_guard_status('payment', 'status');

alter table billing.standing_orders enable row level security;
alter table billing.standing_orders force row level security;
alter table billing.donation_intents enable row level security;
alter table billing.donation_intents force row level security;
alter table billing.payments enable row level security;
alter table billing.payments force row level security;
-- The service role reads; it writes only through the functions of this module.
revoke insert, update, delete, truncate on billing.standing_orders, billing.donation_intents, billing.payments
  from service_role;

-- >>> supabase/schemas/85_billing/030_refunds_payouts_kyc_webhooks.sql
-- Billing · refunds, payouts, KYC profiles, provider webhook events

insert into kc_private.fsm_state (machine_id, status) values
  ('refund', 'pending'), ('refund', 'succeeded'), ('refund', 'failed'),
  ('payout', 'pending'), ('payout', 'succeeded'), ('payout', 'failed'),
  ('kyc', 'pending'), ('kyc', 'approved'), ('kyc', 'rejected'),
  ('webhook_event', 'pending'), ('webhook_event', 'processed'), ('webhook_event', 'failed');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  -- Only the provider's word settles a refund or a payout.
  ('refund', 'pending', 'succeeded', 'provider'),
  ('refund', 'pending', 'failed', 'provider'),
  ('payout', 'pending', 'succeeded', 'provider'),
  ('payout', 'pending', 'failed', 'provider'),
  -- The provider may revise its verdict at any time: a rejected party is checked again,
  -- an approved one is re-verified periodically.
  ('kyc', 'pending', 'approved', 'provider'),
  ('kyc', 'pending', 'rejected', 'provider'),
  ('kyc', 'rejected', 'pending', 'provider'),
  ('kyc', 'approved', 'pending', 'provider'),
  ('kyc', 'approved', 'rejected', 'provider'),
  ('kyc', 'rejected', 'approved', 'provider'),
  -- A failed event is applied again when the provider resends it.
  ('webhook_event', 'pending', 'processed', ''),
  ('webhook_event', 'pending', 'failed', ''),
  ('webhook_event', 'failed', 'processed', '');

-- Money returned to a donor. Opened by a platform admin, settled by a provider event.
create table billing.refunds (
  id              uuid primary key default gen_random_uuid(),
  payment_id      uuid not null references billing.payments (id) on delete restrict,
  amount_agorot   bigint not null check (amount_agorot > 0),
  -- Stable reason code; free text never enters the money tables.
  reason          text not null check (reason in ('donor_request', 'duplicate', 'fraud', 'error')),
  -- Lifecycle, machine `refund`.
  status          text not null default 'pending',
  provider_ref    text,
  idempotency_key text not null unique check (char_length(idempotency_key) between 8 and 200),
  opened_by       uuid references public.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  settled_at      timestamptz,
  constraint refunds_settled_chk check ((status = 'pending') = (settled_at is null))
);
comment on table billing.refunds is 'Refunds of payments; the ledger is posted when the provider confirms.';
-- Refunds of a payment (remaining refundable amount); covers the payment foreign key.
create index refunds_payment_idx on billing.refunds (payment_id);
create index refunds_opened_by_idx on billing.refunds (opened_by) where opened_by is not null;

-- Money the provider transfers to an organization's bank account.
create table billing.payouts (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid not null references public.organizations (id) on delete restrict,
  amount_agorot   bigint not null check (amount_agorot > 0),
  currency        text not null default 'ILS' check (currency = 'ILS'),
  -- Lifecycle, machine `payout`.
  status          text not null default 'pending',
  provider_ref    text,
  idempotency_key text not null unique check (char_length(idempotency_key) between 8 and 200),
  created_at      timestamptz not null default now(),
  settled_at      timestamptz,
  constraint payouts_settled_chk check ((status = 'pending') = (settled_at is null))
);
comment on table billing.payouts is 'Payouts to organizations; the ledger is posted when the provider confirms.';
-- Payouts of an organization, newest first (finance screen, open payouts in the balance check).
create index payouts_org_idx on billing.payouts (org_id, created_at desc);

-- "Know your customer" state of a payer (a member) or a recipient (an organization), as
-- reported by the provider. Only the state and the provider's reference: documents stay
-- with the provider. A payer's profile leaves with the account.
create table billing.kyc_profiles (
  id           uuid primary key default gen_random_uuid(),
  party_type   text not null check (party_type in ('payer', 'recipient')),
  user_id      uuid unique references public.users (id) on delete cascade,
  org_id       uuid unique references public.organizations (id) on delete cascade,
  -- State, machine `kyc`.
  status       text not null default 'pending',
  provider_ref text,
  verified_at  timestamptz,
  updated_at   timestamptz not null default now(),
  constraint kyc_profiles_party_chk check (
    case party_type when 'payer' then user_id is not null and org_id is null
                    else org_id is not null and user_id is null end)
);
comment on table billing.kyc_profiles is 'KYC state of payers and recipient organizations, as reported by the provider.';

-- Every event a provider sent, once: (provider, event id) is the idempotency key of the
-- whole webhook path.
create table billing.webhook_events (
  id                uuid primary key default gen_random_uuid(),
  provider_slug     text not null,
  provider_event_id text not null check (char_length(provider_event_id) between 1 and 200),
  event_type        text,
  payload           jsonb not null check (jsonb_typeof(payload) = 'object'),
  -- Processing state, machine `webhook_event`.
  status            text not null default 'pending',
  processed_at      timestamptz,
  -- Stable error code of the last failed attempt.
  error_code        text,
  created_at        timestamptz not null default now(),
  unique (provider_slug, provider_event_id)
);
comment on table billing.webhook_events is 'Provider events, each stored and applied once.';
-- Operations: events that failed, oldest first.
create index webhook_events_failed_idx on billing.webhook_events (created_at) where status = 'failed';

create trigger refunds_status_fsm
  before insert or update of status on billing.refunds
  for each row execute function kc_private.fsm_guard_status('refund', 'status');
create trigger payouts_status_fsm
  before insert or update of status on billing.payouts
  for each row execute function kc_private.fsm_guard_status('payout', 'status');
create trigger kyc_profiles_status_fsm
  before insert or update of status on billing.kyc_profiles
  for each row execute function kc_private.fsm_guard_status('kyc', 'status');
create trigger kyc_profiles_set_updated_at
  before update on billing.kyc_profiles
  for each row execute function kc_private.set_updated_at();
create trigger webhook_events_status_fsm
  before insert or update of status on billing.webhook_events
  for each row execute function kc_private.fsm_guard_status('webhook_event', 'status');

alter table billing.refunds enable row level security;
alter table billing.refunds force row level security;
alter table billing.payouts enable row level security;
alter table billing.payouts force row level security;
alter table billing.kyc_profiles enable row level security;
alter table billing.kyc_profiles force row level security;
alter table billing.webhook_events enable row level security;
alter table billing.webhook_events force row level security;
revoke insert, update, delete, truncate
  on billing.refunds, billing.payouts, billing.kyc_profiles, billing.webhook_events from service_role;

-- >>> supabase/schemas/85_billing/040_ledger.sql
-- Billing · ledger (double entry, append-only)
--
-- Every money move is recorded as one ledger transaction: lines that share a `txn_id` and
-- whose debits equal their credits. The balance is checked when the database transaction
-- commits, so no path — a function of this module, a migration, a manual fix — can leave
-- an unbalanced transaction behind. A line is never changed or removed by any role; a
-- mistake is corrected by a new, opposite transaction.
--
-- Accounts:
--   provider_clearing  money held for us by the payment provider (asset)
--   org_payable        money owed to an organization (liability; `org_id` says to which)
-- Moves:  payment  debit provider_clearing / credit org_payable
--         refund   debit org_payable / credit provider_clearing
--         payout   debit org_payable / credit provider_clearing

create table billing.ledger_entries (
  id            bigint generated always as identity primary key,
  txn_id        uuid not null,
  account       text not null check (account in ('provider_clearing', 'org_payable')),
  -- The organization whose money the move is about.
  org_id        uuid not null references public.organizations (id) on delete restrict,
  debit_agorot  bigint not null default 0 check (debit_agorot >= 0),
  credit_agorot bigint not null default 0 check (credit_agorot >= 0),
  currency      text not null default 'ILS' check (currency = 'ILS'),
  -- The business record the transaction belongs to. No foreign key: one column refers to
  -- three tables, and those rows can never be deleted (restrict from their own children).
  ref_type      text not null check (ref_type in ('payment', 'refund', 'payout')),
  ref_id        uuid not null,
  created_at    timestamptz not null default now(),
  -- A line is one-sided.
  constraint ledger_entries_one_side_chk check ((debit_agorot > 0) <> (credit_agorot > 0)),
  -- Idempotency: a business record is posted once.
  unique (ref_type, ref_id, account)
);
comment on table billing.ledger_entries is
  'Double-entry ledger in agorot. Balanced per transaction at commit; append-only for every role.';

-- Lines of a transaction (the balance check).
create index ledger_entries_txn_idx on billing.ledger_entries (txn_id);
-- Balance and statement of an organization per account; covers the organization foreign key.
create index ledger_entries_org_account_idx on billing.ledger_entries (org_id, account, id);

alter table billing.ledger_entries enable row level security;
alter table billing.ledger_entries force row level security;
revoke insert, update, delete, truncate on billing.ledger_entries from service_role;

-- No change and no removal, for any role (the table owner included).
create trigger ledger_entries_append_only
  before update or delete on billing.ledger_entries
  for each row execute function kc_private.audit_reject_change();
create trigger ledger_entries_no_truncate
  before truncate on billing.ledger_entries
  for each statement execute function kc_private.audit_reject_change();

-- Raises unless the transaction of the inserted line balances, per currency.
create function kc_private.ledger_assert_balanced()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1
               from billing.ledger_entries e
              where e.txn_id = new.txn_id
              group by e.currency
             having sum(e.debit_agorot) <> sum(e.credit_agorot)) then
    raise exception 'ledger_unbalanced' using errcode = 'P0001', detail = format('txn %s', new.txn_id);
  end if;
  return null;
end;
$$;
comment on function kc_private.ledger_assert_balanced() is
  'Deferred constraint trigger: a ledger transaction must balance when the database transaction commits.';

create constraint trigger ledger_entries_balanced
  after insert on billing.ledger_entries
  deferrable initially deferred
  for each row execute function kc_private.ledger_assert_balanced();

-- Posts one balanced transaction of two lines for a business record. Posting the same
-- record again is a no-op, so a replayed provider event cannot double-count.
create function kc_private.ledger_post(
  p_ref_type text,
  p_ref_id uuid,
  p_org_id uuid,
  p_debit_account text,
  p_credit_account text,
  p_amount_agorot bigint
)
returns void
language sql
security definer
set search_path = ''
as $$
  with txn as (select gen_random_uuid() as id)
  insert into billing.ledger_entries (txn_id, account, org_id, debit_agorot, credit_agorot, ref_type, ref_id)
  select txn.id, l.account, p_org_id, l.debit, l.credit, p_ref_type, p_ref_id
    from txn, (values (p_debit_account, p_amount_agorot, 0::bigint),
                      (p_credit_account, 0::bigint, p_amount_agorot)) as l (account, debit, credit)
  on conflict (ref_type, ref_id, account) do nothing;
$$;
comment on function kc_private.ledger_post(text, uuid, uuid, text, text, bigint) is
  'Posts the two balanced lines of a payment, refund or payout; idempotent per business record.';

-- What the product still owes an organization: collected, minus refunded and paid out.
create function kc_private.billing_org_balance(p_org_id uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(e.credit_agorot - e.debit_agorot), 0)::bigint
    from billing.ledger_entries e
   where e.org_id = p_org_id and e.account = 'org_payable';
$$;
comment on function kc_private.billing_org_balance(uuid) is 'Balance owed to an organization, in agorot, from the ledger.';

-- >>> supabase/schemas/85_billing/050_receipts.sql
-- Billing · donation receipts (D20, D77; FR-FIN-007 AC4, FR-FIN-008, FR-FIN-021)
--
-- One receipt record per succeeded payment, numbered per organization without gaps: the
-- serial comes from a counter row that the issuing transaction locks, so two receipts
-- issued at the same moment queue up, and a transaction that fails gives its number back.
-- The record carries whether the donation is eligible under Section 46(a) — true only
-- while the organization's approval is active on the day of the payment; the product
-- records that fact and never decides it (D77). The official document itself is produced
-- by the organization's own tools from this record.

-- Last serial issued per organization.
create table billing.receipt_counters (
  org_id      uuid primary key references public.organizations (id) on delete restrict,
  last_serial bigint not null default 0 check (last_serial >= 0)
);
comment on table billing.receipt_counters is 'Per-organization receipt counter; locked by the issuing transaction.';
alter table billing.receipt_counters enable row level security;
alter table billing.receipt_counters force row level security;

create table billing.receipts (
  id                    uuid primary key default gen_random_uuid(),
  org_id                uuid not null references public.organizations (id) on delete restrict,
  -- Gapless within the organization, starting at 1.
  serial                bigint not null check (serial > 0),
  payment_id            uuid not null unique references billing.payments (id) on delete restrict,
  user_id               uuid references public.users (id) on delete set null,
  user_tombstone        bytea check (octet_length(user_tombstone) = 32),
  amount_agorot         bigint not null check (amount_agorot > 0),
  currency              text not null default 'ILS' check (currency = 'ILS'),
  -- Section 46(a) eligibility on the payment date, with the approval number it rests on.
  sec46_eligible        boolean not null default false,
  sec46_approval_number text,
  issued_at             timestamptz not null default now(),
  unique (org_id, serial),
  constraint receipts_party_chk check (num_nonnulls(user_id, user_tombstone) = 1),
  constraint receipts_sec46_chk check (sec46_eligible = (sec46_approval_number is not null))
);
comment on table billing.receipts is 'Receipt record of each succeeded donation, with a gapless serial per organization.';
-- "My receipts"; covers the member foreign key.
create index receipts_user_idx on billing.receipts (user_id, issued_at desc) where user_id is not null;

alter table billing.receipts enable row level security;
alter table billing.receipts force row level security;
revoke insert, update, delete, truncate on billing.receipts, billing.receipt_counters from service_role;

-- A receipt is never removed and never rewritten. The one permitted change replaces the
-- member reference by the tombstone when the account is purged.
create function kc_private.receipts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op <> 'UPDATE'
     or (to_jsonb(new) - 'user_id' - 'user_tombstone') <> (to_jsonb(old) - 'user_id' - 'user_tombstone') then
    raise exception 'append_only' using errcode = 'P0001',
      detail = format('%s on %s.%s', tg_op, tg_table_schema, tg_table_name);
  end if;
  return new;
end;
$$;

create trigger receipts_immutable
  before update or delete on billing.receipts
  for each row execute function kc_private.receipts_guard();
create trigger receipts_no_truncate
  before truncate on billing.receipts
  for each statement execute function kc_private.receipts_guard();

insert into kc_private.notification_kinds (kind, category, title_key, body_key) values
  -- FR-FIN-021 AC4: the donor learns that a receipt exists; a member may switch it off.
  ('donation_receipt_ready', 'social', 'notifications.donationReceiptReadyTitle',
   'notifications.donationReceiptReadyBody');

-- Issues the receipt of a succeeded payment and returns it; a payment that already has
-- one gets the same receipt back. Runs inside the transaction that settles the payment.
-- Errors: P0001 payment_not_found (no such succeeded payment).
create function kc_private.billing_receipt_issue(p_payment_id uuid)
returns billing.receipts
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment billing.payments;
  v_receipt billing.receipts;
  v_approval text;
  v_serial bigint;
begin
  -- The payment row serialises two issues of the same payment.
  select p.* into v_payment from billing.payments p
   where p.id = p_payment_id and p.status = 'succeeded' for update;
  if not found then
    raise exception 'payment_not_found' using errcode = 'P0001';
  end if;
  select r.* into v_receipt from billing.receipts r where r.payment_id = p_payment_id;
  if found then
    return v_receipt;
  end if;

  select o.sec46_approval_number into v_approval
    from public.organizations o
   where o.id = v_payment.org_id and o.sec46_status = 'active'
     and v_payment.created_at::date between o.sec46_valid_from and o.sec46_valid_until;

  -- The counter row is locked until this transaction ends: serials are handed out in
  -- commit order and a rollback returns the number.
  insert into billing.receipt_counters (org_id) values (v_payment.org_id) on conflict (org_id) do nothing;
  update billing.receipt_counters c set last_serial = c.last_serial + 1
   where c.org_id = v_payment.org_id
  returning c.last_serial into v_serial;

  insert into billing.receipts (org_id, serial, payment_id, user_id, user_tombstone, amount_agorot, currency,
                                sec46_eligible, sec46_approval_number)
  values (v_payment.org_id, v_serial, p_payment_id, v_payment.user_id, v_payment.user_tombstone,
          v_payment.amount_agorot, v_payment.currency, v_approval is not null, v_approval)
  returning * into v_receipt;

  perform kc_private.audit_record('receipt_issued', 'payment', p_payment_id,
    jsonb_build_object('receipt_id', v_receipt.id, 'org_id', v_receipt.org_id, 'serial', v_serial), null);
  if v_payment.user_id is not null then
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', 'donation_receipt_ready', 'recipient_id', v_payment.user_id, 'actor_id', null,
      'entity', jsonb_build_object('type', 'payment', 'id', p_payment_id),
      'data', jsonb_build_object('org_id', v_receipt.org_id, 'serial', v_serial,
                                 'dedupe_key', 'donation_receipt_ready:' || p_payment_id)));
  end if;
  return v_receipt;
end;
$$;
comment on function kc_private.billing_receipt_issue(uuid) is
  'Issues the gapless-numbered receipt of a succeeded payment; idempotent per payment.';

-- >>> supabase/schemas/85_billing/060_org_finance.sql
-- Billing · organization bookkeeping (requirements/19: FR-FIN-001/002/003/005/009/013, D76, D78)
--
-- Every organization — Karma Community included — keeps simple single-entry books:
-- accounts (where the money sits) and entries (what came in and went out). Entries are
-- typed by hand or mirrored from in-app payments. This is the organization's own record
-- and is separate from the double-entry ledger of 040_ledger.sql, which is the product's
-- record of the money it holds.
-- Not part of this baseline (FR-FIN phases not built): category tree and rules,
-- attachments, receipt tracking of manual entries, imports, budgets, documents, snapshots.

insert into kc_private.fsm_state (machine_id, status) values
  ('org_finance_entry', 'pending'), ('org_finance_entry', 'cleared'), ('org_finance_entry', 'cancelled');
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('org_finance_entry', 'pending', 'cleared', ''),
  ('org_finance_entry', 'cleared', 'pending', ''),
  -- Void replaces delete (FR-FIN-005 AC2); a voided entry is final.
  ('org_finance_entry', 'pending', 'cancelled', ''),
  ('org_finance_entry', 'cleared', 'cancelled', '');

create table billing.org_finance_accounts (
  id                     uuid primary key default gen_random_uuid(),
  org_id                 uuid not null references public.organizations (id) on delete restrict,
  name                   text not null check (char_length(btrim(name)) between 1 and 80),
  kind                   text not null check (kind in ('bank', 'cash', 'bit', 'paybox', 'payment_provider', 'other')),
  last4                  text check (last4 ~ '^[0-9]{4}$'),
  opening_balance_agorot bigint not null default 0,
  opening_balance_at     date,
  -- An account with entries is deactivated, never deleted (FR-FIN-003 AC2).
  is_active              boolean not null default true,
  sort_order             integer not null default 0,
  created_by             uuid references public.users (id) on delete set null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (org_id, name)
);
comment on table billing.org_finance_accounts is 'Financial accounts of an organization: bank, cash box, payment apps, the payment provider.';
create index org_finance_accounts_created_by_idx on billing.org_finance_accounts (created_by) where created_by is not null;

create table billing.org_finance_entries (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid not null references public.organizations (id) on delete restrict,
  account_id      uuid references billing.org_finance_accounts (id) on delete restrict,
  kind            text not null check (kind in ('donation_in', 'grant_in', 'other_in', 'expense', 'refund_out',
                                                'other_out', 'transfer')),
  -- Derived from the kind; a transfer between own accounts has none.
  direction       text generated always as (
                    case when kind in ('donation_in', 'grant_in', 'other_in') then 'in'
                         when kind in ('expense', 'refund_out', 'other_out') then 'out' end) stored,
  amount_agorot   bigint not null check (amount_agorot > 0),
  currency        text not null default 'ILS' check (currency = 'ILS'),
  occurred_at     timestamptz not null,
  counterparty    text check (char_length(counterparty) <= 200),
  -- Category key from the app's list (FR-FIN-004 default keys), or the organization's own text.
  category        text check (char_length(category) <= 60),
  description     text check (char_length(description) <= 2000),
  -- Lifecycle, machine `org_finance_entry`. `cancelled` = voided, with the reason.
  status          text not null default 'pending',
  void_reason     text check (char_length(void_reason) between 3 and 500),
  -- False keeps the entry out of the public transparency numbers (FR-FIN-022 AC4).
  is_public       boolean not null default true,
  -- `payment_sync` entries mirror an in-app payment or refund; `source_ref` names it.
  source          text not null default 'manual' check (source in ('manual', 'payment_sync')),
  source_ref      text unique,
  -- The donor of a mirrored donation; never shown publicly (FR-FIN-019 AC6).
  donor_user_id   uuid references public.users (id) on delete set null,
  donor_tombstone bytea check (octet_length(donor_tombstone) = 32),
  -- Matched to a bank or provider statement; freezes the entry (FR-FIN-013).
  reconciled_at   timestamptz,
  reconciled_by   uuid references public.users (id) on delete set null,
  created_by      uuid references public.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint org_finance_entries_void_chk check ((status = 'cancelled') = (void_reason is not null)),
  constraint org_finance_entries_source_chk check ((source = 'manual') = (source_ref is null)),
  constraint org_finance_entries_donor_chk check (num_nonnulls(donor_user_id, donor_tombstone) <= 1)
);
comment on table billing.org_finance_entries is 'Single-entry books of an organization: manual entries and mirrored in-app payments.';

-- The books of an organization, newest first (keyset on occurred_at, id), and its public totals.
create index org_finance_entries_org_idx on billing.org_finance_entries (org_id, occurred_at desc, id desc);
-- Balance of an account; covers the account foreign key.
create index org_finance_entries_account_idx on billing.org_finance_entries (account_id) where account_id is not null;
-- Foreign keys to members.
create index org_finance_entries_donor_idx on billing.org_finance_entries (donor_user_id) where donor_user_id is not null;
create index org_finance_entries_reconciled_by_idx on billing.org_finance_entries (reconciled_by)
  where reconciled_by is not null;
create index org_finance_entries_created_by_idx on billing.org_finance_entries (created_by) where created_by is not null;

-- What may still change on an entry (FR-FIN-005 AC2/AC3, FR-FIN-013 AC3):
--   entry_voided            a voided entry never changes
--   entry_reconciled        a reconciled entry keeps its kind, amount, date, account and status
--   entry_locked_by_source  a mirrored entry keeps its kind, amount, date, account and counterparty
create function kc_private.org_finance_entries_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  -- The member references are not content: the purge of an account replaces them even
  -- on a voided entry. `direction` is generated and not yet computed in a BEFORE trigger.
  v_ignored constant text[] := array['donor_user_id', 'donor_tombstone', 'created_by', 'reconciled_by', 'direction'];
begin
  if (to_jsonb(new) - v_ignored) = (to_jsonb(old) - v_ignored) then
    return new;
  elsif old.status = 'cancelled' then
    raise exception 'entry_voided' using errcode = 'P0001';
  elsif old.reconciled_at is not null and new.reconciled_at is not null
        and (new.kind, new.amount_agorot, new.occurred_at, new.account_id, new.status)
            is distinct from (old.kind, old.amount_agorot, old.occurred_at, old.account_id, old.status) then
    raise exception 'entry_reconciled' using errcode = 'P0001';
  elsif old.source = 'payment_sync'
        and (new.kind, new.amount_agorot, new.occurred_at, new.account_id, new.counterparty, new.source_ref)
            is distinct from (old.kind, old.amount_agorot, old.occurred_at, old.account_id, old.counterparty, old.source_ref) then
    raise exception 'entry_locked_by_source' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger org_finance_entries_guard
  before update on billing.org_finance_entries
  for each row execute function kc_private.org_finance_entries_guard();
create trigger org_finance_entries_status_fsm
  before insert or update of status on billing.org_finance_entries
  for each row execute function kc_private.fsm_guard_status('org_finance_entry', 'status');
create trigger org_finance_entries_set_updated_at
  before update on billing.org_finance_entries
  for each row execute function kc_private.set_updated_at();
create trigger org_finance_accounts_set_updated_at
  before update on billing.org_finance_accounts
  for each row execute function kc_private.set_updated_at();

alter table billing.org_finance_accounts enable row level security;
alter table billing.org_finance_accounts force row level security;
alter table billing.org_finance_entries enable row level security;
alter table billing.org_finance_entries force row level security;
revoke insert, update, delete, truncate on billing.org_finance_accounts, billing.org_finance_entries from service_role;

-- The signed-in caller, who must hold a finance permission on the organization
-- (requirements/19 § Permissions):
--   view          platform admins; org_admin, org_treasurer, org_accountant of the
--                 organization; moderators for the platform organization only
--   manage        platform admins; org_admin, org_treasurer
--   transparency  platform admins; org_admin
-- Raises forbidden (42501) otherwise.
create function kc_private.finance_assert(p_org_id uuid, p_permission text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_roles constant text[] := (select m.roles from public.org_memberships m
                               where m.org_id = p_org_id and m.user_id = v_user_id);
begin
  if kc_access.has_admin_role('admin')
     or v_roles && (case p_permission
                      when 'view' then array['org_admin', 'org_treasurer', 'org_accountant']
                      when 'manage' then array['org_admin', 'org_treasurer']
                      when 'transparency' then array['org_admin'] end)
     or (p_permission = 'view' and kc_access.has_admin_role('moderator')
         and exists (select 1 from public.organizations o where o.id = p_org_id and o.is_platform)) then
    return v_user_id;
  end if;
  raise exception 'forbidden' using errcode = '42501';
end;
$$;
comment on function kc_private.finance_assert(uuid, text) is
  'Returns auth.uid(); raises forbidden unless the caller holds the finance permission on the organization.';

-- Mirrors a settled in-app payment or refund into the organization's books (FR-FIN-009):
-- a cleared entry on the organization's payment-provider account, created on first use.
-- Idempotent per source record. A failure is audited and never fails the money move
-- (AC6); the entry can be added by hand.
create function kc_private.org_finance_mirror(
  p_org_id uuid,
  p_kind text,
  p_amount_agorot bigint,
  p_occurred_at timestamptz,
  p_source_ref text,
  p_provider_id uuid,
  p_donor_user_id uuid,
  p_donor_tombstone bytea,
  p_category text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_provider_name constant text := (select p.display_name from billing.payment_providers p where p.id = p_provider_id);
  v_account_id uuid;
begin
  select a.id into v_account_id from billing.org_finance_accounts a
   where a.org_id = p_org_id and a.kind = 'payment_provider' order by a.created_at limit 1;
  if not found then
    insert into billing.org_finance_accounts (org_id, name, kind) values (p_org_id, v_provider_name, 'payment_provider')
    returning id into v_account_id;
  end if;
  insert into billing.org_finance_entries (org_id, account_id, kind, amount_agorot, occurred_at, counterparty,
                                           category, status, source, source_ref, donor_user_id, donor_tombstone)
  values (p_org_id, v_account_id, p_kind, p_amount_agorot, p_occurred_at, v_provider_name, p_category, 'cleared',
          'payment_sync', p_source_ref, p_donor_user_id, p_donor_tombstone)
  on conflict (source_ref) do nothing;
exception when others then
  perform kc_private.audit_record('finance_sync_failed', 'organization', p_org_id,
                                  jsonb_build_object('source_ref', p_source_ref, 'sqlstate', sqlstate), null);
end;
$$;
comment on function kc_private.org_finance_mirror(uuid, text, bigint, timestamptz, text, uuid, uuid, bytea, text) is
  'Mirrors a settled payment or refund into the organization''s books; never fails the caller.';

-- >>> supabase/schemas/85_billing/070_money_moves.sql
-- Billing · settling money moves
--
-- The functions that turn a provider's word into records. Each one is a single
-- transaction step: the business row, its ledger lines, the receipt, the organization's
-- books, the audit event and the notification are written together or not at all. Each
-- one is safe to repeat: a second call for the same record changes nothing.

insert into kc_private.notification_kinds (kind, category, title_key, body_key) values
  -- D20: the donor receives a confirmation.
  ('donation_succeeded', 'critical', 'notifications.donationSucceededTitle', 'notifications.donationSucceededBody'),
  ('donation_refunded', 'critical', 'notifications.donationRefundedTitle', 'notifications.donationRefundedBody'),
  -- A charge of a standing order did not go through (D80 lists it as a tracked event).
  ('standing_order_charge_failed', 'critical', 'notifications.standingOrderChargeFailedTitle',
   'notifications.standingOrderChargeFailedBody');

-- Tells a member about a money event of theirs; nothing for a purged account.
create function kc_private.billing_notify(p_kind text, p_user_id uuid, p_entity_type text, p_entity_id uuid, p_data jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  select kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', p_kind, 'recipient_id', p_user_id, 'actor_id', null,
    'entity', jsonb_build_object('type', p_entity_type, 'id', p_entity_id),
    'data', p_data || jsonb_build_object('dedupe_key', p_kind || ':' || p_entity_id)))
   where p_user_id is not null;
$$;

-- The provider reports the outcome of an intent's charge. Success: the payment, its
-- ledger transaction, the receipt and the mirrored book entry. Failure: a failed payment
-- row, and a notice when it was a standing-order charge. Returns the payment id, or null
-- when the intent was already settled that way.
-- Errors: P0001 intent_not_found, intent_not_payable, amount_mismatch.
create function kc_private.billing_payment_settle(
  p_intent_id uuid,
  p_succeeded boolean,
  p_event_key text,
  p_provider_ref text,
  p_amount_agorot bigint default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_intent billing.donation_intents;
  v_payment_id uuid;
begin
  select i.* into v_intent from billing.donation_intents i where i.id = p_intent_id for update;
  if not found then
    raise exception 'intent_not_found' using errcode = 'P0001';
  elsif v_intent.status = 'succeeded' or (v_intent.status = 'failed' and not p_succeeded) then
    return null;
  elsif v_intent.status not in ('checkout', 'failed') then
    raise exception 'intent_not_payable' using errcode = 'P0001';
  elsif p_amount_agorot is distinct from v_intent.amount_agorot and p_amount_agorot is not null then
    raise exception 'amount_mismatch' using errcode = 'P0001';
  end if;

  insert into billing.payments (intent_id, user_id, user_tombstone, org_id, amount_agorot, currency, status,
                                provider_id, provider_ref, idempotency_key)
  values (p_intent_id, v_intent.user_id, v_intent.user_tombstone, v_intent.org_id, v_intent.amount_agorot,
          v_intent.currency, case when p_succeeded then 'succeeded' else 'failed' end,
          v_intent.provider_id, p_provider_ref, p_event_key)
  returning id into v_payment_id;

  perform set_config('kc.fsm_role', 'provider', true);
  update billing.donation_intents i
     set status = case when p_succeeded then 'succeeded' else 'failed' end
   where i.id = p_intent_id;
  perform set_config('kc.fsm_role', '', true);

  perform kc_private.audit_record(
    case when p_succeeded then 'payment_succeeded' else 'payment_failed' end, 'payment', v_payment_id,
    jsonb_build_object('intent_id', p_intent_id, 'org_id', v_intent.org_id, 'amount_agorot', v_intent.amount_agorot,
                       'standing_order_id', v_intent.standing_order_id), null);

  if not p_succeeded then
    if v_intent.standing_order_id is not null then
      perform kc_private.billing_notify('standing_order_charge_failed', v_intent.user_id, 'standing_order',
        v_intent.standing_order_id, jsonb_build_object('org_id', v_intent.org_id, 'intent_id', p_intent_id));
    end if;
    return v_payment_id;
  end if;

  perform kc_private.ledger_post('payment', v_payment_id, v_intent.org_id, 'provider_clearing', 'org_payable',
                                 v_intent.amount_agorot);
  perform kc_private.billing_receipt_issue(v_payment_id);
  perform kc_private.org_finance_mirror(
    v_intent.org_id, 'donation_in', v_intent.amount_agorot, now(), 'payment:' || v_payment_id,
    v_intent.provider_id, v_intent.user_id, v_intent.user_tombstone,
    case when v_intent.standing_order_id is null then 'individual_donations' else 'standing_orders' end);
  perform kc_private.billing_notify('donation_succeeded', v_intent.user_id, 'payment', v_payment_id,
    jsonb_build_object('org_id', v_intent.org_id, 'amount_agorot', v_intent.amount_agorot));
  return v_payment_id;
end;
$$;
comment on function kc_private.billing_payment_settle(uuid, boolean, text, text, bigint) is
  'Applies the provider''s outcome of a donation intent: payment, ledger, receipt, books, audit, notice — atomically.';

-- The provider reports the outcome of a refund. Success posts the ledger, adds the amount
-- to the payment's refunded total (a full refund marks the payment `refunded`) and
-- mirrors it into the books. Errors: P0001 refund_not_found.
create function kc_private.billing_refund_settle(p_refund_id uuid, p_succeeded boolean, p_provider_ref text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_refund billing.refunds;
  v_payment billing.payments;
begin
  select r.* into v_refund from billing.refunds r where r.id = p_refund_id for update;
  if not found then
    raise exception 'refund_not_found' using errcode = 'P0001';
  elsif v_refund.status <> 'pending' then
    return;
  end if;
  select p.* into strict v_payment from billing.payments p where p.id = v_refund.payment_id for update;

  perform set_config('kc.fsm_role', 'provider', true);
  update billing.refunds r
     set status = case when p_succeeded then 'succeeded' else 'failed' end,
         provider_ref = coalesce(p_provider_ref, r.provider_ref), settled_at = now()
   where r.id = p_refund_id;
  if p_succeeded then
    update billing.payments p
       set refunded_agorot = p.refunded_agorot + v_refund.amount_agorot,
           status = case when p.refunded_agorot + v_refund.amount_agorot = p.amount_agorot
                         then 'refunded' else p.status end
     where p.id = v_payment.id;
  end if;
  perform set_config('kc.fsm_role', '', true);

  perform kc_private.audit_record('refund_settled', 'refund', p_refund_id,
    jsonb_build_object('payment_id', v_payment.id, 'org_id', v_payment.org_id, 'succeeded', p_succeeded,
                       'amount_agorot', v_refund.amount_agorot), null);
  if not p_succeeded then
    return;
  end if;
  perform kc_private.ledger_post('refund', p_refund_id, v_payment.org_id, 'org_payable', 'provider_clearing',
                                 v_refund.amount_agorot);
  perform kc_private.org_finance_mirror(
    v_payment.org_id, 'refund_out', v_refund.amount_agorot, now(), 'refund:' || p_refund_id,
    v_payment.provider_id, v_payment.user_id, v_payment.user_tombstone, 'donor_refunds');
  perform kc_private.billing_notify('donation_refunded', v_payment.user_id, 'payment', v_payment.id,
    jsonb_build_object('org_id', v_payment.org_id, 'amount_agorot', v_refund.amount_agorot,
                       'refund_id', p_refund_id));
end;
$$;
comment on function kc_private.billing_refund_settle(uuid, boolean, text) is
  'Applies the provider''s outcome of a refund, with its ledger transaction and book entry.';

-- The provider reports the outcome of a payout. Errors: P0001 payout_not_found.
create function kc_private.billing_payout_settle(p_payout_id uuid, p_succeeded boolean, p_provider_ref text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payout billing.payouts;
begin
  select p.* into v_payout from billing.payouts p where p.id = p_payout_id for update;
  if not found then
    raise exception 'payout_not_found' using errcode = 'P0001';
  elsif v_payout.status <> 'pending' then
    return;
  end if;
  perform set_config('kc.fsm_role', 'provider', true);
  update billing.payouts p
     set status = case when p_succeeded then 'succeeded' else 'failed' end,
         provider_ref = coalesce(p_provider_ref, p.provider_ref), settled_at = now()
   where p.id = p_payout_id;
  perform set_config('kc.fsm_role', '', true);
  if p_succeeded then
    perform kc_private.ledger_post('payout', p_payout_id, v_payout.org_id, 'org_payable', 'provider_clearing',
                                   v_payout.amount_agorot);
  end if;
  perform kc_private.audit_record('payout_settled', 'payout', p_payout_id,
    jsonb_build_object('org_id', v_payout.org_id, 'succeeded', p_succeeded,
                       'amount_agorot', v_payout.amount_agorot), null);
end;
$$;
comment on function kc_private.billing_payout_settle(uuid, boolean, text) is
  'Applies the provider''s outcome of a payout, with its ledger transaction.';

-- The provider confirmed a standing-order mandate: the order becomes active and its first
-- charge is due at once. Repeating the event changes nothing.
create function kc_private.billing_standing_order_activate(p_order_id uuid, p_provider_ref text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('kc.fsm_role', 'provider', true);
  update billing.standing_orders o
     set status = 'active', provider_ref = p_provider_ref, next_charge_at = now()
   where o.id = p_order_id and o.status = 'pending';
  perform set_config('kc.fsm_role', '', true);
end;
$$;

-- The provider reports the KYC state of a payer (member) or a recipient (organization).
create function kc_private.billing_kyc_set(p_party_type text, p_party_id uuid, p_status text, p_provider_ref text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('kc.fsm_role', 'provider', true);
  insert into billing.kyc_profiles (party_type, user_id, org_id, provider_ref)
  values (p_party_type, case p_party_type when 'payer' then p_party_id end,
          case p_party_type when 'recipient' then p_party_id end, p_provider_ref)
  on conflict do nothing;
  update billing.kyc_profiles k
     set status = p_status, provider_ref = coalesce(p_provider_ref, k.provider_ref),
         verified_at = case when p_status = 'approved' then now() else k.verified_at end
   where k.party_type = p_party_type and p_party_id in (k.user_id, k.org_id);
  perform set_config('kc.fsm_role', '', true);
end;
$$;
comment on function kc_private.billing_kyc_set(text, uuid, text, text) is
  'Records the KYC state the provider reports for a payer or a recipient organization.';

-- >>> supabase/schemas/85_billing/080_provider_events.sql
-- Billing · provider events and the service-role entry points
--
-- The Edge Functions (`payments-webhook`, `subscriptions-charger`) run as the service role
-- and call the functions of this file by name; no client role may execute them. The
-- webhook function verifies the provider's signature and hands over a normalized event:
--   { "type": "payment.succeeded" | "payment.failed",   "intent_id", "provider_ref", "amount_agorot"? }
--   { "type": "refund.succeeded" | "refund.failed",     "refund_id", "provider_ref"? }
--   { "type": "payout.succeeded" | "payout.failed",     "payout_id", "provider_ref"? }
--   { "type": "standing_order.activated",               "standing_order_id", "provider_ref" }
--   { "type": "kyc.updated", "party_type": "payer" | "recipient", "party_id", "status", "provider_ref"? }

-- Stores a provider event and applies it, once. A repeated event returns the stored id
-- and does nothing; an event that cannot be applied is kept as `failed` with its error
-- code, changes nothing else, and is applied again when the provider resends it.
create function public.provider_webhook_apply(p_provider_slug text, p_event_id text, p_payload jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event billing.webhook_events;
  v_type constant text := p_payload ->> 'type';
  v_ok constant boolean := v_type like '%.succeeded';
  v_ref constant text := p_payload ->> 'provider_ref';
  v_error text;
begin
  insert into billing.webhook_events (provider_slug, provider_event_id, event_type, payload)
  values (p_provider_slug, p_event_id, v_type, p_payload)
  on conflict (provider_slug, provider_event_id) do nothing
  returning * into v_event;
  if not found then
    select e.* into strict v_event from billing.webhook_events e
     where e.provider_slug = p_provider_slug and e.provider_event_id = p_event_id for update;
    if v_event.status = 'processed' then
      return v_event.id;
    end if;
  end if;

  begin
    case
      when v_type in ('payment.succeeded', 'payment.failed') then
        -- A provider settles only the intents that were sent to it.
        if not exists (select 1 from billing.donation_intents i
                         join billing.payment_providers p on p.id = i.provider_id
                        where i.id = (p_payload ->> 'intent_id')::uuid and p.slug = p_provider_slug) then
          raise exception 'intent_not_found' using errcode = 'P0001';
        end if;
        perform kc_private.billing_payment_settle(
          (p_payload ->> 'intent_id')::uuid, v_ok, p_provider_slug || ':' || p_event_id, v_ref,
          (p_payload ->> 'amount_agorot')::bigint);
      when v_type in ('refund.succeeded', 'refund.failed') then
        perform kc_private.billing_refund_settle((p_payload ->> 'refund_id')::uuid, v_ok, v_ref);
      when v_type in ('payout.succeeded', 'payout.failed') then
        perform kc_private.billing_payout_settle((p_payload ->> 'payout_id')::uuid, v_ok, v_ref);
      when v_type = 'standing_order.activated' then
        perform kc_private.billing_standing_order_activate((p_payload ->> 'standing_order_id')::uuid, v_ref);
      when v_type = 'kyc.updated' then
        perform kc_private.billing_kyc_set(p_payload ->> 'party_type', (p_payload ->> 'party_id')::uuid,
                                           p_payload ->> 'status', v_ref);
      else
        raise exception 'unknown_event_type' using errcode = 'P0001';
    end case;
  exception when others then
    -- Everything the event did is rolled back; only its failure is recorded.
    v_error := case sqlstate when 'P0001' then sqlerrm else sqlstate end;
  end;

  update billing.webhook_events e
     set status = case when v_error is null then 'processed' else 'failed' end,
         processed_at = case when v_error is null then now() end,
         error_code = v_error
   where e.id = v_event.id;
  return v_event.id;
end;
$$;
comment on function public.provider_webhook_apply(text, text, jsonb) is
  'Service role: stores and applies a provider event exactly once; returns the stored event id.';

-- The checkout session the provider opened for an intent: the donor is sent to its page.
-- Errors: P0001 intent_not_found (no such intent waiting for a checkout).
create function public.api_donation_intent_set_checkout(p_intent_id uuid, p_provider_ref text, p_checkout_url text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update billing.donation_intents i
     set status = 'checkout', provider_ref = p_provider_ref, checkout_url = p_checkout_url
   where i.id = p_intent_id and i.status = 'created';
  if not found then
    raise exception 'intent_not_found' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.api_donation_intent_set_checkout(uuid, text, text) is
  'Service role: records the provider checkout session of a donation intent.';

-- Opens the charge of every active standing order that is due and moves each order to
-- its next date. Returns the intents to charge at the provider; the outcome of each
-- arrives as a provider event. Concurrent runs never take the same order, and an order's
-- period is charged once (the intent's idempotency key names the order and the due date).
create function public.api_standing_orders_charge_due(p_limit integer default 20)
returns table (intent_id uuid, standing_order_id uuid, amount_agorot bigint, mandate_ref text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order billing.standing_orders;
begin
  for v_order in
    select o.* from billing.standing_orders o
     where o.status = 'active' and o.next_charge_at <= now()
     order by o.next_charge_at
     limit least(greatest(coalesce(p_limit, 20), 1), 200)
       for update skip locked
  loop
    insert into billing.donation_intents as i (user_id, user_tombstone, org_id, standing_order_id, amount_agorot,
                                               currency, status, provider_id, idempotency_key)
    values (v_order.user_id, v_order.user_tombstone, v_order.org_id, v_order.id, v_order.amount_agorot,
            v_order.currency, 'checkout', v_order.provider_id,
            'standing_order:' || v_order.id || ':' || to_char(v_order.next_charge_at at time zone 'UTC', 'YYYY-MM-DD'))
    on conflict (idempotency_key) do nothing
    returning i.id into intent_id;
    update billing.standing_orders o
       set next_charge_at = o.next_charge_at + case o.cadence when 'monthly' then interval '1 month'
                                                               when 'quarterly' then interval '3 months'
                                                               else interval '1 year' end
     where o.id = v_order.id;
    if intent_id is not null then
      standing_order_id := v_order.id;
      amount_agorot := v_order.amount_agorot;
      mandate_ref := v_order.provider_ref;
      return next;
    end if;
  end loop;
end;
$$;
comment on function public.api_standing_orders_charge_due(integer) is
  'Service role: opens the due charges of active standing orders and returns them for the provider.';

-- Opens a payout of what the product holds for an organization. The amount may not
-- exceed the organization's ledger balance less its payouts already on the way. The same
-- idempotency key returns the same payout.
-- Errors: P0001 insufficient_balance.
create function public.api_payout_open(p_org_id uuid, p_amount_agorot bigint, p_idempotency_key text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payout_id uuid;
begin
  -- One payout decision per organization at a time.
  perform pg_advisory_xact_lock(hashtextextended('billing.payout:' || p_org_id, 0));
  select p.id into v_payout_id from billing.payouts p where p.idempotency_key = p_idempotency_key;
  if found then
    return v_payout_id;
  end if;
  if p_amount_agorot > kc_private.billing_org_balance(p_org_id)
       - coalesce((select sum(p.amount_agorot) from billing.payouts p
                    where p.org_id = p_org_id and p.status = 'pending'), 0) then
    raise exception 'insufficient_balance' using errcode = 'P0001';
  end if;
  insert into billing.payouts (org_id, amount_agorot, idempotency_key)
  values (p_org_id, p_amount_agorot, p_idempotency_key)
  returning id into v_payout_id;
  perform kc_private.audit_record('payout_opened', 'payout', v_payout_id,
    jsonb_build_object('org_id', p_org_id, 'amount_agorot', p_amount_agorot), null);
  return v_payout_id;
end;
$$;
comment on function public.api_payout_open(uuid, bigint, text) is
  'Service role: opens a payout to an organization within its ledger balance.';

-- A platform admin opens a refund of a succeeded payment, in full or in part; the
-- provider's confirmation settles it. The same idempotency key returns the same refund.
-- Errors: forbidden (42501); P0001 payment_not_refundable, refund_exceeds_payment; 23514
-- for an unknown reason code.
create function public.admin_refund_payment(
  p_payment_id uuid,
  p_amount_agorot bigint,
  p_reason text,
  p_idempotency_key text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.require_admin_role('admin');
  v_payment billing.payments;
  v_refund_id uuid;
begin
  select p.* into v_payment from billing.payments p
   where p.id = p_payment_id and p.status = 'succeeded' for update;
  if not found then
    raise exception 'payment_not_refundable' using errcode = 'P0001';
  end if;
  select r.id into v_refund_id from billing.refunds r where r.idempotency_key = p_idempotency_key;
  if found then
    return v_refund_id;
  end if;
  if p_amount_agorot > v_payment.amount_agorot - v_payment.refunded_agorot
       - coalesce((select sum(r.amount_agorot) from billing.refunds r
                    where r.payment_id = p_payment_id and r.status = 'pending'), 0) then
    raise exception 'refund_exceeds_payment' using errcode = 'P0001';
  end if;
  insert into billing.refunds (payment_id, amount_agorot, reason, idempotency_key, opened_by)
  values (p_payment_id, p_amount_agorot, p_reason, p_idempotency_key, v_actor)
  returning id into v_refund_id;
  perform kc_private.audit_record('refund_opened', 'refund', v_refund_id,
    jsonb_build_object('payment_id', p_payment_id, 'org_id', v_payment.org_id,
                       'amount_agorot', p_amount_agorot, 'reason', p_reason));
  return v_refund_id;
end;
$$;
comment on function public.admin_refund_payment(uuid, bigint, text, text) is
  'Platform admin: opens a full or partial refund of a succeeded payment.';
grant execute on function public.admin_refund_payment(uuid, bigint, text, text) to authenticated;

-- >>> supabase/schemas/85_billing/090_donor_rpcs.sql
-- Billing · what a donor calls (D4, D20; FR-DONATE-011, FR-FIN-021)
--
-- Every function identifies the caller, reads or writes `billing` with definer rights and
-- returns only the caller's own data. Amounts are agorot.
-- Errors, SQLSTATE P0001 unless noted: unauthenticated (42501), account_not_active,
-- money_min_amount, verified_org_required, payments_unavailable, idempotency_key_conflict,
-- cadence_not_supported, order_not_found, illegal_transition.

-- An organization may receive donations when it is active and either a verified nonprofit
-- or the platform organization itself (D20: donations to KC).
create function kc_private.billing_assert_can_donate(p_org_id uuid, p_amount_agorot bigint)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_amount_agorot is null or p_amount_agorot < (select s.min_donation_agorot from billing.settings s) then
    raise exception 'money_min_amount' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.organizations o
                  where o.id = p_org_id and o.status = 'active' and (o.is_verified_nonprofit or o.is_platform)) then
    raise exception 'verified_org_required' using errcode = 'P0001';
  end if;
end;
$$;

-- Starts a one-time donation and returns the intent. The app then asks the payments Edge
-- Function for the provider's checkout page. Repeating the call with the same key returns
-- the same intent; a key that belongs to another donation is refused.
create function public.create_donation_intent(
  p_org_id uuid,
  p_amount_agorot bigint,
  p_idempotency_key text,
  p_post_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_intent billing.donation_intents;
begin
  select i.* into v_intent from billing.donation_intents i where i.idempotency_key = p_idempotency_key;
  if not found then
    perform kc_private.billing_assert_can_donate(p_org_id, p_amount_agorot);
    insert into billing.donation_intents (user_id, org_id, post_id, amount_agorot, provider_id, idempotency_key)
    values (v_user_id, p_org_id, p_post_id, p_amount_agorot, kc_private.billing_default_provider(), p_idempotency_key)
    on conflict (idempotency_key) do nothing
    returning * into v_intent;
    if not found then
      select i.* into strict v_intent from billing.donation_intents i where i.idempotency_key = p_idempotency_key;
    end if;
  end if;
  if (v_intent.user_id, v_intent.org_id, v_intent.amount_agorot) is distinct from (v_user_id, p_org_id, p_amount_agorot) then
    raise exception 'idempotency_key_conflict' using errcode = 'P0001';
  end if;
  return jsonb_build_object('intent_id', v_intent.id, 'status', v_intent.status, 'org_id', v_intent.org_id,
                            'amount_agorot', v_intent.amount_agorot, 'currency', v_intent.currency,
                            'checkout_url', v_intent.checkout_url);
end;
$$;
comment on function public.create_donation_intent(uuid, bigint, text, uuid) is
  'Starts a one-time donation of the caller to an organization; idempotent on the key.';
grant execute on function public.create_donation_intent(uuid, bigint, text, uuid) to authenticated;

-- The caller's donations that went through, newest first, each with its receipt.
-- Keyset: pass paid_at and payment_id of the last row.
create function public.list_my_donation_history(
  p_limit integer default 50,
  p_after_paid_at timestamptz default null,
  p_after_id uuid default null
)
returns table (payment_id uuid, org_id uuid, org_name text, amount_agorot bigint, refunded_agorot bigint,
               currency text, status text, paid_at timestamptz, standing_order_id uuid,
               receipt_serial bigint, sec46_eligible boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select p.id, p.org_id, o.name, p.amount_agorot, p.refunded_agorot, p.currency, p.status, p.created_at,
         i.standing_order_id, r.serial, r.sec46_eligible
    from billing.payments p
    join billing.donation_intents i on i.id = p.intent_id
    join public.organizations o on o.id = p.org_id
    left join billing.receipts r on r.payment_id = p.id
   where p.user_id = (select auth.uid())
     and p.status in ('succeeded', 'refunded')
     and (p_after_paid_at is null or (p.created_at, p.id) < (p_after_paid_at, p_after_id))
   order by p.created_at desc, p.id desc
   limit least(greatest(coalesce(p_limit, 50), 1), 100);
$$;
comment on function public.list_my_donation_history(integer, timestamptz, uuid) is
  'The caller''s settled donations with their receipts, newest first (keyset).';
grant execute on function public.list_my_donation_history(integer, timestamptz, uuid) to authenticated;

-- The receipt of one of the caller's donations; null when the payment is not theirs or
-- has no receipt.
create function public.get_donation_receipt(p_payment_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
           'receipt_id', r.id, 'serial', r.serial, 'issued_at', r.issued_at, 'payment_id', r.payment_id,
           'amount_agorot', r.amount_agorot, 'currency', r.currency, 'sec46_eligible', r.sec46_eligible,
           'sec46_approval_number', r.sec46_approval_number,
           'org_id', o.id, 'org_name', o.name, 'org_slug', o.slug)
    from billing.receipts r
    join public.organizations o on o.id = r.org_id
   where r.payment_id = p_payment_id and r.user_id = (select auth.uid());
$$;
comment on function public.get_donation_receipt(uuid) is 'The receipt record of one of the caller''s donations.';
grant execute on function public.get_donation_receipt(uuid) to authenticated;

-- What the app shows of a standing order.
create function kc_private.standing_order_json(p_order billing.standing_orders)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'order_id', p_order.id, 'org_id', p_order.org_id,
    'org_name', (select o.name from public.organizations o where o.id = p_order.org_id),
    'amount_agorot', p_order.amount_agorot, 'currency', p_order.currency, 'cadence', p_order.cadence,
    'status', p_order.status, 'next_charge_at', p_order.next_charge_at, 'cancelled_at', p_order.cancelled_at,
    'created_at', p_order.created_at);
$$;

-- Starts a monthly standing order (FR-DONATE-011). It waits as `pending` until the
-- provider confirms the mandate. Idempotent on the key, like a one-time donation.
create function public.create_standing_order(
  p_org_id uuid,
  p_amount_agorot bigint,
  p_idempotency_key text,
  p_cadence text default 'monthly'
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_order billing.standing_orders;
begin
  select o.* into v_order from billing.standing_orders o where o.idempotency_key = p_idempotency_key;
  if not found then
    if p_cadence is distinct from 'monthly' then
      raise exception 'cadence_not_supported' using errcode = 'P0001';
    end if;
    perform kc_private.billing_assert_can_donate(p_org_id, p_amount_agorot);
    insert into billing.standing_orders (user_id, org_id, amount_agorot, cadence, provider_id, idempotency_key)
    values (v_user_id, p_org_id, p_amount_agorot, p_cadence, kc_private.billing_default_provider(), p_idempotency_key)
    returning * into v_order;
  end if;
  if (v_order.user_id, v_order.org_id, v_order.amount_agorot) is distinct from (v_user_id, p_org_id, p_amount_agorot) then
    raise exception 'idempotency_key_conflict' using errcode = 'P0001';
  end if;
  return kc_private.standing_order_json(v_order);
end;
$$;
comment on function public.create_standing_order(uuid, bigint, text, text) is
  'Starts a recurring donation of the caller to an organization; idempotent on the key.';
grant execute on function public.create_standing_order(uuid, bigint, text, text) to authenticated;

-- Moves one of the caller's standing orders: `paused`, `active` (resume) or `cancelled`.
-- A resumed order is charged again from now; repeating a move is a no-op.
create function kc_private.standing_order_move(p_order_id uuid, p_to text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_order billing.standing_orders;
begin
  select o.* into v_order from billing.standing_orders o
   where o.id = p_order_id and o.user_id = v_user_id for update;
  if not found then
    raise exception 'order_not_found' using errcode = 'P0001';
  end if;
  if v_order.status <> p_to then
    update billing.standing_orders o
       set status = p_to,
           next_charge_at = case when p_to = 'active' then now() end,
           cancelled_at = case when p_to = 'cancelled' then now() end
     where o.id = p_order_id
    returning * into v_order;
    perform kc_private.audit_record('standing_order_' || p_to, 'standing_order', p_order_id,
                                    jsonb_build_object('org_id', v_order.org_id));
  end if;
  return kc_private.standing_order_json(v_order);
end;
$$;

create function public.pause_standing_order(p_order_id uuid)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select kc_private.standing_order_move(p_order_id, 'paused');
$$;
comment on function public.pause_standing_order(uuid) is 'Pauses the caller''s active standing order.';
grant execute on function public.pause_standing_order(uuid) to authenticated;

create function public.resume_standing_order(p_order_id uuid)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select kc_private.standing_order_move(p_order_id, 'active');
$$;
comment on function public.resume_standing_order(uuid) is 'Resumes the caller''s paused standing order.';
grant execute on function public.resume_standing_order(uuid) to authenticated;

create function public.cancel_standing_order(p_order_id uuid)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select kc_private.standing_order_move(p_order_id, 'cancelled');
$$;
comment on function public.cancel_standing_order(uuid) is 'Cancels the caller''s standing order for good.';
grant execute on function public.cancel_standing_order(uuid) to authenticated;

-- The caller's standing orders, newest first (a member has a handful at most).
create function public.list_my_standing_orders()
returns setof jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select kc_private.standing_order_json(o)
    from billing.standing_orders o
   where o.user_id = (select auth.uid())
   order by o.created_at desc
   limit 100;
$$;
comment on function public.list_my_standing_orders() is 'The caller''s standing orders, newest first.';
grant execute on function public.list_my_standing_orders() to authenticated;

-- >>> supabase/schemas/85_billing/100_org_finance_rpcs.sql
-- Billing · the organization's finance screens (requirements/19; Admin Portal finance sub-tree)
--
-- Every function takes the organization and starts with kc_private.finance_assert, so a
-- finance role of one organization never reaches the books of another (FR-FIN-001 AC2).
-- Every write is audited with ids only.
-- Errors: forbidden (42501); P0001 — account_not_found, entry_not_found, invalid_date,
-- invalid_settings, entry_voided, entry_reconciled, entry_locked_by_source,
-- illegal_transition; SQLSTATE 23xxx for a value a column refuses.

-- Accounts of an organization with their balance: opening balance plus cleared income
-- minus cleared expenses (FR-FIN-003 AC1).
create function public.finance_accounts_list(p_org_id uuid)
returns table (id uuid, name text, kind text, last4 text, opening_balance_agorot bigint, opening_balance_at date,
               is_active boolean, sort_order integer, balance_agorot bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform kc_private.finance_assert(p_org_id, 'view');
  return query
  select a.id, a.name, a.kind, a.last4, a.opening_balance_agorot, a.opening_balance_at, a.is_active, a.sort_order,
         (a.opening_balance_agorot + coalesce((
            select sum(case e.direction when 'in' then e.amount_agorot when 'out' then -e.amount_agorot else 0 end)
              from billing.org_finance_entries e
             where e.account_id = a.id and e.status = 'cleared'), 0))::bigint
    from billing.org_finance_accounts a
   where a.org_id = p_org_id
   order by a.is_active desc, a.sort_order, a.name;
end;
$$;
comment on function public.finance_accounts_list(uuid) is 'Finance roles: the accounts of an organization with their balances.';
grant execute on function public.finance_accounts_list(uuid) to authenticated;

-- Creates an account (p_account_id null) or changes one; null leaves a field as it is.
create function public.finance_account_upsert(
  p_org_id uuid,
  p_account_id uuid default null,
  p_name text default null,
  p_kind text default null,
  p_last4 text default null,
  p_opening_balance_agorot bigint default null,
  p_opening_balance_at date default null,
  p_is_active boolean default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.finance_assert(p_org_id, 'manage');
  v_id uuid;
begin
  if p_account_id is null then
    insert into billing.org_finance_accounts (org_id, name, kind, last4, opening_balance_agorot, opening_balance_at,
                                              is_active, created_by)
    values (p_org_id, btrim(p_name), p_kind, p_last4, coalesce(p_opening_balance_agorot, 0), p_opening_balance_at,
            coalesce(p_is_active, true), v_actor)
    returning id into v_id;
  else
    update billing.org_finance_accounts a
       set name = coalesce(btrim(p_name), a.name), kind = coalesce(p_kind, a.kind), last4 = coalesce(p_last4, a.last4),
           opening_balance_agorot = coalesce(p_opening_balance_agorot, a.opening_balance_agorot),
           opening_balance_at = coalesce(p_opening_balance_at, a.opening_balance_at),
           is_active = coalesce(p_is_active, a.is_active)
     where a.id = p_account_id and a.org_id = p_org_id
    returning a.id into v_id;
    if not found then
      raise exception 'account_not_found' using errcode = 'P0001';
    end if;
  end if;
  perform kc_private.audit_record('finance_account_upsert', 'organization', p_org_id,
                                  jsonb_build_object('account_id', v_id));
  return v_id;
end;
$$;
comment on function public.finance_account_upsert(uuid, uuid, text, text, text, bigint, date, boolean) is
  'Finance managers: creates or changes a financial account of an organization.';
grant execute on function public.finance_account_upsert(uuid, uuid, text, text, text, bigint, date, boolean) to authenticated;

-- The books of an organization, newest first. Voided entries are listed only when asked
-- for by status. Keyset: pass occurred_at and id of the last row.
create function public.finance_ledger_list(
  p_org_id uuid,
  p_direction text default null,
  p_status text default null,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_limit integer default 100,
  p_after_occurred_at timestamptz default null,
  p_after_id uuid default null
)
returns table (id uuid, kind text, direction text, amount_agorot bigint, currency text, occurred_at timestamptz,
               account_id uuid, counterparty text, category text, description text, status text,
               void_reason text, is_public boolean, source text, reconciled_at timestamptz,
               created_at timestamptz, updated_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform kc_private.finance_assert(p_org_id, 'view');
  return query
  select e.id, e.kind, e.direction, e.amount_agorot, e.currency, e.occurred_at, e.account_id, e.counterparty,
         e.category, e.description, e.status, e.void_reason, e.is_public, e.source, e.reconciled_at,
         e.created_at, e.updated_at
    from billing.org_finance_entries e
   where e.org_id = p_org_id
     and e.status = coalesce(p_status, case e.status when 'cancelled' then null else e.status end)
     and (p_direction is null or e.direction = p_direction)
     and (p_from is null or e.occurred_at >= p_from)
     and (p_to is null or e.occurred_at <= p_to)
     and (p_after_occurred_at is null or (e.occurred_at, e.id) < (p_after_occurred_at, p_after_id))
   order by e.occurred_at desc, e.id desc
   limit least(greatest(coalesce(p_limit, 100), 1), 500);
end;
$$;
comment on function public.finance_ledger_list(uuid, text, text, timestamptz, timestamptz, integer, timestamptz, uuid) is
  'Finance roles: the entries of an organization''s books, newest first (keyset).';
grant execute on function public.finance_ledger_list(uuid, text, text, timestamptz, timestamptz, integer, timestamptz, uuid)
  to authenticated;

-- Creates an entry (p_entry_id null) or changes one; null leaves a field as it is. The
-- date may not lie more than a day ahead (FR-FIN-005 AC1); what a reconciled or mirrored
-- entry may still change is decided by the table's guard.
create function public.finance_ledger_upsert(
  p_org_id uuid,
  p_entry_id uuid default null,
  p_kind text default null,
  p_amount_agorot bigint default null,
  p_occurred_at timestamptz default null,
  p_account_id uuid default null,
  p_counterparty text default null,
  p_category text default null,
  p_description text default null,
  p_status text default null,
  p_is_public boolean default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.finance_assert(p_org_id, 'manage');
  v_id uuid;
begin
  if p_occurred_at > now() + interval '1 day' then
    raise exception 'invalid_date' using errcode = 'P0001';
  end if;
  if p_account_id is not null and not exists (
       select 1 from billing.org_finance_accounts a
        where a.id = p_account_id and a.org_id = p_org_id and a.is_active) then
    raise exception 'account_not_found' using errcode = 'P0001';
  end if;
  if p_entry_id is null then
    insert into billing.org_finance_entries (org_id, kind, amount_agorot, occurred_at, account_id, counterparty,
                                             category, description, status, is_public, created_by)
    values (p_org_id, p_kind, p_amount_agorot, coalesce(p_occurred_at, now()), p_account_id, p_counterparty,
            p_category, p_description, coalesce(p_status, 'pending'), coalesce(p_is_public, true), v_actor)
    returning id into v_id;
  else
    update billing.org_finance_entries e
       set kind = coalesce(p_kind, e.kind), amount_agorot = coalesce(p_amount_agorot, e.amount_agorot),
           occurred_at = coalesce(p_occurred_at, e.occurred_at), account_id = coalesce(p_account_id, e.account_id),
           counterparty = coalesce(p_counterparty, e.counterparty), category = coalesce(p_category, e.category),
           description = coalesce(p_description, e.description), status = coalesce(p_status, e.status),
           is_public = coalesce(p_is_public, e.is_public)
     where e.id = p_entry_id and e.org_id = p_org_id
    returning e.id into v_id;
    if not found then
      raise exception 'entry_not_found' using errcode = 'P0001';
    end if;
  end if;
  perform kc_private.audit_record(
    case when p_entry_id is null then 'finance_entry_create' else 'finance_entry_update' end,
    'organization', p_org_id, jsonb_build_object('entry_id', v_id));
  return v_id;
end;
$$;
comment on function public.finance_ledger_upsert(uuid, uuid, text, bigint, timestamptz, uuid, text, text, text, text, boolean) is
  'Finance managers: creates or changes an entry of an organization''s books.';
grant execute on function public.finance_ledger_upsert(uuid, uuid, text, bigint, timestamptz, uuid, text, text, text, text, boolean)
  to authenticated;

-- Voids an entry with a reason (p_reason given), or marks it reconciled / not reconciled
-- (p_reconciled given). A voided entry stays in the books and counts nowhere.
create function public.finance_ledger_mark(
  p_org_id uuid,
  p_entry_id uuid,
  p_void_reason text default null,
  p_reconciled boolean default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor constant uuid := kc_private.finance_assert(p_org_id, 'manage');
begin
  update billing.org_finance_entries e
     set status = case when p_void_reason is null then e.status else 'cancelled' end,
         void_reason = coalesce(btrim(p_void_reason), e.void_reason),
         reconciled_at = case when p_reconciled is null then e.reconciled_at when p_reconciled then now() end,
         reconciled_by = case when p_reconciled is null then e.reconciled_by when p_reconciled then v_actor end
   where e.id = p_entry_id and e.org_id = p_org_id;
  if not found then
    raise exception 'entry_not_found' using errcode = 'P0001';
  end if;
  perform kc_private.audit_record(
    case when p_void_reason is not null then 'finance_entry_void' else 'finance_reconcile' end,
    'organization', p_org_id, jsonb_build_object('entry_id', p_entry_id, 'reconciled', p_reconciled));
end;
$$;
comment on function public.finance_ledger_mark(uuid, uuid, text, boolean) is
  'Finance managers: voids an entry, or sets or clears its reconciliation.';
grant execute on function public.finance_ledger_mark(uuid, uuid, text, boolean) to authenticated;

-- Switches the public finance blocks of an organization (FR-FIN-022 AC1). p_settings maps
-- block names to booleans; a block that is not named keeps its state.
create function public.finance_transparency_settings_set(p_org_id uuid, p_settings jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.finance_assert(p_org_id, 'transparency');
  if jsonb_typeof(p_settings) is distinct from 'object' or exists (
       select 1 from jsonb_each(p_settings) s
        where s.key not in ('show_totals', 'show_donations_count', 'show_program_ratio',
                            'show_category_breakdown', 'show_monthly_trend')
           or jsonb_typeof(s.value) <> 'boolean') then
    raise exception 'invalid_settings' using errcode = 'P0001';
  end if;
  update public.organizations o
     set show_totals = coalesce((p_settings ->> 'show_totals')::boolean, o.show_totals),
         show_donations_count = coalesce((p_settings ->> 'show_donations_count')::boolean, o.show_donations_count),
         show_program_ratio = coalesce((p_settings ->> 'show_program_ratio')::boolean, o.show_program_ratio),
         show_category_breakdown = coalesce((p_settings ->> 'show_category_breakdown')::boolean, o.show_category_breakdown),
         show_monthly_trend = coalesce((p_settings ->> 'show_monthly_trend')::boolean, o.show_monthly_trend)
   where o.id = p_org_id;
  perform kc_private.audit_record('transparency_settings_set', 'organization', p_org_id, p_settings);
end;
$$;
comment on function public.finance_transparency_settings_set(uuid, jsonb) is
  'Organization admins: choose which live finance blocks the public page shows.';
grant execute on function public.finance_transparency_settings_set(uuid, jsonb) to authenticated;

-- Records the Section 46(a) approval of an organization (FR-FIN-007 AC2). `none` and
-- `pending` clear the number and the dates; `active` needs all three (table constraint).
create function public.finance_sec46_set(
  p_org_id uuid,
  p_status text,
  p_approval_number text default null,
  p_valid_from date default null,
  p_valid_until date default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_keep constant boolean := p_status not in ('none', 'pending');
begin
  perform kc_private.finance_assert(p_org_id, 'manage');
  update public.organizations o
     set sec46_status = p_status,
         sec46_approval_number = case when v_keep then p_approval_number end,
         sec46_valid_from = case when v_keep then p_valid_from end,
         sec46_valid_until = case when v_keep then p_valid_until end
   where o.id = p_org_id;
end;
$$;
comment on function public.finance_sec46_set(uuid, text, text, date, date) is
  'Finance managers: records the Section 46(a) approval an organization holds.';
grant execute on function public.finance_sec46_set(uuid, text, text, date, date) to authenticated;

-- >>> supabase/schemas/85_billing/110_entitlements.sql
-- Billing · member entitlements (Pro tier)
--
-- Whether a member holds the paid tier, and until when. The store purchase itself is
-- handled by RevenueCat; its webhook (Edge Function `revenuecat-webhook`, service role)
-- reports the state here. An entitlement granted by hand (support, promotion) is never
-- overwritten by the store.

create table billing.user_entitlements (
  user_id    uuid primary key references public.users (id) on delete cascade,
  tier       text not null default 'pro' check (tier in ('pro')),
  source     text not null check (source in ('revenuecat', 'admin', 'promo')),
  active     boolean not null default true,
  -- Null = no end date.
  expires_at timestamptz,
  updated_at timestamptz not null default now()
);
comment on table billing.user_entitlements is 'Paid-tier entitlement of a member, as reported by the store or granted by hand.';

create trigger user_entitlements_set_updated_at
  before update on billing.user_entitlements
  for each row execute function kc_private.set_updated_at();

alter table billing.user_entitlements enable row level security;
alter table billing.user_entitlements force row level security;
revoke insert, update, delete, truncate on billing.user_entitlements from service_role;

-- True while the member's entitlement is switched on and has not run out.
create function kc_private.is_pro(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from billing.user_entitlements e
     where e.user_id = p_user_id and e.active and (e.expires_at is null or e.expires_at > now()));
$$;
comment on function kc_private.is_pro(uuid) is 'The member holds the Pro tier right now.';

-- The caller's own tier.
create function public.api_my_pro_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'is_pro', kc_private.is_pro((select auth.uid())),
    'expires_at', (select e.expires_at from billing.user_entitlements e where e.user_id = (select auth.uid())),
    'source', (select e.source from billing.user_entitlements e where e.user_id = (select auth.uid())));
$$;
comment on function public.api_my_pro_status() is 'Whether the caller holds the Pro tier, until when and from which source.';
grant execute on function public.api_my_pro_status() to authenticated;

-- Sets a member's entitlement from a given source and returns what happened:
--   unknown_user          no such member
--   skipped_manual_grant  the store may not replace an active entitlement granted by hand
--   granted | revoked
create function kc_private.entitlement_set(p_user_id uuid, p_active boolean, p_expires_at timestamptz, p_source text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.users u where u.id = p_user_id) then
    return jsonb_build_object('status', 'unknown_user');
  end if;
  if p_source = 'revenuecat' and exists (
       select 1 from billing.user_entitlements e
        where e.user_id = p_user_id and e.source <> 'revenuecat' and e.active) then
    return jsonb_build_object('status', 'skipped_manual_grant');
  end if;
  insert into billing.user_entitlements (user_id, source, active, expires_at)
  values (p_user_id, p_source, coalesce(p_active, false), p_expires_at)
  on conflict (user_id) do update
    set source = excluded.source, active = excluded.active, expires_at = excluded.expires_at;
  return jsonb_build_object('status', case when p_active then 'granted' else 'revoked' end);
end;
$$;

create function public.api_revenuecat_set_pro(p_user_id uuid, p_active boolean, p_expires_at timestamptz)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select kc_private.entitlement_set(p_user_id, p_active, p_expires_at, 'revenuecat');
$$;
comment on function public.api_revenuecat_set_pro(uuid, boolean, timestamptz) is
  'Service role (RevenueCat webhook): reports a member''s store subscription state.';

create function public.api_set_pro_entitlement(
  p_user_id uuid,
  p_active boolean,
  p_expires_at timestamptz default null,
  p_source text default 'admin'
)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select kc_private.entitlement_set(p_user_id, p_active, p_expires_at, p_source);
$$;
comment on function public.api_set_pro_entitlement(uuid, boolean, timestamptz, text) is
  'Service role (operations): grants or revokes the Pro tier by hand.';

-- >>> supabase/schemas/85_billing/120_account_purge.sql
-- Billing · money records of a purged account (design §4.1.4, §12 Q5)
--
-- When an account is purged its money records stay: payments, receipts, donation intents,
-- standing orders and the organizations' book entries are statutory records. What goes is
-- the link to the person — `user_id` is replaced by the account's deletion tombstone (the
-- salted hash of audit.deletion_tombstones), so the rows of one former member still
-- belong together and can be matched to a tombstone, but name nobody.
--
-- How long they are then kept is one setting (billing.settings.retention_after_account_deletion).
-- It is empty until the legal question is answered, and while it is empty nothing is due.
-- This baseline erases nothing: the function at the end only lists what a future purge
-- may take.

-- One row per purged member who left money records behind.
create table billing.detached_parties (
  user_tombstone bytea primary key check (octet_length(user_tombstone) = 32),
  detached_at    timestamptz not null default now()
);
comment on table billing.detached_parties is 'Tombstones of purged members with money records, and when they were detached.';
alter table billing.detached_parties enable row level security;
alter table billing.detached_parties force row level security;
revoke insert, update, delete, truncate on billing.detached_parties from service_role;

-- Detaches a member's money records from their account. The purge job calls it for each
-- account before it removes the auth identity; calling it again, or for a member without
-- money records, changes nothing. Open standing orders and unpaid intents are cancelled:
-- nobody is left to charge.
create function kc_private.billing_detach_user(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hash constant bytea := kc_private.audit_tombstone_hash(p_user_id);
  v_rows bigint := 0;
  v_step bigint;
begin
  update billing.standing_orders o
     set user_id = null, user_tombstone = v_hash,
         status = 'cancelled', next_charge_at = null,
         cancelled_at = coalesce(o.cancelled_at, now())
   where o.user_id = p_user_id;
  get diagnostics v_rows = row_count;
  update billing.donation_intents i
     set user_id = null, user_tombstone = v_hash,
         status = case when i.status in ('created', 'checkout') then 'cancelled' else i.status end
   where i.user_id = p_user_id;
  get diagnostics v_step = row_count;
  v_rows := v_rows + v_step;
  update billing.payments p set user_id = null, user_tombstone = v_hash where p.user_id = p_user_id;
  update billing.receipts r set user_id = null, user_tombstone = v_hash where r.user_id = p_user_id;
  update billing.org_finance_entries e set donor_user_id = null, donor_tombstone = v_hash
   where e.donor_user_id = p_user_id;
  get diagnostics v_step = row_count;
  v_rows := v_rows + v_step;

  if v_rows > 0 then
    insert into billing.detached_parties (user_tombstone) values (v_hash) on conflict do nothing;
    perform kc_private.audit_record('billing_user_detached', 'user', null,
                                    jsonb_build_object('tombstone', encode(v_hash, 'hex')), null);
  end if;
end;
$$;
comment on function kc_private.billing_detach_user(uuid) is
  'Purge job: replaces a member''s reference in the money records by their deletion tombstone.';

-- Safety net: the same detachment runs whenever a member row is deleted, so an account
-- removal can neither fail on a money record nor take one with it, whichever path deletes
-- the account. The foreign keys (`on delete set null`) then find nothing left to clear.
create function kc_private.users_detach_billing()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.billing_detach_user(old.id);
  return old;
end;
$$;

create trigger users_detach_billing
  before delete on public.users
  for each row execute function kc_private.users_detach_billing();

-- Tombstones whose retention period has ended. Empty while the period is not set.
create function kc_private.billing_detached_past_retention()
returns setof bytea
language sql
stable
security definer
set search_path = ''
as $$
  select d.user_tombstone
    from billing.detached_parties d
   cross join billing.settings s
   where d.detached_at <= now() - s.retention_after_account_deletion;
$$;
comment on function kc_private.billing_detached_past_retention() is
  'Tombstones of purged members whose money records are past the retention period; none while the period is unset.';

-- >>> supabase/schemas/85_billing/130_public_pages.sql
-- Billing · what every signed-in member may see of an organization's money
--
-- Two read-only pages, for signed-in members only (design §12.1: nothing for signed-out
-- callers). Both return totals, never a donor, a counterparty, an account or an entry
-- (FR-FIN-019 AC6, FR-FIN-022 AC3).

-- The donations page of a verified nonprofit (FR-ORG-010): its profile texts, the total
-- raised through the product and its campaign posts with what each raised. Null for an
-- unknown, suspended or unverified organization.
create function public.get_nonprofit_public_page(p_org_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'org_id', o.id, 'slug', o.slug, 'name', o.name,
    'tagline_he', o.public_tagline_he, 'tagline_en', o.public_tagline_en,
    'about_he', o.public_about_he, 'about_en', o.public_about_en,
    'is_verified_nonprofit', o.is_verified_nonprofit, 'verification_level', o.verification_level,
    'sec46_active', o.sec46_status = 'active' and current_date between o.sec46_valid_from and o.sec46_valid_until,
    'total_raised_agorot', (
      select coalesce(sum(p.amount_agorot - p.refunded_agorot), 0)
        from billing.payments p
       where p.org_id = o.id and p.status = 'succeeded'),
    'campaigns', coalesce((
      select jsonb_agg(jsonb_build_object(
               'post_id', c.id, 'title', c.title, 'status', c.status, 'published_at', c.published_at,
               'raised_agorot', (
                 select coalesce(sum(p.amount_agorot - p.refunded_agorot), 0)
                   from billing.donation_intents i
                   join billing.payments p on p.intent_id = i.id and p.status = 'succeeded'
                  where i.post_id = c.id))
             order by c.published_at desc)
        from public.posts c
       where c.beneficiary_org_id = o.id and c.world_slug = 'money' and c.visibility = 'Public'
         and c.status in ('open', 'closed_delivered')), '[]'::jsonb))
    from public.organizations o
   where o.slug = p_org_slug and o.is_verified_nonprofit and o.status = 'active'
     and (select auth.uid()) is not null;
$$;
comment on function public.get_nonprofit_public_page(text) is
  'Donations page of a verified nonprofit: profile texts, total raised and campaigns. Totals only.';
grant execute on function public.get_nonprofit_public_page(text) to authenticated;

-- Live public finance numbers of an organization (FR-FIN-022, D111); p_slug null = the
-- platform organization. Only the blocks the organization switched on are returned, computed
-- over cleared public entries, transfers aside; `{"enabled": false}` when the organization
-- is unknown or shows nothing. Expense categories outside the app's list fold into
-- `other_out` (the list mirrors FINANCE_EXPENSE_CATEGORIES of @kc/domain).
create function public.rpc_org_transparency(p_slug text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_org public.organizations;
  v_income bigint;
  v_expense bigint;
  v_program bigint;
  v_count bigint;
  v_last timestamptz;
  v_result jsonb;
begin
  perform kc_private.require_caller();
  select o.* into v_org from public.organizations o
   where o.status = 'active' and case when p_slug is null then o.is_platform else o.slug = p_slug end;
  if not found or not (v_org.show_totals or v_org.show_donations_count or v_org.show_program_ratio
                       or v_org.show_category_breakdown or v_org.show_monthly_trend) then
    return jsonb_build_object('enabled', false);
  end if;

  select coalesce(sum(e.amount_agorot) filter (where e.direction = 'in'), 0),
         coalesce(sum(e.amount_agorot) filter (where e.direction = 'out'), 0),
         coalesce(sum(e.amount_agorot) filter (where e.direction = 'out' and e.category = 'program'), 0),
         count(*) filter (where e.kind in ('donation_in', 'grant_in')),
         max(e.occurred_at)
    into v_income, v_expense, v_program, v_count, v_last
    from billing.org_finance_entries e
   where e.org_id = v_org.id and e.status = 'cleared' and e.is_public and e.direction is not null;

  v_result := jsonb_build_object('enabled', true, 'currency', 'ILS', 'last_entry_at', v_last);
  if v_org.show_totals then
    v_result := v_result || jsonb_build_object(
      'income_agorot', v_income, 'expense_agorot', v_expense, 'net_agorot', v_income - v_expense);
  end if;
  if v_org.show_donations_count then
    v_result := v_result || jsonb_build_object('donations_count', v_count);
  end if;
  if v_org.show_program_ratio and v_expense > 0 then
    v_result := v_result || jsonb_build_object('program_ratio', round(v_program::numeric / v_expense, 4));
  end if;
  if v_org.show_category_breakdown then
    v_result := v_result || jsonb_build_object('by_category', coalesce((
      select jsonb_agg(jsonb_build_object('key', c.key, 'agorot', c.agorot) order by c.agorot desc)
        from (select case when e.category in ('program', 'payroll', 'rent_ops', 'marketing_fundraising',
                                              'admin_general', 'fees', 'donor_refunds')
                          then e.category else 'other_out' end as key,
                     sum(e.amount_agorot)::bigint as agorot
                from billing.org_finance_entries e
               where e.org_id = v_org.id and e.status = 'cleared' and e.is_public and e.direction = 'out'
               group by 1) c), '[]'::jsonb));
  end if;
  if v_org.show_monthly_trend then
    -- The last twelve calendar months, empty ones included.
    v_result := v_result || jsonb_build_object('monthly', (
      select jsonb_agg(jsonb_build_object('month', to_char(s.month, 'YYYY-MM'), 'income_agorot', s.income,
                                          'expense_agorot', s.expense) order by s.month)
        from (select m.month,
                     coalesce(sum(e.amount_agorot) filter (where e.direction = 'in'), 0)::bigint as income,
                     coalesce(sum(e.amount_agorot) filter (where e.direction = 'out'), 0)::bigint as expense
                from generate_series(date_trunc('month', now()) - interval '11 months',
                                     date_trunc('month', now()), interval '1 month') as m (month)
                left join billing.org_finance_entries e
                  on e.org_id = v_org.id and e.status = 'cleared' and e.is_public and e.direction is not null
                 and date_trunc('month', e.occurred_at) = m.month
               group by m.month) s));
  end if;
  return v_result;
end;
$$;
comment on function public.rpc_org_transparency(text) is
  'Live public finance numbers of an organization, limited to the blocks it switched on. Totals only.';
grant execute on function public.rpc_org_transparency(text) to authenticated;

-- >>> supabase/schemas/90_research/010_surveys.sql
-- Research · in-app surveys (FR-SETTINGS-015, FR-SETTINGS-016)
--
-- Surveys are server-driven: the app renders whatever the current version of a survey
-- holds, so wording changes without an app release. Publishing creates a new immutable
-- version with its questions; answers belong to a question, hence to one version, and a
-- new version starts every member over. Members read the catalog and their own answers
-- under RLS; they write answers only through upsert_survey_answers().

create table public.surveys (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,60}$'),
  title_he        text not null check (char_length(title_he) between 1 and 200),
  description_he  text check (char_length(description_he) <= 1000),
  is_active       boolean not null default true,
  -- 0 until the first version is published.
  current_version integer not null default 0 check (current_version >= 0),
  -- When the prompt banner is offered (FR-SETTINGS-016 AC6, AC10):
  --   { "min_sessions": 3, "min_active_days_14d": 2, "require_closure": true,
  --     "require_profile_complete": true }
  prompt_rules    jsonb not null default '{}'::jsonb check (jsonb_typeof(prompt_rules) = 'object'),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
comment on table public.surveys is 'Catalog of server-driven surveys; current_version advances on each publish.';

create trigger surveys_set_updated_at
  before update on public.surveys
  for each row execute function kc_private.set_updated_at();

create table public.survey_versions (
  id           uuid primary key default gen_random_uuid(),
  survey_id    uuid not null references public.surveys (id) on delete cascade,
  version      integer not null check (version >= 1),
  -- The admin who published it; kept as null once their account is removed.
  published_by uuid references public.users (id) on delete set null,
  published_at timestamptz not null default now(),
  -- Also the lookup of a survey's current version; covers the survey foreign key.
  constraint survey_versions_survey_version_key unique (survey_id, version)
);
comment on table public.survey_versions is 'One immutable row per published version of a survey.';

-- Covers the publisher foreign key (account removal).
create index survey_versions_published_by_idx on public.survey_versions (published_by)
  where published_by is not null;

create table public.survey_questions (
  id                    uuid primary key default gen_random_uuid(),
  survey_version_id     uuid not null references public.survey_versions (id) on delete cascade,
  sort_order            integer not null,
  -- A 1–7 rating, or exactly one of `choice_options`; both take an optional text.
  question_type         text not null default 'rating_1_7_with_optional_text' check (question_type in
                          ('rating_1_7_with_optional_text', 'single_choice_with_optional_text')),
  short_label_he        text not null,
  prompt_he             text not null,
  context_he            text not null default '',
  text_placeholder_he   text not null default '',
  -- Labels of the two ends of the rating scale.
  rating_anchor_low_he  text not null default '',
  rating_anchor_high_he text not null default '',
  -- Single-choice questions only: ordered [{ "key", "label_he" }], two to six options.
  choice_options        jsonb,
  -- Questions of a version in display order; covers the version foreign key.
  constraint survey_questions_version_order_key unique (survey_version_id, sort_order),
  constraint survey_questions_choice_options_chk check (case question_type
    when 'single_choice_with_optional_text' then
      jsonb_typeof(choice_options) = 'array' and jsonb_array_length(choice_options) between 2 and 6
    else choice_options is null end)
);
comment on table public.survey_questions is 'Ordered questions of one survey version.';

create table public.survey_answers (
  user_id     uuid not null references public.users (id) on delete cascade,
  question_id uuid not null references public.survey_questions (id) on delete cascade,
  rating      integer check (rating between 1 and 7),
  choice_key  text check (char_length(choice_key) between 1 and 64),
  answer_text text check (char_length(answer_text) between 1 and 500),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  -- One answer per member per question; editable while the version is current.
  primary key (user_id, question_id),
  -- An answer is a rating or a chosen option, never both (FR-SETTINGS-016 AC9).
  constraint survey_answers_one_value_chk check (num_nonnulls(rating, choice_key) = 1)
);
comment on table public.survey_answers is 'A member''s answer to one survey question. Written through upsert_survey_answers().';

-- Results of a question; covers the question foreign key.
create index survey_answers_question_idx on public.survey_answers (question_id);

create trigger survey_answers_set_updated_at
  before update on public.survey_answers
  for each row execute function kc_private.set_updated_at();

alter table public.surveys enable row level security;
alter table public.surveys force row level security;
alter table public.survey_versions enable row level security;
alter table public.survey_versions force row level security;
alter table public.survey_questions enable row level security;
alter table public.survey_questions force row level security;
alter table public.survey_answers enable row level security;
alter table public.survey_answers force row level security;

-- Members read surveys that are active and published, with their versions and questions.
-- The version and question subqueries run under the caller's access to the parent table.
create policy surveys_select_published on public.surveys
  for select to authenticated
  using (is_active and current_version > 0);
create policy survey_versions_select_member on public.survey_versions
  for select to authenticated
  using (exists (select 1 from public.surveys s where s.id = survey_versions.survey_id));
create policy survey_questions_select_member on public.survey_questions
  for select to authenticated
  using (exists (select 1 from public.survey_versions v where v.id = survey_questions.survey_version_id));
-- A member reads only their own answers.
create policy survey_answers_select_own on public.survey_answers
  for select to authenticated
  using (user_id = (select auth.uid()));
-- The super admin reads every survey (retired ones too) and every answer, for the results
-- screens (FR-ADMIN, survey reports).
create policy surveys_select_super_admin on public.surveys
  for select to authenticated
  using ((select kc_access.has_admin_role('super_admin')));
create policy survey_answers_select_super_admin on public.survey_answers
  for select to authenticated
  using ((select kc_access.has_admin_role('super_admin')));

grant select on public.surveys to authenticated;
grant select on public.survey_versions to authenticated;
grant select on public.survey_questions to authenticated;
grant select on public.survey_answers to authenticated;

-- >>> supabase/schemas/90_research/020_survey_rpcs.sql
-- Research · survey RPCs (FR-SETTINGS-016)
--
-- Reading a survey needs no RPC: the app selects `surveys` with its current version, the
-- questions and the caller's own answers under RLS. These are the writes and the prompt rule.

-- Saves the caller's answers to questions of the survey's current version; an answer given
-- before is replaced (FR-SETTINGS-016 AC4).
--   p_answers   [{ "question_id", "rating" | "choice_key", "answer_text"? }], at most 50
--   survey_not_found   no active, published survey with this slug
--   invalid_input      not an array, a question of another version, a rating on a choice
--                      question (or the reverse), or a key that is not one of its options
create function public.upsert_survey_answers(p_slug text, p_answers jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_version_id uuid;
  v_written integer;
begin
  select v.id into v_version_id
    from public.surveys s
    join public.survey_versions v on v.survey_id = s.id and v.version = s.current_version
   where s.slug = p_slug and s.is_active;
  if not found then
    raise exception 'survey_not_found' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_answers) is distinct from 'array' or jsonb_array_length(p_answers) > 50 then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  insert into public.survey_answers as sa (user_id, question_id, rating, choice_key, answer_text)
  select v_user_id, q.id, a.rating, a.choice_key, nullif(btrim(a.answer_text), '')
    from jsonb_to_recordset(p_answers)
           as a (question_id uuid, rating integer, choice_key text, answer_text text)
    join public.survey_questions q on q.id = a.question_id and q.survey_version_id = v_version_id
   where case q.question_type
           when 'single_choice_with_optional_text' then
             a.rating is null
             and q.choice_options @> jsonb_build_array(jsonb_build_object('key', a.choice_key))
           else a.choice_key is null and a.rating is not null end
  on conflict (user_id, question_id) do update
    set rating = excluded.rating, choice_key = excluded.choice_key, answer_text = excluded.answer_text;
  get diagnostics v_written = row_count;
  -- All or nothing: one answer that does not fit its question refuses the call.
  if v_written <> jsonb_array_length(p_answers) then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.upsert_survey_answers(text, jsonb) is
  'Saves the caller''s answers to the current version of a survey.';
grant execute on function public.upsert_survey_answers(text, jsonb) to authenticated;

-- Whether the survey's prompt banner should be offered to the caller now
-- (FR-SETTINGS-016 AC6, AC10): { "show": bool, "reasons": [text] }. The session count is
-- the device's own number; active days are counted on the server.
create function public.check_survey_prompt_eligibility(p_slug text, p_session_count integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_survey public.surveys;
  v_reasons text[] := '{}';
begin
  select s.* into v_survey from public.surveys s
   where s.slug = p_slug and s.is_active and s.current_version > 0;
  if not found then
    return jsonb_build_object('show', false, 'reasons', array['survey_inactive_or_not_found']);
  end if;

  -- Every question of the current version already has the caller's answer.
  if not exists (
       select 1
         from public.survey_versions v
         join public.survey_questions q on q.survey_version_id = v.id
        where v.survey_id = v_survey.id and v.version = v_survey.current_version
          and not exists (select 1 from public.survey_answers a
                           where a.user_id = v_user_id and a.question_id = q.id)) then
    v_reasons := array_append(v_reasons, 'already_completed');
  end if;
  if coalesce(p_session_count, 0) < (v_survey.prompt_rules ->> 'min_sessions')::integer then
    v_reasons := array_append(v_reasons, 'session_count_below_threshold');
  end if;
  if kc_private.user_active_days_14d(v_user_id) < (v_survey.prompt_rules ->> 'min_active_days_14d')::integer then
    v_reasons := array_append(v_reasons, 'active_days_below_threshold');
  end if;
  if (v_survey.prompt_rules ->> 'require_closure')::boolean and not exists (
       select 1 from public.posts p where p.owner_id = v_user_id and p.status = 'closed_delivered') then
    v_reasons := array_append(v_reasons, 'no_closed_delivered_post');
  end if;
  if (v_survey.prompt_rules ->> 'require_profile_complete')::boolean then
    if not exists (select 1 from public.users u where u.id = v_user_id and u.display_name is not null) then
      v_reasons := array_append(v_reasons, 'profile_incomplete_display_name');
    end if;
    if not exists (select 1 from public.user_stats s where s.user_id = v_user_id and s.posts_created_total > 0) then
      v_reasons := array_append(v_reasons, 'profile_incomplete_no_post');
    end if;
  end if;

  return jsonb_build_object(
    'show', cardinality(v_reasons) = 0,
    'reasons', case when cardinality(v_reasons) = 0 then array['eligible'] else v_reasons end);
end;
$$;
comment on function public.check_survey_prompt_eligibility(text, integer) is
  'Whether the caller should be offered a survey''s prompt banner, with the reasons.';
grant execute on function public.check_survey_prompt_eligibility(text, integer) to authenticated;

-- Publishes a new version of a survey, creating the survey on first use
-- (FR-SETTINGS-016 AC5, AC7). Super admin only. Returns the new version number.
--   p_questions   [{ "question_type"?, "short_label_he", "prompt_he", "context_he"?,
--                    "text_placeholder_he"?, "rating_anchor_low_he"?, "rating_anchor_high_he"?,
--                    "choice_options"? }] in display order, 1 to 50
--   forbidden (42501) · invalid_input
create function public.publish_survey_version(
  p_slug text, p_title_he text, p_description_he text, p_is_active boolean, p_prompt_rules jsonb,
  p_questions jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_admin_id constant uuid := kc_private.require_admin_role('super_admin');
  v_survey public.surveys;
  v_version_id uuid;
begin
  if jsonb_typeof(p_questions) is distinct from 'array'
     or jsonb_array_length(p_questions) not between 1 and 50 then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  insert into public.surveys as s (slug, title_he, description_he, is_active, prompt_rules, current_version)
  values (p_slug, p_title_he, p_description_he, coalesce(p_is_active, true),
          coalesce(p_prompt_rules, '{}'::jsonb), 1)
  on conflict (slug) do update
    set title_he = excluded.title_he, description_he = excluded.description_he,
        is_active = excluded.is_active, prompt_rules = excluded.prompt_rules,
        current_version = s.current_version + 1
  returning s.* into v_survey;

  insert into public.survey_versions (survey_id, version, published_by)
  values (v_survey.id, v_survey.current_version, v_admin_id)
  returning id into v_version_id;

  insert into public.survey_questions (
    survey_version_id, sort_order, question_type, short_label_he, prompt_he, context_he,
    text_placeholder_he, rating_anchor_low_he, rating_anchor_high_he, choice_options)
  select v_version_id, q.ordinality::integer,
         coalesce(q.item ->> 'question_type', 'rating_1_7_with_optional_text'),
         q.item ->> 'short_label_he', q.item ->> 'prompt_he', coalesce(q.item ->> 'context_he', ''),
         coalesce(q.item ->> 'text_placeholder_he', ''), coalesce(q.item ->> 'rating_anchor_low_he', ''),
         coalesce(q.item ->> 'rating_anchor_high_he', ''), q.item -> 'choice_options'
    from jsonb_array_elements(p_questions) with ordinality as q (item, ordinality);

  perform kc_private.audit_record(
    'survey_version_published', 'survey', v_survey.id,
    jsonb_build_object('slug', p_slug, 'version', v_survey.current_version));
  return v_survey.current_version;
end;
$$;
comment on function public.publish_survey_version(text, text, text, boolean, jsonb, jsonb) is
  'Super admin: publishes a new version of a survey with its questions.';
grant execute on function public.publish_survey_version(text, text, text, boolean, jsonb, jsonb) to authenticated;

-- >>> supabase/schemas/90_research/030_public_research.sql
-- Research · public research form (FR-RESEARCH-001..003)
--
-- A survey of `public.surveys` can also be answered by people without an account, on a web
-- page. Their answers never touch the API schema: the page calls the `public-research-submit`
-- Edge Function, which checks the origin, hashes the visitor's address with a salt that
-- changes every day, and calls the one function below with the service role. The raw
-- address never reaches the database, and the three tables are reachable by no client role.

create table kc_private.research_responses (
  id              uuid primary key default gen_random_uuid(),
  -- Slug and version as answered; no foreign key, so answers outlive a retired survey.
  survey_slug     text not null,
  version         integer not null check (version >= 1),
  -- Campaign the visitor came from (`?src=`); FR-RESEARCH-001 AC4.
  source          text not null default 'direct' check (source ~ '^[a-z0-9_-]{1,32}$'),
  -- SHA-256 of the visitor's address / user agent with the day's salt, hex. Never raw.
  ip_hash         text not null check (ip_hash ~ '^[0-9a-f]{64}$'),
  user_agent_hash text check (user_agent_hash ~ '^[0-9a-f]{64}$'),
  -- { "<question id>": { "rating": int, "answer_text": text|null } }
  answers         jsonb not null check (jsonb_typeof(answers) = 'object'),
  created_at      timestamptz not null default now()
);
comment on table kc_private.research_responses is 'Anonymous answers to a public research survey. Written by submit_public_research_response().';

-- Per-visitor rate limits: answers of one address hash in the last minute, hour and day.
create index research_responses_ip_recent_idx on kc_private.research_responses (ip_hash, created_at desc);
-- Circuit breaker: all answers of the last minute.
create index research_responses_created_idx on kc_private.research_responses (created_at desc);

-- A visitor who asked to be contacted. Kept apart from the answers so either can be
-- deleted without the other (FR-RESEARCH-003 AC2).
create table kc_private.research_contact_requests (
  id             uuid primary key default gen_random_uuid(),
  response_id    uuid not null references kc_private.research_responses (id) on delete cascade,
  contact_email  text not null check (contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(contact_email) <= 254),
  -- When the visitor prefers to be contacted, in their own words.
  contact_window text check (char_length(contact_window) between 1 and 200),
  consent_at     timestamptz not null default now()
);
comment on table kc_private.research_contact_requests is 'Contact details a research respondent chose to leave.';

-- Covers the response foreign key.
create index research_contact_requests_response_idx on kc_private.research_contact_requests (response_id);

-- The rotating salt (`daily_research_salt`). A value is created on first use, so no secret
-- is ever written into a migration.
create table kc_private.research_secrets (
  key        text primary key check (key = 'daily_research_salt'),
  value      text not null check (char_length(value) >= 32),
  rotated_at timestamptz not null default now()
);
comment on table kc_private.research_secrets is 'Rotating salt for hashing research visitors. Service role only.';

alter table kc_private.research_responses enable row level security;
alter table kc_private.research_responses force row level security;
alter table kc_private.research_contact_requests enable row level security;
alter table kc_private.research_contact_requests force row level security;
alter table kc_private.research_secrets enable row level security;
alter table kc_private.research_secrets force row level security;

-- Sets a fresh random salt and returns when. Called daily through the
-- `rotate-research-salt` Edge Function; after it, yesterday's hashes can no longer be
-- linked to today's visitors.
create function public.rotate_research_salt()
returns timestamptz
language sql
security definer
set search_path = ''
as $$
  insert into kc_private.research_secrets as s (key, value)
  values ('daily_research_salt', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  on conflict (key) do update set value = excluded.value, rotated_at = now()
  returning s.rotated_at;
$$;
comment on function public.rotate_research_salt() is 'Replaces the research salt with a new random value. Service role only.';

-- The current salt, for the Edge Function that hashes the visitor's address; creates the
-- first one when none exists yet.
create function public.get_research_salt()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_value text;
begin
  select s.value into v_value from kc_private.research_secrets s where s.key = 'daily_research_salt';
  if not found then
    perform public.rotate_research_salt();
    select s.value into v_value from kc_private.research_secrets s where s.key = 'daily_research_salt';
  end if;
  return v_value;
end;
$$;
comment on function public.get_research_salt() is 'The current research salt. Service role only.';

-- Stores one anonymous response and, when given, the contact request. Returns the
-- response id.
--   honeypot    a filled hidden field returns a random id and stores nothing (AC1)
--   survey_not_found_or_version_mismatch   the slug is not an active survey at this version
--   rate_limited_minute | _hour | _day     more than 5 / 30 / 100 from one address hash (AC3)
--   research_circuit_open                  more than 500 responses in the last minute (AC4)
--   invalid_input                          answers are not an object
create function public.submit_public_research_response(
  p_slug text, p_version integer, p_source text, p_ip_hash text, p_user_agent_hash text,
  p_answers jsonb, p_honeypot text, p_contact_email text default null,
  p_contact_window_he text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_response_id uuid;
  v_recent record;
begin
  if nullif(btrim(p_honeypot), '') is not null then
    return gen_random_uuid();
  end if;
  if not exists (select 1 from public.surveys s
                  where s.slug = p_slug and s.is_active and s.current_version = p_version) then
    raise exception 'survey_not_found_or_version_mismatch' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_answers) is distinct from 'object' then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  select count(*) filter (where r.created_at > now() - interval '1 minute') as last_minute,
         count(*) filter (where r.created_at > now() - interval '1 hour') as last_hour,
         count(*) as last_day
    into v_recent
    from kc_private.research_responses r
   where r.ip_hash = p_ip_hash and r.created_at > now() - interval '1 day';
  if v_recent.last_minute >= 5 then
    raise exception 'rate_limited_minute' using errcode = 'P0001';
  elsif v_recent.last_hour >= 30 then
    raise exception 'rate_limited_hour' using errcode = 'P0001';
  elsif v_recent.last_day >= 100 then
    raise exception 'rate_limited_day' using errcode = 'P0001';
  end if;
  if (select count(*) from kc_private.research_responses r
       where r.created_at > now() - interval '1 minute') > 500 then
    raise exception 'research_circuit_open' using errcode = 'P0001';
  end if;

  insert into kc_private.research_responses (survey_slug, version, source, ip_hash, user_agent_hash, answers)
  values (p_slug, p_version, coalesce(nullif(btrim(p_source), ''), 'direct'), p_ip_hash,
          p_user_agent_hash, p_answers)
  returning id into v_response_id;
  if nullif(btrim(p_contact_email), '') is not null then
    insert into kc_private.research_contact_requests (response_id, contact_email, contact_window)
    values (v_response_id, btrim(p_contact_email), nullif(btrim(p_contact_window_he), ''));
  end if;
  return v_response_id;
end;
$$;
comment on function public.submit_public_research_response(text, integer, text, text, text, jsonb, text, text, text) is
  'public-research-submit: stores one anonymous research response after the abuse checks. Service role only.';

-- The questions of a survey's current version, for the public form:
-- { slug, title_he, description_he, version, questions: [...] }, or null when the survey is
-- not active. Read by the service role on behalf of the page.
create function public.get_public_research_questions(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
           'slug', s.slug, 'title_he', s.title_he, 'description_he', s.description_he,
           'version', s.current_version,
           'questions', coalesce((
             select jsonb_agg(to_jsonb(q) - 'survey_version_id' order by q.sort_order)
               from public.survey_questions q where q.survey_version_id = v.id), '[]'::jsonb))
    from public.surveys s
    join public.survey_versions v on v.survey_id = s.id and v.version = s.current_version
   where s.slug = p_slug and s.is_active;
$$;
comment on function public.get_public_research_questions(text) is
  'Questions of the current version of an active survey, for the public research form. Service role only.';
